window.NOTES_SEARCH_INDEX = [{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"accessibility-title","heading":"","text":"Accessibility Foundations","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-7d43965ea6e9","heading":"","text":"Build and verify semantic, named, keyboard-operable interfaces with predictable focus and feedback.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-aef5322528f0","heading":"","text":"Semantic HTML & the accessibility tree","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-f2f82b8c5faa","heading":"","text":"Accessible names, descriptions & states","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-8cb8955b8216","heading":"","text":"Keyboard navigation & focus ownership","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-f1d6615fe8d1","heading":"","text":"Dynamic updates, errors & live regions","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-ccf8cfe09411","heading":"","text":"WCAG, zoom & practical verification","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-c25ec6d47dcd","heading":"","text":"Review: demonstrate a usable task","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-tree","heading":"Semantic HTML & the accessibility tree","text":"Semantic HTML & the accessibility tree","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-tree-definition","heading":"Semantic HTML & the accessibility tree","text":"Browsers expose an accessibility tree derived from DOM semantics, state, and rendering. Assistive technologies use it to understand roles, names, values, and relationships. It is related to the DOM but is not a one-to-one copy.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-028089693ae1","heading":"Semantic HTML & the accessibility tree","text":"Example: A native button exposes role and state plus built-in keyboard behavior. A div with role=button changes exposed semantics but still needs focusability and keyboard activation. ARIA describes semantics; it does not implement missing behavior.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-5a0bffd8d469","heading":"Semantic HTML & the accessibility tree","text":"Use: Start with native headings, landmarks, links, buttons, labels, and form controls. Inspect the accessibility tree when markup appears correct but a control is unnamed or misrepresented. Use ARIA to fill a real semantic gap, not to override valid native behavior.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-30d528191335","heading":"Semantic HTML & the accessibility tree","text":"Pitfalls: aria-hidden hides a subtree from assistive technology but does not itself prevent keyboard focus. Do not hide a focused control or ancestor. Decorative icons can be hidden; interactive content needs an operable and understandable contract. See component accessibility guarantees.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-names","heading":"Accessible names, descriptions & states","text":"Accessible names, descriptions & states","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-names-definition","heading":"Accessible names, descriptions & states","text":"An accessible name identifies a control; an accessible description supplies additional guidance. Browsers compute names from sources such as associated labels, aria-labelledby, aria-label, and element content according to the element’s naming rules.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-a60d59395a2f","heading":"Accessible names, descriptions & states","text":"\u003clabel for=\"email\">Email address\u003c/label> \u003cinput id=\"email\" name=\"email\" type=\"email\" aria-describedby=\"email-hint\"> \u003cp id=\"email-hint\">Used for receipts.\u003c/p> \u003cbutton type=\"button\" aria-label=\"Close dialog\">×\u003c/button>","kind":"Code"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-fff4e3898b2d","heading":"Accessible names, descriptions & states","text":"Use: Prefer visible labels that match the accessible name; use aria-labelledby to reference visible text. aria-label can override a name that would otherwise come from content, so adding it casually can create a mismatch. Placeholder text is not a replacement for a persistent label.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-2064a78d8e15","heading":"Accessible names, descriptions & states","text":"State: Expose expanded, selected, checked, disabled, and invalid states through native controls or the correct ARIA attributes. aria-disabled communicates state but does not block clicks or submissions; implement the behavior. Use useId for stable label/description relationships, not as a domain identifier.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-86a9c67dfd79","heading":"Accessible names, descriptions & states","text":"Alternative: If native semantics already express the contract, avoid redundant ARIA. For validation, connect descriptive error text to the field and follow the form feedback model.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-focus","heading":"Keyboard navigation & focus ownership","text":"Keyboard navigation & focus ownership","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-focus-definition","heading":"Keyboard navigation & focus ownership","text":"Focus order should follow a meaningful reading and task sequence. Tab generally moves between controls; composite widgets can use arrow keys internally according to their interaction model. DOM order, visual layout, and focus behavior must work together.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-f82a6351e5ea","heading":"Keyboard navigation & focus ownership","text":"Example: Opening a modal moves focus appropriately, keeps interaction in the modal while it is active, and returns focus to the invoking control after close when that control still exists. Native dialog.showModal supplies important browser behavior; choose an initial focus target based on the task.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-c235657e3d8f","heading":"Keyboard navigation & focus ownership","text":"Use: Prefer natural document order and tabindex=0 for elements that truly require focus. tabindex=-1 allows programmatic focus without adding a normal tab stop. Avoid positive tabindex values that create a second, brittle ordering system.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-d0f5a39b9001","heading":"Keyboard navigation & focus ownership","text":"Composite widgets: Roving tabindex moves DOM focus among items; aria-activedescendant keeps focus on a container/input while identifying the active item. They are different implementations and require correct roles, IDs, and keyboard behavior. Virtualization must keep the active descendant available.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-f1fbf8279356","heading":"Keyboard navigation & focus ownership","text":"Pitfalls: A focusable element is not necessarily understandable or operable. Prevent focus traps, preserve visible focus indicators, and handle unmounted targets during navigation. See compound widgets and default-action cancellation.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-announcements","heading":"Dynamic updates, errors & live regions","text":"Dynamic updates, errors & live regions","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-announcements-definition","heading":"Dynamic updates, errors & live regions","text":"A visual DOM update is not always announced to a screen-reader user. Live regions communicate important updates without moving focus. role=status provides polite status semantics; role=alert is assertive and should be reserved for appropriate urgent feedback.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-ac78be92fbec","heading":"Dynamic updates, errors & live regions","text":"Example: Keep a status region mounted and update it with “3 results found” after a search completes. Announcing every keystroke or every streamed token overwhelms the user. A submission failure may need an error summary and intentional focus rather than only a live announcement.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-e807cdaafa51","heading":"Dynamic updates, errors & live regions","text":"Use: Announce meaningful outcomes, maintain focus for ordinary background refreshes, and avoid replacing the focused control unnecessarily. Mark a changing region busy where appropriate and clear the state when updates finish.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-3cc68c6e058f","heading":"Dynamic updates, errors & live regions","text":"Alternatives and limits: Focus movement is appropriate when the task context changes, such as opening a dialog or navigating to an error summary. Live-region behavior varies by browser/assistive-technology combination; verify the actual task with a screen reader rather than assuming every announcement is guaranteed.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-validation","heading":"WCAG, zoom & practical verification","text":"WCAG, zoom & practical verification","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-validation-definition","heading":"WCAG, zoom & practical verification","text":"WCAG organizes accessibility requirements around perceivable, operable, understandable, and robust experiences. Conformance is broader than passing an automated scan; each criterion has applicability and exceptions.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-13ec0e87a0a8","heading":"WCAG, zoom & practical verification","text":"Practical baseline: Check text contrast (generally 4.5:1 for ordinary text, 3:1 for large text), meaningful non-text contrast, visible focus, meaningful link names, alternative text, reflow, zoom, keyboard access, and errors that do not rely on color alone. Target WCAG 2.2 criteria as relevant, including target size and focus not being obscured.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-59ce39f363ec","heading":"WCAG, zoom & practical verification","text":"Verify a task: Navigate only with the keyboard; inspect names/roles/states in the accessibility tree; test zoom and a narrow viewport; enable reduced motion; use a screen reader to submit and recover from an invalid form. Automated tools help find missing labels and some contrast issues but cannot judge a logical workflow or good alternative text.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-208e1bcf2004","heading":"WCAG, zoom & practical verification","text":"Tradeoffs: Custom controls and highly dynamic layouts increase the behavior you must implement. Prefer established accessible primitives when they fit. Accessibility is part of the component contract, not a final visual polish pass.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-review","heading":"Review: demonstrate a usable task","text":"Review: demonstrate a usable task","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-review-definition","heading":"Review: demonstrate a usable task","text":"Explain semantics, naming, keyboard interaction, focus ownership, status/error feedback, and verification together. Show how an autocomplete or dialog works for keyboard and screen-reader users, including asynchronous results and recovery. Correct role names alone are not a complete implementation.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-title","heading":"","text":"Application Design Patterns","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-fd9fe876709f","heading":"","text":"Read from principles to code-level patterns, then architecture and distributed recovery. Finish with comparisons and the common-use lookup. Each pattern keeps its purpose, example, tradeoffs and alternatives together.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3867005e12f1","heading":"","text":"Choose by the problem","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-6ad12a3677b4","heading":"","text":"SOLID: principles and examples","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-ef3e3c61b87b","heading":"","text":"DRY: principle and example","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d6056822f69e","heading":"","text":"Strategy","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-5522282479ab","heading":"","text":"Dependency injection","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-67931e0f91d3","heading":"","text":"Adapter","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-b7a8cb8ca6e2","heading":"","text":"Facade","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-194b3637874e","heading":"","text":"Ports and adapters","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-8722755198f8","heading":"","text":"Backend for Frontend (BFF)","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-f4f3e3956eb8","heading":"","text":"CQRS","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d0e94bf7ec65","heading":"","text":"Strangler Fig / branch by abstraction","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-698f2f149352","heading":"","text":"Saga","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-ca8e5fff18ae","heading":"","text":"Circuit Breaker / Bulkhead","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-cb2d6e2bfdff","heading":"","text":"Leases","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-cc07edf4eed5","heading":"","text":"Sweepers","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-fb7dddfe6299","heading":"","text":"Fencing and idempotency","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-715600de2362","heading":"","text":"Compare solutions","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-5ac5a174f4ba","heading":"","text":"Checkout comparison","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-b3d33810fe60","heading":"","text":"Common-use lookup","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-784e9e130b0b","heading":"","text":"Design recap","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-cc771f0b9fad","heading":"","text":"Foundations","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-selection","heading":"Choose a pattern by the pressure it resolves","text":"Choose a pattern by the pressure it resolves","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-93ad3e6d998a","heading":"Choose a pattern by the pressure it resolves","text":"Design patterns describe recurring solutions and their tradeoffs. Architectural patterns organize larger boundaries; principles guide decisions. Use the smallest mechanism that makes ownership, behavior, and failure handling explicit. A function or module is often enough; naming a pattern does not require classes or a framework.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-49c9116078f6","heading":"Choose a pattern by the pressure it resolves","text":"PressureStart withRelated alternative","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-750267b44d86","heading":"Choose a pattern by the pressure it resolves","text":"Interchangeable algorithmsStrategyA direct conditional for a small fixed choice.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-c7bc0b9bdc31","heading":"Choose a pattern by the pressure it resolves","text":"Mismatched external contractAdapterUse the original API directly when its coupling is acceptable.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-b61c18152222","heading":"Choose a pattern by the pressure it resolves","text":"Hard-coded dependenciesDependency injectionDirect imports for stable, pure helpers.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-6681b3e397f4","heading":"Choose a pattern by the pressure it resolves","text":"A complicated subsystemFacadeDirect calls when the workflow is already simple.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-0aa0aab26741","heading":"Choose a pattern by the pressure it resolves","text":"Business rules coupled to infrastructurePorts and adaptersModules with explicit boundaries for small applications.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-14341e9426d0","heading":"Choose a pattern by the pressure it resolves","text":"Client-specific API compositionBFFA shared API or framework server route when sufficient.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-fb934a7742cc","heading":"Choose a pattern by the pressure it resolves","text":"Risky replacementStrangler Fig / branch by abstractionA direct replacement for small, easily verified changes.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-2a7b1b30a581","heading":"Choose a pattern by the pressure it resolves","text":"Dependency failures spreadingCircuit breaker / bulkheadTimeouts and bounded concurrency as a baseline.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d8fd6381e569","heading":"Choose a pattern by the pressure it resolves","text":"Abandoned background workLease + recovery scanManaged queue visibility timeout/redelivery, or a short transaction for database-only work.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-0d9662f22d02","heading":"Choose a pattern by the pressure it resolves","text":"Multi-service workflow with partial failureSagaA single database transaction when all changes share one transactional boundary.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-0c477caa585d","heading":"Choose a pattern by the pressure it resolves","text":"Different models for writes and readsCQRSOne CRUD model with indexes/views when sufficient.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-686b6a6af6d6","heading":"Choose a pattern by the pressure it resolves","text":"Database read capacity / standby failoverPrimary/replica replicationQuery/index tuning first; assess staleness and recovery requirements.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-1aa9f22ff2ac","heading":"Choose a pattern by the pressure it resolves","text":"For messages and state transitions, use the existing commands, events, and actions, unidirectional data flow, and state-machine sections. This page focuses on application code and integration boundaries.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-solid","heading":"SOLID: principles for code that can change","text":"SOLID: principles for code that can change","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-solid-definition","heading":"SOLID: principles for code that can change","text":"SOLID is five design principles for reducing coupling and making changes safer. They originated in object-oriented design; their ideas also apply to functions, modules and React components. They guide decisions rather than requiring classes, microservices or a pattern for every function.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-f9892cfa14d8","heading":"SOLID: principles for code that can change","text":"Each principle below combines its meaning, a common use and a minimal before/after example.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-solid-examples","heading":"SOLID: principles for code that can change","text":"Read each pair as one small refactoring, not a requirement to add abstractions everywhere.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"solid-examples-intro","heading":"SOLID: principles for code that can change","text":"Each pair is an independent illustration: before shows the coupling or broken contract; after shows the smallest useful change. Keep these abstractions only where they solve a real change pressure.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"solid-example-s","heading":"SOLID: principles for code that can change › S · Single Responsibility Principle","text":"S · Single Responsibility Principle","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"solid-single-responsibility","heading":"SOLID: principles for code that can change › S · Single Responsibility Principle","text":"A module has one cohesive responsibility—one reason to change.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3ef50cd210a2","heading":"SOLID: principles for code that can change › S · Single Responsibility Principle","text":"Common use: A checkout form renders inputs; a payment adapter handles provider-specific integration. Changing the provider should not require rewriting field markup.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-85e38463486c","heading":"SOLID: principles for code that can change › S · Single Responsibility Principle","text":"Before","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-ef4c0a9892e1","heading":"SOLID: principles for code that can change › S · Single Responsibility Principle","text":"function receipt(items) { const total = items.reduce((sum, item) => sum + item.price, 0); return `Total: ${total}`; }","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-c3b77b1a8c2f","heading":"SOLID: principles for code that can change › S · Single Responsibility Principle","text":"After","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-8c9560d0fd1d","heading":"SOLID: principles for code that can change › S · Single Responsibility Principle","text":"const totalPrice = items => items.reduce((sum, item) => sum + item.price, 0); const formatReceipt = total => `Total: ${total}`; const receipt = items => formatReceipt(totalPrice(items));","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-5dea1c6053d4","heading":"SOLID: principles for code that can change › S · Single Responsibility Principle","text":"What improved: Calculation and formatting have different reasons to change. The composing function may call both; SRP does not forbid orchestration. For a tiny stable helper, the original can be sufficient.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-56d4872cf878","heading":"SOLID: principles for code that can change › S · Single Responsibility Principle","text":"Single responsibility is not one function per file. Several functions can serve one cohesive responsibility.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"solid-example-o","heading":"SOLID: principles for code that can change › O · Open/Closed Principle","text":"O · Open/Closed Principle","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"solid-open-closed","heading":"SOLID: principles for code that can change › O · Open/Closed Principle","text":"Support expected variations by extending behavior without repeatedly changing stable core logic.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-32768448152d","heading":"SOLID: principles for code that can change › O · Open/Closed Principle","text":"Common use: A product sorter accepts a ranking function. Add a new ranking Strategy without changing the sorter.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-a1876abe64db","heading":"SOLID: principles for code that can change › O · Open/Closed Principle","text":"Before","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-8cc835c6a324","heading":"SOLID: principles for code that can change › O · Open/Closed Principle","text":"function rank(items, mode) { return [...items].sort(mode === 'price' ? (a, b) => a.price - b.price : (a, b) => b.rating - a.rating); }","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-41586d31e2d7","heading":"SOLID: principles for code that can change › O · Open/Closed Principle","text":"After","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-dd8efa2e250f","heading":"SOLID: principles for code that can change › O · Open/Closed Principle","text":"const rank = (items, compare) => [...items].sort(compare); const byPrice = (a, b) => a.price - b.price; rank(products, byPrice);","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-624edd33170b","heading":"SOLID: principles for code that can change › O · Open/Closed Principle","text":"What improved: A new ranking supplies another comparator; the sorting workflow stays unchanged. products is caller-supplied data.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-8512f59b2477","heading":"SOLID: principles for code that can change › O · Open/Closed Principle","text":"Open/closed does not forbid editing code. Add extension points for real variation, not speculative future possibilities.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"solid-example-l","heading":"SOLID: principles for code that can change › L · Liskov Substitution Principle","text":"L · Liskov Substitution Principle","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"solid-liskov","heading":"SOLID: principles for code that can change › L · Liskov Substitution Principle","text":"A replacement implementation must honor its abstraction’s behavioral contract: do not strengthen preconditions or weaken promised outcomes.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-5b467c9c0cc9","heading":"SOLID: principles for code that can change › L · Liskov Substitution Principle","text":"Common use: If storage.save() promises persistence before resolving, an adapter that resolves after only buffering in memory is not a valid substitute. Matching TypeScript signatures is insufficient.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-34fee30fbd2f","heading":"SOLID: principles for code that can change › L · Liskov Substitution Principle","text":"Before","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-6a349dfd3dd4","heading":"SOLID: principles for code that can change › L · Liskov Substitution Principle","text":"// Behavioral contract: return ascending values; leave input unchanged. // This signature alone does NOT express the non-mutation promise. type Sorter = (items: number[]) => number[]; const sort: Sorter = items => items.sort((a, b) => a - b); const original = [3, 1, 2]; const sorted = sort(original); // sorted: [1, 2, 3] — correct. // original: [1, 2, 3] — WRONG: the caller expected [3, 1, 2].","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3151e6ef6909","heading":"SOLID: principles for code that can change › L · Liskov Substitution Principle","text":"After","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4d436d8fcdc9","heading":"SOLID: principles for code that can change › L · Liskov Substitution Principle","text":"// Same behavioral contract and type; safe for the same caller. type Sorter = (items: number[]) => number[]; const sort: Sorter = items => [...items].sort((a, b) => a - b); const original = [3, 1, 2]; const sorted = sort(original); // sorted: [1, 2, 3]; original: [3, 1, 2] — both promises honored.","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4820a5eb6cc3","heading":"SOLID: principles for code that can change › L · Liskov Substitution Principle","text":"What improved: a caller may need both the original order and a sorted view. The first implementation breaks that caller’s assumption; the second can replace any sorter promising to preserve the input. That substitutability is the Liskov connection. Mutation alone is not a violation: without the non-mutation promise, the first implementation could be valid. Copying also costs an extra array allocation.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-f7f420d29fc9","heading":"SOLID: principles for code that can change › L · Liskov Substitution Principle","text":"Liskov is about behavior, not just types. Errors, accepted inputs and side effects must preserve the documented contract.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"solid-liskov-readonly","heading":"SOLID: principles for code that can change › L · Liskov Substitution Principle","text":"Make the contract more explicit: accept readonly number[] instead of number[]. TypeScript then rejects calling the mutating items.sort() through that parameter. Sorting a copy still works; modern JavaScript also offers items.toSorted(). Readonly is a compile-time restriction, not a runtime freeze.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"solid-example-i","heading":"SOLID: principles for code that can change › I · Interface Segregation Principle","text":"I · Interface Segregation Principle","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"solid-interface-segregation","heading":"SOLID: principles for code that can change › I · Interface Segregation Principle","text":"Consumers should not depend on capabilities they do not need.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-9a09eb9f4a99","heading":"SOLID: principles for code that can change › I · Interface Segregation Principle","text":"Common use: A search feature depends on a SearchClient contract, rather than a large platform-service interface including billing and administration.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-b2c0644d0118","heading":"SOLID: principles for code that can change › I · Interface Segregation Principle","text":"Before","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-04c70542a82a","heading":"SOLID: principles for code that can change › I · Interface Segregation Principle","text":"type PlatformApi = { search(q: string): Promise\u003cstring[]>; deleteUser(id: string): Promise\u003cvoid>; }; const find = (api: PlatformApi, q: string) => api.search(q);","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-ce4962f4a3c8","heading":"SOLID: principles for code that can change › I · Interface Segregation Principle","text":"After","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-a04daa043ed3","heading":"SOLID: principles for code that can change › I · Interface Segregation Principle","text":"type SearchApi = { search(q: string): Promise\u003cstring[]> }; const find = (api: SearchApi, q: string) => api.search(q);","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-7c8ce423edad","heading":"SOLID: principles for code that can change › I · Interface Segregation Principle","text":"What improved: The search consumer and its test doubles no longer need an unrelated administration capability. A larger platform client can still satisfy the smaller contract.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3d0eb6db71ed","heading":"SOLID: principles for code that can change › I · Interface Segregation Principle","text":"Interface segregation is not splitting every method into its own interface. Group capabilities around consumer needs.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"solid-example-d","heading":"SOLID: principles for code that can change › D · Dependency Inversion Principle","text":"D · Dependency Inversion Principle","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"solid-dependency-inversion","heading":"SOLID: principles for code that can change › D · Dependency Inversion Principle","text":"High-level policy and low-level details depend on abstractions; infrastructure implements contracts shaped by the business needs.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-b7881f8ba43f","heading":"SOLID: principles for code that can change › D · Dependency Inversion Principle","text":"Common use: PlaceOrder depends on a PaymentGateway port. A Stripe adapter implements it; order logic does not import the Stripe SDK. See ports and adapters.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-677c40126c31","heading":"SOLID: principles for code that can change › D · Dependency Inversion Principle","text":"Before","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-f694d2260847","heading":"SOLID: principles for code that can change › D · Dependency Inversion Principle","text":"// Illustrative vendor SDK, configured elsewhere. import { provider } from './vendor-sdk'; const pay = (amountMinor: number) => provider.charges.create({ amount_cents: amountMinor });","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3688da876c73","heading":"SOLID: principles for code that can change › D · Dependency Inversion Principle","text":"After","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-43d4b773f5db","heading":"SOLID: principles for code that can change › D · Dependency Inversion Principle","text":"type PaymentGateway = { charge(amountMinor: number): Promise\u003cvoid> }; const pay = (gateway: PaymentGateway, amount: number) => gateway.charge(amount); // Infrastructure adapter translates the vendor API into the app-owned port. const gateway: PaymentGateway = { charge: async amount => { await provider.charges.create({ amount_cents: amount }); }, }; await pay(gateway, 1000);","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-61168ebb00ab","heading":"SOLID: principles for code that can change › D · Dependency Inversion Principle","text":"What improved: The application owns PaymentGateway; infrastructure implements it. Supplying gateway is dependency injection. The SDK API is illustrative, and the after snippet assumes the adapter module imports the configured provider.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-abb39486f4f4","heading":"SOLID: principles for code that can change › D · Dependency Inversion Principle","text":"Dependency inversion differs from dependency injection. Inversion defines the dependency direction; injection supplies the implementation. Injecting a concrete vendor client alone does not establish a business-owned abstraction.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"solid-practical-distinctions","heading":"SOLID: principles for code that can change › Applying SOLID in practice","text":"Applying SOLID in practice","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-102d6553db22","heading":"SOLID: principles for code that can change › Applying SOLID in practice","text":"Frontend connection: a headless hook can separate interaction behavior from presentation (S); a render strategy can support extension (O). A component replacement must preserve its accessibility and callback contract (L). Use composition and headless APIs where that flexibility is useful, rather than forcing class inheritance.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-52875b47472e","heading":"SOLID: principles for code that can change › Applying SOLID in practice","text":"Explanation: “I apply SOLID to concrete change pressures: separate responsibilities that change independently, provide extension points where variation exists, preserve behavioral contracts, keep consumer interfaces focused and protect business policy from infrastructure details.”","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-1e9e303f6cc9","heading":"SOLID: principles for code that can change › Applying SOLID in practice","text":"When not to add abstractions: stable pure helpers and small local workflows often need only direct functions. Strategy supports O, focused ports support I and ports/adapters supports D, but using those patterns does not automatically satisfy all five principles.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-dry","heading":"DRY: one authoritative definition per rule","text":"DRY: one authoritative definition per rule","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-dry-definition","heading":"DRY: one authoritative definition per rule","text":"DRY (Don’t Repeat Yourself) means avoiding multiple independent definitions of the same knowledge or business rule. The goal is that a policy change has one authoritative place to update—not that every similar line of code must become a shared helper.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"dry-common-use","heading":"DRY: one authoritative definition per rule › Common use: one shipping policy, two screens","text":"Common use: one shipping policy, two screens","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-56ea03f885fe","heading":"DRY: one authoritative definition per rule › Common use: one shipping policy, two screens","text":"The cart and checkout display the same delivery fee. If each owns a copy of the rule, changing the free-shipping threshold can make them disagree. This simplified example assumes one currency, region and delivery method; amounts are in minor units.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-06fd3a7ee612","heading":"DRY: one authoritative definition per rule › Common use: one shipping policy, two screens","text":"Before","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d4544bc66ffe","heading":"DRY: one authoritative definition per rule › Common use: one shipping policy, two screens","text":"const cartShipping = subtotal => subtotal >= 5000 ? 0 : 499; const checkoutShipping = subtotal => subtotal >= 5000 ? 0 : 499; // A policy change must be repeated in both places.","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-6c0311aa6d5d","heading":"DRY: one authoritative definition per rule › Common use: one shipping policy, two screens","text":"After","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-758d6cf0404f","heading":"DRY: one authoritative definition per rule › Common use: one shipping policy, two screens","text":"const shippingFee = subtotal => subtotal >= 5000 ? 0 : 499; const cartShipping = shippingFee(cartSubtotal); const checkoutShipping = shippingFee(checkoutSubtotal);","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-518327abee5b","heading":"DRY: one authoritative definition per rule › Common use: one shipping policy, two screens","text":"What improved: both screens use the same policy function. A threshold change has one definition to update. The two subtotal values come from their respective screens.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"dry-when-to-extract","heading":"DRY: one authoritative definition per rule › When should I extract shared code?","text":"When should I extract shared code?","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4bd21dece344","heading":"DRY: one authoritative definition per rule › When should I extract shared code?","text":"Extract when the copies express the same rule and should change together. Common candidates include pricing rules, canonical validation schemas and generated API contracts. In React, a custom hook can share repeated behavior and cleanup; each call still has its own state. See custom hook contracts.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"dry-false-duplication","heading":"DRY: one authoritative definition per rule › When similar code should stay separate","text":"When similar code should stay separate","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-cf98d8837484","heading":"DRY: one authoritative definition per rule › When similar code should stay separate","text":"An account display name and a delivery instruction may both start with “non-empty text” validation, but they represent different rules and may evolve independently. Sharing a validator only because the code currently looks alike creates accidental coupling. A shared helper that accumulates flags for every caller is a signal to reconsider the abstraction.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-f680b9a3ddde","heading":"DRY: one authoritative definition per rule › When similar code should stay separate","text":"Frontend/server distinction: checking a field in the browser and validating it again on the server is necessary enforcement at two trust boundaries. Share an appropriate schema where useful, but never remove server validation to avoid duplication. Likewise, shared frontend shipping calculations are previews; the server must determine the authoritative charge.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-2fa75243ccee","heading":"DRY: one authoritative definition per rule › When similar code should stay separate","text":"Relationship to SOLID: DRY centralizes one rule; Single Responsibility separates rules that change for different reasons. Extracting every similar block into one generic module can work against that separation.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-89d43ff7a1d4","heading":"DRY: one authoritative definition per rule › When similar code should stay separate","text":"Rule of thumb: “Would these copies need to change together for the same business reason? If yes, consider one shared definition. If not, similar code may be safer than the wrong abstraction.”","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d3f788a5402c","heading":"DRY: one authoritative definition per rule › When similar code should stay separate","text":"Code-level patterns","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-strategy","heading":"Strategy: make a behavior interchangeable","text":"Strategy: make a behavior interchangeable","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-cd1cd9096c3b","heading":"Strategy: make a behavior interchangeable","text":"Purpose: Encapsulate alternative algorithms behind one contract. The caller chooses a strategy without knowing its implementation. In JavaScript, an injected function is often simpler than a class hierarchy.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4597b3b4e6d8","heading":"Strategy: make a behavior interchangeable","text":"Use when: A product list supports several ranking policies, or an export feature supports different formatters. Each policy varies independently of the calling workflow.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-8cfd2f2fa082","heading":"Strategy: make a behavior interchangeable","text":"type Product = { price: number; rating: number }; type Ranking = (a: Product, b: Product) => number; const byPrice: Ranking = (a, b) => a.price - b.price; const byRating: Ranking = (a, b) => b.rating - a.rating; function rank(products: Product[], strategy: Ranking) { return [...products].sort(strategy); // Preserve caller-owned data. } const ranked = rank([{ price: 20, rating: 4 }, { price: 10, rating: 3 }], byPrice);","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-8486f5e73e94","heading":"Strategy: make a behavior interchangeable","text":"Benefits and tradeoffs: Policies are independently testable and replaceable, but extra indirection makes a tiny workflow harder to follow. Strategies must honor the same semantics, including mutation, errors, and ordering guarantees.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4415ccf222c8","heading":"Strategy: make a behavior interchangeable","text":"When not to use: For one stable algorithm or two trivial local branches, use a function or conditional. A data lookup table suits constants; Strategy suits executable behavior.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-532ea4427b04","heading":"Strategy: make a behavior interchangeable","text":"Compare: Strategy selects how to perform work; the State pattern changes behavior according to lifecycle state. An Adapter translates an incompatible contract rather than selecting an algorithm. A React render prop may inject a rendering strategy; see composition patterns.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-di","heading":"Dependency injection: supply dependencies explicitly","text":"Dependency injection: supply dependencies explicitly","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3ee3567a59d8","heading":"Dependency injection: supply dependencies explicitly","text":"Purpose: Let an application function receive its collaborators instead of locating or constructing them internally. This separates policy from dependency creation and enables deterministic testing.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-hook-injection","heading":"Dependency injection: supply dependencies explicitly","text":"Is a hook dependency injection? Only when it receives a collaborator, for example useSearch(query, searchClient). A hook that directly imports a fixed client is not DI merely because it is a hook. A provider can also supply the dependency; preserve stable identity and appropriate request/session scope.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-1a5319ebf3c2","heading":"Dependency injection: supply dependencies explicitly","text":"Use when: Time, network clients, storage, or feature policies need to vary by environment or test. Construct them at a composition root—the application’s setup boundary—and inject through parameters, constructors, or a scoped provider.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-6392eaa9414e","heading":"Dependency injection: supply dependencies explicitly","text":"type Clock = () => number; type Session = { expiresAt: number }; function isExpired(session: Session, now: Clock): boolean { return now() >= session.expiresAt; } isExpired({ expiresAt: 2000 }, () => 1000); // Deterministic: false. isExpired({ expiresAt: 2000 }, Date.now); // Production clock.","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-a6c6fdda213e","heading":"Dependency injection: supply dependencies explicitly","text":"Benefits and tradeoffs: Dependencies become visible and replaceable. Too many parameters can reveal an oversized responsibility; a DI container can hide the dependency graph and introduce lifetime mistakes.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-58b72951b00c","heading":"Dependency injection: supply dependencies explicitly","text":"When not to use: Stable pure helpers usually work as direct imports. Prefer explicit parameters before introducing a container. A service locator asks a registry for dependencies inside business code; it hides requirements that injection makes explicit.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-78b701a99369","heading":"Dependency injection: supply dependencies explicitly","text":"Compare: React Context can distribute an injected service, but Context is a delivery mechanism, not dependency injection itself. Keep service identity stable when appropriate and scope personalized services per request/session; a global singleton can leak SSR user data. Ports define contracts; injection supplies implementations.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-adapter","heading":"Adapter: translate an external contract","text":"Adapter: translate an external contract","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-a51ad6b430c5","heading":"Adapter: translate an external contract","text":"Purpose: Convert an existing interface or data model into the one your application expects. Keep vendor naming, serialization, and error formats at the boundary instead of spreading them through components.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-868fc8ab03f0","heading":"Adapter: translate an external contract","text":"Example: A provider returns { payment_id, amount_cents, currency_code }; a payment adapter maps it into your Payment model. Do not silently guess currency precision: money units are part of the contract.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-94b82493cf24","heading":"Adapter: translate an external contract","text":"Use when: Integrating a vendor, migrating APIs, or connecting a form library to an input contract. Validate untrusted JSON at runtime before adapting it; TypeScript annotations do not validate a network response.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-17d46c9d0e3f","heading":"Adapter: translate an external contract","text":"type ProviderPayment = { payment_id: string; amount_cents: number; currency_code: 'USD' }; type Payment = { id: string; amountMinor: number; currency: 'USD' }; function adaptPayment(raw: ProviderPayment): Payment { return { id: raw.payment_id, amountMinor: raw.amount_cents, currency: raw.currency_code }; }","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-1f48404e2597","heading":"Adapter: translate an external contract","text":"Benefits and tradeoffs: Isolates external changes and makes application models consistent. Mapping code and error translation need maintenance; a lowest-common-denominator interface can hide essential provider capabilities.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-fd4d1452f7de","heading":"Adapter: translate an external contract","text":"When not to use: Do not wrap every utility in a pass-through adapter. Use a stable API directly if there is no meaningful mismatch or boundary to protect.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-666632bcf9ac","heading":"Adapter: translate an external contract","text":"Compare: Adapter translates a contract; Facade simplifies a subsystem; Strategy swaps behavior. An anti-corruption layer is a broader domain boundary that prevents another system’s concepts from distorting your model, often using adapters. See component and form adapters.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-facade","heading":"Facade: expose a cohesive workflow","text":"Facade: expose a cohesive workflow","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4073d07054af","heading":"Facade: expose a cohesive workflow","text":"Purpose: Give callers a small interface over a complex subsystem. A facade hides coordination details while exposing outcomes the caller needs.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-bff-facade","heading":"Facade: expose a cohesive workflow","text":"Is a BFF a Facade? Often, yes: it hides backend-service coordination behind a frontend-friendly API. Facade describes simplification; BFF describes a backend tailored to a client experience. A facade may also be a local module, so the terms are not interchangeable.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-fbebeb8e35ba","heading":"Facade: expose a cohesive workflow","text":"Example: checkout.submit(draft) coordinates validation, an order API, and confirmation mapping. The React form knows about pending, success, and actionable failure rather than every SDK involved.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-f9aa17c7f835","heading":"Facade: expose a cohesive workflow","text":"Use when: Several callers repeat the same sequence or must obey the same integration rules. Return explicit domain outcomes and preserve enough error information for recovery.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-022c69e0b731","heading":"Facade: expose a cohesive workflow","text":"Minimal example · one call hides several steps:","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-57c6925049a4","heading":"Facade: expose a cohesive workflow","text":"async function loadDashboard(userId) { const [profile, orders] = await Promise.all([ users.get(userId), ordersApi.list(userId), ]); return { profile, orders }; }","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-a76c72d595be","heading":"Facade: expose a cohesive workflow","text":"The caller uses one dashboard operation instead of coordinating the two services. Error policy remains part of the facade contract.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-e42431e4ea32","heading":"Facade: expose a cohesive workflow","text":"Benefits and tradeoffs: Reduces coupling and centralizes orchestration. An expanding facade can become a god object; keep it scoped to a cohesive capability. Calling several APIs through one method does not make the workflow atomic—handle partial failure explicitly.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-87fd7f979091","heading":"Facade: expose a cohesive workflow","text":"When not to use: One clear operation rarely needs another wrapper. If the concern is only translating one provider’s contract, use an Adapter. If business orchestration is substantial, use an application service with injected collaborators.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-241a8779cd05","heading":"Facade: expose a cohesive workflow","text":"Compare: A facade can be a local module. A BFF is a server boundary and may expose facade-like endpoints. A proxy preserves an interface while controlling access or remote invocation; a facade intentionally simplifies the interface.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-162c78302ff1","heading":"Facade: expose a cohesive workflow","text":"Architecture and evolution","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-ports","heading":"Ports and adapters: protect business rules","text":"Ports and adapters: protect business rules","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4facf7101cfd","heading":"Ports and adapters: protect business rules","text":"Purpose: In hexagonal architecture, the application core defines the capabilities it needs through ports. Infrastructure implements those ports through adapters. Source-code dependencies point toward the core’s contracts; the core does not import React, a database driver, or a payment SDK.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-2e84c0af4e53","heading":"Ports and adapters: protect business rules","text":"Example: A place-order use case accepts a PaymentGateway port and an OrderRepository port. An HTTP handler is a driving adapter that invokes the use case; a payment SDK adapter is a driven adapter used by it. A composition root wires them together through dependency injection.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-cc65d0d159b3","heading":"Ports and adapters: protect business rules","text":"Use when: Business rules are meaningful, several entry points share them, or infrastructure changes independently. In a frontend, keep pricing rules or workflow decisions in framework-independent modules, while hooks adapt those rules to React lifecycles.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-20638e230883","heading":"Ports and adapters: protect business rules","text":"// Core contract: owned by the application, not a vendor SDK. interface OrderRepository { findById(id: string): Promise\u003c{ id: string; totalMinor: number } | null>; } function makeLoadOrder(orders: OrderRepository) { return (id: string) => orders.findById(id); } // An HTTP or database adapter implements the port; the use case stays unchanged.","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4340b113bf93","heading":"Ports and adapters: protect business rules","text":"Benefits and tradeoffs: Supports focused tests and replaceable infrastructure. Interfaces and mappings add indirection; a port for every CRUD getter can merely duplicate a library API.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-8a67e20f56cc","heading":"Ports and adapters: protect business rules","text":"When not to use: A small UI with minimal business logic may need only feature modules and a clear API client. Extract boundaries when a real dependency or policy needs isolation.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-8f3012211614","heading":"Ports and adapters: protect business rules","text":"Compare: A layered architecture can also enforce inward dependencies; folder names alone do not guarantee this. An Adapter is one building block, while hexagonal architecture governs relationships across the application. Keep authoritative rules on the server even if shared client logic improves UX; see server authorization.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-5173b2e8c2be","heading":"Ports and adapters: protect business rules","text":"Relationship to SOLID: this architecture applies Dependency Inversion. Microservices define deployment/service boundaries; ports and adapters organize dependencies inside a monolith, service or frontend.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-bff","heading":"Backend for Frontend: shape a server boundary for a client","text":"Backend for Frontend: shape a server boundary for a client","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-571ed61971e1","heading":"Backend for Frontend: shape a server boundary for a client","text":"Purpose: A BFF provides APIs tailored to one frontend experience. It can aggregate upstream responses, adapt payloads, and keep upstream credentials on the server.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-df62cfedcd6c","heading":"Backend for Frontend: shape a server boundary for a client","text":"Example: A product page calls GET /web/product-page/42; its BFF fetches product and availability data, authorizes the user, and returns a view-oriented response. Reviews may remain independently loaded so a slow optional dependency does not block the page.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-681c646bb3b5","heading":"Backend for Frontend: shape a server boundary for a client","text":"Use when: Web and mobile have materially different data needs, browser-to-service orchestration is complex, or a server-managed session fits the credential threat model. Framework route handlers can implement this boundary without a separate service.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-228f1270d39f","heading":"Backend for Frontend: shape a server boundary for a client","text":"Minimal example · one frontend-specific response:","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-355cbe9253e0","heading":"Backend for Frontend: shape a server boundary for a client","text":"// Inside an authenticated dashboard HTTP handler: const [user, orders] = await Promise.all([ users.get(currentUser.id), ordersApi.list(currentUser.id), ]); return { greeting: user.name, recentOrders: orders.slice(0, 3) };","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-b8aee91e3ca9","heading":"Backend for Frontend: shape a server boundary for a client","text":"The BFF returns the screen’s data shape; the browser makes one request instead of two. These service clients are illustrative.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-ce110f42efa4","heading":"Backend for Frontend: shape a server boundary for a client","text":"Benefits and tradeoffs: Reduces client coupling and can reduce request waterfalls, but adds server operations, latency, cache policies, and another failure boundary. Enforce resource authorization; avoid an unbounded pass-through proxy or aggregation endpoint.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-47c09b950c56","heading":"Backend for Frontend: shape a server boundary for a client","text":"When not to use: If a shared API already fits, use it directly. Use an API gateway for shared routing, authentication infrastructure, or quotas; use a BFF for client-specific composition. GraphQL offers a query contract and execution model and can be used within a BFF—it is not automatically an alternative deployment boundary.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-b60ce3b1d288","heading":"Backend for Frontend: shape a server boundary for a client","text":"Compare: Server Components govern component execution and can call server-side services; a BFF governs the browser-facing API/session boundary. A single framework application can contain both. Protect upstream work with timeouts and failure containment.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-cqrs","heading":"CQRS: separate write decisions from read models","text":"CQRS: separate write decisions from read models","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-cqrs-definition","heading":"CQRS: separate write decisions from read models","text":"CQRS (Command Query Responsibility Segregation) means designing changing data and reading data as separate responsibilities, with models suited to each. A command asks the system to make a change; a query asks for information without changing business state. A “model” here means the data shape and rules used for that responsibility—not necessarily a separate database.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-01c2f121f028","heading":"CQRS: separate write decisions from read models","text":"Start with the problem: an employer edits a job; thousands of job seekers search it. Editing needs ownership checks and valid changes. Searching needs fast filters, counts and display-ready results. Making both use the same general-purpose job model can become awkward as these needs diverge.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-fb00ea09196b","heading":"CQRS: separate write decisions from read models","text":"Before / ordinary CRUD: one Job model supports editing and searching. This is often sufficient. After / CQRS: the write side owns business changes; the read side exposes a purpose-built search model. You separate the responsibilities because they need different behavior—not simply because one endpoint is POST and another is GET.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-eae0f8019889","heading":"CQRS: separate write decisions from read models","text":"Concrete split · the same job, two purposes:","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-f6693c48a418","heading":"CQRS: separate write decisions from read models","text":"// Write-side command: change authoritative data; enforce business rules. async function changeJobTitle(user, jobId, title) { await permissions.requireJobEditor(user, jobId); await jobs.updateTitle(jobId, title); } // Read-side query: return display-ready search results. async function searchJobs(filters) { return jobSearchView.find(filters); // Includes company name and facet counts. }","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-71a1ce3a9ca8","heading":"CQRS: separate write decisions from read models","text":"These are illustrative configured adapters, not built-in APIs. The write model might store a job with a company ID and enforce who can edit it. The read model can combine job title, company name and filterable fields so search does not repeatedly assemble them. Reading still enforces visibility permissions; separating reads never bypasses authorization.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-e7fbd8ac95a8","heading":"CQRS: separate write decisions from read models","text":"Example with a separate search index · how the models stay connectedCommand: update jobAn employer changes the title to “Senior React Engineer.” Check authorization and title rules, then save the job.Project committed changesCopy the committed title and relevant fields into the search document. This transformation is called a projection.Query: search jobsA seeker searches for React. Read search documents and facet counts, rather than invoking the editing workflow.If projection updates run asynchronously, search may briefly show the old title. Report that indexing is pending or use an explicit read-your-writes strategy when required.","kind":"Diagram"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-1874ef4be387","heading":"CQRS: separate write decisions from read models","text":"When it earns its cost: complicated write rules and demanding reads need different models or independent scaling. When not to use it: a small CRUD app can keep one model with good queries/indexes. CQRS adds extra models to maintain; a separate asynchronous read store also adds lag, synchronization, retries and rebuild work. You can start with separate command/query logic in one application and one database—CQRS does not require microservices, a queue or eventual consistency.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-bc77a23f40e7","heading":"CQRS: separate write decisions from read models","text":"Compare: primary/replica replication copies database data for availability/read capacity; CQRS changes the read/write models. Event sourcing stores events as the authoritative history; CQRS does not require it. Saga coordinates multi-step business changes; it can coexist with CQRS. See the concrete job-search read model.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-cqrs-takeaway","heading":"CQRS: separate write decisions from read models","text":"Remember: “Use one model to decide and apply valid changes, and another to answer the reads efficiently.” A separate search index is one concrete implementation; the essential idea is the separation of read and write responsibilities/models.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-migrations","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Incremental replacement: Strangler Fig & branch by abstraction","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-74eb67721de3","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Purpose: Replace a legacy implementation in controlled steps while keeping the product usable. These approaches reduce the amount of behavior changed at once.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d5fb4b932f98","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Use when: A design-system, framework, API, or persistence migration is too broad for a safe direct replacement. Define the seam, behavior contracts, verification metrics, rollout cohorts, and rollback path before moving traffic.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-6a2186bf72cb","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Minimal example · Strangler Fig vs branch by abstraction:","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-e76bbfb4985f","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"// Strangler Fig: migrate one external capability/route. const app = path.startsWith('/products') ? newApp : legacyApp; app.handle(request); // Branch by abstraction: switch behind the same internal API. const storage = useNewStorage ? indexedDbAdapter : legacyAdapter; storage.save(draft);","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-f8f2d6c0d07d","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Routing and adapters are illustrative. Each switch chooses one implementation, rather than silently dual-writing both.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3d4c7f82ea8e","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"ApproachMechanismExample","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4500ade6df24","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Strangler FigRoute selected capabilities to the new implementation while the legacy implementation serves the rest.Move product routes to a new frontend, then checkout, then remove the old frontend.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-c875f74e2c2d","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Branch by abstractionIntroduce a stable interface, implement old and new variants behind it, and migrate callers before removing the old variant.A storage port switches from localStorage to IndexedDB without rewriting each feature simultaneously.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-7e94f3dfeada","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Example plan: Adapt the legacy implementation behind the interface; add the new implementation; switch a small cohort with a feature flag; compare errors and user outcomes; expand; remove the flag and old code. For data/schema changes, use backward-compatible expand-and-contract steps. Rolling code back may not undo already-written data.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-699986c37cba","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Benefits and tradeoffs: Smaller releases and explicit rollback come with temporary duplication and compatibility work. Assign an owner and removal criteria so the transition does not become permanent.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-7af4137ea697","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"When not to use: Prefer a direct replacement for a small, well-tested change. A feature flag is a routing tool, not a migration architecture. Avoid casually dual-writing both systems: divergent writes need an explicit consistency and recovery policy.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-c67627210a41","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Compare: Strangler Fig moves capability boundaries; branch by abstraction moves implementations behind a contract. Adapters translate old/new interfaces; production performance measurements help verify a migration’s actual outcome.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-11ed035e70ba","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Distributed workflows and recovery","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-saga","heading":"Saga: coordinate a workflow across services","text":"Saga: coordinate a workflow across services","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-saga-definition","heading":"Saga: coordinate a workflow across services","text":"A Saga splits a multi-service business operation into local transactions. Each committed step has a planned compensating action when the workflow cannot complete. It addresses distributed workflow consistency; it is not one database transaction.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-0c192d142a1d","heading":"Saga: coordinate a workflow across services","text":"Example: checkout reserves stock, authorizes payment and confirms an order. If confirmation permanently fails, release the stock reservation and void the payment authorization. If payment was already captured, compensation may be a refund rather than an undo.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-90111d374003","heading":"Saga: coordinate a workflow across services","text":"Use when: independent services own their databases and a business operation spans them. Expose pending, completed and compensating states in the UI; a successful first step is not final success.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-7d6497f89870","heading":"Saga: coordinate a workflow across services","text":"Minimal example · forward steps and compensations:","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-9c6e17e9b9c0","heading":"Saga: coordinate a workflow across services","text":"// Illustrative durable workflow-engine API, not built-in JavaScript. await saga.run([ { execute: reserveStock, compensate: releaseStock }, { execute: authorizePayment, compensate: voidAuthorization }, { execute: confirmOrder }, ]);","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-92dc121c4747","heading":"Saga: coordinate a workflow across services","text":"On permanent failure, the engine compensates completed steps in reverse order. It must persist progress and recover/retry; a plain try/catch is not a durable Saga.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-38df3008b137","heading":"Saga: coordinate a workflow across services","text":"Checkout Saga · forward work and recoveryReserve stockInventory commits a reservation.Authorize paymentPayment service records the authorization. Retry transient failures within a budget.Confirm orderIf successful, complete the workflow. On permanent failure, start compensation.Compensate completed stepsVoid authorization, then release stock. Persist progress and retry failed compensation; escalate when automatic recovery cannot finish.A network timeout is an uncertain outcome. Resolve it using stable operation IDs/status checks before deciding which compensations are required.","kind":"Diagram"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-f1e06d82fdfa","heading":"Saga: coordinate a workflow across services","text":"Two coordination styles: Orchestration uses a durable coordinator to issue commands and track progress—clear for complex workflows, but adds a central workflow component. Choreography lets services react to events—fewer central dependencies, but harder to trace and avoid cycles as the workflow grows. Both need idempotent handlers and durable state/message delivery.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-ebd22cb562bc","heading":"Saga: coordinate a workflow across services","text":"Limits / alternative: Saga does not provide automatic rollback or isolation; users may observe intermediate state, and compensation can fail. Use reservations, version checks and reconciliation where needed. Prefer a single ACID transaction when all changes fit one database. Two-phase commit offers distributed atomic commitment where supported, with coordination/availability costs; Saga trades that atomicity for recoverable business steps.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3f7df505b949","heading":"Saga: coordinate a workflow across services","text":"Connect: commands and events express the work and results; a state machine models progress; transactional outbox connects local commits to message publication. A Circuit Breaker protects individual dependency calls; it does not compensate a workflow.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-resilience","heading":"Failure containment: circuit breakers & bulkheads","text":"Failure containment: circuit breakers & bulkheads","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-5f970f6088d8","heading":"Failure containment: circuit breakers & bulkheads","text":"Purpose: Protect application capacity when dependencies slow down or fail. These patterns are most relevant in your backend/BFF; a browser can degrade its UI but cannot enforce service-wide protection.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-circuit-breaker","heading":"Failure containment: circuit breakers & bulkheads › Circuit breaker: stop repeatedly calling a failing dependency","text":"Circuit breaker: stop repeatedly calling a failing dependency","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-9d801f1549fa","heading":"Failure containment: circuit breakers & bulkheads › Circuit breaker: stop repeatedly calling a failing dependency","text":"Minimal example · fail fast while open:","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-7f896dbb88ab","heading":"Failure containment: circuit breakers & bulkheads › Circuit breaker: stop repeatedly calling a failing dependency","text":"// Illustrative resilience-library API. const breaker = makeBreaker(recommendations.fetch); const items = await breaker.call(userId);","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-e90fd011e1e6","heading":"Failure containment: circuit breakers & bulkheads › Circuit breaker: stop repeatedly calling a failing dependency","text":"The library tracks failures: closed allows calls, open rejects quickly, half-open permits probes. Configure thresholds and handle rejection with a defined fallback.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-360f9512aaf5","heading":"Failure containment: circuit breakers & bulkheads › Circuit breaker: stop repeatedly calling a failing dependency","text":"A breaker monitors configured failure/timeout rates. In closed state it allows calls; in open state it rejects quickly for a cooldown; in half-open state it permits limited probes to decide whether to recover. Scope breakers to the dependency/operation that fails rather than disabling unrelated work.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-e41010846f68","heading":"Failure containment: circuit breakers & bulkheads › Circuit breaker: stop repeatedly calling a failing dependency","text":"Example: After repeated recommendation-service timeouts, return a clearly degraded product page without recommendations. A breaker needs minimum sample sizes, suitable thresholds, bounded probes, and observability. It does not repair the dependency.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-bulkhead","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Bulkhead: isolate capacity so failures cannot consume everything","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-97365b664cce","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Minimal example · isolate concurrency capacity:","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-eb9d1bc019cf","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"// Illustrative library API: separate bounded pools. const imagePool = makePool({ concurrency: 2, maxQueued: 10 }); const checkoutPool = makePool({ concurrency: 20, maxQueued: 40 }); await checkoutPool.run(() => placeOrder(order));","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-99a4bb5c75f0","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Image work must use imagePool; checkout uses checkoutPool. Saturating one pool does not consume the other’s slots. Separate pools still share process CPU and memory.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-6d162cddd3d9","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"A bulkhead gives operations separate bounded resources, such as concurrency limits, connection pools, or queues. If image processing saturates its allocation, checkout still has capacity. Bound waiting queues and reject or degrade when capacity is exhausted.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-a685f114d79f","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Use when: A shared process calls unreliable services or handles workloads with different criticality. Breakers reduce futile work; bulkheads limit how far resource exhaustion spreads. They complement each other.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-33d4655a025e","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Benefits and tradeoffs: Better failure isolation costs configuration and capacity planning. Isolated pools can leave capacity unused; a breaker can block a recovering dependency if poorly tuned. Per-instance breakers do not automatically coordinate across a fleet.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-b5ac3b3da400","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"When not to use: Start with request deadlines, bounded concurrency, cancellation where supported, and actionable errors. Add breakers where repeated failures are a demonstrated risk; avoid placing every browser fetch behind a homegrown global breaker.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-051c1f3526ca","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"MechanismPrimary question","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-c166f05027ab","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Timeout/deadlineHow long may this operation occupy resources?","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3272d5911b27","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Retry with exponential backoff and jitterIs a bounded additional attempt likely to succeed safely?","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d48f5f467c67","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Circuit breakerShould we attempt this dependency now?","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-ddd1a30a2b3e","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"BulkheadHow much isolated capacity may this workload consume?","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-2d26c294e76c","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Rate limitingHow frequently may requests enter?","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-16ce94c66231","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"React error boundaryWhich UI subtree should show a fallback after a rendering failure?","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3841dbbf9fe7","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Retry safely: Retry only suitable transient failures within an overall deadline and attempt budget. Use backoff/jitter to avoid synchronized retry storms; respect server guidance. Mutations need idempotency semantics, and aborting a browser fetch does not guarantee upstream work stopped. Rate limiting protects admission; error boundaries isolate UI failures rather than dependency capacity.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-leases","heading":"Leases: temporary ownership of background work","text":"Leases: temporary ownership of background work","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"lease-definition","heading":"Leases: temporary ownership of background work","text":"A lease grants ownership until an expiry time. The owner must renew it to keep working; expiration lets another owner recover work after a crash. A lease bounds how long others wait for an unresponsive owner. It does not stop an expired owner’s code from continuing.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-2d9c4f0cf431","heading":"Leases: temporary ownership of background work","text":"Example: A worker claims a purchase-processing job for 30 seconds and renews every 10 seconds while healthy. If it crashes, its lease expires and the job becomes recoverable. These intervals are illustrative: choose them from operation latency, pause time, renewal load, and acceptable recovery delay.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"lease-claim","heading":"Leases: temporary ownership of background work › Atomic claiming: one authoritative ownership transition","text":"Atomic claiming: one authoritative ownership transition","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-320d67b1875b","heading":"Leases: temporary ownership of background work › Atomic claiming: one authoritative ownership transition","text":"Store a durable job record with status, owner_id, lease_until, a monotonically increasing generation, attempts, and run_after. Claim it with an atomic conditional update or a short transaction; a separate SELECT followed by an unchecked UPDATE lets two workers both believe they own it.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-118d707cf60a","heading":"Leases: temporary ownership of background work › Atomic claiming: one authoritative ownership transition","text":"-- PostgreSQL. $1 is this worker's ID. Initialize attempts/generation to 0. -- run_after is the earliest eligible retry time; status starts as 'pending'. WITH candidate AS ( SELECT id FROM jobs WHERE status = 'pending' AND run_after \u003c= statement_timestamp() AND attempts \u003c 5 ORDER BY run_after, id FOR UPDATE SKIP LOCKED LIMIT 1 ) UPDATE jobs AS j SET status = 'running', owner_id = $1, lease_until = statement_timestamp() + interval '30 seconds', generation = j.generation + 1, attempts = j.attempts + 1 FROM candidate AS c WHERE j.id = c.id RETURNING j.id, j.generation, j.lease_until;","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d0573fbe84a3","heading":"Leases: temporary ownership of background work › Atomic claiming: one authoritative ownership transition","text":"How it works: The row lock protects selection and update in one statement. SKIP LOCKED lets other claimers choose different jobs; it is useful for queue-like access, not a general consistent-read strategy. No returned row means no eligible job was claimed. Commit promptly and perform the long-running work outside the transaction; do not hold a database lock while calling a purchase provider.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"lease-renewal","heading":"Leases: temporary ownership of background work › Renewal & completion: verify the current generation","text":"Renewal & completion: verify the current generation","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-b7579cb13066","heading":"Leases: temporary ownership of background work › Renewal & completion: verify the current generation","text":"-- $1: job ID; $2: worker ID; $3: generation returned by the claim. UPDATE jobs SET lease_until = statement_timestamp() + interval '30 seconds' WHERE id = $1 AND owner_id = $2 AND generation = $3 AND status = 'running' AND lease_until > statement_timestamp() RETURNING lease_until; -- Record success only if this claim is still valid. UPDATE jobs SET status = 'completed', owner_id = NULL, lease_until = NULL WHERE id = $1 AND owner_id = $2 AND generation = $3 AND status = 'running' AND lease_until > statement_timestamp() RETURNING id;","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-dff6d5ccc4af","heading":"Leases: temporary ownership of background work › Renewal & completion: verify the current generation","text":"Failure contract: Zero updated rows means ownership was lost. A renewal timeout is also uncertain: stop initiating new side effects until ownership is confirmed, and cancel ongoing work when possible. Do not resurrect an expired lease with an unconditional extension. Avoid overlapping renewal calls; a heartbeat is evidence of liveness, while a successful conditional renewal extends ownership.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-6f1d0dd6c777","heading":"Leases: temporary ownership of background work › Renewal & completion: verify the current generation","text":"Time & tradeoffs: Use a documented authoritative time source, such as the same database clock for claim, renewal, and expiry checks; independently skewed worker clocks are unsafe. Wall-clock jumps and store failover remain concerns. Short leases recover faster but increase false expiry and renewal traffic; long leases tolerate pauses but delay recovery. Use a durable coordinator with defined consistency guarantees.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-64b7ba4a8dcd","heading":"Leases: temporary ownership of background work › Renewal & completion: verify the current generation","text":"Compare: A transaction lock protects a short database critical section; a lease supports ownership across longer work without holding that transaction open. A TTL only expires data unless an ownership protocol gives it lease semantics. Local mutexes do not coordinate separate processes. See transactions and conditional updates.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-sweepers","heading":"Sweepers: find expired work & recover it safely","text":"Sweepers: find expired work & recover it safely","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"sweeper-definition","heading":"Sweepers: find expired work & recover it safely","text":"A sweeper is a periodic background scan that detects abandoned or overdue records and applies a recovery policy. It may requeue expired jobs, release expired reservations, or clean up temporary resources. A lease defines when ownership ends; the sweeper decides what happens afterward. They are complementary mechanisms, not a mandatory pair.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-cf131f0ee831","heading":"Sweepers: find expired work & recover it safely","text":"Purchase job: claim, process & recoverClaim atomicallyWorker A receives generation 41 and a lease deadline.Work & renewHealthy A extends its lease with ownership checks; successful work is completed conditionally.Recover an expired claimIf A stops renewing, the sweeper requeues its expired job with a retry delay.Claim a new generationWorker B receives generation 42. A’s stale completion must fail; external side effects need additional protection.Recovery deliberately permits retries. Fencing and idempotency address different consequences of overlapping attempts.","kind":"Diagram"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-e30409ad5cc7","heading":"Sweepers: find expired work & recover it safely","text":"-- PostgreSQL: recover at most 100 expired claims per batch. WITH expired AS ( SELECT id FROM jobs WHERE status = 'running' AND lease_until \u003c= statement_timestamp() ORDER BY lease_until, id FOR UPDATE SKIP LOCKED LIMIT 100 ) UPDATE jobs AS j SET status = CASE WHEN j.attempts \u003c 5 THEN 'pending' ELSE 'failed' END, owner_id = NULL, lease_until = NULL, run_after = statement_timestamp() + interval '5 seconds' FROM expired AS e WHERE j.id = e.id AND j.status = 'running' AND j.lease_until \u003c= statement_timestamp() RETURNING j.id, j.status;","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d4168918658a","heading":"Sweepers: find expired work & recover it safely","text":"Concurrency: The short row-locking transaction coordinates renewal and sweeping; expiry predicates are rechecked during recovery. Concurrent sweepers skip locked rows rather than process one record together. Already recovered/completed records no longer match, making repeated scans safe at the state-transition level. Keep generation monotonic across retries; never reset it when requeuing.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-562eab96f090","heading":"Sweepers: find expired work & recover it safely","text":"Bounded operation: Index the scan path, for example a PostgreSQL partial index on (lease_until, id) WHERE status = 'running'. Process small batches and commit between them. The example uses a fixed retry delay for clarity; production retries usually need capped exponential backoff with jitter, an attempt limit, and a terminal-failure/manual-review policy.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-e03e38d2f374","heading":"Sweepers: find expired work & recover it safely","text":"Recovery latency: Expect roughly the remaining lease duration plus scan interval and scheduling/queue delay. A sweeper is periodic recovery, not an exact timer. Monitor oldest expired lease age, sweep duration, retry rate, renewal failures, and terminal failures.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-9b8bf299cf5d","heading":"Sweepers: find expired work & recover it safely","text":"When not to build one: A managed job queue’s visibility timeout and redelivery may already provide this mechanism. Directly reclaiming expired rows can eliminate a separate sweeper for a simple queue; opportunistic cleanup can suit low-volume temporary data. Database TTL deletion is useful for disposal, but usually does not implement business recovery or an audit trail.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-lease-safety","heading":"Fencing & idempotency: protect against stale owners and retries","text":"Fencing & idempotency: protect against stale owners and retries","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"lease-safety-definition","heading":"Fencing & idempotency: protect against stale owners and retries","text":"Lease expiration is not mutual exclusion at the CPU or network level. A paused worker may resume after another worker has taken ownership, and an old in-flight request may finish after expiry. Correctness must be enforced where the protected write or side effect happens.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d44d0541a65e","heading":"Fencing & idempotency: protect against stale owners and retries","text":"Minimal example: worker A holds generation 7; after expiry, B gets generation 8. A’s write with token 7 is rejected by the resource enforcing the current token (fencing). B retries payment with the same purchase key order-42; the provider returns the original payment outcome instead of charging twice (idempotency).","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"lease-fencing","heading":"Fencing & idempotency: protect against stale owners and retries › Fencing tokens: reject obsolete ownership generations","text":"Fencing tokens: reject obsolete ownership generations","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-cbd15c3a5286","heading":"Fencing & idempotency: protect against stale owners and retries › Fencing tokens: reject obsolete ownership generations","text":"A fencing token is a monotonically increasing ownership number that accompanies protected operations. The resource must validate it atomically with the write. In the job record above, checking the current generation rejects A’s generation 41 after B claims 42. Checking the lease also rejects A before a new owner arrives.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-ae77eb20a17f","heading":"Fencing & idempotency: protect against stale owners and retries › Fencing tokens: reject obsolete ownership generations","text":"For a separate resource, token ordering must match the resource’s ownership scope. Independent per-job counters cannot safely fence a resource shared by multiple jobs. A resource that only remembers the highest token seen can reject an older token after observing a newer one, but cannot detect expiry by itself. Stronger guarantees require checking current ownership/expiry through an appropriate coordination contract. Merely generating or logging a token is not fencing.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"lease-idempotency","heading":"Fencing & idempotency: protect against stale owners and retries › Idempotency: avoid repeating the logical business effect","text":"Idempotency: avoid repeating the logical business effect","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-af314206686d","heading":"Fencing & idempotency: protect against stale owners and retries › Idempotency: avoid repeating the logical business effect","text":"Example: A calls the payment provider successfully, then crashes before marking the job completed. B retries. The job generation protects the completion record, but cannot undo A’s payment. Use a stable idempotency key for the logical purchase operation, shared across attempts, with the provider’s documented deduplication/retention contract. A new key per lease generation defeats that protection.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-022226f625c9","heading":"Fencing & idempotency: protect against stale owners and retries › Idempotency: avoid repeating the logical business effect","text":"Combine mechanisms: Use generation/lease checks for job ownership, a unique constraint or transaction for database effects, and idempotency or reconciliation for external effects. Keep an operation result/receipt so an ambiguous timeout can be resolved. Do not claim exactly-once execution from a lease and sweeper; retries and overlapping execution remain possible. See ambiguous API outcomes and optimistic concurrency control.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-5ac380b158f3","heading":"Fencing & idempotency: protect against stale owners and retries › Idempotency: avoid repeating the logical business effect","text":"MechanismWhat it solvesWhat it does not guarantee","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-adbd6c645ed2","heading":"Fencing & idempotency: protect against stale owners and retries › Idempotency: avoid repeating the logical business effect","text":"LeaseTemporary ownership and eventual recovery after missed renewals.An expired process stops executing.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-9972e07d30cd","heading":"Fencing & idempotency: protect against stale owners and retries › Idempotency: avoid repeating the logical business effect","text":"SweeperDetection and recovery of abandoned durable state.Immediate recovery or deduplicated business effects.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-03c8a11c5481","heading":"Fencing & idempotency: protect against stale owners and retries › Idempotency: avoid repeating the logical business effect","text":"FencingRejection of stale ownership at an enforcing resource.Deduplication of all valid retries or arbitrary external effects.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4aa12b1f8377","heading":"Fencing & idempotency: protect against stale owners and retries › Idempotency: avoid repeating the logical business effect","text":"IdempotencyRepeated logical operations do not repeat their effect within the defined contract.Exclusive execution or recovery of stuck work.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-e57e37bdbf4b","heading":"Fencing & idempotency: protect against stale owners and retries › Idempotency: avoid repeating the logical business effect","text":"When to use: Durable background jobs, temporary reservations, and workflows that outlive an HTTP request. For short database-only changes, prefer transactions and constraints; for local work, use a local concurrency primitive; for queue workloads, evaluate existing queue guarantees first.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-033d2fb45bbe","heading":"Fencing & idempotency: protect against stale owners and retries › Idempotency: avoid repeating the logical business effect","text":"Shutdown connection: Stop claiming jobs, keep renewing while draining work you still own, then finish or release conditionally. Never release ownership while the old worker can still perform unprotected writes. Crashes bypass graceful cleanup, so expiry and recovery remain necessary; see Node.js graceful shutdown.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-ebff137f2ccf","heading":"Fencing & idempotency: protect against stale owners and retries › Idempotency: avoid repeating the logical business effect","text":"Design checks: Pause a worker beyond expiry, race renewal with sweeping, lose a renewal response, run two sweepers, and crash after the external effect but before completion. State precisely which operation is atomic, where fencing is enforced, and how a retry finds an existing result.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-66db25ab103f","heading":"Fencing & idempotency: protect against stale owners and retries › Idempotency: avoid repeating the logical business effect","text":"Compare and review","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-same-problem","heading":"Compare patterns against the same problem","text":"Compare patterns against the same problem","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-same-problem-definition","heading":"Compare patterns against the same problem","text":"Several patterns can contribute to one feature, but they solve different pressures. Compare alternative designs for the same requirement, then explain which combinations are complementary.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4cee963cf5e5","heading":"Compare patterns against the same problem","text":"RequirementSmallest approachPattern / alternative and consideration","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-5b5e9e3c6a60","heading":"Compare patterns against the same problem","text":"Switch between two sorting policiesA local conditional or comparator function.Strategy earns its cost when policies vary independently or are injected; an Adapter is relevant only if input/output contracts differ.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-e3b21630a836","heading":"Compare patterns against the same problem","text":"Integrate two payment providersOne direct SDK call if only one stable provider exists.Adapters normalize provider contracts; injected strategies select a provider. Preserve provider-specific capabilities when the generic contract would hide essential behavior.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-c3c967d98a21","heading":"Compare patterns against the same problem","text":"Reuse a checkout sequenceOne explicit application function.A Facade gives callers a small workflow API; ports/adapters protect domain dependencies when replacement/testing pressure exists. Extra wrappers alone do not improve correctness.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-a48d6aca0366","heading":"Compare patterns against the same problem","text":"Notify analytics and show confirmationExplicit calls after a confirmed outcome.Pub/sub fits independent optional reactions; keep required workflow steps/error ownership explicit. A bus hides control flow and supplies no transaction by itself.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-1c1e120774e5","heading":"Compare patterns against the same problem","text":"Coordinate upload lifecycleA reducer for a small explicit FSM.XState/statecharts fit richer transitions/actors; Strategy varies an algorithm, while State/FSM changes allowed behavior by lifecycle.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-50047080eef6","heading":"Compare patterns against the same problem","text":"Share reusable UI behaviorA custom hook for logic; props for a parent-owned value.Headless components/compound slots coordinate related UI; Context distributes the shared owner. Hook reuse alone does not share state.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-ac3724a20564","heading":"Compare patterns against the same problem","text":"Migrate an old storage implementationDirect replacement when small and well verified.Branch by abstraction swaps a contract’s implementation; Strangler Fig routes capabilities progressively. Both add temporary compatibility/cleanup work.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-6c3845f84c99","heading":"Compare patterns against the same problem","text":"Protect checkout from a slow optional serviceTimeout + bounded concurrency + optional degraded UI.Bulkhead isolates capacity; breaker suppresses repeated failed attempts; retry addresses transient failure. They are complementary and need a shared deadline/budget.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-e2a9286fc9ee","heading":"Compare patterns against the same problem","text":"Decision rule: Name the pressure, owner, invariant, and failure path before the pattern. Compare coupling, operational cost, subscription scope, testability, and migration effort—not simply code length. Prefer the smallest mechanism that resolves the pressure.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-checkout-alternatives","heading":"Worked comparison: design the same checkout feature","text":"Worked comparison: design the same checkout feature","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-checkout-alternatives-definition","heading":"Worked comparison: design the same checkout feature","text":"Requirement: A checkout collects details, submits one order, supports retry after an uncertain result, and displays confirmation. The server remains authoritative for prices, permissions, order state, and payment effects.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-b818138ed31a","heading":"Worked comparison: design the same checkout feature","text":"DesignWhen it fitsCost / failure consideration","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-e49aeb46316f","heading":"Worked comparison: design the same checkout feature","text":"Local form + submit handler + server-state mutationOne screen with a straightforward pending/success/error lifecycle.Few moving parts; enforce disabled duplicate actions and stable operation IDs. A failed response does not prove the order failed.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-1338b825a93c","heading":"Worked comparison: design the same checkout feature","text":"Reducer + ContextSeveral nested checkout components share a modest draft/transition model.Scoped ownership is clear, but you write effect orchestration and guards. Context is not a remote result cache or property-selector store.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-c9d4d0681a44","heading":"Worked comparison: design the same checkout feature","text":"Redux Toolkit + RTK QueryCheckout participates in a broader shared client workspace and team-wide store conventions.Selectors/tooling help coordination; distinguish draft slices from RTK Query’s authoritative remote cache. Do not mirror the same order in two owners.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-030cf2dda2b0","heading":"Worked comparison: design the same checkout feature","text":"XState actor + chosen query/data layerConditional steps, timers, cancel/retry, and independent verification make lifecycle rules central.Model legal events and actor disposal explicitly. A client machine cannot roll back a payment or make backend retries safe.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3e5f4a9d376c","heading":"Worked comparison: design the same checkout feature","text":"Server/BFF orchestration behind one endpointThe browser should not coordinate provider calls and trusted business rules.Reduces client coupling, but adds an operational boundary. Partial failures still require durable reconciliation/idempotency.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-ecef2bb3970b","heading":"Worked comparison: design the same checkout feature","text":"Patterns working together: Inject a PaymentGateway port; use a provider Adapter at that boundary; an application service coordinates the business workflow; expose a focused Facade/BFF contract to the UI. Choose the client owner separately. These are different layers of the same solution, not mutually exclusive libraries.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-522d563fa86d","heading":"Worked comparison: design the same checkout feature","text":"Invariants: Exactly one accepted logical order per idempotency contract, trusted server-derived amounts, valid workflow transitions, and a way to resolve unknown outcomes. Keep database transactions short; external payments need provider deduplication/reconciliation. See client-tool alternatives, external-effect idempotency, and API contract decisions.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-1d2c000f0901","heading":"Worked comparison: design the same checkout feature","text":"What would change the choice? More nested fields alone does not require Redux or XState. Cross-feature sharing suggests store evaluation; complex legal transition rules suggest statechart evaluation; a remote-data synchronization problem suggests a query cache. Use profiling and concrete change scenarios to justify an upgrade rather than migrating preemptively.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-common-usage","heading":"Quick reference: patterns and common uses","text":"Quick reference: patterns and common uses","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-common-usage-definition","heading":"Quick reference: patterns and common uses","text":"Use this as a quick recognition map; follow each reference for its mechanism, minimal example and tradeoffs. One feature can combine several patterns.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-2c5128280fb8","heading":"Quick reference: patterns and common uses","text":"PatternCommon use","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-ac2286eb6bef","heading":"Quick reference: patterns and common uses","text":"StrategyChoose cheapest, highest-rated or recommended product ranking.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-0089c7d0cdf3","heading":"Quick reference: patterns and common uses","text":"AdapterMap a payment provider’s response into your Payment model.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-89a1174d59f6","heading":"Quick reference: patterns and common uses","text":"Dependency injectionPass an API client into a hook or a repository into a service; substitute a fake in tests.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-39a7a0bb69ab","heading":"Quick reference: patterns and common uses","text":"FacadeloadDashboard() hides calls to profile, order and notification services.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3fc2b0954567","heading":"Quick reference: patterns and common uses","text":"Ports and adaptersOrder logic depends on a PaymentGateway contract implemented by a provider adapter.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d30b18bd7003","heading":"Quick reference: patterns and common uses","text":"BFFA mobile-specific endpoint combines services into a compact screen response.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-76035c754332","heading":"Quick reference: patterns and common uses","text":"Strangler FigMove /products to a new application while other routes stay on the legacy app.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-f78ec79f0a23","heading":"Quick reference: patterns and common uses","text":"Branch by abstractionSwitch a storage contract from localStorage to IndexedDB without changing callers.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-7de9d0213044","heading":"Quick reference: patterns and common uses","text":"CQRSWrite job records transactionally; query a separate denormalized search model.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-cc3fc73d92cf","heading":"Quick reference: patterns and common uses","text":"SagaCoordinate inventory, payment and order confirmation with compensation after failure.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-79468c99d327","heading":"Quick reference: patterns and common uses","text":"Circuit BreakerTemporarily stop calling a failing recommendations service and show a defined fallback.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d6e50e8ea2ef","heading":"Quick reference: patterns and common uses","text":"BulkheadGive image processing and checkout separate bounded concurrency capacity.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-a04fd21e1896","heading":"Quick reference: patterns and common uses","text":"LeaseA worker temporarily claims a background job and renews ownership while processing.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-add20834d4a7","heading":"Quick reference: patterns and common uses","text":"SweeperPeriodically detect expired reservations and release them safely.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-132077adbb8e","heading":"Quick reference: patterns and common uses","text":"FencingA resource rejects writes from an old worker using a lower ownership token.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-469bc885d282","heading":"Quick reference: patterns and common uses","text":"IdempotencyRetry a payment with the same logical operation key without charging again.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-fb222c6b6943","heading":"Quick reference: patterns and common uses","text":"ObserverA store notifies components subscribed directly to its changes.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-f5fa9cd695e2","heading":"Quick reference: patterns and common uses","text":"Publish–subscribeAn order.created topic independently triggers analytics and notifications.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-907d12fed435","heading":"Quick reference: patterns and common uses","text":"State machineAn upload permits explicit transitions: idle → uploading → succeeded or failed.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-7fb03eb2f15d","heading":"Quick reference: patterns and common uses","text":"Compound componentsTabs.Root, Tabs.List and Tabs.Panel coordinate selection through shared state.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-00ad88bc1e5b","heading":"Quick reference: patterns and common uses","text":"SlotsA dialog accepts replaceable header and footer content.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-0f8ec998b6fa","heading":"Quick reference: patterns and common uses","text":"Headless hookuseAutocomplete() exposes behavior and accessibility props; the consumer chooses markup.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-36f2e739525a","heading":"Quick reference: patterns and common uses","text":"Progressive enhancementAn HTML search form works through server navigation; JavaScript adds in-place results.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-50e017ceeca2","heading":"Quick reference: patterns and common uses","text":"Primary/replica replicationWrite to the primary; serve reporting reads from a replica when lag is acceptable.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-9137cb59bc33","heading":"Quick reference: patterns and common uses","text":"Combined example: a BFF can act as a Facade, receive service clients through dependency injection, translate vendor data through Adapters and protect downstream calls with Circuit Breakers. These describe different responsibilities, not competing names for the same thing.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-review","heading":"Review: explain the seam and the cost","text":"Review: explain the seam and the cost","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-8da07886fb50","heading":"Review: explain the seam and the cost","text":"Start with a concrete pressure: changing policy, an external contract, hidden dependencies, repeated orchestration, migration risk, or failure propagation. Identify who owns the contract, show the smallest implementation, and describe how it fails and is tested. Explain the simpler alternative and why the current complexity earns its cost.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-5481d021ca2e","heading":"Review: explain the seam and the cost","text":"Practice: Design a replaceable payment client (Adapter + injection), keep checkout rules independent (ports), hide coordination behind a focused facade, and explain why that does not make payment and order persistence atomic. For frontend state, connect these decisions to command handlers and pure reducers.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-programming-title","heading":"","text":"Promises & Async Programming","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-346134525704","heading":"","text":"Coordinate work with explicit dependencies, failure semantics, concurrency bounds, and cancellation.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-0e6877c664e3","heading":"","text":"Promises, async/await & error propagation","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-0a4601ff589a","heading":"","text":"Choose a Promise combinator by failure semantics","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-73e0f341b54c","heading":"","text":"Sequential, parallel & bounded concurrency","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-a3d5f39cc04a","heading":"","text":"Cancellation, deadlines & stale results","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-af59ef29645f","heading":"","text":"Async iteration & backpressure","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-2cb4d027c138","heading":"","text":"Review: define ownership and outcome","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-promises","heading":"Promises, async/await & error propagation","text":"Promises, async/await & error propagation","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-promises-definition","heading":"Promises, async/await & error propagation","text":"A Promise represents an eventual fulfillment or rejection. Its executor runs synchronously; registered reactions run as microtasks after the current stack completes. async functions always return a promise, and await suspends that function’s continuation, not the JavaScript thread.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-9ae1d0900193","heading":"Promises, async/await & error propagation","text":"async function readJson(url, signal) { const response = await fetch(url, { signal }); if (!response.ok) throw new Error(`HTTP ${response.status}`); return response.json(); } try { const profile = await readJson('/api/me'); console.log(profile); } catch (error) { console.error('Profile unavailable', error); }","kind":"Code"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-d17f44b461b9","heading":"Promises, async/await & error propagation","text":"Mechanism: Returning a promise from a then callback adopts its eventual result; throwing rejects the next promise. A catch handler that returns normally converts rejection into fulfillment. Return or await work whose failure the caller must observe; “fire and forget” needs an explicit rejection handler.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-a59c40fe8cc0","heading":"Promises, async/await & error propagation","text":"Pitfalls: Fetch usually fulfills for HTTP 4xx/5xx, so inspect status. try/catch catches an awaited rejection, not an unrelated promise you start without awaiting. Avoid async promise executors: their returned promise is ignored by the Promise constructor. See task and microtask scheduling.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-combinators","heading":"Choose a Promise combinator by failure semantics","text":"Choose a Promise combinator by failure semantics","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-combinators-definition","heading":"Choose a Promise combinator by failure semantics","text":"Combinators coordinate promises; they do not create threads, impose concurrency limits, or cancel underlying operations. Constructing an array with async calls usually starts all those operations before the combinator observes them.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-0b07d9eeec7b","heading":"Choose a Promise combinator by failure semantics","text":"APIResultGood fit / pitfall","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-7e96874f90e0","heading":"Choose a Promise combinator by failure semantics","text":"Promise.allAll values in input order; rejects when an input rejects.Independent required reads. Other requests continue after rejection.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-6c5bb3412526","heading":"Choose a Promise combinator by failure semantics","text":"Promise.allSettledAll outcomes after every input settles.Optional widgets or batch reporting; inspect each outcome.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-e7419a70049b","heading":"Choose a Promise combinator by failure semantics","text":"Promise.raceFirst settlement, success or failure.Competing outcomes; a timeout race does not cancel the request.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-277662eca62b","heading":"Choose a Promise combinator by failure semantics","text":"Promise.anyFirst fulfillment; AggregateError if all reject.Equivalent redundant sources where any success suffices. Losers continue.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-dae1eda96e8c","heading":"Choose a Promise combinator by failure semantics","text":"Example: Fetch profile and permissions with Promise.all if the page needs both. Use allSettled for independent dashboard widgets that can fail separately. Do not issue duplicate payments with Promise.any to “make them faster.” Empty inputs also differ: all/allSettled fulfill, any rejects, race stays pending.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-3d0f2d5886b3","heading":"Choose a Promise combinator by failure semantics","text":"Alternative: Use sequential awaits when operation B depends on A, or when a deliberate ordering/rate constraint requires it. For many independent operations, use bounded concurrency rather than an unbounded Promise.all.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-concurrency","heading":"Sequential, parallel & bounded concurrency","text":"Sequential, parallel & bounded concurrency","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-concurrency-definition","heading":"Sequential, parallel & bounded concurrency","text":"Concurrency means operations are in progress during overlapping periods. Parallelism means execution happens simultaneously. Network concurrency does not imply parallel JavaScript execution; CPU-heavy work may need a worker.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-a4cc0cce63ad","heading":"Sequential, parallel & bounded concurrency","text":"// Independent requests overlap; returned values retain input order. const [profile, settings] = await Promise.all([ readJson('/api/profile'), readJson('/api/settings') ]); // Simple bounded batches, assuming readJson above and an array of URLs. const results = []; for (let index = 0; index \u003c urls.length; index += 4) { results.push(...await Promise.all(urls.slice(index, index + 4).map(url => readJson(url)))); }","kind":"Code"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-1bafb15b8ec0","heading":"Sequential, parallel & bounded concurrency","text":"Use: Bound concurrency for bulk imports, uploads, or upstream API calls to avoid exhausting memory or connection capacity. Batches are simple but wait for the slowest member before starting the next batch; a worker pool or maintained limiter keeps capacity utilized.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-eaf53c0166be","heading":"Sequential, parallel & bounded concurrency","text":"Choose failure behavior: The example stops starting further batches after failure, but already-started requests continue. Decide whether to collect failures or cancel siblings where supported. forEach(async ...) does not await callbacks; use for/of, map with a combinator, or a limiter.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-a3e41d2db8b9","heading":"Sequential, parallel & bounded concurrency","text":"Comparison: Concurrency limits bound simultaneous work; rate limits bound frequency. Bulkheads isolate capacity between workloads.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-cancellation","heading":"Cancellation, deadlines & stale results","text":"Cancellation, deadlines & stale results","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-cancellation-definition","heading":"Cancellation, deadlines & stale results","text":"Cancellation is an operation’s agreement to stop unnecessary work, not a property of every promise. Use AbortController/AbortSignal for supporting APIs and a request/version guard before committing a result that may now be obsolete.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-45ac359a9048","heading":"Cancellation, deadlines & stale results","text":"Example: Query A starts, then B starts; B finishes first. Cancel A if possible and ensure only the current request updates the display. In a mutation, cancellation cannot prove the server did not commit the write.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-9b75c3b662b0","heading":"Cancellation, deadlines & stale results","text":"Use deadlines: Bound total user-visible time, including retries and queueing. Promise.race can stop waiting but leaves the losing work running; a timeout signal can request cancellation. Clear manually created timers in cleanup.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-d70577c671cb","heading":"Cancellation, deadlines & stale results","text":"When not to retry: Validation errors, authorization failures, and unsafe duplicate effects need resolution, not blind repetition. Use bounded backoff/jitter and idempotency policies where appropriate. See failure containment.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-iteration","heading":"Async iteration & backpressure","text":"Async iteration & backpressure","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-iteration-definition","heading":"Async iteration & backpressure","text":"An async iterable supplies values through promises; for await...of consumes them one at a time. It fits paginated sources and streams that produce values over time. Pull-based consumption can provide backpressure when the producer respects demand; an unbounded push buffer does not become safe merely because it exposes an async iterator.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-c328a4c4904e","heading":"Async iteration & backpressure","text":"async function* pages(loadPage) { let cursor; do { const page = await loadPage(cursor); yield page.items; cursor = page.nextCursor; } while (cursor != null); } for await (const items of pages(loadPage)) { await saveBatch(items); // Illustrative application functions. }","kind":"Code"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-50386357663a","heading":"Async iteration & backpressure","text":"Use: Incremental processing without loading everything into memory. Handle stream errors, cancellation, and resource release; breaking a for-await loop invokes the iterator’s return method when available. A stream reader may still need explicit cancellation/release through its own API.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-f8cfa960b3bb","heading":"Async iteration & backpressure","text":"Alternatives: A normal array and loop are simpler for already-loaded data. Use streams for continuous or large transfers; use a bounded task pool when processing items concurrently is safe. Respect pagination contracts rather than assuming every API uses the same cursor rules.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-review","heading":"Review: define ownership and outcome","text":"Review: define ownership and outcome","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-review-definition","heading":"Review: define ownership and outcome","text":"For each asynchronous workflow, explain its dependencies, concurrency bound, failure policy, cancellation owner, stale-result guard, and cleanup. Distinguish a task that failed from a response that never reached the client. Connect those decisions to command handlers and outcome events.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"backend-api-title","heading":"","text":"Backend & API Fundamentals","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-ca451eb993b0","heading":"","text":"Implement trustworthy endpoints with explicit validation, error contracts, pagination, database behavior, and resource bounds.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-e17d4b1af7ea","heading":"","text":"Request handlers, middleware & application services","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-e19978172493","heading":"","text":"Validate input & enforce authorization at the server","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-98cb38dc310e","heading":"","text":"Error contracts, retries & ambiguous outcomes","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-e324983c15e0","heading":"","text":"Pagination: offset, keyset & cursor contracts","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-a39372c8ab79","heading":"","text":"Indexes, transactions & connection pools","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-f89b97798512","heading":"","text":"Primary/replica databases: read scaling and replication lag","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-685effc9aae0","heading":"","text":"N+1 queries, batching & request-scoped caching","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-6ab6e821f51c","heading":"","text":"Review: make the endpoint’s guarantees explicit","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-request-lifecycle","heading":"Request handlers, middleware & application services","text":"Request handlers, middleware & application services","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-request-lifecycle-definition","heading":"Request handlers, middleware & application services","text":"A request pipeline typically parses and bounds the request, establishes identity, validates input, authorizes the operation, invokes application logic, and serializes the result. Middleware handles cross-cutting concerns; domain rules belong in explicit services/use cases rather than an opaque chain of hooks.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-0753f8a8ce0a","heading":"Request handlers, middleware & application services","text":"Example: PATCH /projects/42 runs through a body-size limit, session validation, schema validation, project-specific permission checks, an update transaction, and a response serializer. Generate a request/correlation ID and propagate it to downstream calls and logs.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-3f6903f5168e","heading":"Request handlers, middleware & application services","text":"Use: Keep transport handlers thin and return well-defined outcomes. Order middleware deliberately: an error handler must cover the relevant downstream work, and logging must not expose tokens or sensitive payloads. Bound time, body size, and queued work.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-30661e236096","heading":"Request handlers, middleware & application services","text":"Alternatives: A small endpoint can be a clear function rather than many layers. Introduce a facade or ports and adapters when dependencies and rules justify them. GraphQL resolvers are another transport/application entry point, not permission to bypass these boundaries.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-8f412b9a9472","heading":"Request handlers, middleware & application services","text":"For the execution resources beneath a Node handler and ownership during termination, see Node.js runtime and graceful shutdown.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-validation","heading":"Validate input & enforce authorization at the server","text":"Validate input & enforce authorization at the server","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-validation-definition","heading":"Validate input & enforce authorization at the server","text":"Input validation checks shape, types, ranges, allowed combinations, and business constraints at a trust boundary. Authorization checks whether this principal may perform this operation on this resource. Client types and validation improve UX but cannot establish either server guarantee.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-49bf52d97320","heading":"Validate input & enforce authorization at the server","text":"Example: A create-order endpoint accepts product IDs and quantities, derives trusted prices on the server, validates availability, and checks the account’s permissions. It must not trust a price or tenant owner supplied by the browser.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-a35e62ca4080","heading":"Validate input & enforce authorization at the server","text":"Implementation: Parse into a validated input model, allowlist writable fields to prevent mass assignment, enforce object/tenant scope in data access, and use parameterized queries and output defenses. JSON/schema validation is distinct from HTML sanitisation and SQL parameter binding.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-b4982aeee299","heading":"Validate input & enforce authorization at the server","text":"Tradeoffs: Shared schemas can reduce drift, but server business rules may exceed what the client can know. Avoid duplicating authorization in every UI component as if that protected the endpoint; use server-enforced object-level checks.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-errors","heading":"Error contracts, retries & ambiguous outcomes","text":"Error contracts, retries & ambiguous outcomes","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-errors-definition","heading":"Error contracts, retries & ambiguous outcomes","text":"An API error contract gives clients a stable machine-readable code plus safe details. HTTP status describes the protocol-level outcome; application codes identify recoverable cases without requiring clients to parse human wording.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-4131ba7d9c3e","heading":"Error contracts, retries & ambiguous outcomes","text":"{ \"type\": \"https://example.com/problems/validation\", \"title\": \"Validation failed\", \"status\": 422, \"errors\": [{ \"field\": \"quantity\", \"code\": \"OUT_OF_RANGE\" }], \"requestId\": \"req-42\" }","kind":"Code"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-2512b01177e4","heading":"Error contracts, retries & ambiguous outcomes","text":"Example: Use a documented Problem Details representation or another consistent contract. Expose safe field errors; keep stack traces, credentials, and internal database details out of the response. Log diagnostic context with the same request ID.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-06d8e0074deb","heading":"Error contracts, retries & ambiguous outcomes","text":"Choose recovery: Validation failures need corrected input; forbidden actions need permission changes; transient overload may permit a bounded retry. A 202 acceptance needs a status/polling contract. A lost response after a write is ambiguous: use an idempotency/result lookup policy rather than assuming rollback.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-13e376bd0416","heading":"Error contracts, retries & ambiguous outcomes","text":"Alternatives: A simple API can use a small explicit error union. Do not return 200 with an undocumented failure-shaped body for ordinary REST errors. GraphQL has a separate data-plus-errors execution model. See HTTP status semantics.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-37c37fda9331","heading":"Error contracts, retries & ambiguous outcomes","text":"For asynchronous jobs that outlive a request, leases and sweepers recover abandoned work. Pair ownership checks with stable business-operation idempotency so a crash after an external effect does not repeat that effect on retry.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-pagination","heading":"Pagination: offset, keyset & cursor contracts","text":"Pagination: offset, keyset & cursor contracts","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-pagination-definition","heading":"Pagination: offset, keyset & cursor contracts","text":"Pagination bounds work and data transfer. Offset pagination skips a count of rows; keyset pagination continues after an ordered key. A cursor is a continuation contract and may encode keyset position, snapshot information, or another server token.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-fe6c9ad10105","heading":"Pagination: offset, keyset & cursor contracts","text":"-- Keyset example for a descending feed; parameter syntax is PostgreSQL. SELECT id, created_at, title FROM posts WHERE tenant_id = $1 AND (created_at, id) \u003c ($2, $3) ORDER BY created_at DESC, id DESC LIMIT $4;","kind":"Code"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-1f0f6db30ada","heading":"Pagination: offset, keyset & cursor contracts","text":"Use: Keyset pagination fits large feeds with deterministic sorting; a matching index such as (tenant_id, created_at, id) can help. Include a unique tiebreaker and bound page size. Offset is simpler for small datasets or page-number navigation but can become expensive and shift under insertions/deletions.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-83f8a89c82e0","heading":"Pagination: offset, keyset & cursor contracts","text":"Contract: Validate cursor format and relevant filter/order scope; an opaque cursor is not authorization. Return next-cursor/has-more information. Pagination alone does not promise a consistent snapshot across changing data; define whether duplicates/gaps are acceptable or snapshot semantics are required.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-ca6949897c75","heading":"Pagination: offset, keyset & cursor contracts","text":"Comparison: GraphQL connection-style edges/pageInfo describe one pagination schema, not a mandatory database algorithm. Frontend virtualization bounds rendered nodes; pagination bounds data retrieval. Use both when needed.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-database","heading":"Indexes, transactions & connection pools","text":"Indexes, transactions & connection pools","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-database-definition","heading":"Indexes, transactions & connection pools","text":"An index accelerates suitable lookup/order operations at the cost of write overhead and storage. A transaction groups database changes under atomicity and isolation rules. A connection pool reuses a bounded number of database connections; it does not create unlimited database capacity.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-77d81e9e01bd","heading":"Indexes, transactions & connection pools","text":"Example: Creating an order and its line items belongs in a transaction so partial writes do not become a valid order. Keep transactions short; a payment provider call is not automatically included in the database transaction. Design explicit recovery for external side effects.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-f2bc1e24009e","heading":"Indexes, transactions & connection pools","text":"Measure: Use query plans and representative data to check index use and actual scans. Composite-column order, selectivity, filtering, and sort requirements matter. Avoid adding indexes to every column without evidence.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-147802fcc319","heading":"Indexes, transactions & connection pools","text":"Concurrency: Isolation levels allow different anomalies. Use atomic conditional updates, constraints, or locks for correctness instead of an unchecked read-then-write. Handle deadlocks/serialization failures with a suitable retry policy. See optimistic concurrency control.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-b52a350238c6","heading":"Indexes, transactions & connection pools","text":"Pool limits: Account for all service instances, bound queue wait and request time, and release connections in finally/managed scopes. Serverless scaling can exhaust a database even when each instance has a small pool. Increasing pool size can increase contention rather than throughput.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-a961eb5125ea","heading":"Indexes, transactions & connection pools","text":"For a concrete PostgreSQL example of row locking, SKIP LOCKED, and generation-checked updates, see atomic job claiming. Keep that transaction short and perform remote work after committing.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-replication","heading":"Primary/replica databases: read scaling and replication lag","text":"Primary/replica databases: read scaling and replication lag","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-replication-definition","heading":"Primary/replica databases: read scaling and replication lag","text":"Primary/replica replication is the current terminology for the single-writer topology historically called “master/slave.” Writes go to a primary; replicas apply its transaction log and can serve reads when permitted by the database/configuration. Replication is a database architecture pattern, not a React component pattern.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-588fcef512ba","heading":"Primary/replica databases: read scaling and replication lag","text":"Minimal example · choose a read destination:","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-7662eb1f2cf7","heading":"Primary/replica databases: read scaling and replication lag","text":"await primary.updateProfile(userId, changes); const ownProfile = await primary.getProfile(userId); // Read own write. const publicList = await replica.listPublicProfiles(); // May be stale.","kind":"Code"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-30243ef974f2","heading":"Primary/replica databases: read scaling and replication lag","text":"Illustrative database clients: route freshness-sensitive reads to the primary; use the replica only where lag is acceptable.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-2f4ae0d0f905","heading":"Primary/replica databases: read scaling and replication lag","text":"Example: a user updates their profile on the primary, then immediately reads from an asynchronous replica. The old name can appear because the replica has not applied the write yet: replication lag. For read-your-writes, route the relevant read to the primary or wait for a confirmed replication position. A fixed delay is only a heuristic, not a guarantee.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-940b8100de6c","heading":"Primary/replica databases: read scaling and replication lag","text":"Asynchronous replication reduces commit waiting but permits stale reads and possible loss of acknowledged writes if an out-of-date replica is promoted. Synchronous replication waits for a configured replica acknowledgement level; durability and read visibility depend on whether the replica has received, persisted or applied the log. It adds latency and can reduce write availability when required replicas are unreachable.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-d459646a11ba","heading":"Primary/replica databases: read scaling and replication lag","text":"Use when: you need read capacity, a standby for failover or regional read placement. Replicas do not automatically scale primary writes. Failover needs an election/managed promotion mechanism, fencing of the old primary and client reconnection; avoid split-brain writes.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-6458f8cae572","heading":"Primary/replica databases: read scaling and replication lag","text":"Costs / alternative: routing, lag, failover and operational cost. Start with indexes, query tuning and a single suitably sized database when sufficient. A cache reduces repeated reads but introduces its own invalidation policy; sharding partitions data to distribute write load; CQRS separates models. These mechanisms solve different problems and may coexist.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-9ce9e094bc20","heading":"Primary/replica databases: read scaling and replication lag","text":"Design check: “Which reads tolerate staleness, where do reads after writes go, what replica acknowledgement is required, and what happens during failover?” Monitor lag, replication errors and failover recovery. Replication is not a backup: accidental deletion can propagate, so maintain tested backup/point-in-time recovery separately. See per-operation consistency guarantees.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-n-plus-one","heading":"N+1 queries, batching & request-scoped caching","text":"N+1 queries, batching & request-scoped caching","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-n-plus-one-definition","heading":"N+1 queries, batching & request-scoped caching","text":"N+1 describes fetching a collection once and then making an additional request/query per item or relation. It occurs in REST handlers, ORM code, and GraphQL resolvers; GraphQL does not cause or automatically solve it.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-1b471d143ea4","heading":"N+1 queries, batching & request-scoped caching","text":"Example: Load 30 orders, then load each customer separately: up to 31 queries. Use an appropriate join/eager load, or collect customer IDs and batch the lookup. Preserve authorization scope and input/output ordering.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-45f880bf7fbc","heading":"N+1 queries, batching & request-scoped caching","text":"Use: Trace database/upstream call counts for representative operations. A request-scoped batch loader can deduplicate repeated entity IDs during one operation; do not share personalized loader caches across users. GraphQL resolver batching shows the integration point.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-b2645cc39a2a","heading":"N+1 queries, batching & request-scoped caching","text":"Tradeoffs: Large joins can multiply rows and transfer unnecessary data; batches need limits and per-key failure semantics. Request-local deduplication is not a shared cache invalidation strategy. Choose based on query shape and measured execution, not endpoint style.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-review","heading":"Review: make the endpoint’s guarantees explicit","text":"Review: make the endpoint’s guarantees explicit","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-review-definition","heading":"Review: make the endpoint’s guarantees explicit","text":"Describe validation, authorization, status/error semantics, pagination, query cost, transaction scope, and bounded resources. Explain what happens when a write succeeds but its response is lost. Prefer clear application contracts over transport-specific magic.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"browser-apis-title","heading":"","text":"Browser APIs: Observation, Workers & Storage","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-5011a6ae043a","heading":"","text":"Choose APIs for cancellation, observation, background computation, persistence, and cross-tab coordination. Define the lifecycle, failure behavior, and data owner before using each mechanism.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-cf38a8dbea93","heading":"","text":"Use browser-managed observation for visibility and size changes, and cooperative cancellation for obsolete asynchronous work. These APIs avoid repeated polling and make resource cleanup explicit.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-b3f5ba84a709","heading":"","text":"AbortController & AbortSignal: cancel obsolete work","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-2e181423707c","heading":"","text":"Intersection Observer: observe visibility boundaries","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-88c75e94f836","heading":"","text":"Resize Observer: observe element dimensions","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-2e0a8d1edb04","heading":"","text":"Web Workers: move computation off the main thread","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-9ee8a7949309","heading":"","text":"Browser storage: choose by data and lifetime","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-ab75b3b08f12","heading":"","text":"Cross-tab synchronization: notifications are not transactions","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-4de4a9f54004","heading":"","text":"Choosing the right API","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-abort","heading":"AbortController & AbortSignal: cancel obsolete work","text":"AbortController & AbortSignal: cancel obsolete work","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-6287dc1e24d1","heading":"AbortController & AbortSignal: cancel obsolete work","text":"AbortController owns the cancellation action: call abort(). Its AbortSignal communicates cancellation to supporting operations through the signal option, the aborted flag, and an abort event. This is cooperative cancellation, not a way to forcibly stop arbitrary JavaScript or any Promise.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-70f5a0e3a538","heading":"AbortController & AbortSignal: cancel obsolete work","text":"Use it for: Aborting an obsolete search, canceling a fetch when a React component unmounts, or removing event listeners registered with a signal. It complements debouncing and request deduplication; those reduce different kinds of work.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-b51e9a972d8c","heading":"AbortController & AbortSignal: cancel obsolete work","text":"// Inside a Client Component: useEffect(() => { const controller = new AbortController(); const { signal } = controller; async function load() { try { const response = await fetch( '/api/search?q=' + encodeURIComponent(query), { signal } ); if (!response.ok) throw new Error('HTTP ' + response.status); const results = await response.json(); // Guard the state update if cancellation occurred meanwhile. if (!signal.aborted) setResults(results); } catch (error) { if (!signal.aborted) setError(error); } } load(); return () => controller.abort(); // Query changes or unmount. }, [query]);","kind":"Code"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-b73ea1b07712","heading":"AbortController & AbortSignal: cancel obsolete work","text":"One-shot lifecycle: An aborted signal stays aborted. Create a new controller for a new operation; a shared signal intentionally cancels all operations listening to it.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-4f716bc23e09","heading":"AbortController & AbortSignal: cancel obsolete work","text":"Error handling: Default abort() cancellation causes fetch to reject with an AbortError. Custom abort reasons and timeout signals can produce other reasons, so do not assume every cancellation has that name.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-8460662c7308","heading":"AbortController & AbortSignal: cancel obsolete work","text":"Timeouts & composition: Where supported, AbortSignal.timeout(ms) provides a timeout signal and AbortSignal.any([...]) combines signals, aborting when the first input aborts. Distinguish user cancellation from timeouts when presenting errors.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-9eed67f276a6","heading":"AbortController & AbortSignal: cancel obsolete work","text":"Correctness boundary: Aborting a request does not guarantee server-side processing stops or undo a completed mutation. Prevent obsolete results from committing to state as well; use a request identity when multiple operations can overlap beyond one effect lifecycle. The state-machine example shows a request-ID transition guard.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-956f4b06b200","heading":"AbortController & AbortSignal: cancel obsolete work","text":"To package these lifecycles as reusable behavior, follow the custom hook contracts; choose effect timing using effects and synchronization.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-intersection","heading":"Intersection Observer: observe visibility boundaries","text":"Intersection Observer: observe visibility boundaries","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-be90ba9111ad","heading":"Intersection Observer: observe visibility boundaries","text":"Intersection Observer asynchronously reports when an element’s intersection with a viewport or scroll container crosses configured thresholds. It replaces many scroll handlers that repeatedly measure element geometry.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-d27752ce70e8","heading":"Intersection Observer: observe visibility boundaries","text":"root: The viewport by default (null), or an ancestor scroll container.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-397401e52856","heading":"Intersection Observer: observe visibility boundaries","text":"rootMargin: Expands or shrinks the observation boundary. A positive bottom margin can trigger prefetching before an element enters the viewport.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-05d4c88cdc9c","heading":"Intersection Observer: observe visibility boundaries","text":"threshold: Intersection-ratio boundaries between 0 and 1. A threshold of 0.5 reports crossings around 50% intersection; it does not promise continuous position updates.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-817a739a35bb","heading":"Intersection Observer: observe visibility boundaries","text":"Use it for: Infinite-scroll sentinels, prefetching upcoming content, or starting work when a section approaches the viewport. For ordinary offscreen images, prefer native loading=\"lazy\" when it meets your needs.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-0afe19728675","heading":"Intersection Observer: observe visibility boundaries","text":"// Prefetch a section shortly before it enters the viewport. const observer = new IntersectionObserver(entries => { for (const entry of entries) { if (!entry.isIntersecting) continue; observer.unobserve(entry.target); // One-time trigger. prefetchSection(entry.target.dataset.section); } }, { root: null, rootMargin: '0px 0px 300px 0px', threshold: 0 }); observer.observe(section); // On teardown: observer.disconnect();","kind":"Code"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-357b248c75bb","heading":"Intersection Observer: observe visibility boundaries","text":"Important limits: Geometric intersection does not prove the user actually saw an element; overlays or a background tab can affect visibility. Impression tracking may also need page-visibility checks and a minimum exposure duration. For infinite scrolling, guard against concurrent loads and stop observing when no more data remains.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-resize","heading":"Resize Observer: observe element dimensions","text":"Resize Observer: observe element dimensions","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-7cf1b8fad4c8","heading":"Resize Observer: observe element dimensions","text":"Resize Observer reports changes to an element’s observed box size, even when the browser window stays the same size. For example, opening a sidebar can resize a chart without firing a window.resize event.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-5aa0b342b0bc","heading":"Resize Observer: observe element dimensions","text":"Use it for: Resizing charts or canvases, measuring variable-height virtualized rows, or informing JavaScript widgets of container-size changes. For purely visual responsive styles, prefer CSS container queries when possible.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-ad1ee3e47bf7","heading":"Resize Observer: observe element dimensions","text":"// A chart needs an explicit width when its container changes size. const observer = new ResizeObserver(entries => { for (const entry of entries) { chart.resize({ width: entry.contentRect.width }); } }); observer.observe(chartContainer); // Content box by default. // On teardown: observer.disconnect();","kind":"Code"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-954a2400c2e3","heading":"Resize Observer: observe element dimensions","text":"Box model: Choose content-box, border-box, or device-pixel-content-box as appropriate. contentRect reports content-box dimensions; the size properties provide the corresponding box measurements.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-93c6e4ce2b54","heading":"Resize Observer: observe element dimensions","text":"Resize feedback loops: Changing the observed element’s size inside the callback can trigger more resize notifications. Avoid circular dependencies; compare expected dimensions before writing. Scheduling writes with requestAnimationFrame() can defer them, but does not fix a logically endless resize loop.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-e7b15441405b","heading":"Resize Observer: observe element dimensions","text":"Scope: This API observes size, not position or viewport intersection. Keep callback work small; expensive callbacks still consume rendering time. See layout thrashing for the cost of interleaving geometry reads and DOM writes.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-workers","heading":"Web Workers: move computation off the main thread","text":"Web Workers: move computation off the main thread","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-d82aa677ac98","heading":"Web Workers: move computation off the main thread","text":"A dedicated Web Worker runs JavaScript in a separate execution context and thread, keeping CPU-heavy parsing, indexing, or transformations from blocking input. It cannot access the DOM. Ordinary async functions and React transitions do not move calculations to another thread.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-1c8c5e8b0c60","heading":"Web Workers: move computation off the main thread","text":"// main.js — initialize once per owner, not on every render. const worker = new Worker(new URL('./sum-worker.js', import.meta.url), { type: 'module' }); let latestId = 0; worker.onmessage = ({ data }) => { if (data.id === latestId) console.log('Current sum:', data.sum); }; function calculate(values) { worker.postMessage({ id: ++latestId, values }); } // On teardown: worker.terminate(); // sum-worker.js — a separate file. self.onmessage = ({ data: { id, values } }) => { const sum = values.reduce((total, value) => total + value, 0); self.postMessage({ id, sum }); };","kind":"Code"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-f7a27669e9f6","heading":"Web Workers: move computation off the main thread","text":"Communication: postMessage normally uses structured cloning. Transfer large ArrayBuffer values through a transfer list to avoid copying; the sender’s buffer becomes detached. Functions and DOM nodes cannot be cloned.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-cdd00a44a5ad","heading":"Web Workers: move computation off the main thread","text":"Ownership: Track request IDs, handle error/messageerror, and terminate when the owner is disposed. A cancel message cannot interrupt a worker’s long synchronous function; chunk work so it can process messages, or terminate the worker when losing all its tasks is acceptable.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-63db4cd9dc6f","heading":"Web Workers: move computation off the main thread","text":"Tradeoff: Startup, serialization, and communication add overhead. Use a worker for substantial independent CPU work, not small calculations or ordinary network fetching. Measure the main-thread bottleneck first.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-92f579bf47de","heading":"Web Workers: move computation off the main thread","text":"Different workers: A Service Worker is an event-driven network/offline intermediary with a browser-managed lifetime; it is not a permanently running computation worker.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-storage","heading":"Browser storage: choose by data and lifetime","text":"Browser storage: choose by data and lifetime","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-10b9c8f9ae19","heading":"Browser storage: choose by data and lifetime","text":"StorageSuitable useMechanism and tradeoffs","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-82058133f189","heading":"Browser storage: choose by data and lifetime","text":"localStorageSmall preferences such as a theme.Synchronous string key/value API, generally scoped by origin. JSON serialization is manual. Blocking operations make it unsuitable for large datasets. JavaScript can read it.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-39b96cdba8df","heading":"Browser storage: choose by data and lifetime","text":"sessionStorageTemporary tab-specific drafts.Synchronous, scoped by origin and top-level browsing context; survives reloads but is not a shared cross-tab store.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-fa3ee5a08c69","heading":"Browser storage: choose by data and lifetime","text":"IndexedDBStructured offline data, larger datasets, blobs.Asynchronous transactional object stores with indexes. Handle schema upgrades and blocked upgrades from other open tabs; a wrapper can simplify its event-based API.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-0f6dd945d332","heading":"Browser storage: choose by data and lifetime","text":"CookiesSmall server-facing values, especially session identifiers.Attached automatically to matching HTTP requests, adding request overhead. Server-set HttpOnly cookies are inaccessible to JavaScript. Scope, expiration, Secure, and SameSite affect security.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-46138658f264","heading":"Browser storage: choose by data and lifetime","text":"Decision: Keep temporary state in memory, shareable navigation in the URL, small preferences in localStorage, and substantial offline records in IndexedDB. Storage persists a snapshot; it does not make that snapshot authoritative or current. For credentials, follow the token storage threat model.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-storage-quotas","heading":"Browser storage: choose by data and lifetime › Storage quotas, eviction & recovery","text":"Storage quotas, eviction & recovery","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-f1d88382a98d","heading":"Browser storage: choose by data and lifetime › Storage quotas, eviction & recovery","text":"Quota and eviction policies vary by browser, storage type, device, and browsing mode. Origin storage is often best-effort; users or the browser can remove it. Do not promise a universal capacity or treat local persistence as a backup.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-f515546960de","heading":"Browser storage: choose by data and lifetime › Storage quotas, eviction & recovery","text":"Estimate: await navigator.storage.estimate() returns approximate usage/quota for managed origin storage. It is not a guarantee that the next write succeeds and does not replace each API’s limits.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-a75763e8d7b8","heading":"Browser storage: choose by data and lifetime › Storage quotas, eviction & recovery","text":"Persist deliberately: navigator.storage.persist() requests protection against automatic storage-pressure eviction; check its boolean result. It does not stop users clearing data.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-0c18874ad491","heading":"Browser storage: choose by data and lifetime › Storage quotas, eviction & recovery","text":"Handle failures: Catch QuotaExceededError, transaction aborts, blocked access, and malformed stored JSON. Evict expendable cached data, bound cache size, and provide an in-memory fallback. Keep irreplaceable drafts recoverable or synchronize them to a server.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-522832fc234c","heading":"Browser storage: choose by data and lifetime › Storage quotas, eviction & recovery","text":"SSR boundary: Browser storage is unavailable during server rendering. Read it in an appropriate client lifecycle and avoid hydration mismatches from different initial values.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-cross-tab","heading":"Cross-tab synchronization: notifications are not transactions","text":"Cross-tab synchronization: notifications are not transactions","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-51eeda065863","heading":"Cross-tab synchronization: notifications are not transactions","text":"Use BroadcastChannel for messages between eligible same-origin contexts in the same storage partition, or the storage event for localStorage changes. A localStorage change notifies other eligible documents, not the document performing the write. Neither mechanism supplies durable event history.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-9ad2a045c489","heading":"Cross-tab synchronization: notifications are not transactions","text":"const channel = new BroadcastChannel('app-session'); channel.onmessage = ({ data }) => { if (data?.type === 'session-changed') { // Application-owned: recheck session, then refresh/clear identity-scoped data. revalidateSession(); } }; // Publish a notification, never a credential. channel.postMessage({ type: 'session-changed' }); // On teardown: channel.close();","kind":"Code"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-f403140ef906","heading":"Cross-tab synchronization: notifications are not transactions","text":"Practical contracts: Update the sending tab locally, validate message shape, and re-read authoritative state after a notification. Recheck on focus/resume because a closed or suspended tab can miss messages. For atomic shared data updates use IndexedDB transactions; read-modify-write through localStorage or BroadcastChannel is not atomic. Version records and define conflict behavior. Cross-tab logout improves UX, while server invalidation supplies the security boundary.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-review","heading":"Choosing the right API","text":"Choosing the right API","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-8c9f2691955d","heading":"Choosing the right API","text":"“Is this section approaching the viewport?” Use Intersection Observer.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-44761b09b900","heading":"Choosing the right API","text":"“Did this chart’s container change size?” Use Resize Observer.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-2d6b7df86f37","heading":"Choosing the right API","text":"“Is this request still relevant?” Use AbortController with a supporting operation and guard stale updates.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-8b864ed21ce6","heading":"Choosing the right API","text":"For CPU work, choose a Web Worker; for persistence, choose by data size and lifetime; for multi-tab coordination, use notifications with explicit recovery.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-e30b93635463","heading":"Choosing the right API","text":"Resource lifecycle: Use unobserve(element) to stop observing one target, or disconnect() for all targets. In React, set up observers in an effect and disconnect them in its cleanup; create controllers within each effect execution so cleanup and StrictMode replay remain safe.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-93241791d1af","heading":"","text":"DOM Events, Scheduling & Delegation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-3393809d5ce7","heading":"","text":"Start with how work is scheduled, then follow an event through the DOM. From there, control its behavior, manage listener lifetime, and handle component boundaries.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-5b782fdd3dd4","heading":"","text":"Event loop & scheduling","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-4f2068a35997","heading":"","text":"Event flow & delegation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-c63f7c15b9d0","heading":"","text":"Default actions & cancellation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-b268b8072f07","heading":"","text":"Listener lifecycle","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-796439747bf7","heading":"","text":"Shadow DOM boundaries","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-ad251098ada8","heading":"","text":"Review","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"events-scheduling","heading":"Event loop & scheduling","text":"Event loop & scheduling","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"events-execution-order","heading":"Event loop & scheduling › Execution order in the browser","text":"Execution order in the browser","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-ea135f7b3008","heading":"Event loop & scheduling › Execution order in the browser","text":"Run the current task’s synchronous code until it finishes. Calling an async function also runs its body synchronously up to its first await.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-3b5e30377698","heading":"Event loop & scheduling › Execution order in the browser","text":"Drain microtasks in enqueue order: Promise .then()/.catch()/.finally() callbacks, ready await continuations, and queueMicrotask(). Keep running newly queued microtasks until the queue is empty.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-b436e3f95d35","heading":"Event loop & scheduling › Execution order in the browser","text":"If a rendering opportunity is due: run requestAnimationFrame() callbacks before painting the frame. Rendering is not guaranteed between every pair of tasks.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-83034113eef0","heading":"Event loop & scheduling › Execution order in the browser","text":"Run the next eligible task (for example, a timer or user-input task), then repeat the microtask checkpoint and rendering check.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-62e1bcdca9d9","heading":"Event loop & scheduling › Execution order in the browser","text":"Remember: synchronous code → all queued microtasks → possible rendering → next task. A Promise callback has no special priority over queueMicrotask(); whichever is enqueued first runs first. There is no guaranteed order between a zero-delay timer and requestAnimationFrame() across all scheduling conditions.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-86825dacc9d2","heading":"Event loop & scheduling › Execution order in the browser","text":"The browser coordinates JavaScript execution, input, and rendering through the event loop. JavaScript on a given main thread runs to completion: a handler cannot be interrupted by another handler halfway through its synchronous work.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-c898f9af8e67","heading":"Event loop & scheduling › Execution order in the browser","text":"Tasks (often called macrotasks): Include timer callbacks and event dispatch for user interactions. There are multiple task queues; do not assume one global FIFO order across all task sources.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-3d303af5f258","heading":"Event loop & scheduling › Execution order in the browser","text":"Microtasks: Include Promise reactions, continuations after await, and queueMicrotask() callbacks. At a microtask checkpoint, the browser drains the queue, including newly added microtasks, before continuing. An endless chain causes microtask starvation, delaying input and rendering.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-71db6c2a80df","heading":"Event loop & scheduling › Execution order in the browser","text":"Rendering opportunities: The browser may update rendering between tasks when a frame is due. It does not paint after every task. requestAnimationFrame() callbacks run before the associated rendering update paints, making them suitable for visual updates; heavy callback work still delays the frame.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-a386fed38ab6","heading":"Event loop & scheduling › Execution order in the browser","text":"Timers are not deadlines: setTimeout(fn, 0) schedules a future task after an applicable minimum delay; current work, microtasks, and throttling can postpone it. It neither executes immediately nor guarantees a paint first.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-7b66d338e69d","heading":"Event loop & scheduling › Execution order in the browser","text":"console.log('A'); setTimeout(() => console.log('timer'), 0); Promise.resolve().then(() => console.log('promise')); queueMicrotask(() => console.log('microtask')); console.log('B'); // For this standalone example: // A → B → promise → microtask → timer","kind":"Code"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"events-order-example","heading":"Event loop & scheduling › Execution order in the browser","text":"Output: A → B → promise → microtask → timer. A and B are synchronous. The Promise callback is enqueued before the explicit microtask. Both run before the timer task.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-605f7eacc0d2","heading":"Event loop & scheduling › Execution order in the browser","text":"Practical diagnosis: If typing is delayed while a large filter runs, changing an event handler to async does not move the calculation off the main thread. await Promise.resolve() only yields to microtasks, not to a rendering opportunity. Split work and yield via a task boundary, such as scheduler.yield() where supported, or move suitable computation to a Web Worker. See long tasks and execution measurement.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-4bb95b1163d9","heading":"Event loop & scheduling › Execution order in the browser","text":"For promise composition, rejection propagation, and bounded parallel requests, see Promises and asynchronous programming. The event loop explains scheduling; combinators define outcome policy.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-b1f247f7e78b","heading":"Event loop & scheduling › Execution order in the browser","text":"For server-specific runtime resources rather than DOM scheduling, see libuv thread-pool contention and worker threads.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-254ea6b34db2","heading":"Event propagation, bubbling & delegation","text":"Event propagation, bubbling & delegation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-f23eeaafa353","heading":"Event propagation, bubbling & delegation","text":"How the event travels through the DOM tree.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-d425058d6f06","heading":"Event propagation, bubbling & delegation","text":"The phase in which an event travels upward from its target toward ancestors.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-a1556644705a","heading":"Event propagation, bubbling & delegation","text":"Where we choose to handle the event: at a common ancestor rather than each child.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"events-propagation","heading":"Event propagation, bubbling & delegation › Event propagation","text":"Event propagation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-341313821bb0","heading":"Event propagation, bubbling & delegation › Event propagation","text":"Event propagation describes the path a DOM event takes. For a typical click, it has three phases: capturing (ancestors down toward the target), target (the element where the event occurred), and bubbling (back up through ancestors). Not every event bubbles.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-7f59522e66aa","heading":"Event propagation, bubbling & delegation › Event bubbling","text":"Event bubbling","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-8a021011916e","heading":"Event propagation, bubbling & delegation › Event bubbling","text":"When a user clicks a nested element, a bubbling click can be observed by listeners on its ancestors. For example, a click on a \u003cbutton> can also reach its enclosing \u003cli> and \u003cul>. Propagation control is separate from default-action cancellation; see Default actions & cancellation for the precise method contracts.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-e46bd5b35a98","heading":"Event propagation, bubbling & delegation › Event delegation","text":"Event delegation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-4af385fa7feb","heading":"Event propagation, bubbling & delegation › Event delegation","text":"Delegation is the intentional use of propagation to centralize event handling. We attach a listener to a parent, inspect event.target, and use a selector such as closest() to identify the relevant descendant. It is especially helpful for dynamic lists and plain DOM code.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-b12b263cbf4a","heading":"Event propagation, bubbling & delegation › Event delegation › Example","text":"Example","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-85aeeedfaee2","heading":"Event propagation, bubbling & delegation › Event delegation › Example","text":"\u003cul id=\"products\"> \u003cli data-id=\"1\">\u003cbutton>Buy iPhone\u003c/button>\u003c/li> \u003cli data-id=\"2\">\u003cbutton>Buy MacBook\u003c/button>\u003c/li> \u003c/ul> \u003cscript> const products = document.querySelector(\"#products\"); products.addEventListener(\"click\", event => { const item = event.target.closest(\"li[data-id]\"); if (!item || !products.contains(item)) return; console.log(\"Clicked product:\", item.dataset.id); }); \u003c/script>","kind":"Code"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-8a8424b5ecec","heading":"Event propagation, bubbling & delegation › Event delegation › Example","text":"Why closest()? The actual clicked element may be a button or a nested span. closest(\"li[data-id]\") walks from that element toward its ancestors to find the nearest product row. event.target identifies the target visible to this listener (Shadow DOM retargeting can change it); event.currentTarget is the element whose listener is executing (here, the ul).","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-cbdfe7c38968","heading":"Event propagation, bubbling & delegation › Event delegation › Example","text":"React connection: Hydration connects server-rendered interactive UI to client-side React logic. React already uses delegated handling internally for many events, so ordinary onClick handlers on individual React elements are fine. You still need to understand propagation, event.target vs. event.currentTarget, and stopPropagation().","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-2820fb785226","heading":"Event propagation, bubbling & delegation › Event delegation › Example","text":"Key distinction: Propagation is the browser mechanism. Bubbling is one propagation phase. Delegation is the technique built on top of it, usually using bubbling, although capture-based delegation is also possible.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"events-cancellation","heading":"Default actions & cancellation","text":"Default actions & cancellation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-05ffd1974766","heading":"Default actions & cancellation","text":"Default actions are browser behaviors associated with events, such as following a link or submitting a form. They are distinct from listener execution and event propagation.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-a8c7d3c308e3","heading":"Default actions & cancellation","text":"MethodEffectDoes not do","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-fa41429a331d","heading":"Default actions & cancellation","text":"preventDefault()Cancels the default action if the event is cancelable and the listener is not passive.Stop propagation or other listeners.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-11f5d25996c3","heading":"Default actions & cancellation","text":"stopPropagation()Stops further propagation along the event path.Cancel default actions or stop other listeners on the current target.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-baa7a2881e7a","heading":"Default actions & cancellation","text":"stopImmediatePropagation()Also stops remaining listeners on the current target.Cancel the default action.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-51fa89c53663","heading":"Default actions & cancellation","text":"form.addEventListener('submit', event => { event.preventDefault(); // Handle submission without native navigation. saveForm(new FormData(form)); });","kind":"Code"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-8881073e1577","heading":"Default actions & cancellation","text":"Check the contract: event.cancelable tells whether cancellation is supported; event.defaultPrevented records successful cancellation. Calling preventDefault() after an await can be too late; cancel synchronously during dispatch when you need to take over the action.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-095df19bd133","heading":"Default actions & cancellation","text":"Passive listeners: { passive: true } promises not to cancel the default action, allowing the browser to proceed without waiting for a cancellation decision on scroll-blocking events. It does not make handler work faster. A genuinely canceling listener needs passive: false; use it only when necessary.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-90284b2309ae","heading":"Default actions & cancellation","text":"Preserve native behavior: Broad propagation blocking can break ancestor controls and analytics. Intercept only the action you own; custom link handling should preserve modified clicks and opening new tabs.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"events-lifecycle","heading":"Listener lifecycle & resource ownership","text":"Listener lifecycle & resource ownership","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-6180514d1871","heading":"Listener lifecycle & resource ownership","text":"Register listeners when their owner becomes active and remove them when it is disposed. Listeners attached to long-lived targets such as window can retain stale closures and component data after the UI disappears.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-e0e3d6a1c12d","heading":"Listener lifecycle & resource ownership","text":"capture: Selects capture-phase registration; removal must match the same capture flag.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-3ff18c8a96ef","heading":"Listener lifecycle & resource ownership","text":"once: Removes the listener after its first invocation. If the event never arrives, explicit teardown may still be required.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-4724b7dd3105","heading":"Listener lifecycle & resource ownership","text":"passive: Declares that the listener will not cancel the default action; choose it according to the behavior described above.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-f285f5e6b111","heading":"Listener lifecycle & resource ownership","text":"signal: Associates listener lifetime with an AbortSignal. Aborting its controller removes all listeners registered with that signal. See the AbortSignal cancellation contract.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-13acff1698f6","heading":"Listener lifecycle & resource ownership","text":"function mountPanel(panel) { const controller = new AbortController(); const { signal } = controller; panel.addEventListener('click', handlePanelClick, { signal }); window.addEventListener('resize', updatePanelLayout, { signal }); return () => controller.abort(); // Call when the panel is disposed. }","kind":"Code"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-e0f172c35be0","heading":"Listener lifecycle & resource ownership","text":"Callback identity matters: removeEventListener(type, callback, capture) must receive the original function reference, event type, and matching capture flag. A fresh arrow function or a new bind() result will not remove the original listener. The options object itself need not be the same object; passive and once are not removal-matching keys.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-20899986f6cd","heading":"Listener lifecycle & resource ownership","text":"React integration: Install native subscriptions in an effect and return cleanup; the effect dependency and timing rules explain when re-synchronization occurs. Include reactive dependencies to avoid stale closures; recreating the subscription when dependencies change is valid. Make cleanup safe for StrictMode’s development setup/cleanup replay. See AbortController lifecycle for signal reuse and cancellation limits.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"events-resource-pattern","heading":"Listener lifecycle & resource ownership › Resource ownership & disposal as a general pattern","text":"Resource ownership & disposal as a general pattern","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-258a82140ff1","heading":"Listener lifecycle & resource ownership › Resource ownership & disposal as a general pattern","text":"Purpose: Pair acquisition with release at the same ownership boundary. Subscriptions, observers, timers, workers, and connections should not outlive the feature that owns them. This is explicit resource management; it resembles RAII’s ownership discipline, but JavaScript garbage collection does not provide deterministic cleanup of external resources.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-c9c044565851","heading":"Listener lifecycle & resource ownership › Resource ownership & disposal as a general pattern","text":"Example: A chart component creates a ResizeObserver, subscribes to store updates, and starts a refresh timer in its effect. Cleanup disconnects the observer, unsubscribes, and clears the timer; a shared application connection instead belongs to a longer-lived service, not each chart.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-224534559bcb","heading":"Listener lifecycle & resource ownership › Resource ownership & disposal as a general pattern","text":"Use when: Setup registers future work or retains a resource. Return a disposer, use try/finally for bounded imperative work, or use an effect cleanup for React synchronization. If setup partially fails, release resources already acquired. Cleanup should tolerate the lifecycle’s repeated setup/teardown.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-0a613b4cf106","heading":"Listener lifecycle & resource ownership › Resource ownership & disposal as a general pattern","text":"Benefits and tradeoffs: Prevents leaks, duplicate notifications, and stale writes. Cleanup alone does not undo a completed server operation; combine it with cooperative cancellation and stale-result guards.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-577d704f1048","heading":"Listener lifecycle & resource ownership › Resource ownership & disposal as a general pattern","text":"When not to use: Pure calculations and derived values need no disposal effect. Do not add an effect just to calculate data; see derived state. A finalizer is not a reliable substitute for explicit release. Effect dependencies define resynchronization; subscription contracts define what unsubscribe must stop.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"events-shadow-dom","heading":"When delegation breaks inside a web component","text":"When delegation breaks inside a web component","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-a9c0e4bc845c","heading":"When delegation breaks inside a web component","text":"Symptom: An ancestor listens for a click and calls event.target.closest('button'), but cannot find a button inside a custom element’s shadow tree.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-89c11db065b4","heading":"When delegation breaks inside a web component","text":"Event retargeting: Outside the shadow boundary, event.target typically points to the custom-element host rather than its internal button. closest() does not traverse from a host into its shadow tree.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-2ee0dc69ee8e","heading":"When delegation breaks inside a web component","text":"bubbles vs. composed: Bubbling controls upward propagation; composition controls crossing shadow boundaries. A bubbling custom event still stays inside its shadow tree unless it is composed. Native click events are normally both bubbling and composed.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-2477240e23e5","heading":"When delegation breaks inside a web component","text":"composedPath(): Inspect the event path during dispatch when diagnosing an open shadow root. Closed-root internals are hidden from outside observers. Depending on internal button selectors creates a fragile coupling even when it works.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-b8b7753197ea","heading":"When delegation breaks inside a web component","text":"Prefer a public semantic event: Let the component handle its internal DOM and emit an event such as product-selected with a documented payload. Consumers depend on the component’s public behavior rather than its markup.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-6b8e43c27e90","heading":"When delegation breaks inside a web component","text":"// Inside the component's shadow-root click handler: button.dispatchEvent(new CustomEvent('product-selected', { detail: { productId }, bubbles: true, composed: true })); // Outside: delegate on the public event, not the internal button. productList.addEventListener('product-selected', event => { selectProduct(event.detail.productId); });","kind":"Code"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-bbb49b783717","heading":"When delegation breaks inside a web component","text":"Custom-event contract: CustomEvent defaults to bubbles: false, composed: false, and cancelable: false. Opt into each deliberately. If the component supports a cancelable action, set cancelable: true and check dispatchEvent()’s return value before performing that action. Only expose payload data that belongs in the public API.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-be47a2ea493a","heading":"Review: event delegation","text":"Review: event delegation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-fb61e0419da8","heading":"Review: event delegation","text":"Event delegation is a pattern built on top of DOM event propagation. Instead of registering event listeners on multiple child elements, we register a single listener on their common ancestor. When an event occurs on a child, it bubbles up to the ancestor, where we can identify the original target and handle the event accordingly. This reduces the need for individual listeners and also works for dynamically added children.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-tooling-title","heading":"","text":"Build Tooling & Modules","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-9859b23d459b","heading":"","text":"Understand what the toolchain transforms, what ships to the browser, and how releases remain compatible.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-ce89985f11e7","heading":"","text":"ES modules, CommonJS & module resolution","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-c8388f8a8dd5","heading":"","text":"Bundling, transpilation & polyfills","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-4d3307e46e33","heading":"","text":"Tree shaking, side effects & dependency duplication","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-08582e3dae5e","heading":"","text":"Asset versioning, source maps & configuration","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-5d4dd7f56e9e","heading":"","text":"Review: inspect the emitted application","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-modules","heading":"ES modules, CommonJS & module resolution","text":"ES modules, CommonJS & module resolution","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-modules-definition","heading":"ES modules, CommonJS & module resolution","text":"ES modules (ESM) use import/export with a statically analyzable structure and live bindings. CommonJS (CJS) uses require/module.exports with different loading and interop semantics. Resolution determines which file/package entry a specifier refers to; it depends on runtime, package exports, extensions, and tool configuration.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-b8da3476e4a1","heading":"ES modules, CommonJS & module resolution","text":"// counter.js — ESM export let count = 0; export function increment() { count += 1; } // consumer.js — imported count is a live binding, not a copied snapshot. import { count, increment } from './counter.js'; increment(); console.log(count); // 1","kind":"Code"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-ddcaae452ca5","heading":"ES modules, CommonJS & module resolution","text":"Use: Understand which environment executes a module and how its entry points are selected. Browser native ESM, Node, TypeScript, and bundlers can resolve differently. TypeScript path aliases do not automatically configure the runtime resolver.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-b3459713ec2b","heading":"ES modules, CommonJS & module resolution","text":"Pitfalls: Cyclic dependencies can expose uninitialized bindings or order-sensitive setup. CJS/ESM default/named import interop varies by environment. Fix the dependency graph and package exports rather than relying on accidental transpiler behavior. Code splitting with dynamic import returns a promise; loading can fail.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-86ac61f778f5","heading":"ES modules, CommonJS & module resolution","text":"For runtime ordering, live bindings, circular dependencies, and top-level await, see module execution order. Build-time chunk structure does not replace the language evaluation model.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-pipeline","heading":"Bundling, transpilation & polyfills","text":"Bundling, transpilation & polyfills","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-pipeline-definition","heading":"Bundling, transpilation & polyfills","text":"A bundler analyzes dependencies and emits deployable assets/chunks. Transpilation rewrites source syntax for a target. Type checking verifies types. A polyfill supplies a missing runtime API. These jobs are separate even when one toolchain combines them.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-575a95e89626","heading":"Bundling, transpilation & polyfills","text":"Example: A tool may strip TypeScript and transform optional chaining while never running a full type check. Transforming syntax does not provide fetch, Promise.any, or another missing runtime API. Set explicit browser/runtime targets and run a separate type-check step if needed.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-66ad496a4ef3","heading":"Bundling, transpilation & polyfills","text":"Use: Define supported environments and feature detection before adding polyfills. Prefer native APIs when supported; use targeted compatibility tooling when the support contract requires it. Avoid large indiscriminate polyfill bundles and do not assume a successful build means type-safe or runtime-compatible code.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-1b652d3e5cdf","heading":"Bundling, transpilation & polyfills","text":"Tradeoffs: Bundling can reduce request and packaging overhead; native ESM can simplify suitable deployments. Development behavior can differ from optimized production output, so verify a production build, not only the dev server.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-tree-shaking","heading":"Tree shaking, side effects & dependency duplication","text":"Tree shaking, side effects & dependency duplication","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-tree-shaking-definition","heading":"Tree shaking, side effects & dependency duplication","text":"Tree shaking removes statically provable unused exports/code in an optimized build. It depends on analyzable modules and correct side-effect information; importing a library does not guarantee only the used function is shipped.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-998f3b3f173c","heading":"Tree shaking, side effects & dependency duplication","text":"Example: A module that registers a locale, patches a global, or imports CSS performs observable work at import time. Incorrectly declaring all files side-effect-free can remove necessary behavior. Package sideEffects metadata and bundler behavior need deliberate configuration.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-92dc2ed6549f","heading":"Tree shaking, side effects & dependency duplication","text":"Use: Inspect a bundle analyzer for duplicate dependencies, large transitive imports, and unexpected chunks. Duplicate React instances can break hook assumptions; align peer dependencies and resolution rather than only deduplicating at random.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-024014aaab13","heading":"Tree shaking, side effects & dependency duplication","text":"Alternatives and limits: Tree shaking is different from minification and from lazy loading. Use selective imports where needed, route/feature splitting for deferred code, and remove unused dependencies. Avoid manual micro-optimizations until the emitted bundle identifies a real cost.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-deployment","heading":"Asset versioning, source maps & configuration","text":"Asset versioning, source maps & configuration","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-deployment-definition","heading":"Asset versioning, source maps & configuration","text":"A production artifact should have explicit runtime configuration and cache behavior. Content-hashed asset names allow long-lived immutable caching while the HTML entry point selects the current build.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-3303523e52ea","heading":"Asset versioning, source maps & configuration","text":"Deployment example: Keep older chunks available during rollout so an already-open tab can load its referenced version. Deleting all old assets immediately can cause chunk-load failures. Provide a deliberate recovery flow that does not discard unsaved work.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-efb21441d748","heading":"Asset versioning, source maps & configuration","text":"Configuration: Build-time environment values are embedded into client assets; treat them as public. Runtime public configuration can vary without rebuilding if the application is designed for it. Server secrets must remain server-side; an environment-variable name or prefix is not a security boundary by itself.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-82b678e74496","heading":"Asset versioning, source maps & configuration","text":"Source maps: Map minified stack traces back to authored code. Associate maps with the exact release; decide whether to publish them or upload privately to reporting tooling, since they may reveal source details. Maps improve diagnosis, not security isolation.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-285f32acec22","heading":"Asset versioning, source maps & configuration","text":"Tradeoffs: Aggressive asset caching needs versioned URLs and rollout compatibility. A service worker adds another cache/update lifecycle; it is not automatically a deployment fix. Connect decisions to HTTP caching and incremental rollout.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-review","heading":"Review: inspect the emitted application","text":"Review: inspect the emitted application","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-review-definition","heading":"Review: inspect the emitted application","text":"Explain module boundaries, package resolution, compile targets, polyfills, chunking, cache policy, and release identification. Distinguish “the compiler accepted it,” “the bundle built,” and “the supported runtime can execute it.” Each is a different guarantee.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-title","heading":"","text":"Component Composition","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-377b78e8ee68","heading":"","text":"Start with composition and state ownership, then define customization, accessibility guarantees, and form validation and submission contracts.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-95ca8e814a20","heading":"","text":"Composition builds larger interfaces by combining small components with explicit responsibilities. Prefer a clear contract for behavior, state ownership, and customization over a component with dozens of interacting boolean props.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-1f35b153c2c4","heading":"","text":"Composition patterns & children","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-81f173955c9e","heading":"","text":"Controlled vs. uncontrolled components","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-5e896e526364","heading":"","text":"Compound components & slots","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-72da9b55f152","heading":"","text":"Headless components, hooks & customization","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-c4d15463c9a1","heading":"","text":"Accessible component contracts","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-736d260055d5","heading":"","text":"Progressive enhancement: start with a working platform contract","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-488a24f1335d","heading":"","text":"Complex forms: fields, validation & asynchronous submission","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-ad251098ada8","heading":"","text":"Review","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-patterns","heading":"Composition patterns & children","text":"Composition patterns & children","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-e87262f53ec8","heading":"Composition patterns & children","text":"Containment with props.children: A wrapper accepts nested React nodes without knowing their concrete component types. A Card can provide structure while callers supply content.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-ba47a12e3b72","heading":"Composition patterns & children","text":"Named slots: Props such as header and footer accept React nodes for specific insertion points. Use them when placement has meaning beyond a single children region.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-ae2bdffcaaed","heading":"Composition patterns & children","text":"Render props: A function prop, such as renderItem(item), lets the caller render content using state or data supplied by the component. A function-valued children prop is also a render-prop pattern when the component explicitly invokes it.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-7ce165571cff","heading":"Composition patterns & children","text":"function Card({ title, children, footer }) { return ( \u003csection> \u003ch2>{title}\u003c/h2> \u003cdiv>{children}\u003c/div> \u003cfooter>{footer}\u003c/footer> \u003c/section> ); } \u003cCard title=\"Products\" footer={\u003cPagination />}> \u003cProductList /> \u003c/Card>","kind":"Code"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-ba39dc4f80ba","heading":"Composition patterns & children","text":"Contract: Ordinary children are React nodes, not callbacks. Do not assume every child is an element you can clone; it may be text, a fragment, or null. Prefer explicit props or context over inspecting and rewriting arbitrary children.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-controlled","heading":"Controlled vs. uncontrolled components","text":"Controlled vs. uncontrolled components","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-488ba639d316","heading":"Controlled vs. uncontrolled components","text":"Controlled: The parent owns the input’s value contract (separate from server/client data ownership) and supplies the source of truth through value and a change callback. Use it for coordinated inputs, validation, or externally driven updates. The callback requests a change; the parent must supply the updated value.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-ea00488e52b0","heading":"Controlled vs. uncontrolled components","text":"Uncontrolled: The component or native DOM input owns current state. defaultValue supplies an initial value; changing it later is not a controlled update. When editing fetched data, use an explicit server snapshot and draft policy. Read native input values through form submission or refs when needed; see handling submit events with FormData.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-e3c0c71fd0af","heading":"Controlled vs. uncontrolled components","text":"Hybrid API: A reusable component may support either mode, but each state variable must have one owner. For native text inputs, keep controlled values as strings, often value={value ?? ''}, and avoid switching between controlled and uncontrolled modes during the component’s lifetime.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-3b58c5cddd05","heading":"Controlled vs. uncontrolled components","text":"// Controlled: React state is the source of truth. \u003cinput value={query} onChange={event => setQuery(event.target.value)} /> // Uncontrolled: the DOM owns the current value. \u003cinput name=\"query\" defaultValue=\"React\" />","kind":"Code"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-compound","heading":"Compound components & slots","text":"Compound components & slots","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-e57acc8e768b","heading":"Compound components & slots","text":"Compound components expose cooperating parts under one API. For example, Autocomplete.Root, Autocomplete.Input, and Autocomplete.Results share a state and behavior contract, often through context, while callers control their arrangement.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-bfc250621451","heading":"Compound components & slots","text":"// Illustrative API: these named parts are supplied by a component library. \u003cAutocomplete.Root value={selected} onValueChange={setSelected}> \u003clabel htmlFor=\"product-search\">Product\u003c/label> \u003cAutocomplete.Input id=\"product-search\" /> \u003cAutocomplete.Results> {products.map(product => ( \u003cAutocomplete.Item key={product.id} value={product.id}> {product.name} \u003c/Autocomplete.Item> ))} \u003c/Autocomplete.Results> \u003c/Autocomplete.Root>","kind":"Code"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-80d9ef7cc118","heading":"Compound components & slots","text":"Compound parts vs. slots: Autocomplete.Input is a named component in a compound API; its behavior comes from its implementation and shared contract. A slot is an insertion or replacement point. They can work together, but dot notation alone does not create slot behavior or shared state.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-4c996efb8f22","heading":"Compound components & slots","text":"Shared behavior: The root coordinates selection, open state, active option, and IDs. Parts consume only what they need. Keep ownership explicit if input query and selected value are separate state variables.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-eb1d270ac405","heading":"Compound components & slots","text":"Accessibility contract: A real autocomplete must implement combobox/listbox semantics, accessible names, keyboard navigation, focus management, and relationships such as aria-controls and aria-activedescendant. Flexible composition must preserve those guarantees; see the accessible component contract.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-headless","heading":"Headless components, hooks & customization","text":"Headless components, hooks & customization","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-119494589f95","heading":"Headless components, hooks & customization","text":"Headless APIs separate behavior from visual presentation. A headless component may render unstyled semantic elements; a custom hook can expose state, actions, and prop getters while the caller renders the DOM. See custom hook API design for lifecycle, return-value, and testing contracts. A hook does not automatically share state between callers; shared state needs a provider or store.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-99694a3dc80b","heading":"Headless components, hooks & customization","text":"Minimal example · behavior without prescribed markup:","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-1de2334125c8","heading":"Headless components, hooks & customization","text":"function useToggle() { const [open, setOpen] = useState(false); return { open, toggle: () => setOpen(value => !value) }; } // Inside a component (with useState imported): const { open, toggle } = useToggle(); return \u003cbutton onClick={toggle}>{open ? 'Hide' : 'Show'}\u003c/button>;","kind":"Code"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-fef413827bdc","heading":"Headless components, hooks & customization","text":"The hook owns behavior; the consumer chooses the markup. A separate slot example customizes one named region: \u003cPanel footer={\u003cSaveButton />} />. The Panel implementation decides where to render footer.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-c2848d72d38c","heading":"Headless components, hooks & customization","text":"Props: Configure supported behavior and appearance, such as disabled, size, or a formatter. Prefer explicit options for common variations.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-2052747ec664","heading":"Headless components, hooks & customization","text":"Slots & render props: Replace a region or its rendering when callers need structural flexibility. Forward required refs and accessibility attributes, and compose internal and user event handlers deliberately.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-b23957fe5112","heading":"Headless components, hooks & customization","text":"Adapters: Translate an external contract into the component’s contract. For example, a form-library adapter maps field value, change, blur, error, and ref behavior to the input API. Keep vendor-specific details out of the reusable core. See Adapter vs. Strategy and Facade for integration boundaries.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-f91d75d1afb0","heading":"Headless components, hooks & customization","text":"Tradeoff: More customization creates more combinations to support. Define which party owns markup, focus, state, and accessibility; an unrestricted escape hatch can break invariants that ordinary props preserve.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-f1c4dac5cb08","heading":"Headless components, hooks & customization","text":"Worked case: Follow the reusable autocomplete architecture to combine a headless core, compound presentation, host adapters, and explicit package exports.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-accessibility","heading":"Accessible component contracts","text":"Accessible component contracts","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-af159c031e7b","heading":"Accessible component contracts","text":"An accessible component API guarantees semantics, keyboard behavior, focus ownership, and state announcements across its supported customizations. See accessibility foundations for the tree, names, and keyboard model. Accessibility belongs to the behavior contract, including in headless APIs.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-5ec8d9cf9e05","heading":"Accessible component contracts","text":"Prefer native semantics: A native button provides keyboard activation and disabled behavior. Adding role=\"button\" to a div does not implement these. Give non-submit buttons inside forms type=\"button\".","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-4fa7063e26ba","heading":"Accessible component contracts","text":"Define the accessible name: Associate labels with inputs; expose labels for icon-only controls. Forward stable IDs, aria-describedby, and state attributes to the actual interactive element. Use useId for relationships, not list keys.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-63d94797b9e1","heading":"Accessible component contracts","text":"Own focus deliberately: A modal dialog needs an accessible title, appropriate initial focus, constrained focus navigation, inert background behavior, and focus restoration on close. Native dialog.showModal() supplies important platform behavior; custom dialogs must implement it.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-397467afad4e","heading":"Accessible component contracts","text":"Specify keyboard interaction: Compound widgets need a documented model, such as arrow navigation and an active descendant for a combobox. aria-activedescendant references a real option ID while DOM focus stays on the input; keep that option mounted when virtualizing.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-784b078a9766","heading":"Accessible component contracts","text":"Preserve the contract through slots: Forward refs and merge required IDs, ARIA attributes, and handlers. A replacement must preserve the expected element semantics. Define whether a user handler’s preventDefault() vetoes internal behavior; see default-action cancellation.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-029b820ba93c","heading":"Accessible component contracts","text":"Validate: Test keyboard-only use, focus restoration, accessible names/states, zoom, and a screen reader. Automated accessibility checks catch only part of the contract. Reuse established accessible primitives for complex widgets when their API fits.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-progressive","heading":"Progressive enhancement: start with a working platform contract","text":"Progressive enhancement: start with a working platform contract","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-3bec404c99e5","heading":"Progressive enhancement: start with a working platform contract","text":"Progressive enhancement means making the basic task work with HTML and the server first, then adding JavaScript conveniences. For example, a search form should submit and show results even before React hydrates. JavaScript can then make the same search update in place instead of navigating to a new page.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-26c44902d4e8","heading":"Progressive enhancement: start with a working platform contract","text":"Baseline in this example: the server delivers the form below. Entering “laptop” and pressing Search navigates to /search?q=laptop; that endpoint must return an HTML results page. The input’s name=\"q\" becomes the query parameter. A form that only appears after JavaScript loads does not provide this no-JavaScript baseline.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-efecc847a45e","heading":"Progressive enhancement: start with a working platform contract","text":"\u003cform action=\"/search\" method=\"get\"> \u003clabel htmlFor=\"catalog-query\">Search products\u003c/label> \u003cinput id=\"catalog-query\" name=\"q\" type=\"search\" /> \u003cbutton type=\"submit\">Search\u003c/button> \u003c/form>","kind":"Code"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-87c5b970fce2","heading":"Progressive enhancement: start with a working platform contract","text":"Enhance the same task: once JavaScript is ready, intercept submission, request results asynchronously and update the page without a full navigation. Add loading/error feedback and keep the URL consistent. A failed JavaScript load still leaves the native form usable. Server endpoints must validate input and enforce authorization where required; state-changing forms also need CSRF protection.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-619473afcc9a","heading":"Progressive enhancement: start with a working platform contract","text":"When useful / tradeoff: public search, content navigation and ordinary forms benefit from working during slow or failed JavaScript loading. The cost is supporting and testing both native navigation and enhanced updates against the same server rules. Real links also preserve keyboard navigation, copy-link and open-in-new-tab behavior.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-837893d99ab1","heading":"Progressive enhancement: start with a working platform contract","text":"When not to force it: a canvas editor or live collaborative tool may require JavaScript for its core behavior. Keep navigation accessible and provide clear loading, failure and draft recovery rather than building a second, unusable editor.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-a5daac2c7a4c","heading":"Progressive enhancement: start with a working platform contract","text":"Distinction: SSR and hydration explain HTML delivery and client activation. SSR alone does not make an interaction work without JavaScript; the form/link still needs a working server destination. Graceful degradation starts with the rich experience and adds fallbacks; progressive enhancement starts with the working baseline. Framework form Actions have specific guarantees—check them against the submission behavior you need.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-forms","heading":"Complex forms: fields, validation & asynchronous submission","text":"Complex forms: fields, validation & asynchronous submission","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-bc10980d3dba","heading":"Complex forms: fields, validation & asynchronous submission","text":"A complex form has fields that affect one another, validation rules and a save request that can succeed or fail. Think of registration: email, username, password and confirmation. The form must check the values, submit them and show the result without losing the user’s input.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-form-ownership","heading":"Complex forms: fields, validation & asynchronous submission","text":"Split the responsibilities: the form component coordinates values, cross-field validation and submission. Reusable field components render a label, input and error; sections group related fields with fieldset/legend. A field adapter connects a custom input to the form’s value, change, blur and focus APIs. Here is how the registration flow works:","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-74328cddb250","heading":"Complex forms: fields, validation & asynchronous submission","text":"Collect the values: Native inputs plus FormData are enough for a simple form. Use controlled fields when one field must immediately affect another. For many fields, a form library can track dirty (changed) and touched (visited/blurred) state and dynamic field arrays. Keep one owner for each value; preserve drafts when remote data changes.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-f18f0f02ddab","heading":"Complex forms: fields, validation & asynchronous submission","text":"Check the rules: required and type=\"email\" handle basic browser checks; schema/domain validation checks rules such as matching passwords. Validate again on the server and authorize the operation. Client validation gives faster feedback; it cannot protect the server. Validation does not replace output encoding or HTML sanitization.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-b97a61b6b71c","heading":"Complex forms: fields, validation & asynchronous submission","text":"Check remote conditions: Username availability needs an API request. Debounce the check, cancel obsolete requests and ignore stale responses. Show feedback after blur or a submit attempt rather than reporting errors while the user has barely started. An availability check is advisory; a database unique constraint must still enforce uniqueness when saving.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-138332e5887d","heading":"Complex forms: fields, validation & asynchronous submission","text":"Submit and recover: On submit, validate and enter a pending state while awaiting the server. On success, confirm completion; on validation failure, show field errors; on conflict or network failure, retain values and offer the appropriate correction/retry. Distinguish these states rather than using one loading flag for everything. React Action-based forms can use useActionState and useFormStatus.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-form-field-example","heading":"Complex forms: fields, validation & asynchronous submission","text":"One field in that form: the parent supplies value, onChange and a validation error. This EmailField displays them and connects the error to the input for assistive technology; it does not submit the whole form or call the API.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-ed0104875d55","heading":"Complex forms: fields, validation & asynchronous submission","text":"// A reusable field contract; the form owner supplies validation state. function EmailField({ id, value, onChange, error }) { const errorId = id + '-error'; return ( \u003cdiv> \u003clabel htmlFor={id}>Email\u003c/label> \u003cinput id={id} name=\"email\" type=\"email\" required value={value} onChange={onChange} aria-invalid={error ? true : undefined} aria-describedby={error ? errorId : undefined} /> {error && \u003cp id={errorId}>{error}\u003c/p>} \u003c/div> ); }","kind":"Code"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-33b28ddfad00","heading":"Complex forms: fields, validation & asynchronous submission","text":"Accessible feedback: On failed submission, render an error summary with links to invalid fields and move focus to the summary or first invalid field. Associate inline errors through aria-describedby; announce submission status through a restrained live region. Do not announce every keystroke or rely on color alone.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-3b50d20b5bdc","heading":"Complex forms: fields, validation & asynchronous submission","text":"Complexity and tradeoffs: Use stable domain IDs for dynamic field arrays so reordering preserves field identity. Define validation and draft retention across multi-step forms. A disabled submit button only prevents local repeats; retries and ambiguous network outcomes still need a server-supported idempotency and conflict policy. Aborting the request does not undo a save.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-review","heading":"Review","text":"Review","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-4b4054c92dd5","heading":"Review","text":"Key takeaway: Start with state ownership and accessibility, then choose props, children, compound parts, or a headless hook according to the flexibility callers actually need. See Context + useReducer for coordinating compound parts.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"context-title","heading":"","text":"State Ownership, Context & Data","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-12c0258b7efb","heading":"","text":"Choose the authoritative owner first, including the URL. Model transitions and sharing, then coordinate remote data, drafts, overlapping mutations, and real-time updates.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-22d266e9c9b3","heading":"","text":"Server state vs. client state: choose by ownership","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-d22b571a30fb","heading":"","text":"Hooks, state, Context & stores: compare the right dimensions","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-b9b81b1daf4e","heading":"","text":"Context + reducer vs. Redux Toolkit vs. XState","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e5ae43401d04","heading":"","text":"URL state: navigation is a state owner","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-69668fcfb8f0","heading":"","text":"Unidirectional data flow & derived state","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-9376036c0d74","heading":"","text":"Message design: actions, commands, events & payloads","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-a505255275ef","heading":"","text":"Model local workflows and valid transitions","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-88984cf6c665","heading":"","text":"Same problem, different tools: choose by the pressure","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-bb2219b3510c","heading":"","text":"Share state through Context","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-a1b4094f6865","heading":"","text":"Observer, publish–subscribe & external stores","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-9750620907ed","heading":"","text":"Synchronize remote data and local drafts","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-7cc8248fc8c9","heading":"","text":"Optimistic updates & concurrent mutation conflicts","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-16421a2385c5","heading":"","text":"Real-time updates: WebSockets vs. Server-Sent Events","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ad251098ada8","heading":"","text":"Review","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-server-client","heading":"Server state vs. client state: choose by ownership","text":"Server state vs. client state: choose by ownership","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-05a89860497e","heading":"Server state vs. client state: choose by ownership","text":"Client state is state whose authoritative owner is the running UI: an open dialog, selected tab, or unsaved form draft. Server state is data owned by a remote system: a product, profile, or purchase record. The browser holds a cached representation of server state that can become stale or change independently of this tab.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-1bdf77b995e6","heading":"Server state vs. client state: choose by ownership","text":"Two separate dimensions: Server/client state describes data ownership. Server/Client Components describe component execution boundaries. A Client Component can read and mutate server state; sending fetched data as props does not turn it into client-owned state.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-5c4f083115e1","heading":"Server state vs. client state: choose by ownership","text":"QuestionClient stateServer state","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-a326bc07adc5","heading":"Server state vs. client state: choose by ownership","text":"Who owns the truth?The UI, its parent, or a client store.A remote system; the client has a snapshot.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-94a265229866","heading":"Server state vs. client state: choose by ownership","text":"Typical changesUser interactions and local workflow transitions.Reads, mutations, other users, background jobs, and remote events.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-8df9caf46cc9","heading":"Server state vs. client state: choose by ownership","text":"Primary concernsOwnership, transitions, persistence needs, and subscription scope.Freshness, fetching, errors, retries, invalidation, and reconciliation.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-9a86cb99c3de","heading":"Server state vs. client state: choose by ownership","text":"Typical toolsuseState, useReducer, Context, or a client store.Framework loaders/Server Components, TanStack Query, SWR, or a supported data layer.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-tool-selection","heading":"Server state vs. client state: choose by ownership › When to use which tool","text":"When to use which tool","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-4fb53216bdd1","heading":"Server state vs. client state: choose by ownership › When to use which tool","text":"Local UI state: Start with useState; use useReducer for related transitions. Keep the owner close to its consumers.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-bf51e7af9473","heading":"Server state vs. client state: choose by ownership › When to use which tool","text":"Shared client state: Lift state to a common parent or distribute it through Context. An external store can fit broad, frequent, selectively subscribed updates; sharing alone does not make state server state.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-375458426d0b","heading":"Server state vs. client state: choose by ownership › When to use which tool","text":"Navigation state: Put shareable filters, sorting, and pagination in the URL when refresh, back/forward navigation, or copied links should preserve them. The query result is server state; the selected filter is a client/navigation input.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-f146459bb7d5","heading":"Server state vs. client state: choose by ownership › When to use which tool","text":"Read-mostly page data: A framework loader or Server Component may fetch before rendering and provide route-level revalidation. Do not automatically add a second client cache when the framework already owns the needed data lifecycle.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-de0c9b3fa33a","heading":"Server state vs. client state: choose by ownership › When to use which tool","text":"Interactive remote data: Use a query cache when multiple consumers need remote data, background refresh, mutation coordination, or cache reuse across navigation. A small isolated request can use an effect, but then you own cancellation and race handling plus the remaining loading/error lifecycle.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-tradeoffs","heading":"Server state vs. client state: choose by ownership › Benefits, limitations & alternatives","text":"Benefits, limitations & alternatives","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e807f9f3f85a","heading":"Server state vs. client state: choose by ownership › Benefits, limitations & alternatives","text":"Local state/reducer — benefits: Explicit UI ownership, simple transitions, no remote-cache machinery. Tradeoff: Sharing and persistence require design; these hooks do not provide refetching or invalidation.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-2e99a79220e4","heading":"Server state vs. client state: choose by ownership › Benefits, limitations & alternatives","text":"Context/client store — benefits: Shares client-owned workflows and operations across a subtree. Tradeoff: Provider updates and subscription granularity need attention. Context can distribute fetched data, but does not itself supply a server-state synchronization policy.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c7e2cca196e9","heading":"Server state vs. client state: choose by ownership › Benefits, limitations & alternatives","text":"Query cache — benefits: Shares keyed remote data and provides configurable freshness, retries, in-flight deduplication, and mutation lifecycle hooks. Tradeoff: Adds a dependency and policies for keys, invalidation, memory, and identity changes. It cannot infer all business relationships or make cached data always current.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-bb3e88c6c0c7","heading":"Server state vs. client state: choose by ownership › Benefits, limitations & alternatives","text":"Framework-managed data — benefits: Integrates loading, rendering, navigation, and potentially SSR. Tradeoff: Cache and revalidation semantics depend on the framework; mixed framework/client caches require explicit coordination.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-tool-dimensions","heading":"Hooks, state, Context & stores: compare the right dimensions","text":"Hooks, state, Context & stores: compare the right dimensions","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-tool-dimensions-definition","heading":"Hooks, state, Context & stores: compare the right dimensions","text":"Hooks and state are not alternatives. State is data that changes; hooks are React APIs that access state and other capabilities. useState/useReducer manage local state, useContext reads a distributed value, and a custom hook packages logic. Choose by ownership, lifetime, transitions, and subscription needs—not by the number of components alone.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-28d898d19a0d","heading":"Hooks, state, Context & stores: compare the right dimensions","text":"QuestionUseful comparisonDecision / limitation","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ff8b4d336d91","heading":"Hooks, state, Context & stores: compare the right dimensions","text":"Does a change affect the rendered UI?useState vs. useRefState schedules rendering; refs hold mutable non-render data such as handles. A ref is not an optimization for hiding UI updates.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-473316208a83","heading":"Hooks, state, Context & stores: compare the right dimensions","text":"Are transitions related?useState vs. useReducerUse local state for simple independent changes; a reducer centralizes related rules. Both are local to the owner unless explicitly shared.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-bcf5a30c704b","heading":"Hooks, state, Context & stores: compare the right dimensions","text":"Is the value derivable?Compute during render vs. store another copyDerive first; useMemo only when measured calculation/identity costs justify it. It does not create a second authoritative state owner.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-d41c4495a14b","heading":"Hooks, state, Context & stores: compare the right dimensions","text":"Should several components share one instance?Props/lifted state vs. Context/storeA custom hook called twice normally creates two independent state instances; sharing code is not sharing state.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-7b57115615b7","heading":"Hooks, state, Context & stores: compare the right dimensions","text":"Is the data remotely authoritative?Client store vs. query cache/framework dataChoose remote freshness, invalidation, and reconciliation policies; avoid copying the same server entity into an unrelated store.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-92c926e46958","heading":"Hooks, state, Context & stores: compare the right dimensions","text":"Is the hard part legal transitions?Reducer vs. explicit statechartUse guards and lifecycle modeling when invalid transitions, concurrency, and cancellation dominate the problem.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-43dc7059308c","heading":"Hooks, state, Context & stores: compare the right dimensions","text":"Example: A search page uses local state for an uncommitted input, the URL for committed filters, and a query cache for results. A custom hook can compose those APIs without becoming another source of truth. A global Redux store or statechart is unnecessary unless additional sharing or workflow pressure justifies it.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c56a8d1cce9b","heading":"Hooks, state, Context & stores: compare the right dimensions","text":"Read next: useState, useReducer, useRef, and custom hooks explain their implementation guarantees.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-library-comparison","heading":"Context + reducer vs. Redux Toolkit vs. XState","text":"Context + reducer vs. Redux Toolkit vs. XState","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-library-comparison-definition","heading":"Context + reducer vs. Redux Toolkit vs. XState","text":"These tools emphasize different responsibilities. Context distributes a value through a React subtree. Redux Toolkit is the standard Redux approach to a shared store and event/reducer updates. XState models statecharts and actors with explicit workflow lifecycles. They can coexist when their ownership boundaries are clear.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-fe4eced00218","heading":"Context + reducer vs. Redux Toolkit vs. XState","text":"ApproachUse when / strengthCost / when another choice is clearer","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-f75d274302e0","heading":"Context + reducer vs. Redux Toolkit vs. XState","text":"Local useState/useReducerOne component/subtree owns a modest interaction or workflow.Sharing needs explicit design; no built-in remote cache, external store, or actor orchestration.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-a4eda16596e7","heading":"Context + reducer vs. Redux Toolkit vs. XState","text":"Context + useReducerA scoped feature needs shared transitions with a relatively modest subscription surface. No state-library dependency.Native Context broadcasts provider-value changes to its consumers. Splitting contexts helps; it does not provide built-in property-level selectors or async orchestration.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-d3ec9ef85e53","heading":"Context + reducer vs. Redux Toolkit vs. XState","text":"Redux Toolkit + React ReduxMany independent consumers share client-owned domain data, need selectors, consistent update conventions, middleware, and Redux DevTools.Adds store/slice conventions and global-lifetime risks. Scope providers deliberately; keep non-serializable resources out of ordinary state. A small local modal rarely benefits.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-6f1b34382bf6","heading":"Context + reducer vs. Redux Toolkit vs. XState","text":"XState + @xstate/reactThe problem is valid transitions, guarded events, cancellation, retries, nested/parallel states, and independently owned actors.Adds statechart/actor vocabulary and lifecycle modeling. A simple collection/filter may be clearer as a reducer/store; a machine is not automatically a server-data cache.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ce4e2af315ab","heading":"Context + reducer vs. Redux Toolkit vs. XState","text":"Zustand or another selector storeShared client state needs a small external-store API and selective subscriptions without Redux conventions.Team conventions, side effects, persistence, and transition discipline remain your responsibility. Less ceremony is not an automatic correctness guarantee.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-cde3f44f962c","heading":"Context + reducer vs. Redux Toolkit vs. XState","text":"TanStack Query / SWRRemote data needs keyed caching, deduplication, freshness, refetching, and mutation coordination.Query libraries do not replace client workflow ownership; business invalidation and conflict policies remain explicit.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-5be4365034f0","heading":"Context + reducer vs. Redux Toolkit vs. XState","text":"RTK QueryThe app already uses Redux Toolkit and needs an integrated server-data cache.Use it as the cache owner rather than automatically duplicating the same entities in slices or another query library.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-2c5edfa7152b","heading":"Context + reducer vs. Redux Toolkit vs. XState","text":"Framework loader / Server ComponentRoute/render lifecycle can own initial remote reads and revalidation.Client interactivity may still need a query layer; only add one when lifecycle/freshness requirements justify it.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-xstate-context","heading":"Context + reducer vs. Redux Toolkit vs. XState › Important distinction: XState context is not React Context","text":"Important distinction: XState context is not React Context","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-5f306c010a48","heading":"Context + reducer vs. Redux Toolkit vs. XState › Important distinction: XState context is not React Context","text":"XState’s context is extended data associated with an actor’s state, such as a request or retry counter. React Context is a provider/consumer distribution mechanism. You can provide a stable actor reference through React Context and use selector subscriptions to that actor; this does not make the two concepts interchangeable.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-113a2fc253f2","heading":"Context + reducer vs. Redux Toolkit vs. XState › Important distinction: XState context is not React Context","text":"Capabilities overlap: Redux can represent an FSM with disciplined reducers; XState can store shared data; Context can distribute either a store or actor. Choose the tool whose default model best exposes the dominant risk. Do not claim “Redux cannot do workflows” or “Context is always slow.” Measure render and operational complexity in the actual feature.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-0f36f7b24037","heading":"Context + reducer vs. Redux Toolkit vs. XState › Important distinction: XState context is not React Context","text":"SSR/lifetime: Create request-scoped stores/actors for personalized server rendering and reset/dispose them at the correct session/feature boundary. Persistence, schema migration, cross-tab synchronization, and backend durability are separate contracts. See Context propagation, external-store subscriptions, and the same problems solved in different ways.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-url","heading":"URL state: navigation is a state owner","text":"URL state: navigation is a state owner","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-95c1dd4374bd","heading":"URL state: navigation is a state owner","text":"Use the URL for state that should survive refresh, support copied links, and participate in back/forward navigation: search terms, filters, sort order, pagination, and the selected resource. Keep transient UI such as hover state local. The URL stores the selection; a query cache stores the resulting server data.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-d059a3da62c0","heading":"URL state: navigation is a state owner","text":"Read and validate: Parse URLSearchParams, allowlist sort values, normalize defaults, and validate page numbers. Use the normalized values in query keys so cache identity matches the request.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-7eefd10b5c9f","heading":"URL state: navigation is a state owner","text":"Update through the router: Prefer its search-parameter API for subscriptions, navigation, and SSR integration. Use push for meaningful history entries and replace for refinements that should not flood history. Reset the page when a filter changes.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-90aa6b8552b1","heading":"URL state: navigation is a state owner","text":"One authoritative source: Derive committed filters from the URL. A local input draft is useful while typing, but define when it is committed and how navigation resets it. Two independently synchronized copies invite loops and stale values.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-b28e1fc9a2af","heading":"URL state: navigation is a state owner","text":"Tradeoffs: URLs improve shareability but expose values in history, logs, and potentially referrers. Do not put credentials or sensitive drafts there. Encoding is not encryption.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-f1b1340ca77c","heading":"URL state: navigation is a state owner","text":"Implementation: Read new URLSearchParams(location.search) at a router boundary, normalize inputs, then pass them to the data layer. Bare history.pushState() does not emit popstate; a custom integration must publish its own updates and handle back/forward events. See persistence choices for state that should persist without becoming a link.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-7239403ac77d","heading":"URL state: navigation is a state owner","text":"For History API behavior, pending transitions, focus/scroll restoration, and dirty-form guards, continue with Routing & Navigation. URL ownership and navigation lifecycle solve different parts of the problem.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-unidirectional","heading":"Unidirectional data flow & derived state","text":"Unidirectional data flow & derived state","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-354a45d0b82a","heading":"Unidirectional data flow & derived state","text":"Purpose: Make changes traceable: interaction → handler/action → state transition → render. The rendered view derives from state; it does not maintain an independently synchronized copy of the same truth.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-423530d86ee5","heading":"Unidirectional data flow & derived state","text":"Minimal example · derive instead of copying:","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-4d461d43a32f","heading":"Unidirectional data flow & derived state","text":"function ProductList({ products }) { const [query, setQuery] = useState(''); const visible = products.filter(p => p.name.includes(query)); return \u003c>\u003cinput value={query} onChange={e => setQuery(e.target.value)} /> {visible.map(p => \u003cdiv key={p.id}>{p.name}\u003c/div>)}\u003c/>; }","kind":"Code"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c277c2eabc72","heading":"Unidirectional data flow & derived state","text":"With useState imported from React: input changes query → render derives visible items. There is no second visible-items state to synchronize.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-a2538947e578","heading":"Unidirectional data flow & derived state","text":"Example: Store items and query, then calculate visibleItems = items.filter(matchesQuery) during render. Do not store visibleItems and update it through an effect after every item or query change. That creates temporary inconsistency and extra work.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-b1b5e47132b8","heading":"Unidirectional data flow & derived state","text":"Use when: Designing form ownership, list filters, reducers, or shared stores. Choose one authoritative owner for each fact, and expose explicit change requests. See controlled component contracts and message design.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c4ef21f25ae0","heading":"Unidirectional data flow & derived state","text":"Benefits and tradeoffs: Predictable transitions and fewer synchronization bugs. Expensive derived calculations may need memoization or indexed computation; memoization is an optimization, not a new owner. A form draft intentionally diverges from a server snapshot and is a separate state concept.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-a39db829933c","heading":"Unidirectional data flow & derived state","text":"When not to overengineer: A simple local interaction needs no store or action system. Native uncontrolled forms are valid. Two-way-binding frameworks can still have explicit ownership; the problem is ambiguous or duplicated ownership, not the presence of a binding API. Avoid using effects to synchronize values that can be derived directly.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-message-design","heading":"Message design: actions, commands, events & payloads","text":"Message design: actions, commands, events & payloads","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-8810781e8509","heading":"Message design: actions, commands, events & payloads","text":"These are message-design concepts, not one formal design pattern. They appear in reducers, state machines, domain-driven design (DDD), and event-driven systems. The useful distinction is between intent and fact; the same JavaScript object shape can represent either.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-message-parts","heading":"Message design: actions, commands, events & payloads › What each part means","text":"What each part means","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-2b59efe1fe8e","heading":"Message design: actions, commands, events & payloads › What each part means","text":"TermResponsibilityExample","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-3f314a81d5c6","heading":"Message design: actions, commands, events & payloads › What each part means","text":"CommandRequests an operation. A handler validates it, checks permissions, and attempts the work. It can be rejected.CreateOrder: please create an order.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-651e1f0ae371","heading":"Message design: actions, commands, events & payloads › What each part means","text":"EventDescribes an occurrence. A domain event records a business fact; other consumers may react to it.OrderCreated: an order was successfully created.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-651c73ec82e7","heading":"Message design: actions, commands, events & payloads › What each part means","text":"ActionA message accepted by a state-management API. In Redux, a plain action is an object with a string type. Its meaning can be command-like or event-like.{ type: 'orders/orderCreated', payload: order } represents a fact as a Redux action.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-751135e2d9d9","heading":"Message design: actions, commands, events & payloads › What each part means","text":"PayloadThe data needed to process or understand a message, separate from its type and metadata. It is not an operation by itself.A creation command carries product ID and quantity; the resulting event carries the saved order and its assigned ID.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-695b56715fc1","heading":"Message design: actions, commands, events & payloads › What each part means","text":"Type and metadata: The type identifies what the message means. Optional metadata can carry a request ID, correlation ID, timestamp, or schema version. payload is a common convention, not a JavaScript requirement: useReducer accepts any action shape you design, and the state-machine example uses top-level fields. An action creator simply constructs an action; dispatch submits it to the store or reducer integration.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-message-flow","heading":"Message design: actions, commands, events & payloads › How they work together","text":"How they work together","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-340937592002","heading":"Message design: actions, commands, events & payloads › How they work together","text":"Create an order: intent → work → fact → UI state User submits the formThe UI constructs a CreateOrder command with productId and quantity as its payload. The command handler attempts the operationThe handler sends the request. The server validates input, authorizes access, and applies the business rules. Success produces a confirmed factThe server returns the saved order. The frontend represents that confirmation as an orders/orderCreated action whose payload is the order. The reducer updates the UI modelA pure state transition stores the confirmed order. React renders the confirmation UI. On rejection or network failure, report the failed attempt; do not claim OrderCreated. This example uses local action dispatch, not a message broker or durable domain-event publication.","kind":"Diagram"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-message-example","heading":"Message design: actions, commands, events & payloads › Example: keep side effects outside the reducer","text":"Example: keep side effects outside the reducer","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-60490760e6fd","heading":"Message design: actions, commands, events & payloads › Example: keep side effects outside the reducer","text":"The example assumes one in-flight submission and starts with { status: 'idle', order: null, error: null }. The handler owns the asynchronous work; the reducer only derives state from the resulting actions.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-610adb883623","heading":"Message design: actions, commands, events & payloads › Example: keep side effects outside the reducer","text":"// Message design example: a command handler performs the side effect. async function handleCreateOrder(command, dispatch) { if (command.type !== 'CreateOrder') throw new Error('Unsupported command'); dispatch({ type: 'orders/submissionStarted' }); try { const response = await fetch('/api/orders', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(command.payload) }); if (!response.ok) throw new Error('Order could not be confirmed'); const order = await response.json(); // API returns the saved order. dispatch({ type: 'orders/orderCreated', payload: order }); } catch (error) { dispatch({ type: 'orders/submissionFailed', payload: { message: error.message } }); } } // A pure reducer consumes actions; it never performs the HTTP request. function orderReducer(state, action) { switch (action.type) { case 'orders/submissionStarted': return { ...state, status: 'submitting', error: null }; case 'orders/orderCreated': return { ...state, status: 'success', order: action.payload }; case 'orders/submissionFailed': return { ...state, status: 'error', error: action.payload.message }; default: return state; } } // From a submit handler; dispatch comes from useReducer or a Redux store. handleCreateOrder({ type: 'CreateOrder', payload: { productId: 'book-42', quantity: 1 } }, dispatch);","kind":"Code"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-9446cc781dae","heading":"Message design: actions, commands, events & payloads › Example: keep side effects outside the reducer","text":"Command payload: The requested product and quantity express what the user wants. The server still validates them and derives trusted values such as price and ownership.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-5001da5697e2","heading":"Message design: actions, commands, events & payloads › Example: keep side effects outside the reducer","text":"Event-like action payload: The confirmed order represents what the server accepted. orders/orderCreated is both a Redux-style action and an event-like message; these categories are not mutually exclusive.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-015c3376ef04","heading":"Message design: actions, commands, events & payloads › Example: keep side effects outside the reducer","text":"Failure semantics: A failed response means the client could not confirm success. A connection loss does not prove that the server did not create the order. Preserve the draft and use the idempotency and reconciliation policy before retrying.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-fbaef9e1b7f1","heading":"Message design: actions, commands, events & payloads › Example: keep side effects outside the reducer","text":"Production integration: For shared server data, use the existing query-cache mutation lifecycle rather than maintaining a second copy in a reducer. The reducer here makes message roles visible; it is not a replacement data layer.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-message-tradeoffs","heading":"Message design: actions, commands, events & payloads › When this distinction helps—and when to keep it simple","text":"When this distinction helps—and when to keep it simple","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c5dd2970a217","heading":"Message design: actions, commands, events & payloads › When this distinction helps—and when to keep it simple","text":"Use it when asynchronous workflows have clear requested, pending, confirmed, and failed outcomes; when several consumers react to one fact; or when a state machine needs explicit transition inputs. Intent/fact naming makes debugging and responsibilities clearer. Tradeoff: Separate message types, handlers, and metadata add code and contracts to maintain. A local toggle may need only setOpen; a command does not require a command bus, and an event does not require a broker.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-03497a95e1df","heading":"Message design: actions, commands, events & payloads › When this distinction helps—and when to keep it simple","text":"Naming: Commands usually use imperative names (CreateOrder); events use past tense (OrderCreated). Naming helps communicate intent but does not enforce correctness.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-8d6684558f9a","heading":"Message design: actions, commands, events & payloads › When this distinction helps—and when to keep it simple","text":"Delivery is a separate contract: Local dispatch is not durable publication or guaranteed delivery. Network events can be duplicated or missed; see real-time synchronization and recovery.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-6d753faa614f","heading":"Message design: actions, commands, events & payloads › When this distinction helps—and when to keep it simple","text":"Related architectures: CQRS separates commands (writes) from queries (reads); it does not inherently require separate databases or event sourcing. Event sourcing persists events as the source of truth. Dispatching event-like actions in React or Redux does not automatically implement either architecture.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-2554ac54d309","heading":"Message design: actions, commands, events & payloads › When this distinction helps—and when to keep it simple","text":"React terminology: React Actions, such as form Actions and useActionState, are functions participating in an update workflow. They are distinct from the message objects discussed here.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-97befee1b2eb","heading":"Message design: actions, commands, events & payloads › When this distinction helps—and when to keep it simple","text":"Explanation: A command expresses intent, an event records an occurrence, an action is the state-management API’s message, and a payload carries the associated data. I perform side effects in a handler or data layer and keep the reducer pure. I choose explicit messages when they clarify a workflow, without introducing unnecessary messaging infrastructure.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-local-workflows","heading":"Model local workflows and valid transitions","text":"Model local workflows and valid transitions","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"context-machines","heading":"Model local workflows and valid transitions › State machines: model valid transitions","text":"State machines: model valid transitions","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-76440fc6a80c","heading":"Model local workflows and valid transitions › State machines: model valid transitions","text":"A finite state machine (FSM) defines states, events, and permitted transitions. Its events describe transition inputs; see commands, events, and action messages for the naming distinction. This avoids contradictory boolean combinations such as isLoading and isSuccess both being true. A reducer can implement an FSM, but a reducer is not automatically a state machine.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-f9ca7bfb4310","heading":"Model local workflows and valid transitions › State machines: model valid transitions","text":"type SearchState = | { status: 'idle' } | { status: 'loading'; requestId: number } | { status: 'success'; results: string[] } | { status: 'error'; message: string }; type SearchEvent = | { type: 'started'; requestId: number } | { type: 'resolved'; requestId: number; results: string[] } | { type: 'rejected'; requestId: number; message: string } | { type: 'reset' }; function searchReducer(state: SearchState, event: SearchEvent): SearchState { if (event.type === 'reset') return { status: 'idle' }; if (event.type === 'started') { return { status: 'loading', requestId: event.requestId }; } // Completion events only apply to the active request. if (state.status !== 'loading' || state.requestId !== event.requestId) { return state; } if (event.type === 'resolved') { return { status: 'success', results: event.results }; } return { status: 'error', message: event.message }; }","kind":"Code"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-db2d6ee022ae","heading":"Model local workflows and valid transitions › State machines: model valid transitions","text":"Discriminated unions make each state’s data explicit. The request-ID check is a transition guard that ignores stale completions. Start requests in an event handler or effect, then dispatch completion events; never fetch inside the reducer. Combine this with request cancellation to reduce wasted work.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c02f0d0315c0","heading":"Model local workflows and valid transitions › State machines: model valid transitions","text":"Tradeoff: An explicit transition model helps async workflows and multi-step UI. For hierarchical states, parallel states, or complex effects, a dedicated state-machine library can be clearer than an expanding reducer. For a simple toggle, local useState is usually enough.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-state-pattern","heading":"Model local workflows and valid transitions › State pattern vs. finite state machine vs. Strategy","text":"State pattern vs. finite state machine vs. Strategy","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-0554d3ff0883","heading":"Model local workflows and valid transitions › State pattern vs. finite state machine vs. Strategy","text":"Purpose: The classic State pattern delegates state-dependent behavior to state-specific objects or functions. An FSM explicitly defines valid states and transitions; the State pattern is an implementation technique and does not by itself guarantee a complete transition model.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-2fde00bb9409","heading":"Model local workflows and valid transitions › State pattern vs. finite state machine vs. Strategy","text":"Example: An upload’s idle state accepts start; uploading accepts pause/cancel; completed accepts neither. For a few states, a discriminated union and reducer make these rules visible. State objects can help if each state owns substantial behavior, but do not trigger subscriptions or requests inside a React reducer.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e7dbbbdc09da","heading":"Model local workflows and valid transitions › State pattern vs. finite state machine vs. Strategy","text":"Use when: Different lifecycle states permit different operations. Benefits: Replaces scattered state checks with localized behavior. Tradeoffs: More objects and indirection; transitions become difficult to audit if spread across implementations.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e028b0585dea","heading":"Model local workflows and valid transitions › State pattern vs. finite state machine vs. Strategy","text":"When not to use: Use a boolean for one independent toggle, a reducer for a modest explicit workflow, or a statechart library for hierarchical/parallel states and complex transitions. Strategy selects an algorithm independently of lifecycle; State selects behavior because the lifecycle changed.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-16eb343bd9ff","heading":"Model local workflows and valid transitions › State pattern vs. finite state machine vs. Strategy","text":"Library choice: The reducer above is a modest FSM. For a side-by-side version using Redux Toolkit and XState, see the same asynchronous search problem. Model complexity, not the presence of async code alone, should drive the choice.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-tool-scenarios","heading":"Same problem, different tools: choose by the pressure","text":"Same problem, different tools: choose by the pressure","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-tool-scenarios-definition","heading":"Same problem, different tools: choose by the pressure","text":"Keep the product behavior fixed while comparing solutions. A library earns its cost when it makes ownership, transitions, failure handling, or subscriptions easier to reason about.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-404f6bc3c6f0","heading":"Same problem, different tools: choose by the pressure","text":"ProblemReasonable starting pointWhen to change / why","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-99bae07b1faa","heading":"Same problem, different tools: choose by the pressure","text":"Shared theme or localeScoped React Context with a stable value.A Redux store can work but adds ceremony for little benefit; there is no complex workflow needing a statechart.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-88adfbcdaa46","heading":"Same problem, different tools: choose by the pressure","text":"Small checkout panel: edit → submit → success/errorA local reducer/discriminated union; Context only if distant descendants need the same owner.Use XState when shipping/payment steps, cancellation, timed recovery, or parallel verification make transitions difficult to audit.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-59c9808e4089","heading":"Same problem, different tools: choose by the pressure","text":"Many screens edit a shared client-owned workspaceRedux Toolkit or a lightweight selector store, with focused selectors.Context + reducers can work, but frequent unrelated updates and provider coupling may justify external-store subscriptions. Redux adds standardized events/tooling; a smaller store trades convention for flexibility.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-23c2e82d17f0","heading":"Same problem, different tools: choose by the pressure","text":"Remote product list and cached detailFramework data layer, TanStack Query, or RTK Query in a Redux app.A plain slice/reducer requires implementing freshness/deduplication/reconciliation yourself; XState may orchestrate a workflow but should not create a second independent entity cache.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e99f6fadfe92","heading":"Same problem, different tools: choose by the pressure","text":"Upload flow: choose → upload; pause/cancel/retry; then processXState when parallel/lifecycle rules are substantial; a reducer for a small explicit FSM.Context distributes the owner but does not enforce valid events; Redux requires explicitly coding the same transition/effect contracts.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-88ef1ffef5fa","heading":"Same problem, different tools: choose by the pressure","text":"Chat applicationLocal draft + URL selection + authoritative message cache; optionally a reconnect actor.Use a shared store for actual cross-feature client state, or a statechart for connection lifecycle. Putting every message in a reconnect machine couples data volume and workflow unnecessarily.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-search-implementations","heading":"Same problem, different tools: choose by the pressure › One asynchronous search: reducer, Redux Toolkit, or XState?","text":"One asynchronous search: reducer, Redux Toolkit, or XState?","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-41b3c711590a","heading":"Same problem, different tools: choose by the pressure › One asynchronous search: reducer, Redux Toolkit, or XState?","text":"Fixed contract: Start a search, show loading, accept only the active result, support failure, and avoid stale completion. The existing local reducer example implements these guards explicitly. Context can share that reducer owner without changing the rules. If the problem is primarily remote result caching, start with a query cache instead of either implementation below.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-6e658c895d37","heading":"Same problem, different tools: choose by the pressure › One asynchronous search: reducer, Redux Toolkit, or XState?","text":"// Redux Toolkit: useful when this workflow belongs in an existing shared store. import { createAsyncThunk, createSlice } from '@reduxjs/toolkit'; export const search = createAsyncThunk\u003cstring[], string>( 'search/run', async (query, { signal }) => { const response = await fetch(`/api/search?q=${encodeURIComponent(query)}`, { signal }); if (!response.ok) throw new Error('Search failed'); return response.json(); // Validate the response at the real API boundary. } ); const initialState: { status: 'idle' | 'loading' | 'success' | 'error'; requestId?: string; results: string[]; } = { status: 'idle', results: [] }; export const searchSlice = createSlice({ name: 'search', initialState, reducers: {}, extraReducers: builder => builder .addCase(search.pending, (state, action) => { state.status = 'loading'; state.requestId = action.meta.requestId; }) .addCase(search.fulfilled, (state, action) => { if (state.requestId !== action.meta.requestId) return; state.status = 'success'; state.results = action.payload; state.requestId = undefined; }) .addCase(search.rejected, (state, action) => { if (state.requestId !== action.meta.requestId) return; state.status = action.meta.aborted ? 'idle' : 'error'; state.requestId = undefined; }) }); // Add searchSlice.reducer to configureStore; dispatch(search(query)). // New dispatches do not automatically abort old thunks: abort their returned // promise when desired. requestId guards protect correctness independently.","kind":"Code"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-b59b32cbae7c","heading":"Same problem, different tools: choose by the pressure › One asynchronous search: reducer, Redux Toolkit, or XState?","text":"Redux tradeoff: Selectors and DevTools integrate this into a shared application model. createAsyncThunk supplies lifecycle actions, but the latest-request policy, transitions, and cancellation ownership remain explicit. Immer-backed reducers permit the apparent mutations above while producing immutable store updates. Do not store AbortController or a promise inside ordinary Redux state.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-087540eb1e19","heading":"Same problem, different tools: choose by the pressure › One asynchronous search: reducer, Redux Toolkit, or XState?","text":"// XState v5: useful when the interaction lifecycle is the main model. import { setup, assign, fromPromise } from 'xstate'; export const searchMachine = setup({ types: { context: {} as { query: string; results: string[] }, events: {} as { type: 'SEARCH'; query: string } | { type: 'CANCEL' } }, actors: { load: fromPromise(async ({ input, signal }: { input: string; signal: AbortSignal }) => { const response = await fetch(`/api/search?q=${encodeURIComponent(input)}`, { signal }); if (!response.ok) throw new Error('Search failed'); return response.json() as Promise\u003cstring[]>; // Real boundary needs validation. }) } }).createMachine({ id: 'search', initial: 'idle', context: { query: '', results: [] }, on: { SEARCH: { target: '.loading', reenter: true, actions: assign({ query: ({ event }) => event.query }) }, CANCEL: { target: '.idle' } }, states: { idle: {}, loading: { invoke: { src: 'load', input: ({ context }) => context.query, onDone: { target: 'success', actions: assign({ results: ({ event }) => event.output }) }, onError: { target: 'error' } } }, success: {}, error: {} } }); // With @xstate/react: create the owner using useActorRef(searchMachine), // select snapshots with useSelector, and actorRef.send({ type: 'SEARCH', query }).","kind":"Code"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ee07899ce058","heading":"Same problem, different tools: choose by the pressure › One asynchronous search: reducer, Redux Toolkit, or XState?","text":"XState tradeoff: Leaving/re-entering loading stops the old invoked promise actor, so its result is no longer applied; passing its AbortSignal also cancels the fetch where supported. It does not guarantee that server work stops. Explicit states and invoked actors make the lifecycle visible, at the cost of additional concepts for this small case. Timed, hierarchical, or parallel behavior is where that model often earns more value.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-895a8e30e9bc","heading":"Same problem, different tools: choose by the pressure › One asynchronous search: reducer, Redux Toolkit, or XState?","text":"React integration: Own the reducer/store/actor at the intended feature boundary. Creating one actor in every leaf hook produces independent workflows, just as separate useReducer calls do. Subscribe through the library’s React integration rather than reading mutable snapshots without subscriptions.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-2ec4403f1d56","heading":"Same problem, different tools: choose by the pressure › One asynchronous search: reducer, Redux Toolkit, or XState?","text":"Recommendation: “I would use the query cache for remote results, local state for the input, and a reducer only if the interaction has meaningful transitions. I would choose Redux if shared client-domain state and conventions dominate, or XState if workflow/lifecycle complexity dominates. Context can distribute whichever owner the feature needs.”","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"context-sharing","heading":"Share state through Context","text":"Share state through Context","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-131463f76ed8","heading":"Share state through Context","text":"Context distributes values; it does not define state transitions. useReducer centralizes transitions, while a provider makes state and operations available to a subtree. Keep local state local; introduce shared state only when multiple consumers need the same source of truth. Start with controlled vs. uncontrolled state ownership when designing a reusable component.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"context-reducer","heading":"Share state through Context › Context + useReducer: separate state, actions & dispatch","text":"Context + useReducer: separate state, actions & dispatch","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-d26ec75ce688","heading":"Share state through Context › Context + useReducer: separate state, actions & dispatch","text":"For hook selection and lazy initialization, see useState versus useReducer. A reducer is a pure function (state, action) => nextState. Return immutable updates and perform side effects outside it. Keep domain actions meaningful, such as itemAdded, rather than exposing arbitrary state mutation. The message-design example separates a command handler’s side effects from event-like actions consumed by a pure reducer.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e0753a753847","heading":"Share state through Context › Context + useReducer: separate state, actions & dispatch","text":"import { createContext, useContext, useReducer, useMemo, useCallback } from 'react'; const StateContext = createContext(undefined); const DispatchContext = createContext(undefined); const ActionsContext = createContext(undefined); function reducer(state, action) { switch (action.type) { case 'increment': return { count: state.count + 1 }; case 'reset': return { count: 0 }; default: throw new Error('Unknown action: ' + action.type); } } function CounterProvider({ children }) { const [state, dispatch] = useReducer(reducer, { count: 0 }); const increment = useCallback(() => dispatch({ type: 'increment' }), [dispatch]); const reset = useCallback(() => dispatch({ type: 'reset' }), [dispatch]); const actions = useMemo(() => ({ increment, reset }), [increment, reset]); return ( \u003cDispatchContext.Provider value={dispatch}> \u003cActionsContext.Provider value={actions}> \u003cStateContext.Provider value={state}> {children} \u003c/StateContext.Provider> \u003c/ActionsContext.Provider> \u003c/DispatchContext.Provider> ); } function useCounterState() { const state = useContext(StateContext); if (state === undefined) throw new Error('CounterProvider is required'); return state; } function useCounterActions() { const actions = useContext(ActionsContext); if (actions === undefined) throw new Error('CounterProvider is required'); return actions; } function useCounterDispatch() { const dispatch = useContext(DispatchContext); if (dispatch === undefined) throw new Error('CounterProvider is required'); return dispatch; }","kind":"Code"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-75f9e074f181","heading":"Share state through Context › Context + useReducer: separate state, actions & dispatch","text":"State context: Read current data; these consumers update when the state value changes.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-cb33382b2efa","heading":"Share state through Context › Context + useReducer: separate state, actions & dispatch","text":"Actions context: Expose stable domain operations that hide action-object structure. A button that only calls increment() need not subscribe to count changes.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-d9ffd551020c","heading":"Share state through Context › Context + useReducer: separate state, actions & dispatch","text":"Dispatch context: Expose raw dispatch when consumers genuinely need it. React guarantees a stable dispatch identity. Often state plus actions or state plus dispatch is sufficient; three contexts are an option, not a requirement.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-44a60ffb92c0","heading":"Share state through Context › Context + useReducer: separate state, actions & dispatch","text":"Custom consumer hooks: Centralize provider checks and expose a domain API. A hook that reads state and then returns only actions still subscribes its caller to state; keep subscriptions separate.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"context-propagation","heading":"Share state through Context › Context propagation & referential stability","text":"Context propagation & referential stability","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-90284adf6d35","heading":"Share state through Context › Context propagation & referential stability","text":"React compares the provider’s previous and next value using Object.is. When it changes, consumers reading that context receive an update, even through React.memo. Reading only state.count from a large context does not create a property-level subscription.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-71de5b114281","heading":"Share state through Context › Context propagation & referential stability","text":"Referential stability: An object literal or inline function creates a new reference on each render. A provider using value={{ state, dispatch }} therefore changes identity whenever that object is recreated.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-cca0e8e5e9c5","heading":"Share state through Context › Context propagation & referential stability","text":"Stable values: useMemo stabilizes a wrapper object when its dependencies are unchanged; useCallback stabilizes a function. Include all reactive dependencies to avoid stale closures. A callback that depends on changing state must change unless it is restructured safely.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e983a3fd42e4","heading":"Share state through Context › Context propagation & referential stability","text":"Why separation helps: Stable action/dispatch contexts do not broadcast state changes to action-only consumers. Splitting unrelated state domains also reduces the subscription scope.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-8e2024bf0aae","heading":"Share state through Context › Context propagation & referential stability","text":"What separation cannot guarantee: Consumers can still render because their own state or props changed, or their ancestor rendered. Context separation removes a particular update source; it does not block ordinary parent-driven rendering. Use the React render analysis workflow to verify the result.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"context-selectors","heading":"Share state through Context › Context selectors & subscription granularity","text":"Context selectors & subscription granularity","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-159790a373b5","heading":"Share state through Context › Context selectors & subscription granularity","text":"A selector derives the slice a consumer needs. Native useContext does not subscribe selectively: a custom hook returning useContext(Context).count still subscribes to the entire context value.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e7f8d3701626","heading":"Share state through Context › Context selectors & subscription granularity","text":"use-context-selector is a third-party library that supports selected-value subscriptions. Create the context using the library’s createContext, then consume it with its selector hook:","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-771f9f945c9d","heading":"Share state through Context › Context selectors & subscription granularity","text":"import { createContext, useContextSelector } from 'use-context-selector'; // Alternative to the native StateContext in the earlier example. const SelectableStateContext = createContext({ count: 0, query: '' }); function CountLabel() { const count = useContextSelector(SelectableStateContext, state => state.count); return \u003cspan>{count}\u003c/span>; }","kind":"Code"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-0680cc6ff0ef","heading":"Share state through Context › Context selectors & subscription granularity","text":"A query-only update need not trigger a selector subscription update when the selected count remains equal. Selectors should be pure and return referentially stable results for unchanged inputs; returning a fresh object defeats this optimization. Parent-driven renders remain possible. For frequent updates or complex subscriptions, consider an external store with selector support and React’s useSyncExternalStore integration. See Observer and external-store contracts for snapshots, ownership, and tradeoffs.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-observer","heading":"Observer, publish–subscribe & external stores","text":"Observer, publish–subscribe & external stores","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-a611de5360fb","heading":"Observer, publish–subscribe & external stores","text":"Purpose: Notify consumers when a producer changes without hard-coding all consumers into its update logic. Observer usually means subscribing directly to a subject. Publish–subscribe introduces a topic/channel or broker between publishers and subscribers; terminology varies, so describe the actual topology.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-b1c872de1d9f","heading":"Observer, publish–subscribe & external stores","text":"Minimal example · subscribe and unsubscribe:","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ad0acad2a441","heading":"Observer, publish–subscribe & external stores","text":"// Observer: subscribe directly to a store (API is illustrative). const unsubscribe = store.subscribe(() => render(store.getSnapshot())); store.setState(nextState); // Notifies subscribers. unsubscribe(); // Pub/sub: a topic routes events to independent subscribers. const stop = bus.subscribe('order.created', showNotification); bus.publish('order.created', { orderId: 'o1' }); stop();","kind":"Code"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-a44226a17a37","heading":"Observer, publish–subscribe & external stores","text":"The store/bus implementations define delivery and error behavior. In React, connect an external store through useSyncExternalStore rather than manually invoking a renderer.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-6e4b61377f5c","heading":"Observer, publish–subscribe & external stores","text":"Examples: A store maintains listeners through subscribe(listener) and returns an unsubscribe function. A local event bus publishes cart/itemAdded to independent analytics and notification consumers. Network pub/sub adds serialization, authorization, and delivery/recovery concerns; a local bus does not supply those guarantees.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-419f8a00c414","heading":"Observer, publish–subscribe & external stores","text":"Use when: Several independent consumers react to a change, or an external data source needs React subscriptions. For shared state, keep a source-of-truth store and expose snapshots; use notifications to announce changes, not as the only record of current state.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c4cfa017f88b","heading":"Observer, publish–subscribe & external stores","text":"React integration: useSyncExternalStore connects a subscription and a stable snapshot reader to React. Return an immutable cached snapshot while data is unchanged, subscribe with an unsubscribe contract, and provide an appropriate server snapshot for SSR. Use selector-capable integrations for slice subscriptions; returning a new object on every snapshot read can cause repeated rendering. React’s protocol helps prevent tearing—components displaying inconsistent versions of the same external store.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-3c32ee56eee1","heading":"Observer, publish–subscribe & external stores","text":"Benefits and tradeoffs: Decouples producers from consumers, but hidden subscriptions obscure execution order and resource ownership. A listener failure or synchronous reentrant publication needs a defined policy; an event bus is not a transaction. Unsubscribe on disposal and bound buffered work.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-9eff84cad0bf","heading":"Observer, publish–subscribe & external stores","text":"When not to use: Prefer props/callbacks for a parent–child interaction, Context for scoped value distribution, and a query cache for server state. Avoid using a global event bus to coordinate a workflow whose steps and errors should be explicit in one handler. Unlike events, commands represent work that needs a responsible handler.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-0a2aecf051bd","heading":"Observer, publish–subscribe & external stores","text":"Compare: Native Context subscribes consumers to provider value changes; selectors or external stores can provide finer granularity. Browser observers are specialized platform subscriptions, not general state stores; see Intersection Observer. See resource ownership for cleanup and WebSockets/SSE for remote delivery.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-remote-data","heading":"Synchronize remote data and local drafts","text":"Synchronize remote data and local drafts","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-query-lifecycle","heading":"Synchronize remote data and local drafts › Server-state lifecycle: read → mutate → reconcile","text":"Server-state lifecycle: read → mutate → reconcile","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-23483bfd5fb4","heading":"Synchronize remote data and local drafts › Server-state lifecycle: read → mutate → reconcile","text":"Identify the resource: A query key includes the resource and every input that affects its result, including relevant tenant/user scope and filters. Keys identify cached representations; they are not authorization checks.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-fc7b47b5c7ee","heading":"Synchronize remote data and local drafts › Server-state lifecycle: read → mutate → reconcile","text":"Define freshness: In TanStack Query v5, staleTime describes how long cached data is considered fresh. Stale does not mean deleted: it may be displayed while eligible triggers refetch. gcTime controls retention after the query becomes inactive; it is a separate concern.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-211fd6da0266","heading":"Synchronize remote data and local drafts › Server-state lifecycle: read → mutate → reconcile","text":"Perform a mutation: Send the command to the server and expose pending/error UI. For confirmation-first behavior, keep the old value until success; for speculative behavior, follow the optimistic UI contract.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-eb1be615add9","heading":"Synchronize remote data and local drafts › Server-state lifecycle: read → mutate → reconcile","text":"Reconcile the cache: Write a complete authoritative response into its detail entry, or invalidate affected query keys. Invalidation marks matching queries stale and normally refetches active matches; it does not discover related lists automatically or fetch every inactive entry immediately.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e588d1600e88","heading":"Synchronize remote data and local drafts › Server-state lifecycle: read → mutate → reconcile","text":"Handle identity and concurrency: Clear/scope sensitive caches when sessions change. Guard obsolete responses; overlapping writes may need version checks or a conflict policy on the server. A stale-time setting is not a distributed consistency guarantee.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-implementation","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"Implementation: local UI state + a remote query cache","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-0e68f248628e","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"This client-rendered example uses TanStack Query v5. It keeps the panel’s expanded state local and the product in one shared query cache. It assumes the API handles authentication, authorization, input validation, and applicable CSRF defenses; the cache does not replace those checks.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-3624d3b18291","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"// Client-side React application; TanStack Query v5. import { useState } from 'react'; import { QueryClient, QueryClientProvider, useQuery, useMutation, useQueryClient } from '@tanstack/react-query'; const queryClient = new QueryClient(); // One stable cache for this client app. async function readJson(response) { if (!response.ok) throw new Error('HTTP ' + response.status); return response.json(); } function ProductPanel({ tenantId, productId }) { const [expanded, setExpanded] = useState(false); // Client state. const cache = useQueryClient(); const key = ['product', tenantId, productId]; const url = '/api/tenants/' + encodeURIComponent(tenantId) + '/products/' + encodeURIComponent(productId); const product = useQuery({ queryKey: key, queryFn: ({ signal }) => fetch(url, { signal }).then(readJson), staleTime: 30_000 }); const favorite = useMutation({ mutationFn: nextValue => fetch(url + '/favorite', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ favorite: nextValue }) }).then(readJson), // API returns the complete, confirmed product. onMutate: () => cache.cancelQueries({ queryKey: key, exact: true }), onSuccess: saved => { cache.setQueryData(key, saved); return cache.invalidateQueries({ queryKey: ['products', tenantId] }); } }); if (product.isPending) return \u003cp role=\"status\">Loading product…\u003c/p>; if (product.isError && !product.data) return \u003cp role=\"alert\">Cannot load product.\u003c/p>; return ( \u003csection> \u003ch2>{product.data.name}\u003c/h2> \u003cbutton aria-expanded={expanded} onClick={() => setExpanded(open => !open)}> {expanded ? 'Hide details' : 'Show details'} \u003c/button> {expanded && \u003cp>{product.data.description}\u003c/p>} \u003cbutton disabled={favorite.isPending} onClick={() => favorite.mutate(!product.data.favorite)}> {favorite.isPending ? 'Saving…' : product.data.favorite ? 'Unfavorite' : 'Favorite'} \u003c/button> {favorite.isError && \u003cp role=\"alert\">Change failed. Please retry.\u003c/p>} \u003c/section> ); } function App() { // In a real app these come from validated session and route data. return ( \u003cQueryClientProvider client={queryClient}> \u003cProductPanel tenantId=\"acme\" productId=\"42\" /> \u003c/QueryClientProvider> ); }","kind":"Code"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-8626af223757","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"Client ownership: expanded belongs only to this panel; it does not need to travel through the server or global Context.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c749f6f29aee","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"Server ownership: product.data stays in the query cache. The query key isolates this tenant/resource representation; staleTime is an explicit freshness choice, not a universal recommendation.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-45c1c2c53b7f","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"Cancellation: The query function consumes the provided AbortSignal. Before the mutation starts, cancelQueries stops an older detail fetch from overwriting the confirmed result later.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-06ec25a2cfba","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"Mutation reconciliation: Success updates the detail entry and invalidates separately keyed product lists. Returning the invalidation Promise keeps the mutation pending through that step. Other related keys still need an explicit policy.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-57ec0837ee60","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"Cache lifetime: A module-level client is suitable for this single client app. For SSR, create/isolate caches per request and follow the framework’s dehydration/hydration integration; never share personalized request data through a process-global cache.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-72d18053590c","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"Failure handling: Initial read failures and mutation failures have separate UI. A full product should also surface background-refresh failures without unnecessarily discarding already-visible data.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-form-drafts","heading":"Synchronize remote data and local drafts › Forms: server snapshot + client-owned draft","text":"Forms: server snapshot + client-owned draft","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ee25ccc5a508","heading":"Synchronize remote data and local drafts › Forms: server snapshot + client-owned draft","text":"A fetched profile is server state; editing its name creates a client-owned draft. Initializing a draft from fetched data can be intentional. Blindly copying every refetch into the form with an effect can overwrite unsaved edits.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ccb95a95c73a","heading":"Synchronize remote data and local drafts › Forms: server snapshot + client-owned draft","text":"Initialize deliberately: Mount the editor after the resource loads. Key it by resource identity if changing records should reset the draft. Changing the key on every server version would also discard edits, so only do that under an explicit reset policy.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-640e6e93d6dd","heading":"Synchronize remote data and local drafts › Forms: server snapshot + client-owned draft","text":"Handle remote changes: Track dirty fields. Keep edits, offer reload/reset, or merge untouched fields when a background update arrives; do not silently replace dirty values.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-48970b226fdf","heading":"Synchronize remote data and local drafts › Forms: server snapshot + client-owned draft","text":"Save and reconcile: Submit the draft, handle validation/conflict errors, update or invalidate the server cache, and reset the draft to the accepted response if that is the intended UX. For conflicting edits, use the server version/ETag precondition and conflict policy.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-480fb6f9d856","heading":"Synchronize remote data and local drafts › Forms: server snapshot + client-owned draft","text":"GraphQL changes the request/schema contract, not server-state ownership. See normalized caches and mutation reconciliation for the GraphQL client choices.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-mutation-conflicts","heading":"Optimistic updates & concurrent mutation conflicts","text":"Optimistic updates & concurrent mutation conflicts","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-2a684abeaf54","heading":"Optimistic updates & concurrent mutation conflicts","text":"An optimistic update displays the expected result before the server confirms it. It improves perceived responsiveness for reversible, predictable operations such as a favorite toggle. For payments, scarce inventory, or ambiguous outcomes, prefer a pending state and authoritative confirmation. useOptimistic models temporary UI; a query-cache mutation lifecycle coordinates shared remote data.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-b087223b617f","heading":"Optimistic updates & concurrent mutation conflicts","text":"Prepare: Cancel obsolete reads where supported; record the affected entity, mutation ID, and base version. Save a snapshot only if rollback cannot erase newer work.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-b2c267557a9c","heading":"Optimistic updates & concurrent mutation conflicts","text":"Apply: Display the pending change, ideally as an overlay of pending operations on a confirmed snapshot. Keep the list and detail representations consistent or invalidate them deliberately.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-627611baeb43","heading":"Optimistic updates & concurrent mutation conflicts","text":"Confirm or reject: Replace pending values with the authoritative response on success. On failure, remove only that operation’s optimistic change and show a recovery action. Reconcile affected queries after pending operations settle.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-concurrent-mutations","heading":"Optimistic updates & concurrent mutation conflicts › Why simple rollback breaks with overlapping writes","text":"Why simple rollback breaks with overlapping writes","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-fe2ca21dac94","heading":"Optimistic updates & concurrent mutation conflicts › Why simple rollback breaks with overlapping writes","text":"Example: Mutation A optimistically sets a name to “Ada”; B then sets it to “Grace.” If A fails and restores its entire old snapshot, it erases B’s newer change. Similarly, an older success response may arrive last and overwrite newer UI. Response arrival order is not business ordering.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-6b761c3a84f9","heading":"Optimistic updates & concurrent mutation conflicts › Why simple rollback breaks with overlapping writes","text":"Serialize or disable per entity: Simplest when users do not need overlapping writes. The existing favorite example disables its button while saving. Other tabs or users can still write concurrently.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ebd59c971449","heading":"Optimistic updates & concurrent mutation conflicts › Why simple rollback breaks with overlapping writes","text":"Track pending operations: Assign mutation IDs and derive the display from confirmed data plus remaining operations. A “latest request” guard protects local display ordering, but does not undo writes already accepted by the server.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c83a686ad489","heading":"Optimistic updates & concurrent mutation conflicts › Why simple rollback breaks with overlapping writes","text":"Optimistic concurrency control: Send a base version or an If-Match precondition with the resource’s ETag. The server checks and writes atomically; failed preconditions produce 412 Precondition Failed, while application conflicts may use 409 Conflict. Refetch and offer merge/retry rather than silently overwriting.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-750f1f2c33a4","heading":"Optimistic updates & concurrent mutation conflicts › Why simple rollback breaks with overlapping writes","text":"Retry safely: For supported operations, reuse an idempotency key for retries of the same logical command. This avoids duplicate effects; it does not resolve two different commands editing the same resource.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e4db6938c804","heading":"Optimistic updates & concurrent mutation conflicts › Why simple rollback breaks with overlapping writes","text":"Form connection: Keep the user’s dirty draft separate from the confirmed snapshot and show a conflict explicitly; follow the draft reconciliation policy and submission contract.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-occ-choice","heading":"Optimistic updates & concurrent mutation conflicts › Choosing optimistic concurrency control","text":"Choosing optimistic concurrency control","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-cec7b51a81a0","heading":"Optimistic updates & concurrent mutation conflicts › Choosing optimistic concurrency control","text":"Problem: Two editors read version 7 and submit different changes. Without a precondition, the later write may silently overwrite the first. With optimistic concurrency control (OCC), each write includes the version it read; the server atomically updates only if that version is still current.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e162942f55f3","heading":"Optimistic updates & concurrent mutation conflicts › Choosing optimistic concurrency control","text":"Example: Read a profile with ETag \"v7\", then send If-Match: \"v7\" with PATCH. After another write advances it to v8, the stale request receives 412. Preserve the local draft, load the latest version, and offer a merge or explicit retry. Use a strong validator for If-Match; server-side compare-and-update must be atomic.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-52e9b17a30b3","heading":"Optimistic updates & concurrent mutation conflicts › Choosing optimistic concurrency control","text":"Use when: Conflicts are infrequent and users can resolve them. Benefits: No lock held during human editing; conflicts are explicit. Tradeoffs: Requires versions and recovery UX. Frequent conflicts may make repeated retries unproductive.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-3004f0d85197","heading":"Optimistic updates & concurrent mutation conflicts › Choosing optimistic concurrency control","text":"Alternatives: A short database transaction with pessimistic locking can coordinate tightly contested server operations; avoid holding a lock across a human editing session. Atomic domain operations such as increment can avoid unnecessary read-modify-write conflicts. Last-write-wins is acceptable only when intentional data loss is harmless; collaborative merging may need specialized algorithms. UI serialization controls one client, not other users.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-05f4986c46fe","heading":"Optimistic updates & concurrent mutation conflicts › Choosing optimistic concurrency control","text":"Distinction: OCC prevents stale writes; an optimistic UI predicts an outcome; an idempotency key deduplicates retries of one logical operation. They solve different problems and can be used together. See migration compatibility when versions span old and new clients.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-realtime","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"Real-time updates: WebSockets vs. Server-Sent Events","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-775c26429f3a","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"Real-time messages deliver changes to server-owned data; they do not create a second source of truth. Feed them into the same query cache or normalized store used by ordinary reads and mutations.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ab31684bb3ae","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"TransportUse whenTradeoffs","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-eee325f9ecca","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"WebSocketBidirectional traffic: chat, collaborative interactions, or frequent client commands.Persistent connection; implement reconnect, heartbeat, resubscription, and application recovery. The classic browser API has no built-in backpressure.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-bfcde3db5950","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"SSE / EventSourceServer-to-client notifications, progress, feeds; send commands through ordinary HTTP.Text event stream over HTTP with automatic reconnect. Event IDs enable resumption only if the server supports replay. Native EventSource cannot set arbitrary Authorization headers.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-963628663c41","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"PollingUpdates are infrequent or operational simplicity matters more than immediate delivery.Simple recovery but repeated requests and freshness delay. Consider visibility-aware polling and conditional reads.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-853bbf88307e","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"Own the lifecycle: Subscribe in an effect or shared data service and close connections on teardown, resource changes, or logout. Avoid a separate connection per row. See effect synchronization.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-5cf80825fe1c","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"Merge safely: Validate message shape, resource identity, and version. Ignore duplicate or older versions. Apply complete authoritative data or invalidate and refetch when a delta cannot be applied safely; coordinate events with pending optimistic operations.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ba203f5b935d","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"Recover gaps: Reconnect does not guarantee missed events are delivered. Use event IDs/sequence numbers and server replay, or refetch a snapshot before resuming. Bound queued messages and coalesce updates when consumers fall behind.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-0f9739c79b70","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"Secure the channel: Authenticate connections and authorize every subscription/resource. Validate WebSocket origins; apply appropriate CORS/credential rules to SSE. Handle session expiry and close subscriptions on logout.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-review","heading":"Review","text":"Review","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-summary","heading":"Review › Practical distinction","text":"Practical distinction","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-6a51745f7c62","heading":"Review › Practical distinction","text":"I classify state by its authoritative owner before choosing a library. UI state stays local or in a shared client store when needed; remote data is a cached server snapshot with explicit freshness and mutation-reconciliation policies. A form can contain both. Context distributes values, but does not replace a query cache, and Server versus Client Components is a separate execution decision.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-868801fac560","heading":"Review › Practical distinction","text":"Related concepts: HTTP and application caching · Form Actions · External-store subscriptions · Authorization and cache isolation · TanStack Query defaults.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"context-review","heading":"Review › Practical design rationale","text":"Practical design rationale","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-d8efade12efa","heading":"Review › Practical design rationale","text":"I make state ownership and valid transitions explicit before choosing a sharing mechanism. For a shared workflow, I can use a pure reducer with Context, separate data subscriptions from stable operations, and expose custom hooks. I know that native context broadcasts value changes to all its consumers, so I use domain separation or selectors when profiling shows a need for finer subscriptions. For asynchronous workflows, I model explicit states and guard stale transitions rather than managing loosely related booleans.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-title","heading":"","text":"Frontend Performance Optimization","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-01fc3e82f3b6","heading":"","text":"Start with a measured symptom. Understand the browser pipeline, isolate React-specific work, then choose a targeted technique and verify its impact.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-c7fa282677cf","heading":"","text":"Start with a user-visible problem, measure its cause, then verify the improvement. A smaller bundle or fewer React renders matters when it improves loading, responsiveness, stability, or resource use. Optimize the critical path rather than an isolated number.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-480d5c172b10","heading":"","text":"Measuring performance","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-8e6249784042","heading":"","text":"Browser rendering pipeline","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-8a59bc6288d1","heading":"","text":"Diagnosing unnecessary React renders","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-e3957012b228","heading":"","text":"Optimization techniques: purpose and tradeoffs","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-a2760d0bb23e","heading":"","text":"Investigation workflow","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-measurement","heading":"Measuring performance","text":"Measuring performance","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-bb3f379f4348","heading":"Measuring performance › Choose the right measurement tool","text":"Choose the right measurement tool","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-8125429d9f08","heading":"Measuring performance › Choose the right measurement tool","text":"React DevTools Profiler: Record an interaction to find expensive component renders and commits. Use its flamegraph, ranked view, and render-reason information where available. React render work is not the same as browser layout or paint; use a browser trace for those costs.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-59887f092003","heading":"Measuring performance › Choose the right measurement tool","text":"Chrome DevTools Performance panel: Record a reproducible user journey. Inspect the main-thread flame chart, interaction timings, JavaScript call stacks, style recalculation, layout, paint, and dropped frames. Bottom-up groups accumulated cost by function; Call tree shows how execution reached it.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-72d89da2ce6a","heading":"Measuring performance › Choose the right measurement tool","text":"Chrome DevTools Network & Coverage: Find request waterfalls, large transfers, cache behavior, and unused JavaScript or CSS in the recorded journey. Unused code on one screen may still be required elsewhere.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-0d76a91b745c","heading":"Measuring performance › Choose the right measurement tool","text":"Lighthouse: A repeatable synthetic (lab) audit for loading and diagnostics under configured conditions. Its score is a signal, not a complete account of real-user experience. Total Blocking Time (TBT) is a lab responsiveness metric; it is not INP.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-e8031096d61d","heading":"Measuring performance › Choose the right measurement tool","text":"Real User Monitoring (RUM): Measure production users across devices, networks, and routes. Compare field data with lab traces to understand who is affected and reproduce their bottleneck. Chrome UX Report (CrUX) offers aggregated field data for eligible pages and origins.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-19d224a2371e","heading":"Measuring performance › Core Web Vitals: the user-facing outcomes","text":"Core Web Vitals: the user-facing outcomes","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-1051dd4fd8fb","heading":"Measuring performance › Core Web Vitals: the user-facing outcomes","text":"MetricWhat it measuresGood thresholdTypical investigation","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-86374ea24160","heading":"Measuring performance › Core Web Vitals: the user-facing outcomes","text":"LCP · Largest Contentful PaintWhen the largest eligible image or text block in the viewport is rendered.≤ 2.5 secondsServer response time, resource discovery, image loading, render-blocking CSS.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-5edc11615fcc","heading":"Measuring performance › Core Web Vitals: the user-facing outcomes","text":"INP · Interaction to Next PaintResponsiveness across click, tap, and keyboard interactions; reports a near-worst interaction, with outliers handled according to interaction count.≤ 200 millisecondsInput delay, event-handler processing, and presentation delay before the next paint.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-30a044a0297c","heading":"Measuring performance › Core Web Vitals: the user-facing outcomes","text":"CLS · Cumulative Layout ShiftThe largest session-window score of unexpected layout shifts; a unitless measure of visual instability.≤ 0.1Images without reserved dimensions, inserted content, and font swaps.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-de3b66640e19","heading":"Measuring performance › Core Web Vitals: the user-facing outcomes","text":"Evaluate at the 75th percentile of page visits, segmented by mobile and desktop. Use additional percentiles and device or route segments to diagnose affected groups. A fast developer laptop can hide problems on slower devices.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-c8e4e0cebea3","heading":"Measuring performance › Measure JavaScript execution and rendering bottlenecks","text":"Measure JavaScript execution and rendering bottlenecks","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-b3d7116aaeb1","heading":"Measuring performance › Measure JavaScript execution and rendering bottlenecks","text":"Self time vs. total time: Self time belongs to the function itself; total time includes functions it calls. Inspect both to avoid blaming a cheap wrapper for expensive descendants.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-f74dbd49d4c5","heading":"Measuring performance › Measure JavaScript execution and rendering bottlenecks","text":"Long tasks: Main-thread tasks longer than 50 ms can delay input and rendering. Split work into smaller tasks and yield to the browser; move suitable CPU-intensive computations to a Web Worker, which cannot access the DOM directly.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-03a88a1dd6af","heading":"Measuring performance › Measure JavaScript execution and rendering bottlenecks","text":"User Timing API: Use performance.mark() and performance.measure() to label application work in a trace. Elapsed time across an await includes waiting; it is not necessarily JavaScript CPU time.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-c16af6191714","heading":"Measuring performance › Measure JavaScript execution and rendering bottlenecks","text":"Frame budget: A 60 Hz display refreshes about every 16.7 ms; at 120 Hz, about every 8.3 ms. JavaScript shares that time with rendering and browser overhead, so it cannot consume the full interval.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-2081ec7c1bca","heading":"Measuring performance › Measure JavaScript execution and rendering bottlenecks","text":"performance.mark('filter-start'); const results = expensiveFilter(products, query); performance.mark('filter-end'); performance.measure('product-filter', 'filter-start', 'filter-end');","kind":"Code"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-browser","heading":"Browser rendering pipeline","text":"Browser rendering pipeline","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-4b67bdd8ad5c","heading":"Browser rendering pipeline","text":"Browser rendering: from document to frameHTML parsingConstruct the DOM: document structure and content.CSS parsingConstruct the CSSOM: parsed style rules.Style calculationResolve selectors, cascade, and inheritance into computed styles.Render treeCombine renderable content with its styles.LayoutCalculate box sizes and positions.PaintProduce drawing instructions for visual content.RasterizationConvert drawing instructions into pixels, commonly in tiles.CompositingCombine rasterized layers into the final frame.DOM and CSSOM construction feed style calculation and render-tree construction. Browsers work incrementally; an update can reuse results and skip stages.","kind":"Diagram"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-91a8d0a3b576","heading":"Browser rendering pipeline","text":"This is a conceptual model: browsers perform work incrementally, and an update may skip stages when earlier results remain valid.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-811da15674e8","heading":"Browser rendering pipeline","text":"DOM (Document Object Model): The parsed document tree. JavaScript can add, remove, or update its nodes.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-9713fcf6893d","heading":"Browser rendering pipeline","text":"CSSOM (CSS Object Model) & style calculation: The browser parses CSS rules and resolves the cascade, inheritance, and selectors into computed styles for elements. CSS can block initial rendering; synchronous scripts can block HTML parsing.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-504fcd16be1a","heading":"Browser rendering pipeline","text":"Render tree: Combines renderable content with its styles. It differs from the DOM; for example, display: none elements produce no layout boxes.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-8ac25136a670","heading":"Browser rendering pipeline","text":"Layout (reflow): Calculates box sizes and positions. Changing geometry, such as width or font size, can invalidate layout for the element and related content.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-6af7e571c297","heading":"Browser rendering pipeline","text":"Paint: Produces drawing instructions for backgrounds, text, borders, and other visual content. Repaint means regenerating affected visual output; changing a color typically needs paint without layout.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-12e3608d05d7","heading":"Browser rendering pipeline","text":"Rasterization: Converts drawing instructions into pixels, commonly in tiles.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-799e2011a90f","heading":"Browser rendering pipeline","text":"Compositing: Combines rasterized layers into the final frame. Animating transform or opacity on a suitable composited layer can avoid layout and paint. Layer promotion is browser-dependent; excessive layers consume memory.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-7e571088a890","heading":"Browser rendering pipeline","text":"Reflow vs. repaint: Reflow changes geometry; repaint changes appearance. A layout change usually leads to paint for affected content, but a paint-only change need not recalculate layout. Neither is the same as a React re-render.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-layout-thrashing","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"Layout thrashing: alternating DOM writes and geometry reads","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-9cc2fb5ed135","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"Forced synchronous layout occurs when JavaScript reads geometry after a change has invalidated layout, forcing the browser to calculate it immediately. Repeating this write/read cycle is layout thrashing.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-db61862e10b8","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"// Avoid: each width update can invalidate the next geometry read. for (const row of rows) { row.style.width = container.offsetWidth + 'px'; } // Prefer: batch the read before the writes. const width = container.offsetWidth; for (const row of rows) { row.style.width = width + 'px'; }","kind":"Code"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-d291f090f0d2","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"Recognize geometry reads: offsetWidth, offsetHeight, and getBoundingClientRect() may require up-to-date layout. A read is not automatically expensive; pending invalidation determines whether it forces work.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-d9e94a8d3a7c","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"Batch DOM reads before writes when the algorithm permits. Prefer CSS layout rules when they can express the relationship directly.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-66c3771317fc","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"Use requestAnimationFrame() to schedule visual updates before a repaint. It does not prevent forced layout if the callback still alternates writes and reads.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-75c2c7ac0fb3","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"Reduce affected work: Large DOM trees and broad style invalidation increase cost. Consider virtualization, CSS containment, or content-visibility for suitable offscreen sections; verify layout, accessibility, and find-in-page behavior.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-4842894c1ccb","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"DOM operations are not equally expensive: The cost depends on which styles and layout boxes become invalid. Many writes can be batched by the browser; one badly timed geometry read can force that pending work onto the critical path.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-react","heading":"Diagnosing unnecessary React renders","text":"Diagnosing unnecessary React renders","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-b2259a0a285d","heading":"Diagnosing unnecessary React renders","text":"A component can render because its state changes, an ancestor renders, or a consumed context changes. A render does not imply a DOM mutation or repaint. First identify which renders are expensive and whether they affect the interaction.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-e58cc2e3cb60","heading":"Diagnosing unnecessary React renders","text":"Record the interaction in React Profiler and find the expensive commits and components.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-a96641d780b6","heading":"Diagnosing unnecessary React renders","text":"Inspect the trigger: Look for state placed too high in the tree, broad context updates, unstable object/function props, or effects that repeatedly update state.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-2480f02ff3c4","heading":"Diagnosing unnecessary React renders","text":"Reduce the scope of updates: Colocate state with its consumers, split unrelated context values, and avoid storing derived values in state when they can be calculated during rendering.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-7428f32d3dcf","heading":"Diagnosing unnecessary React renders","text":"Apply memoization selectively: Use the techniques below when unchanged inputs can skip meaningful work; profile again to confirm the benefit.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-f64797dadb43","heading":"Diagnosing unnecessary React renders","text":"Measurement caveat: Development-mode StrictMode can invoke rendering and effect setup/cleanup extra times to expose bugs. Validate user-facing performance in a representative production build; React profiling itself may require a profiling-enabled build and adds overhead.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-techniques","heading":"Optimization techniques: purpose and tradeoffs","text":"Optimization techniques: purpose and tradeoffs","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-f621a6ca7c12","heading":"Optimization techniques: purpose and tradeoffs › Control frequency and repeated computation","text":"Control frequency and repeated computation","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-debounce","heading":"Optimization techniques: purpose and tradeoffs › Control frequency and repeated computation","text":"Debouncing: Run after a quiet interval, resetting the timer on each input. Example: fetch search suggestions 250 ms after typing stops. It reduces calls but adds latency; cancel pending timers on cleanup.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-743bfb246525","heading":"Optimization techniques: purpose and tradeoffs › Control frequency and repeated computation","text":"Throttling: Limit execution frequency during continuous activity. Example: update scroll analytics at most once every 200 ms. Choose leading-edge and/or trailing-edge behavior deliberately so the final update is handled.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-memoization","heading":"Optimization techniques: purpose and tradeoffs › Control frequency and repeated computation","text":"Memoization: Reuse a result when its inputs are unchanged. useMemo caches a calculation, useCallback caches a function identity, and React.memo can skip a component render when props compare equal. Default comparisons use Object.is for dependencies or individual props. State/context updates still render memoized components. See hook cache guarantees and React Compiler. Memoization costs memory and comparison work; unstable dependencies or cheap calculations may erase its value.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-8afa02f762ed","heading":"Optimization techniques: purpose and tradeoffs › Reduce initial loading and rendering work","text":"Reduce initial loading and rendering work","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-0e807186293b","heading":"Optimization techniques: purpose and tradeoffs › Reduce initial loading and rendering work","text":"Code splitting: Divide JavaScript into independently loadable chunks, often by route or feature, using dynamic import(). This reduces initial download, parsing, and execution work when chunks are deferred. Excessive splitting can create request waterfalls.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-lazy-loading","heading":"Optimization techniques: purpose and tradeoffs › Reduce initial loading and rendering work","text":"Lazy loading: Defer a resource until it is needed. Use React.lazy with Suspense for supported component loading, or loading=\"lazy\" for offscreen images. Reserve image dimensions to avoid CLS; do not lazy-load the likely LCP image. For visibility-triggered custom loading, see Intersection Observer. Code splitting creates chunks; lazy loading decides when to request them. See Streaming SSR and Suspense for progressive server delivery.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-virtualization","heading":"Optimization techniques: purpose and tradeoffs › Reduce initial loading and rendering work","text":"Virtualization (windowing): Mount only visible list items plus a small overscan region. This reduces DOM size, React work, and layout cost. Account for variable row heights, keyboard focus, screen-reader navigation, and browser search. Resize Observer can measure variable row heights.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-238f726029da","heading":"Optimization techniques: purpose and tradeoffs › Reduce initial loading and rendering work","text":"Pagination: Limit the data fetched per page. Cursor-based pagination is often useful for large or changing datasets; offset-based pagination is simpler for page-number navigation. Pagination reduces data volume; virtualization reduces mounted UI. They can be combined.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-c00eb918f6a6","heading":"Optimization techniques: purpose and tradeoffs › Reduce network work and prevent stale results","text":"Reduce network work and prevent stale results","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-caching","heading":"Optimization techniques: purpose and tradeoffs › Reduce network work and prevent stale results","text":"Caching: Reuse responses or computed data. HTTP caching uses Cache-Control; validators such as ETag support conditional requests and revalidation. Application query caches reuse server state across components; see query keys, freshness, and mutation invalidation. Define freshness, invalidation, and user-specific cache keys; personalized responses must not leak through shared caches.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-9859bbf3979a","heading":"Optimization techniques: purpose and tradeoffs › Reduce network work and prevent stale results","text":"Request cancellation: Stop obsolete asynchronous work to reduce wasted processing and prevent stale results. See AbortController & AbortSignal for the mechanism, React cleanup example, and correctness limits.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-deduplication","heading":"Optimization techniques: purpose and tradeoffs › Reduce network work and prevent stale results","text":"Request deduplication: Share one in-flight request among consumers of the same query key. Caching reuses completed results; deduplication shares pending work. Include all result-affecting parameters and the relevant user/tenant scope in the key.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-c98a4975c872","heading":"Optimization techniques: purpose and tradeoffs › Reduce network work and prevent stale results","text":"Example: a slow product search. Debounce typing to reduce requests, cancel or ignore obsolete searches to prevent stale results, deduplicate identical in-flight queries, and cache reusable results. If the result list itself is expensive, paginate the data and virtualize the rows. Use the trace to decide which of these is actually needed.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-d3e290f45d2d","heading":"Optimization techniques: purpose and tradeoffs › Reduce network work and prevent stale results","text":"For the protocol details behind cache and bundle optimizations, see HTTP freshness and validators and tree shaking and module side effects.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-review","heading":"Investigation workflow","text":"Investigation workflow","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-b3cc615e2ff2","heading":"Investigation workflow","text":"Define the symptom and target: Is loading slow, typing delayed, scrolling janky, or content shifting? Choose the relevant metric and affected user segment.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-e0285992fa17","heading":"Investigation workflow","text":"Capture a baseline: Reproduce the same journey with representative data, device constraints, and explicitly cold or warm caches. Use field data to check how widespread it is.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-9dd63679a184","heading":"Investigation workflow","text":"Identify the dominant bottleneck: Network, JavaScript, React rendering, layout, paint, or a combination. Follow the critical path and call stacks rather than guessing.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-9cbc07fb8d85","heading":"Investigation workflow","text":"Make a targeted change and remeasure: Compare repeated runs under equivalent conditions, then check production percentiles. Watch for regressions in memory, accessibility, data freshness, and other metrics.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-8f7b27a48c1a","heading":"Investigation workflow","text":"Prevent recurrence: Establish performance budgets for important journeys and asset sizes, and monitor regressions in CI and production.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-e2525eb826fa","heading":"Investigation workflow","text":"I begin with the user-visible symptom and a representative baseline. I combine field metrics with Chrome performance traces, using React Profiler when component rendering is implicated. I separate JavaScript execution, React render work, and browser layout and paint, then address the largest cost on the critical path. I validate the result under the same conditions and monitor production percentiles, rather than assuming fewer renders or a higher audit score means a better experience.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"graphql-title","heading":"","text":"GraphQL","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-c300ecd6f453","heading":"","text":"Understand the schema-to-resolver execution model, client data ownership, failure semantics, and when REST is the simpler choice.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-04d9a796de1b","heading":"","text":"What GraphQL solves—and what it does not","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-648224e2e827","heading":"","text":"Schema, types & operation documents","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-37567d4d800c","heading":"","text":"How a GraphQL request executes","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-43a6729734b0","heading":"","text":"Resolvers, context & N+1 prevention","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-4722cd13207f","heading":"","text":"Queries, mutations & subscriptions","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-d5d597e33ddd","heading":"","text":"Nullability, partial data & errors","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-ee2968f64ccb","heading":"","text":"Client caching, identity & mutation reconciliation","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-e35ab68ca065","heading":"","text":"Schema evolution, generated types & query safety","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-ae260ba631fd","heading":"","text":"GraphQL vs. REST: choose by the client and operating cost","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-purpose","heading":"What GraphQL solves—and what it does not","text":"What GraphQL solves—and what it does not","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-purpose-definition","heading":"What GraphQL solves—and what it does not","text":"GraphQL is a query language and execution model for a typed API. Clients select fields from a server-defined schema; the server validates and executes the selection and returns a correspondingly shaped result. It is not a database, ORM, transport protocol, or replacement for authorization.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-70b773c3b56e","heading":"What GraphQL solves—and what it does not","text":"Problem: Different screens need different combinations of related data. Fixed endpoint representations may over-fetch unused fields or require several client requests. GraphQL exposes a composable schema so a client can request a tailored view of those relationships.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-b523de7f0b17","heading":"What GraphQL solves—and what it does not","text":"Example: A product page requests product name plus seller name, while checkout requests price and availability. The schema can serve both without a new endpoint per view. One operation can still trigger many backend calls; a small response is not proof of a cheap query.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-972d9407f9b4","heading":"What GraphQL solves—and what it does not","text":"Use: Multiple clients with evolving, relationship-rich views and teams able to own schema governance and execution cost. For a few stable resource operations, REST is often simpler. A BFF can aggregate data using REST or GraphQL; these are separate choices.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-schema","heading":"Schema, types & operation documents","text":"Schema, types & operation documents","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-schema-definition","heading":"Schema, types & operation documents","text":"The schema defines available fields and types. An operation document selects fields, passes arguments, and names the requested work. Variables provide typed values separately from the document; fragments reuse field selections; aliases rename result keys or request a field with different arguments.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-4ee236117d94","heading":"Schema, types & operation documents","text":"type Query { product(id: ID!): Product } type Product { id: ID! name: String! priceMinor: Int! seller: Seller! } type Seller { id: ID! name: String! }","kind":"Code"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-2cf524688419","heading":"Schema, types & operation documents","text":"query ProductCard($id: ID!) { product(id: $id) { id name seller { id name } } }","kind":"Code"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-34ba91de99b9","heading":"Schema, types & operation documents","text":"The successful response follows the selected shape; unselected priceMinor is absent:","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-59b1d188c3ce","heading":"Schema, types & operation documents","text":"{ \"data\": { \"product\": { \"id\": \"42\", \"name\": \"Engineering Handbook\", \"seller\": { \"id\": \"7\", \"name\": \"Bookshop\" } } } }","kind":"Code"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-d2ff84893962","heading":"Schema, types & operation documents","text":"How to read it: ID is an opaque identifier scalar, not necessarily a number. The exclamation mark is a non-null contract. The product lookup itself is nullable (for example, no visible match), while a present product must supply name and seller under this schema. Variables might be { \"id\": \"42\" }; do not concatenate untrusted strings into query source.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-150e1fa8f887","heading":"Schema, types & operation documents","text":"Other components: Scalars represent leaf values; enums constrain named choices; input objects describe structured arguments; interfaces/unions model polymorphic outputs. Directives such as skip/include conditionally select fields. Custom scalars need documented serialization and validation; a Date scalar is not built in. GraphQL Int is a signed 32-bit integer; choose a documented scalar/representation when money or IDs exceed that range.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-000f65a429c8","heading":"Schema, types & operation documents","text":"Pagination: A connection-style field may expose edges/node/cursor and pageInfo/hasNextPage/endCursor. This is a common schema convention, not a GraphQL requirement. Bound first/last and follow the underlying pagination contract.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-execution","heading":"How a GraphQL request executes","text":"How a GraphQL request executes","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-execution-definition","heading":"How a GraphQL request executes","text":"A GraphQL server parses an operation document, validates it against the schema, coerces variables, and executes the selected fields. An operation name selects which operation to run if the document contains several. The schema limits what can be requested; resolvers supply the actual values.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-aa8b884a9234","heading":"How a GraphQL request executes","text":"Product query: selection → validation → resolution → responseClient submits ProductCard and variablesThe selected fields describe the required result, not SQL or the underlying storage layout.Server validates and establishes request contextCheck the operation against the schema and supply validated identity, services, and request-scoped loaders.Resolve product, then selected child fieldsLoad the authorized product; resolve seller through a bounded, scoped data-access path.Return data and any execution errorsThe client handles complete, partial, or failed results according to the operation and UI contract.Authentication and request-context setup are hosting concerns; their exact position in the HTTP pipeline depends on the server framework.","kind":"Diagram"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-06e24ddad54e","heading":"How a GraphQL request executes","text":"Transport: GraphQL is commonly served over HTTP, often at one endpoint. POST can carry document, variables, and operation name; some servers support GET for queries. Mutation operations must not execute through GET. Subscriptions require a supported transport/protocol, such as a chosen WebSocket protocol or SSE integration.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-1722a638ffcf","heading":"How a GraphQL request executes","text":"Tradeoff: A shared endpoint simplifies schema entry but changes logging, caching, and rate-limit granularity. Record operation names/hashes, duration, errors, and backend calls; avoid logging sensitive variables indiscriminately.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-resolvers","heading":"Resolvers, context & N+1 prevention","text":"Resolvers, context & N+1 prevention","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-resolvers-definition","heading":"Resolvers, context & N+1 prevention","text":"A resolver supplies a field’s value. Common server libraries call resolvers with parent/source, arguments, request context, and execution info. Default field resolution often reads an object property; explicit resolvers connect fields to services and relationships.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-cc7c55c8adf7","heading":"Resolvers, context & N+1 prevention","text":"// Common resolver-map convention; wire through your server framework. // context.services enforces access; sellerById is scoped to this request. const resolvers = { Query: { product: (_parent, { id }, context) => context.services.products.findVisibleById(id, context.user) }, Product: { seller: (product, _args, context) => context.loaders.sellerById.load(product.sellerId) } };","kind":"Code"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-3381363f4b2f","heading":"Resolvers, context & N+1 prevention","text":"Context: Supply validated identity, application services, request IDs, and request-scoped loaders. Do not trust a userId variable to establish identity. Enforce authorization consistently in application/data access, including nested fields.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-5c03375ce5aa","heading":"Resolvers, context & N+1 prevention","text":"Batching: A DataLoader-style utility batches loads within its scheduling window and caches them within its configured scope. Its batch function must return results aligned to input keys, including missing values/errors. Scope it per request and authorization boundary; a process-global personalized loader can leak data.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-c8c4d5014fdb","heading":"Resolvers, context & N+1 prevention","text":"Use: Relationship fields with repeated entity lookups. Prefer a join/eager load or purpose-built query when it is simpler and cheaper. A loader cannot rescue an arbitrarily expensive query or guarantee one database round trip for the whole operation. See N+1 tradeoffs.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-operations","heading":"Queries, mutations & subscriptions","text":"Queries, mutations & subscriptions","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-operations-definition","heading":"Queries, mutations & subscriptions","text":"Queries read data. Mutations request changes. Subscriptions establish an event source that produces execution results over time. These are schema operation categories; they do not automatically define persistence or delivery guarantees.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-265aad0ae2f5","heading":"Queries, mutations & subscriptions","text":"input RenameProductInput { id: ID! name: String! } type RenameProductPayload { product: Product } type Mutation { renameProduct(input: RenameProductInput!): RenameProductPayload! }","kind":"Code"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-74438e9a646a","heading":"Queries, mutations & subscriptions","text":"Mutation behavior: Top-level fields in one mutation operation execute serially. This does not make nested resolution serial, create a database transaction, roll back earlier successful fields, or serialize all clients’ writes. Invoke an application service with explicit validation, transaction, and concurrency-control rules.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-f830ff075784","heading":"Queries, mutations & subscriptions","text":"Example: RenameProduct checks access and a permitted name, updates the record, and returns the confirmed product. Return enough identity/version data for the client cache to reconcile. Choose an explicit typed payload for expected business outcomes rather than exposing database exception strings.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-811f75648bfe","heading":"Queries, mutations & subscriptions","text":"Subscription limits: Reconnection does not inherently replay missed events or guarantee exactly-once delivery. Authorize subscriptions, bound resource usage, and define resume/refetch behavior. Ordinary polling may be sufficient for infrequent updates; compare WebSocket, SSE, and polling.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-errors","heading":"Nullability, partial data & errors","text":"Nullability, partial data & errors","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-errors-definition","heading":"Nullability, partial data & errors","text":"A GraphQL execution response can contain both data and errors. A field-level error can leave other fields usable. Non-null propagation moves a null-producing failure to the nearest nullable ancestor; the schema’s nullability determines the blast radius.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-a1697896d980","heading":"Nullability, partial data & errors","text":"Example: In the product schema, seller is non-null. If seller resolution fails, product can become null even when its name resolved successfully, because product is the nullable ancestor. If every ancestor were non-null, the error could null the operation’s data.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-ce17be143599","heading":"Nullability, partial data & errors","text":"List notation: [Product] allows a null list and null items; [Product!] allows a null list but not null items; [Product!]! allows neither. Use non-null for guarantees the server can maintain, not as a blanket preference.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-fcd489244352","heading":"Nullability, partial data & errors","text":"Client policy: Deliberately choose whether partial results render, show a warning, or fail the task. Error paths identify affected fields; expose safe application codes in extensions where the contract specifies them. Transport failure, parse/validation failure, field execution errors, and expected domain rejection need distinct handling.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-f86fb99d8b75","heading":"Nullability, partial data & errors","text":"HTTP: Do not assume HTTP 200 means full application success or that every GraphQL failure must return 200. Status behavior depends on failure phase and the server’s HTTP/media-type contract. Inspect the GraphQL result and the client library’s error policy. See UI failure isolation.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-caching","heading":"Client caching, identity & mutation reconciliation","text":"Client caching, identity & mutation reconciliation","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-caching-definition","heading":"Client caching, identity & mutation reconciliation","text":"A normalized GraphQL cache stores identifiable entities separately and connects query results through references. Clients such as Apollo or Relay can merge representations when configured identity and field policies agree. A plain fetch call has no automatic normalized cache.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-f9b194cb8fae","heading":"Client caching, identity & mutation reconciliation","text":"Example: Two operations fetch Product 42 with different fields. A cache using type plus ID can retain one entity, allowing a confirmed mutation response to update its known fields. Lists, membership, ordering, pagination, deleted entities, and argument-specific fields still require explicit policies.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-965e3f3cb510","heading":"Client caching, identity & mutation reconciliation","text":"Use: Reused entities across relationship-rich screens. Supply stable IDs, sensible pagination/merge rules, and identity/tenant isolation. For a small operation surface, an ordinary query cache plus explicit updates may be simpler than normalization.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-327b930b233f","heading":"Client caching, identity & mutation reconciliation","text":"Server/HTTP caching: POST-based arbitrary operations do not map as naturally to ordinary shared HTTP caching as resource GETs. Persisted queries and suitable GET query support can enable stable request identities, but server/CDN policies must include variables, authorization scope, and relevant headers. Persisted operations are not automatically authorized or cacheable.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-350d0d9834db","heading":"Client caching, identity & mutation reconciliation","text":"Comparison: Request-local loader caching avoids repeated backend reads within an operation; normalized client caching coordinates entity views; HTTP caching reuses responses. Follow the same server-state lifecycle and cache boundaries.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-tooling","heading":"Schema evolution, generated types & query safety","text":"Schema evolution, generated types & query safety","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-tooling-definition","heading":"Schema evolution, generated types & query safety","text":"A typed schema enables documentation, validation, operation-aware code generation, and change detection. Generate types from the actual selected operation when possible; a schema’s Product type is not the same as the ProductCard query’s selected result.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-acb4d123ea8d","heading":"Schema evolution, generated types & query safety","text":"Evolution: Add fields, deprecate old ones, measure usage, and migrate clients before removal. Adding required arguments/input fields breaks callers; nullability and enum changes can break generated assumptions too. A schema registry or CI compatibility check helps, but client rollout behavior still matters.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-071c8f1df6bd","heading":"Schema evolution, generated types & query safety","text":"Cost controls: Bound pagination, operation size, aliases/batching, depth, and estimated cost as appropriate. A shallow query can still be expensive, so combine static policies with timeouts, concurrency limits, and backend measurements. Rate-limit by meaningful work/identity rather than only “one HTTP request.”","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-fe47c12ee373","heading":"Schema evolution, generated types & query safety","text":"Security: Validate scalar/business values and enforce object/field permissions. Disabling introspection is not authorization. Trusted persisted-operation allowlists can reduce exposed query shapes, but authorization and variable validation remain necessary. Avoid leaking internal stack traces and private fields through errors or shared caches.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-5d2f1a51dab7","heading":"Schema evolution, generated types & query safety","text":"Tradeoff: Schema governance and tooling pay off for substantial multi-client APIs but can be overhead for small services. Generated TypeScript still does not establish runtime truth; see static versus runtime validation.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-vs-rest","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"GraphQL vs. REST: choose by the client and operating cost","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-vs-rest-definition","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"REST organizes interactions around resources and representations using HTTP semantics; many practical “REST APIs” use a pragmatic resource-oriented style. GraphQL offers a typed field-selection/execution contract. Neither guarantees good domain design, low latency, security, or maintainability.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-6ae1842b79f1","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"ConcernGraphQLResource-oriented HTTP API","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-9a724d86ba89","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"Variable screen dataClient selects related fields through a schema.Use resource representations, sparse fields, includes, or a BFF as needed.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-4c8e50b5755e","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"Backend workResolvers need batching, authorization, and cost controls.Handlers need efficient queries, authorization, and bounded work too.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-63fbef6ca86c","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"CachingOften client normalization plus explicit server/persisted-query policies.Resource GETs align naturally with HTTP validators and cache policies.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-41b3b8b4c17b","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"ContractsSchema, operation validation, and operation-specific code generation.OpenAPI/JSON Schema and generated clients can also provide typed contracts.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-90b715a9b847","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"Uploads/streamingOften use a signed upload URL or a separate endpoint/protocol.Dedicated endpoints and standard HTTP transfer patterns often fit naturally.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-63bc12925303","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"OperationsTrack operation names/costs and partial errors.Track routes, status semantics, representation sizes, and dependencies.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-b383c551765c","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"Choose GraphQL: Several clients need changing combinations of related entities, shared schema ownership is realistic, and the organization can operate query-level authorization/cost/caching policies.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-c2019d301ee5","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"Choose REST: Resource operations are stable, HTTP caching is valuable, clients are simple, or the team wants a smaller operational surface. Avoid adding GraphQL just to remove one inconvenient endpoint; an aggregate endpoint or BFF may solve it.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-700502c4fa9d","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"Other alternatives: RPC suits explicit commands/workflows and can have generated contracts; gRPC uses Protobuf and requires deliberate browser integration. SSE/WebSockets address ongoing delivery, not resource modeling. A system can combine REST downloads/uploads, GraphQL reads, and event subscriptions without forcing one style everywhere.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-01299ad4647c","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"Explanation: Start with client data shapes and ownership, measure waterfalls and backend work, then choose the contract and operating model. One endpoint or fewer response fields is not a sufficient performance argument.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-networking-title","heading":"","text":"HTTP & Networking","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-36f69aa20188","heading":"","text":"Trace requests, preserve protocol semantics, and choose explicit caching and transport policies.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-765c39339dfd","heading":"","text":"From URL to response: the request lifecycle","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-576c90409331","heading":"","text":"Methods, status codes & idempotency","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-b91e6c59668a","heading":"","text":"HTTP caching: freshness, validation & cache keys","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-9d792cc1e521","heading":"","text":"Payloads, compression & request waterfalls","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-c869469d0274","heading":"","text":"Browser origin, credentials & storage boundaries","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-514d1c19ee92","heading":"","text":"Review: follow the response contract","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-lifecycle","heading":"From URL to response: the request lifecycle","text":"From URL to response: the request lifecycle","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-lifecycle-definition","heading":"From URL to response: the request lifecycle","text":"A network navigation can involve cache lookup, DNS resolution, a connection, TLS negotiation, an HTTP request/response, and browser parsing/rendering. Existing connections, service workers, caches, redirects, and speculative work can change which steps occur.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-76ffceec0c45","heading":"From URL to response: the request lifecycle","text":"Example: A slow product page may have fast server execution but a long DNS/TLS setup, redirect chain, or JavaScript request waterfall. Inspect the Network panel’s timing and initiator chain instead of labeling all waiting time “backend latency.”","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-2adc977ca6cc","heading":"From URL to response: the request lifecycle","text":"Protocol choices: HTTP/1.1 commonly uses multiple connections; HTTP/2 multiplexes streams on a TCP connection but can still suffer connection-level TCP head-of-line blocking; HTTP/3 uses QUIC with independent streams and TLS integration. These change transport behavior, not resource authorization or application semantics.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-a4ad27818270","heading":"From URL to response: the request lifecycle","text":"Use: Diagnose connection reuse, cache behavior, payload transfer, and dependent requests before optimizing. DNS/CDN routing and geographic distance affect latency; moving a service does not fix an avoidable client waterfall. See performance measurement.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-semantics","heading":"Methods, status codes & idempotency","text":"Methods, status codes & idempotency","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-semantics-definition","heading":"Methods, status codes & idempotency","text":"Safe methods have read-only intended semantics; idempotent methods have the same intended server effect when repeated as when applied once. This does not require identical responses and does not mean every implementation obeys the contract.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-0d339133a919","heading":"Methods, status codes & idempotency","text":"MethodIntended useImportant distinction","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-31b956a27410","heading":"Methods, status codes & idempotency","text":"GET / HEADRead representation / response metadata.Safe and idempotent; do not use them for state-changing commands.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-990c50b7685c","heading":"Methods, status codes & idempotency","text":"POSTSubmit work or create a subordinate resource.Not inherently idempotent; a server-supported idempotency key can deduplicate one operation.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-85dd81c7f61c","heading":"Methods, status codes & idempotency","text":"PUTCreate/replace the state of a target resource.Idempotent semantics; send the representation required by the contract.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-1e0d4fc2b8c0","heading":"Methods, status codes & idempotency","text":"PATCHApply partial modifications.Not inherently idempotent; depends on patch semantics.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-46bd2d577655","heading":"Methods, status codes & idempotency","text":"DELETERemove the target resource association.Idempotent intended effect; a second call may return a different status.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-b71a57fcefe6","heading":"Methods, status codes & idempotency","text":"Status contract: 200 for successful content, 201 for creation, 202 for accepted but unfinished work, 204 for no response body. 400 covers invalid requests; 401 unauthenticated, 403 forbidden, 404 unavailable resource, 409 application conflict, 412 failed precondition, 422 semantically invalid content where adopted, 429 rate-limited, and 5xx server/gateway failure. Follow a documented API contract rather than assuming all clients treat codes identically.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-e9fee2e127c9","heading":"Methods, status codes & idempotency","text":"Use: Correct semantics support caching, retry decisions, and client recovery. Never retry a mutation just because a connection failed without considering its idempotency contract. Use structured error bodies for actionable details.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-caching","heading":"HTTP caching: freshness, validation & cache keys","text":"HTTP caching: freshness, validation & cache keys","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-caching-definition","heading":"HTTP caching: freshness, validation & cache keys","text":"An HTTP cache stores a response under a cache key and policy. A fresh response can be reused without contacting the origin; a stale response may need revalidation. Browser private caches and shared CDN/proxy caches have different privacy boundaries.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-2e53b7fc5fb6","heading":"HTTP caching: freshness, validation & cache keys","text":"Cache-Control: public, max-age=60, s-maxage=300 ETag: \"product-v7\" Vary: Accept-Encoding","kind":"Code"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-7249bf469ba9","heading":"HTTP caching: freshness, validation & cache keys","text":"Interpretation: This deliberately public response can be fresh for 60 seconds in a private cache and 300 in shared caches. Vary makes relevant request-header values part of cache selection. Use public policies only for data safe to share across users; URL-only CDN keys can leak personalized content if policy and authorization are wrong.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-f307d42a9076","heading":"HTTP caching: freshness, validation & cache keys","text":"Directives: no-store asks caches not to store; no-cache permits storage but requires validation before reuse; private disallows shared-cache storage. immutable suits fingerprinted assets with long freshness. stale-while-revalidate permits bounded stale reuse while revalidating where supported.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-1d230ced22f6","heading":"HTTP caching: freshness, validation & cache keys","text":"Conditional reads: Send If-None-Match with the ETag; a 304 response reuses the cached body with updated metadata. Last-Modified/If-Modified-Since provide another validator. Conditional writes use If-Match and optimistic concurrency control, which solve a different problem.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-5cc305c16725","heading":"HTTP caching: freshness, validation & cache keys","text":"Choose the layer: HTTP caches reuse responses; a query cache coordinates application data and mutations. One does not automatically invalidate the other. Version static asset URLs, set explicit personalized-response policies, and define invalidation for mutable public resources. See the optimization overview.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-transport","heading":"Payloads, compression & request waterfalls","text":"Payloads, compression & request waterfalls","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-transport-definition","heading":"Payloads, compression & request waterfalls","text":"Total request time includes waiting, transfer, decompression, parsing, and downstream rendering. Smaller wire payloads can still require expensive JavaScript parsing or application work.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-d8a2c1789060","heading":"Payloads, compression & request waterfalls","text":"Use: Inspect transfer size versus decoded size; use negotiated compression for suitable text, appropriately sized images, pagination, and conditional requests. A CDN can cache suitable public assets near users, but does not make an uncacheable personalized request disappear.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-0b53540edfe6","heading":"Payloads, compression & request waterfalls","text":"Waterfall example: Fetch user → then settings → then permissions when settings/permissions only need the user ID creates dependencies. If an authenticated API can provide independent requests or an appropriate aggregate response, start them together. Do not parallelize work that truly depends on earlier results.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-1f11c2d121ca","heading":"Payloads, compression & request waterfalls","text":"Tradeoffs: Aggregation reduces round trips but can couple latency and failures; splitting lets optional UI load independently. Preload/prefetch can help known critical resources but waste bandwidth when overused. Connection reuse and HTTP multiplexing do not eliminate application dependencies. See bounded concurrency and BFF composition.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-browser-boundaries","heading":"Browser origin, credentials & storage boundaries","text":"Browser origin, credentials & storage boundaries","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-browser-boundaries-definition","heading":"Browser origin, credentials & storage boundaries","text":"The browser enforces rules that a server-side HTTP client does not share. An origin is scheme, host, and port; a cookie’s scope and SameSite rules use additional concepts and are not identical to same-origin checks.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-b2488b6a55b9","heading":"Browser origin, credentials & storage boundaries","text":"Example: A fetch can fail browser CORS checks even when a server-side request to the same API succeeds. Cross-origin fetch credentials require the appropriate client option and server policy, while browser cookie restrictions can still block their use.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-2f8399150289","heading":"Browser origin, credentials & storage boundaries","text":"Choose deliberately: Keep the canonical explanations in CORS and TLS, CSRF, and credential storage. CORS governs browser access to responses; it is not authentication or an authorization boundary. Never “fix” credentialed CORS with wildcard origins.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-review","heading":"Review: follow the response contract","text":"Review: follow the response contract","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-review-definition","heading":"Review: follow the response contract","text":"Describe the request path, method semantics, cacheability, validators, credential boundary, and failure response. Diagnose a slow request with timings before choosing a CDN, batching, GraphQL, or a BFF. Those mechanisms address different sources of cost.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"javascript-mechanics-title","heading":"","text":"JavaScript Language Mechanics","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-d0e38d0f263b","heading":"","text":"Understand bindings, invocation, object identity, and memory before applying them to React or backend code.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-d4a6bc7e4083","heading":"","text":"Lexical scope, closures & lifetime","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-344ea1a2ecc2","heading":"","text":"this, arrow functions & method invocation","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-0da0c2272c67","heading":"","text":"Objects, prototypes & classes","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-2d23790b8037","heading":"","text":"Equality, mutation & copying","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-84347f67fd82","heading":"","text":"Property descriptors: ownership, visibility & mutation","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-ef83876a7f3c","heading":"","text":"Coercion: explicit conversion & operator semantics","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-bc09be2eee6d","heading":"","text":"Iteration protocols: iterable, iterator & generator","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-e8b1c59aa97e","heading":"","text":"Module execution order: linking, live bindings & cycles","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-f0c6bb7b89fa","heading":"","text":"Garbage collection & memory leaks","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-e64ee08e851e","heading":"","text":"Review: reason from the runtime","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-scope","heading":"Lexical scope, closures & lifetime","text":"Lexical scope, closures & lifetime","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-scope-definition","heading":"Lexical scope, closures & lifetime","text":"Lexical scope resolves names from where code is defined. A closure retains access to its surrounding lexical environment after the outer function returns. It captures bindings, not an automatic frozen copy of every value.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-closure-meaning","heading":"Lexical scope, closures & lifetime › Closure: a function keeps access to where it was created","text":"Closure: a function keeps access to where it was created","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-2b3419c4e9e0","heading":"Lexical scope, closures & lifetime › Closure: a function keeps access to where it was created","text":"A binding is the association between a variable name and its value. A lexical environment holds bindings and links to surrounding environments. A closure is a function together with access to its surrounding lexical environment. You do not explicitly create a special closure object; JavaScript functions retain this access when they are created.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-b0a69c4c63c3","heading":"Lexical scope, closures & lifetime › Closure: a function keeps access to where it was created","text":"In the counter below, the returned arrow function uses count, which belongs to makeCounter. Returning ends that invocation of makeCounter, but the returned function can still read and update that invocation’s count. That continuing access is the closure.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-4c867e81696d","heading":"Lexical scope, closures & lifetime › Closure: a function keeps access to where it was created","text":"function makeCounter() { let count = 0; return () => ++count; } const next = makeCounter(); next(); // 1 next(); // 2","kind":"Code"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-522f52c38c78","heading":"Lexical scope, closures & lifetime › Closure: a function keeps access to where it was created","text":"makeCounter() creates a new binding: count = 0.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-2da49006033c","heading":"Lexical scope, closures & lifetime › Closure: a function keeps access to where it was created","text":"It creates and returns a function that accesses that binding.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-96ecb9071ff4","heading":"Lexical scope, closures & lifetime › Closure: a function keeps access to where it was created","text":"next now refers to the returned function. The outer call has finished; its execution frame is no longer on the call stack.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-d95eea1addf2","heading":"Lexical scope, closures & lifetime › Closure: a function keeps access to where it was created","text":"The first next() changes the retained binding to 1; the second changes the same binding to 2. The counter does not restart because makeCounter is not being called again.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-394274652bee","heading":"Lexical scope, closures & lifetime › Closure: a function keeps access to where it was created","text":"Separate calls, separate state: const other = makeCounter(); other(); returns 1, even after next() has returned 2. Each invocation creates a different count binding.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-closure-bindings","heading":"Lexical scope, closures & lifetime › Capturing a binding versus computing a snapshot","text":"Capturing a binding versus computing a snapshot","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-d8d00bda16d0","heading":"Lexical scope, closures & lifetime › Capturing a binding versus computing a snapshot","text":"A closure does not automatically copy the value a variable had when the function was created. It reads the binding when it executes. A separately computed value can still be a snapshot:","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-6e378457b4fc","heading":"Lexical scope, closures & lifetime › Capturing a binding versus computing a snapshot","text":"function createReader() { let count = 0; const message = `Initial count: ${count}`; return { increment: () => { count += 1; }, read: () => ({ count, message }), }; } const reader = createReader(); reader.increment(); reader.read(); // { count: 1, message: 'Initial count: 0' }","kind":"Code"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-06c91bf290ad","heading":"Lexical scope, closures & lifetime › Capturing a binding versus computing a snapshot","text":"increment and read share the same invocation’s environment. read sees the updated count. But message was computed once as a string; it is not a formula that re-runs when count changes. To get a fresh message, compute it inside read. This distinction helps explain stale closures and derived snapshots.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-closure-lifetime","heading":"Lexical scope, closures & lifetime › Lifetime: how long the function and retained data remain reachable","text":"Lifetime: how long the function and retained data remain reachable","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-665cbf2847f9","heading":"Lexical scope, closures & lifetime › Lifetime: how long the function and retained data remain reachable","text":"Scope answers “Where can this name be accessed in the source code?” Lifetime answers “How long does this value or environment remain available during execution?” A local binding can outlive the function call that created it when a reachable closure still needs it.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-1131d18e60fa","heading":"Lexical scope, closures & lifetime › Lifetime: how long the function and retained data remain reachable","text":"JavaScript uses reachability-based garbage collection. While application code, a registered event listener or another live reference can reach the closure, the bindings and objects it needs must remain available. Once no live reference can reach them, they become eligible for garbage collection. Collection is not immediate or scheduled by your code. Engines can optimize unused bindings; do not assume every local variable is always retained.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-ee9c202fcf4d","heading":"Lexical scope, closures & lifetime › Lifetime: how long the function and retained data remain reachable","text":"Why the counter survives the outer returnreachable next binding → returned function → lexical environment → count bindingThe call stack frame has finished. The reachable lexical environment supplies the persistent state; the outer function is not still running.","kind":"Diagram"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-closure-cleanup","heading":"Lexical scope, closures & lifetime › Practical lifetime: an event listener can keep data alive","text":"Practical lifetime: an event listener can keep data alive","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-05b5a01b9714","heading":"Lexical scope, closures & lifetime › Practical lifetime: an event listener can keep data alive","text":"function attachPreview(button, job) { const onClick = () => { console.log(job.description); }; button.addEventListener('click', onClick); return () => button.removeEventListener('click', onClick); } let dispose = attachPreview(document.querySelector('#preview'), job); // Later, when this interaction is no longer needed: dispose(); // Remove the listener's reference to onClick. dispose = null; // Release our reference to the cleanup closure too.","kind":"Code"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-b4dffb6c3156","heading":"Lexical scope, closures & lifetime › Practical lifetime: an event listener can keep data alive","text":"A reachable button’s listener retains onClick, whose closure accesses job. The returned cleanup function also references the handler. Removing the listener and releasing the cleanup reference removes these retention paths; the job object can be collected only if nothing else still references it. Closures are useful and normal: a memory leak happens when an unintended live reference retains data longer than needed. Cycles alone do not prevent collection.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-9d1c41c8876a","heading":"Lexical scope, closures & lifetime › Practical lifetime: an event listener can keep data alive","text":"In a React effect, return the cleanup function so React removes the listener at the effect’s lifecycle boundary. See listener lifecycle and render snapshots and effect dependencies.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-e9a6f8dd88b6","heading":"Lexical scope, closures & lifetime › Practical lifetime: an event listener can keep data alive","text":"Explanation: “A closure lets a function access bindings from the lexical environment where it was created. Those bindings can outlive the outer call while the closure remains reachable. Scope determines visibility; reachability determines whether retained data can be garbage-collected.”","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-e6c6af5f73fc","heading":"Lexical scope, closures & lifetime › Practical lifetime: an event listener can keep data alive","text":"Use: Encapsulated state, callbacks, factories, and dependency injection. Each factory invocation has a separate environment; closures created within the same invocation can share bindings. Closures are ordinary functions, not separate threads.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-8d55cab2a5f7","heading":"Lexical scope, closures & lifetime › Practical lifetime: an event listener can keep data alive","text":"Pitfalls: var is function-scoped; let/const are block-scoped and cannot be accessed before initialization because of the temporal dead zone. const prevents reassignment of the binding, not mutation of an object. Long-lived callbacks can retain large environments.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-6a5a835327e1","heading":"Lexical scope, closures & lifetime › Practical lifetime: an event listener can keep data alive","text":"React connection: Each render creates a new snapshot and closures from that render observe its values. Use correct dependencies, functional updates, or refs according to the intended lifecycle; see render snapshots and dependencies. Do not suppress dependencies merely to keep a closure stable.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-this","heading":"this, arrow functions & method invocation","text":"this, arrow functions & method invocation","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-this-definition","heading":"this, arrow functions & method invocation","text":"For ordinary functions, this depends on how the function is called. A method call binds its receiver; extracting the function loses that receiver. Arrow functions inherit this lexically and cannot be rebound with call/apply/bind.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-31e79ee9392b","heading":"this, arrow functions & method invocation","text":"const counter = { value: 2, read() { return this.value; } }; counter.read(); // 2 const read = counter.read.bind(counter); read(); // 2, even when passed as a callback.","kind":"Code"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-93aa2d532adc","heading":"this, arrow functions & method invocation","text":"Use: Understand method callbacks in SDKs and classes. call/apply invoke with an explicit receiver; bind creates another function. In strict mode, an ordinary unbound call has undefined this.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-cbe447ebe272","heading":"this, arrow functions & method invocation","text":"Choose deliberately: Arrow callbacks suit lexical behavior; use an ordinary method when the receiver should vary. A closure with explicit parameters often avoids receiver ambiguity entirely. Repeated bind() creates new references; listener removal requires the original callback identity.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-prototypes","heading":"Objects, prototypes & classes","text":"Objects, prototypes & classes","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-prototypes-definition","heading":"Objects, prototypes & classes","text":"Prototype delegation searches an object’s own properties first, then its prototype chain. Class methods typically live on the prototype; a class is JavaScript syntax with additional semantics, not a separate inheritance runtime.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-8298e5d9aee8","heading":"Objects, prototypes & classes","text":"class Counter { constructor() { this.value = 0; } increment() { this.value += 1; } } const counter = new Counter(); Object.hasOwn(counter, 'value'); // true Object.hasOwn(counter, 'increment'); // false","kind":"Code"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-52a33b8becf2","heading":"Objects, prototypes & classes","text":"Use: Reading library behavior, understanding shared methods, and integrating class-based APIs. Class field arrow functions are created per instance; prototype methods are shared. Native #private fields provide runtime private access, unlike TypeScript’s ordinary private modifier.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-6c996ea36b7c","heading":"Objects, prototypes & classes","text":"Alternatives and pitfalls: Prefer composition and functions when inheritance does not represent a stable substitutable relationship. Avoid changing built-in prototypes. Use Object.hasOwn when inherited keys must not count, and validate untrusted object keys to avoid prototype-pollution paths. A Map can be clearer for a dynamic key/value registry.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-identity","heading":"Equality, mutation & copying","text":"Equality, mutation & copying","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-identity-definition","heading":"Equality, mutation & copying","text":"Primitives compare by value; objects compare by identity. Assigning or passing an object copies its reference value, so two variables can refer to the same mutable object. JavaScript passes arguments by value, including reference values.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-4ed039679329","heading":"Equality, mutation & copying","text":"const previous = { user: { name: 'Ada' }, count: 1 }; const shallow = { ...previous }; shallow !== previous; // true shallow.user === previous.user; // true const next = { ...previous, user: { ...previous.user, name: 'Grace' } }; // Only the changed path has new identities; previous remains unchanged.","kind":"Code"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-d1792a3aa611","heading":"Equality, mutation & copying","text":"Use: Immutable state updates and predictable cache selectors. Spread/Object.assign are shallow copies. structuredClone supports many structured values and cycles, but not functions or DOM nodes and does not preserve arbitrary custom class behavior. JSON round-tripping loses or rejects values such as undefined, dates-as-dates, BigInt, and cycles.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-4004a8612211","heading":"Equality, mutation & copying","text":"Equality details: === considers NaN unequal to itself and +0/-0 equal; Object.is does the opposite for those cases. React uses Object.is in several identity comparisons. Map/Set use SameValueZero for keys/values.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-4aede890560a","heading":"Equality, mutation & copying","text":"When not to deep-copy: Deep-cloning every update wastes work and destroys unchanged reference identities. Use structural sharing or a maintained immutable-update helper; see referential stability and memoization.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-descriptors","heading":"Property descriptors: ownership, visibility & mutation","text":"Property descriptors: ownership, visibility & mutation","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-descriptors-definition","heading":"Property descriptors: ownership, visibility & mutation","text":"A property descriptor defines an own property’s behavior. A data descriptor contains value and writable; an accessor descriptor contains get and/or set. Both can specify enumerable and configurable. A property cannot be both a data property and an accessor.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-a008cf75dfef","heading":"Property descriptors: ownership, visibility & mutation","text":"const account = {}; Object.defineProperty(account, 'id', { value: 'u-42', writable: false, enumerable: true, configurable: false }); Object.keys(account); // ['id'] Object.getOwnPropertyDescriptor(account, 'id'); // In strict mode, assigning account.id throws TypeError.","kind":"Code"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-0dcbeb7a356c","heading":"Property descriptors: ownership, visibility & mutation","text":"Mechanics: For a new property created with Object.defineProperty, omitted boolean attributes default to false; ordinary object-literal data properties normally have all three true. Non-configurable restricts deletion and redefinition, with limited permitted transitions such as writable true to false.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-6bbb5555f34c","heading":"Property descriptors: ownership, visibility & mutation","text":"Use: Library contracts, getters for computed views, and understanding why a property cannot be changed. Object spread and Object.assign read enumerable own property values, including symbols, and may execute getters; they do not clone descriptors or prototypes. Use getOwnPropertyDescriptors with Object.create when descriptor preservation is intentional.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-0aaec8df76e3","heading":"Property descriptors: ownership, visibility & mutation","text":"Alternatives & limits: Prefer plain objects for application data. Object.freeze is shallow and does not prevent mutation inside nested objects or disable an accessor’s setter; TypeScript readonly is a static restriction. Non-enumerable is not private or secure. Connect this to identity and copying and readonly contracts.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-coercion","heading":"Coercion: explicit conversion & operator semantics","text":"Coercion: explicit conversion & operator semantics","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-coercion-definition","heading":"Coercion: explicit conversion & operator semantics","text":"Type coercion converts values between types. Boolean contexts use truthiness; arithmetic and comparison operators apply their own conversion rules. Objects can customize primitive conversion through Symbol.toPrimitive, or valueOf/toString fallbacks.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-aed15af77673","heading":"Coercion: explicit conversion & operator semantics","text":"Boolean('false'); // true: a non-empty string Number(''); // 0: often wrong for an empty form field Number('12px'); // NaN '5' + 1; // '51': string concatenation '5' - 1; // 4: numeric conversion 0 ?? 10; // 0: only null/undefined trigger fallback 0 || 10; // 10: any falsy value triggers fallback null == undefined; // true null === undefined; // false","kind":"Code"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-24986577eddc","heading":"Coercion: explicit conversion & operator semantics","text":"Use: Normalize values at an explicit boundary, such as URL parameters or form inputs. Check empty input before Number, then validate Number.isFinite and domain constraints. parseInt parses a prefix and can accept trailing garbage; it is not general numeric validation.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-b71b2c680d77","heading":"Coercion: explicit conversion & operator semantics","text":"Pitfalls: Empty arrays and objects are truthy; NaN is unequal to itself; strict equality still compares object identity. Mixing BigInt and Number in arithmetic generally throws. Prefer strict equality and intentional conversions; a deliberate value == null check can cover null and undefined when the team agrees on that convention.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-f29b72295ed6","heading":"Coercion: explicit conversion & operator semantics","text":"React connection: count && \u003cBadge /> can render 0; use count > 0 when the condition must be boolean. See equality and boundary validation.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-iteration","heading":"Iteration protocols: iterable, iterator & generator","text":"Iteration protocols: iterable, iterator & generator","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-iteration-definition","heading":"Iteration protocols: iterable, iterator & generator","text":"An iterable exposes [Symbol.iterator](), returning an iterator whose next method produces { value, done }. for…of, array spread, and destructuring consume this protocol. A generator function produces a generator that is both an iterator and an iterable.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-e53d275a3c8d","heading":"Iteration protocols: iterable, iterator & generator","text":"function* range(end) { for (let value = 0; value \u003c end; value++) yield value; } const numbers = range(3); numbers.next(); // { value: 0, done: false } [...numbers]; // [1, 2]: this generator instance is consumed [...range(3)]; // [0, 1, 2]: a fresh instance","kind":"Code"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-23bbc74f54c5","heading":"Iteration protocols: iterable, iterator & generator","text":"Use: Lazy transformations, traversal, and sequences that should not be fully allocated up front. A generator suspends at yield; it does not create a background thread. Avoid spreading a large or unbounded iterable into memory.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-d31933ec2d17","heading":"Iteration protocols: iterable, iterator & generator","text":"Distinctions: An array is reusable as an iterable; a generator instance generally advances once through its sequence. for…in enumerates enumerable string keys, including inherited ones; for…of consumes values. Plain objects are not iterable by default—choose Object.entries for key/value iteration.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-779cea5fc2ee","heading":"Iteration protocols: iterable, iterator & generator","text":"Lifecycle & alternatives: Early exit from for…of calls an iterator’s return method when present; generator finally blocks can clean up resources. Prefer array map/filter for small materialized collections. Async iterables use Symbol.asyncIterator and await each next result; see async iteration and backpressure.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-module-execution","heading":"Module execution order: linking, live bindings & cycles","text":"Module execution order: linking, live bindings & cycles","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-module-execution-definition","heading":"Module execution order: linking, live bindings & cycles","text":"ES modules are linked before their bodies execute: imports connect to exported bindings, rather than copying snapshots. Evaluation follows dependencies; module text order is not a global scheduling guarantee. A module is normally evaluated once per resolved module identity within its environment.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-d2529c156d86","heading":"Module execution order: linking, live bindings & cycles","text":"// counter.mjs export let count = 0; export function increment() { count++; } // main.mjs import { count, increment } from './counter.mjs'; console.log(count); // 0 increment(); console.log(count); // 1: an imported live binding // count = 2; // invalid: import bindings are read-only to importers","kind":"Code"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-e89aae1545f2","heading":"Module execution order: linking, live bindings & cycles","text":"Cycles: Circular imports can link successfully, but reading a let/const/class binding before initialization throws a ReferenceError. Function declarations can be available earlier; relying on evaluation-order accidents still creates fragile coupling. Break cycles by extracting shared contracts or injecting dependencies.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-29399822bc9c","heading":"Module execution order: linking, live bindings & cycles","text":"Async modules: Top-level await delays dependent module evaluation; it does not block the whole JavaScript thread. Independent branches may proceed. Dynamic import returns a promise for a module namespace and is useful for optional code; it does not guarantee a separate network chunk in every build.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-9cb8f7361ce5","heading":"Module execution order: linking, live bindings & cycles","text":"Use & tradeoffs: Keep module top-level work small and predictable. Use an explicit initialization function when ordering, failure, or cleanup needs control. CommonJS executes require synchronously and cycles can expose partially initialized exports. For format/resolution, tree shaking, and bundling, use the module-boundary section; for scheduling, see the existing event-loop explanation.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-memory","heading":"Garbage collection & memory leaks","text":"Garbage collection & memory leaks","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-memory-definition","heading":"Garbage collection & memory leaks","text":"JavaScript garbage collection reclaims objects that are no longer reachable from live roots. An unwanted object that remains reachable is a memory leak; cycles alone are not necessarily leaks.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-8348d648bfc2","heading":"Garbage collection & memory leaks","text":"Example: A window listener keeps a closure alive, which retains a detached panel and its data. An unbounded Map cache or timer can cause the same retention even when the UI disappears.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-39668f84e699","heading":"Garbage collection & memory leaks","text":"Investigate: Reproduce repeated mount/unmount or navigation, compare heap snapshots, inspect retained objects and their retaining paths, and check whether memory stabilizes after collection. Allocation volume and retained memory are different measurements.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-1de3191ddbeb","heading":"Garbage collection & memory leaks","text":"Prevent: Define cache size/eviction and resource disposal. WeakMap/WeakSet avoid strongly retaining keys but are not general cache eviction policies: keys are non-enumerable and collection timing is nondeterministic. FinalizationRegistry does not provide reliable timely cleanup.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-review","heading":"Review: reason from the runtime","text":"Review: reason from the runtime","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-review-definition","heading":"Review: reason from the runtime","text":"Explain where a variable resolves, which invocation owns its binding, how a function gets its receiver, which object identities change, and what keeps data reachable. Use those mechanisms to explain stale closures, failed memoization, mutation bugs, and retained listeners rather than memorizing isolated output puzzles.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"node-runtime-title","heading":"","text":"Node.js Runtime & Server Execution","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-46894aa4a8ac","heading":"","text":"Choose the right execution resource, bound concurrency, and make request and process lifecycles explicit. Build on the existing event-loop foundation.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-1c9b401a2853","heading":"","text":"Server execution: separate JavaScript, I/O & CPU work","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-0018699113a1","heading":"","text":"libuv thread pool: shared capacity & saturation","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-7d4657312802","heading":"","text":"Worker threads: parallel CPU work with explicit ownership","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-d54a66dbc217","heading":"","text":"Streams & backpressure: bound memory as data flows","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-d09b1542dacf","heading":"","text":"Graceful shutdown: stop admission, drain & close","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-2a3c2ce12da7","heading":"","text":"AsyncLocalStorage: request context across async boundaries","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-86c767a6a051","heading":"","text":"Review: identify the constrained resource","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"node-execution","heading":"Server execution: separate JavaScript, I/O & CPU work","text":"Server execution: separate JavaScript, I/O & CPU work","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"node-execution-definition","heading":"Server execution: separate JavaScript, I/O & CPU work","text":"Node.js runs application JavaScript on an event-loop thread per isolate, while delegating work to operating-system facilities and runtime workers. Concurrency allows many requests to be in flight; it does not make CPU-heavy JavaScript execute in parallel on the same thread.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-bc074fc1030c","heading":"Server execution: separate JavaScript, I/O & CPU work","text":"Follow the existing foundation: Tasks, microtasks, starvation, and scheduling are explained in Event loop & scheduling. Node adds host-specific phases and process.nextTick; it has no DOM rendering phase. Do not assume browser timer ordering or memorize one timer/immediate output as a universal guarantee.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-2555ab3b7cea","heading":"Server execution: separate JavaScript, I/O & CPU work","text":"Diagnose: A slow endpoint can wait on I/O, wait for pooled capacity, or block the event loop. Measure event-loop delay/utilization alongside CPU, dependency latency, and queue wait time. High latency alone does not identify which resource is saturated.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-e643abafd6b8","heading":"Server execution: separate JavaScript, I/O & CPU work","text":"Choose: Await asynchronous I/O for database/network work. Use bounded worker capacity for expensive computation. Async syntax around a large synchronous JSON parse or a CPU loop still blocks the thread. Connect execution to the request pipeline.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"node-libuv","heading":"libuv thread pool: shared capacity & saturation","text":"libuv thread pool: shared capacity & saturation","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"node-libuv-definition","heading":"libuv thread pool: shared capacity & saturation","text":"The libuv thread pool handles selected operations that cannot use the same non-blocking mechanism as network sockets. Common consumers include many asynchronous filesystem operations, crypto operations such as pbkdf2/scrypt, zlib, and dns.lookup. Network socket I/O generally uses OS readiness/completion mechanisms instead.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-25b00db916a8","heading":"libuv thread pool: shared capacity & saturation","text":"Example: A burst of password-hash jobs can occupy the pool and delay unrelated filesystem or DNS work. The process-wide pool is shared across event loops, including worker threads; moving pool-using APIs into a worker does not automatically create an independent libuv pool.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-3eb0559d7845","heading":"libuv thread pool: shared capacity & saturation","text":"Diagnose & control: Measure operation latency under concurrent load, bound expensive work, and apply admission control. The default pool size is typically four; UV_THREADPOOL_SIZE is configured before initialization. Raising it can help only when CPU/memory and the workload support greater concurrency.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-c2127a345c06","heading":"libuv thread pool: shared capacity & saturation","text":"Alternatives: Use worker threads for CPU-heavy JavaScript, dedicated services/processes for stronger isolation, and dependency-specific concurrency limits. dns.resolve uses a different DNS path and has different behavior; it is not a drop-in optimization for dns.lookup. See bounded concurrency and bulkheads.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"node-workers","heading":"Worker threads: parallel CPU work with explicit ownership","text":"Worker threads: parallel CPU work with explicit ownership","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"node-workers-definition","heading":"Worker threads: parallel CPU work with explicit ownership","text":"A worker thread runs JavaScript in a separate isolate with its own event loop. Use it for expensive CPU work such as parsing, transformations, or computation that would otherwise delay every request on the main thread. It is usually unnecessary for ordinary asynchronous network I/O.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-ae32f153da75","heading":"Worker threads: parallel CPU work with explicit ownership","text":"// main.mjs — a minimal one-job demonstration, not a production pool import { Worker } from 'node:worker_threads'; const worker = new Worker(new URL('./compute.mjs', import.meta.url), { workerData: { limit: 1_000_000 } }); worker.once('message', result => console.log(result)); worker.once('error', error => console.error(error)); worker.once('exit', code => { if (code !== 0) console.error('Worker failed:', code); }); // compute.mjs import { parentPort, workerData } from 'node:worker_threads'; let sum = 0; for (let i = 0; i \u003c workerData.limit; i++) sum += i; parentPort.postMessage(sum);","kind":"Code"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-087b805a12eb","heading":"Worker threads: parallel CPU work with explicit ownership","text":"Mechanics: Messages usually use structured cloning; transferable ArrayBuffers move ownership and detach the sender’s buffer. SharedArrayBuffer shares memory and requires deliberate synchronization, commonly using Atomics. Worker threads do not receive the main thread’s ordinary object references.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-845922d66627","heading":"Worker threads: parallel CPU work with explicit ownership","text":"Production contract: Reuse a bounded worker pool, bound its queue, reject overload, enforce job deadlines, and handle error/exit/shutdown. Worker creation and serialization cost can exceed the computation saved. Cancellation requires an explicit protocol or termination; rejecting a caller’s promise alone does not stop computation.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-94d211862ec1","heading":"Worker threads: parallel CPU work with explicit ownership","text":"Comparison: Workers share a process and some native resources; child processes provide stronger isolation at higher overhead. Browser Web Workers solve a related responsiveness problem using different APIs; see Web Workers.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"node-streams","heading":"Streams & backpressure: bound memory as data flows","text":"Streams & backpressure: bound memory as data flows","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"node-streams-definition","heading":"Streams & backpressure: bound memory as data flows","text":"A stream processes data incrementally. Readable streams produce chunks; writable streams consume them; transform streams do both. Backpressure makes a fast producer respect a slower consumer instead of buffering an entire file or response in memory.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-d4bd4e6fe4ac","heading":"Streams & backpressure: bound memory as data flows","text":"import { createReadStream, createWriteStream } from 'node:fs'; import { pipeline } from 'node:stream/promises'; import { createGzip } from 'node:zlib'; await pipeline( createReadStream('input.log'), createGzip(), createWriteStream('input.log.gz') ); // Coordinates backpressure and destroys the pipeline on failure.","kind":"Code"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-1de260dfb5e5","heading":"Streams & backpressure: bound memory as data flows","text":"Mechanics: A writable write returning false means the chunk was accepted but the producer should wait for drain before continuing. highWaterMark is a buffering threshold, not a strict global memory cap; object-mode thresholds count objects rather than bytes.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-000719564383","heading":"Streams & backpressure: bound memory as data flows","text":"Use: Large uploads/downloads, exports, compression, and incremental transformations. pipeline is preferable to hand-wiring pipe and independent error listeners for most complete flows. In supported Node versions, pass an AbortSignal to cancel a pipeline; propagate client disconnects when work should stop.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-046c6dd144c1","heading":"Streams & backpressure: bound memory as data flows","text":"Tradeoffs: Buffered reads are simpler for small bounded payloads. Incremental parsers must handle boundaries across chunks; streaming does not remove validation limits. Once HTTP headers are sent, a later stream error cannot become a clean JSON error response. See async iteration for the protocol-level model.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"node-shutdown","heading":"Graceful shutdown: stop admission, drain & close","text":"Graceful shutdown: stop admission, drain & close","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"node-shutdown-definition","heading":"Graceful shutdown: stop admission, drain & close","text":"Graceful shutdown lets accepted work finish within a deadline while stopping new work. It prevents an ordinary restart from unnecessarily dropping requests, abandoning transactions, or losing buffered telemetry.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-ca974b9298f8","heading":"Graceful shutdown: stop admission, drain & close","text":"Mark unready: stop being selected for new traffic; account for routing propagation delays.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-89344c976d94","heading":"Graceful shutdown: stop admission, drain & close","text":"Stop admission: stop accepting new connections/work and reject new jobs appropriately.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-ade9f2374931","heading":"Graceful shutdown: stop admission, drain & close","text":"Drain: track in-flight requests and jobs; allow completion within a bounded period.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-45e86d6ccc4f","heading":"Graceful shutdown: stop admission, drain & close","text":"Close dependencies: release database pools, message clients, workers, and telemetry after their users finish.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-646bf52c6594","heading":"Graceful shutdown: stop admission, drain & close","text":"Enforce a deadline: abort remaining work and close lingering connections; report incomplete work.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-d4bd54ca8d13","heading":"Graceful shutdown: stop admission, drain & close","text":"Implementation: Make SIGTERM/SIGINT handling idempotent. server.close stops accepting connections and waits for eligible connections to close; idle-connection behavior depends on the supported Node version. Track WebSockets/SSE separately because long-lived connections need a shutdown/reconnect contract. Installing signal handlers means the application must finish shutdown itself.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-97b219d61864","heading":"Graceful shutdown: stop admission, drain & close","text":"Pitfalls & alternatives: Calling process.exit immediately can truncate responses and logs. The exit event cannot run awaited cleanup. Crashes and forced termination still happen, so use idempotency and explicit retry semantics rather than treating graceful shutdown as a delivery guarantee. See real-time connection lifecycles.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-bd34592f233b","heading":"Graceful shutdown: stop admission, drain & close","text":"For leased jobs, stop new claims but maintain renewals while safely draining. Lease recovery and stale-owner protection explain why expiry is still required after crashes and why releasing a claim does not stop an in-flight side effect.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"node-request-context","heading":"AsyncLocalStorage: request context across async boundaries","text":"AsyncLocalStorage: request context across async boundaries","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"node-request-context-definition","heading":"AsyncLocalStorage: request context across async boundaries","text":"AsyncLocalStorage propagates context through associated asynchronous execution so logs and traces can carry a request ID without passing it through every utility. It stores execution context, not globally shared “current request” state.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-607697b8786b","heading":"AsyncLocalStorage: request context across async boundaries","text":"import { AsyncLocalStorage } from 'node:async_hooks'; import { randomUUID } from 'node:crypto'; import { createServer } from 'node:http'; const context = new AsyncLocalStorage(); function log(message) { console.log(JSON.stringify({ requestId: context.getStore()?.requestId, message })); } createServer((request, response) => { context.run({ requestId: randomUUID() }, () => { setTimeout(() => { log('request completed'); response.end('ok'); }, 10); }); }).listen(3000);","kind":"Code"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-343854b744d1","heading":"AsyncLocalStorage: request context across async boundaries","text":"Use: Correlation IDs, trace context, and structured diagnostic metadata. run scopes a store to the callback and async work created inside it. Prefer a fresh, small store per request; do not reuse a mutable global context object.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-b245ffb073ae","heading":"AsyncLocalStorage: request context across async boundaries","text":"Boundaries: It does not automatically cross worker/process/network boundaries: transmit allowed metadata explicitly and re-establish context on the receiving side. Some custom callback integrations need AsyncResource or explicit binding. Long-lived background work can retain context; avoid putting entire request bodies or secrets in the store.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"search-b2dcfdb25407","heading":"AsyncLocalStorage: request context across async boundaries","text":"Alternatives & limits: Explicit parameters are clearer for business dependencies. Do not hide authorization or transaction ownership inside an unreviewed ambient store; enforce authorization at the service boundary. AsyncLocalStorage carries metadata; it does not create a database transaction or propagate cancellation.","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"node-review","heading":"Review: identify the constrained resource","text":"Review: identify the constrained resource","kind":"Notes"},{"page":"node-runtime.html","topic":"Node.js Runtime & Server Execution","anchor":"node-review-definition","heading":"Review: identify the constrained resource","text":"For a slow Node endpoint, distinguish event-loop blocking, libuv pool saturation, worker queueing, database-pool contention, and remote I/O. Choose a bounded intervention and measure queue time, memory, latency, and failure behavior. Explain who cancels work, who closes resources, and what happens during shutdown.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-title","heading":"","text":"React Hooks","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d1f9df29c6b0","heading":"","text":"Begin with render snapshots and state. Build up to refs, effects, shared subscriptions, responsive updates, and reusable hooks; use the hook index for direct lookup.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-80c838617e2d","heading":"","text":"Choose hooks by the responsibility they manage: state, synchronization, identity, scheduling, or integration. Hooks compose behavior; they do not replace clear state ownership or make expensive work disappear.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e7a5f24cd7ec","heading":"","text":"Version scope: React 19-era applications, including useEffectEvent in React 19.2+. useFormStatus comes from react-dom; the other React APIs below come from react. Check your installed React version and framework support before adopting newer APIs. Most stateful and effectful hooks belong in Client Components; use has distinct rules and can also be used in Server Components. See component execution boundaries.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f5cd1c11a6ec","heading":"","text":"Study format: Each hook follows the same seven-part structure: purpose, when to use, example, when not to use and alternatives, benefits and tradeoffs, pitfalls and guarantees, and related concepts. Examples are independent; React hooks are imported from react unless a different import is shown. Application helpers and component fragments are identified explicitly.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4bc859dadae8","heading":"","text":"Rules, render snapshots & dependencies","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-b092b14f899d","heading":"","text":"Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-51370648e3cf","heading":"","text":"State & transitions","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c3b18f7cbbfb","heading":"","text":"Refs & imperative integration","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0d768edb4395","heading":"","text":"Effects & synchronization","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8da1dbaac11e","heading":"","text":"Memoization & identity","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-83a8910fb32f","heading":"","text":"Context & external stores","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e47926f77e22","heading":"","text":"Responsive interactions","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-7103dbf587a2","heading":"","text":"Actions, forms & async resources","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-60ae9cfa4a8f","heading":"","text":"Accessibility & diagnostics","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-58f7add2654d","heading":"","text":"Custom hooks","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9b5e3cd96d86","heading":"","text":"Decision process","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-mental-model","heading":"Rules, render snapshots & dependencies","text":"Rules, render snapshots & dependencies","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-18e41d2e96f2","heading":"Rules, render snapshots & dependencies","text":"Rules of Hooks: Call hooks at the top level of a function component or custom hook, before conditional returns. Do not call them in loops, event handlers, or ordinary utility functions. React relies on consistent hook call order. The use API is an explicit exception discussed below.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-1af3e7a8fb4b","heading":"Rules, render snapshots & dependencies","text":"Render snapshots: Each render sees its own props and state. Callbacks close over that snapshot. A stale closure occurs when later work uses an outdated captured value; a dependency omission is a common cause.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-54d64bef5cf3","heading":"Rules, render snapshots & dependencies","text":"Purity: Rendering calculates UI. Do not mutate external data, start subscriptions, or send requests as a render side effect. React may retry or discard render work; reducers, initializers, and memo calculations must also be pure.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-6e518f1f8bfd","heading":"Rules, render snapshots & dependencies","text":"Dependency arrays: Include every reactive value read by an effect or memoized callback/calculation. Dependencies are compared using Object.is. Fix the code’s ownership or synchronization model rather than disabling exhaustive-deps to force a preferred schedule.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-b4e5ebdda923","heading":"Rules, render snapshots & dependencies","text":"Hook identity & state lifetime: State belongs to a component’s position and identity in the tree. Changing its key can reset state; defining component types inside another component can cause unintended remounts. A hook call does not create globally shared state.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-345603a0bec9","heading":"Rules, render snapshots & dependencies","text":"Connect this model to render, reconciliation, and commit, and to referential stability when designing dependencies.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-63e8da7b01ee","heading":"Rules, render snapshots & dependencies","text":"For the language mechanism behind captured values and object identity, see lexical closures and reference equality and structural sharing.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-catalog","heading":"Hook index","text":"Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-7576d14980ba","heading":"Hook index","text":"State & transitions: useState, useReducer","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d8080257148c","heading":"Hook index","text":"Refs & imperative integration: useRef, useImperativeHandle","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-622e0ada346e","heading":"Hook index","text":"Effects & synchronization: useEffect, useLayoutEffect, useEffectEvent, useInsertionEffect","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c6b3cfed42fd","heading":"Hook index","text":"Memoization & identity: useMemo, useCallback","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d4656f27a888","heading":"Hook index","text":"Context & external stores: useContext, useSyncExternalStore","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-40782e71b242","heading":"Hook index","text":"Responsive interactions: useTransition, useDeferredValue","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-cc60c07799eb","heading":"Hook index","text":"Actions, forms & async resources: useActionState, useFormStatus, useOptimistic, use","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d08fc91d1a3f","heading":"Hook index","text":"Accessibility & diagnostics: useId, useDebugValue","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-530f90125e55","heading":"Hook index","text":"Custom hooks: Custom hooks","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-state","heading":"State & transitions","text":"State & transitions","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-state-title","heading":"State & transitions › useState","text":"useState","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-539e047444f0","heading":"State & transitions › useState","text":"Purpose: Stores a local state value and queues renders when it changes. Each render sees a snapshot; a setter does not mutate the value in the running handler.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d76b2c4ae941","heading":"State & transitions › useState","text":"When to use: An independent value such as an expanded panel, input query, or selected tab.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-674835bba06c","heading":"State & transitions › useState › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-608a84eaa1d2","heading":"State & transitions › useState › Example","text":"function Counter() { const [count, setCount] = useState(0); function addTwo() { setCount(previous => previous + 1); setCount(previous => previous + 1); } return \u003cbutton onClick={addTwo}>{count}\u003c/button>; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-37a361d543f0","heading":"State & transitions › useState › Example","text":"Functional updaters run against queued state, so the two updates add 2 even when React batches them.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-bcbb44ef6ac9","heading":"State & transitions › useState › Example","text":"When not to use & alternatives: Do not store values that can be derived from props/state during render. Use useRef for mutable values that should not render, or useReducer for related transitions.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c975dc4d63c7","heading":"State & transitions › useState › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f66559c0c22e","heading":"State & transitions › useState › Benefits & tradeoffs","text":"Benefits: Small API, local ownership, and automatic batching reduce coordination work.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-98c72050c961","heading":"State & transitions › useState › Benefits & tradeoffs","text":"Tradeoffs: Many interdependent setters can obscure invariants; lifting state too far broadens render work.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-cc58143c2fa3","heading":"State & transitions › useState › Benefits & tradeoffs","text":"Pitfalls & guarantees: Use immutable updates and pure updaters. The setter identity is stable; Object.is-equal values can skip updates. useState(() => createInitialDraft()) lazily initializes; pass a function wrapper when storing a function. React may invoke initializers/updaters twice in development. Batching is not one guaranteed render for an entire async workflow.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-926aa0c85ccf","heading":"State & transitions › useState › Benefits & tradeoffs","text":"Related concepts: State ownership · Render snapshots · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-reducer-title","heading":"State & transitions › useReducer","text":"useReducer","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-20e30a999ec8","heading":"State & transitions › useReducer","text":"Purpose: Applies a pure (state, action) => nextState function to queued actions. It makes related transitions explicit.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a20533edb51a","heading":"State & transitions › useReducer","text":"When to use: A workflow with several events and invariants, such as draft editing, retries, or selection management.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-45c6ffb3c318","heading":"State & transitions › useReducer › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-47eb94f43920","heading":"State & transitions › useReducer › Example","text":"function counterReducer(state, action) { switch (action.type) { case 'increment': return { count: state.count + 1 }; case 'reset': return { count: 0 }; default: throw new Error('Unknown action: ' + action.type); } } function Counter() { const [state, dispatch] = useReducer(counterReducer, { count: 0 }); return ( \u003cbutton onClick={() => dispatch({ type: 'increment' })}> {state.count} \u003c/button> ); }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-429b05e84b26","heading":"State & transitions › useReducer › Example","text":"Events describe intent; the reducer centralizes the permitted state change. Shared-provider wiring stays in the existing Context topic.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9b08e2933713","heading":"State & transitions › useReducer › Example","text":"When not to use & alternatives: For one simple value, prefer useState. For hierarchical or parallel workflows, consider a dedicated state-machine library rather than an expanding switch statement.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-66708d27159d","heading":"State & transitions › useReducer › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d357a2c53a8e","heading":"State & transitions › useReducer › Benefits & tradeoffs","text":"Benefits: Centralized transitions are independently testable and easier to audit.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f3142a49e7bb","heading":"State & transitions › useReducer › Benefits & tradeoffs","text":"Tradeoffs: Adds action types and indirection; it does not automatically optimize rendering or share state.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8c5c595454d4","heading":"State & transitions › useReducer › Benefits & tradeoffs","text":"Pitfalls & guarantees: Dispatch has stable identity. Keep reducers immutable and side-effect free; fetch in a handler/effect and dispatch completion events. useReducer(reducer, initialArg, init) supports lazy initialization. A reducer is not automatically an FSM; model states and guards explicitly.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d6c73e734c00","heading":"State & transitions › useReducer › Benefits & tradeoffs","text":"Related concepts: Context + reducer · Finite state machines · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-refs","heading":"Refs & imperative integration","text":"Refs & imperative integration","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-ref-title","heading":"Refs & imperative integration › useRef","text":"useRef","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0221e457c647","heading":"Refs & imperative integration › useRef","text":"Purpose: Keeps a stable object with a mutable current property; mutation does not request a render.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-816c2e5364d6","heading":"Refs & imperative integration › useRef","text":"When to use: DOM access, timer IDs, or an imperative resource that is not the screen’s source of truth.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0cc543cf6442","heading":"Refs & imperative integration › useRef › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-6cca9e4231e7","heading":"Refs & imperative integration › useRef › Example","text":"function SearchField() { const inputRef = useRef(null); return ( \u003c> \u003cinput ref={inputRef} aria-label=\"Search\" /> \u003cbutton onClick={() => inputRef.current?.focus()}>Focus search\u003c/button> \u003c/> ); }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e3089c079cd0","heading":"Refs & imperative integration › useRef › Example","text":"React assigns the DOM node during commit. The click handler uses it without putting the node in state.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d182a0e8915b","heading":"Refs & imperative integration › useRef › Example","text":"When not to use & alternatives: Use state for values that must update UI. Do not use refs to conceal missing effect dependencies; useEffectEvent may fit genuinely non-reactive effect logic.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c53591104506","heading":"Refs & imperative integration › useRef › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-bcadd3617161","heading":"Refs & imperative integration › useRef › Benefits & tradeoffs","text":"Benefits: Provides stable mutable storage and direct integration with DOM APIs.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-106116d27a59","heading":"Refs & imperative integration › useRef › Benefits & tradeoffs","text":"Tradeoffs: Changes are invisible to rendering and can become hidden state if overused.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9bfea531a5a6","heading":"Refs & imperative integration › useRef › Benefits & tradeoffs","text":"Pitfalls & guarantees: Do not generally read/write refs during render except predictable initialization patterns. DOM refs can be null before attachment and after removal. StrictMode may create/discard a ref object in development while checking purity; only the committed instance matters.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e43ba205a3ec","heading":"Refs & imperative integration › useRef › Benefits & tradeoffs","text":"Related concepts: Reactive state · Restricted imperative APIs · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-imperative-handle-title","heading":"Refs & imperative integration › useImperativeHandle","text":"useImperativeHandle","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-bad899d56965","heading":"Refs & imperative integration › useImperativeHandle","text":"Purpose: Customizes the handle exposed through a ref instead of exposing the component’s complete internal DOM.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-51eda7064ea4","heading":"Refs & imperative integration › useImperativeHandle","text":"When to use: A parent needs a small imperative capability such as focus, selection, or scroll-to-item.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-386b93d29450","heading":"Refs & imperative integration › useImperativeHandle › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-032806fc926b","heading":"Refs & imperative integration › useImperativeHandle › Example","text":"// React 19: function components receive ref as a prop. function SearchInput({ ref }) { const inputRef = useRef(null); useImperativeHandle(ref, () => ({ focus() { inputRef.current?.focus(); } }), []); return \u003cinput ref={inputRef} aria-label=\"Search\" />; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-bc3dd468e0ff","heading":"Refs & imperative integration › useImperativeHandle › Example","text":"The parent receives a focus method, not arbitrary access to the internal input API.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-259ee3da6b98","heading":"Refs & imperative integration › useImperativeHandle › Example","text":"When not to use & alternatives: Prefer declarative props for open state, selection, or other persistent UI state. Expose a raw DOM ref only if that is the intended public contract.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f2e295d10fc8","heading":"Refs & imperative integration › useImperativeHandle › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-fb2eec93a241","heading":"Refs & imperative integration › useImperativeHandle › Benefits & tradeoffs","text":"Benefits: Encapsulates implementation details while supporting necessary imperative integration.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-1587b6df5139","heading":"Refs & imperative integration › useImperativeHandle › Benefits & tradeoffs","text":"Tradeoffs: Introduces parent/child timing coupling and a public API that must remain compatible.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ac715a7d923a","heading":"Refs & imperative integration › useImperativeHandle › Benefits & tradeoffs","text":"Pitfalls & guarantees: Include reactive values captured by the handle in dependencies. With no dependency array, a new handle is created each render. React 18 and earlier generally need forwardRef; React 19 supports ref as a prop. Handle access must tolerate unmounted children.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a9d37bbd041d","heading":"Refs & imperative integration › useImperativeHandle › Benefits & tradeoffs","text":"Related concepts: Component customization contracts · DOM refs · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-effects","heading":"Effects & synchronization","text":"Effects & synchronization","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-effect-title","heading":"Effects & synchronization › useEffect","text":"useEffect","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e4999212a357","heading":"Effects & synchronization › useEffect","text":"Purpose: Synchronizes committed UI with an external system through setup and cleanup.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-176df2dc79a3","heading":"Effects & synchronization › useEffect","text":"When to use: Subscriptions, timers, observers, connections, and third-party widgets whose lifetime follows component inputs.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-609aaca0010e","heading":"Effects & synchronization › useEffect › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f785cc12394a","heading":"Effects & synchronization › useEffect › Example","text":"function WindowTitle({ title }) { useEffect(() => { const previousTitle = document.title; document.title = title; return () => { document.title = previousTitle; }; }, [title]); return null; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c189f4ba2946","heading":"Effects & synchronization › useEffect › Example","text":"This single-owner example updates an external browser resource after commit and restores it when synchronization ends.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-812841a825eb","heading":"Effects & synchronization › useEffect › Example","text":"When not to use & alternatives: Calculate derived data during render; handle an explicit user action in its handler. Use useLayoutEffect only when pre-paint measurement is required. Prefer a framework/query cache over hand-written effects for complex server-state fetching.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-75daaa15b981","heading":"Effects & synchronization › useEffect › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ddb2a3d60513","heading":"Effects & synchronization › useEffect › Benefits & tradeoffs","text":"Benefits: Explicit setup/cleanup coordinates resource lifetime with changing inputs.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-079e496d119f","heading":"Effects & synchronization › useEffect › Benefits & tradeoffs","text":"Tradeoffs: Adds lifecycle and race-condition complexity; fetching this way can create waterfalls and misses SSR data delivery.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9eb19a9ac036","heading":"Effects & synchronization › useEffect › Benefits & tradeoffs","text":"Pitfalls & guarantees: No array: runs after each commit. []: no reactive dependencies. [a, b]: cleanup then setup when dependencies change; cleanup also runs on unmount. StrictMode checks setup → cleanup → setup in development. Effects never run on the server, and are not guaranteed to run after paint. Do not make the callback async; return cleanup, not a Promise. Include reactive dependencies and guard obsolete async results.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a38f6b0ca8a2","heading":"Effects & synchronization › useEffect › Benefits & tradeoffs","text":"Related concepts: Listener lifecycle · Async cleanup and cancellation · Non-reactive effect logic · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-layout-effect-title","heading":"Effects & synchronization › useLayoutEffect","text":"useLayoutEffect","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f04a3dc9ddd2","heading":"Effects & synchronization › useLayoutEffect","text":"Purpose: Runs after DOM commit and before the browser repaints, allowing measurement and a synchronous visual correction.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c216efb868f2","heading":"Effects & synchronization › useLayoutEffect","text":"When to use: A tooltip or overlay must measure its rendered box before its final position is painted.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-bfeeb13bccf7","heading":"Effects & synchronization › useLayoutEffect › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-13f9ef90d44d","heading":"Effects & synchronization › useLayoutEffect › Example","text":"function MeasuredLabel({ text }) { const ref = useRef(null); const [width, setWidth] = useState(0); useLayoutEffect(() => { setWidth(ref.current.getBoundingClientRect().width); }, [text]); return \u003cspan ref={ref} data-measured-width={width}>{text}\u003c/span>; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-efb0fc420cda","heading":"Effects & synchronization › useLayoutEffect › Example","text":"The geometry read happens after the DOM exists. This illustrates initial/text-driven measurement, not tracking every font or container-size change.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d58c66382573","heading":"Effects & synchronization › useLayoutEffect › Example","text":"When not to use & alternatives: Use CSS for layout when possible, useEffect for non-visual synchronization, or Resize Observer for ongoing size changes.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-17889bdb906c","heading":"Effects & synchronization › useLayoutEffect › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ac01a0e2f25f","heading":"Effects & synchronization › useLayoutEffect › Benefits & tradeoffs","text":"Benefits: Prevents a visible intermediate position when measurement determines placement.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-899daa396b94","heading":"Effects & synchronization › useLayoutEffect › Benefits & tradeoffs","text":"Tradeoffs: Blocks paint; synchronous updates add work to the frame’s critical path.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-10371f22bd9a","heading":"Effects & synchronization › useLayoutEffect › Benefits & tradeoffs","text":"Pitfalls & guarantees: It does not run during SSR, which has no browser layout. Keep server output stable and choose an appropriate client boundary. Dependency and cleanup rules still apply. Avoid alternating geometry reads and writes, which can force repeated layout.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-5ee4ed3631ef","heading":"Effects & synchronization › useLayoutEffect › Benefits & tradeoffs","text":"Related concepts: Layout thrashing · Resize Observer · Hydration · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-effect-event-title","heading":"Effects & synchronization › useEffectEvent","text":"useEffectEvent","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-384dfb562075","heading":"Effects & synchronization › useEffectEvent","text":"Purpose: Defines non-reactive effect-triggered logic that reads the latest committed props/state without making those values synchronization dependencies. Requires React 19.2+.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8ff4ed751be4","heading":"Effects & synchronization › useEffectEvent","text":"When to use: A connection depends on roomId, while its notification should use the current theme without reconnecting.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f2837cc2b8e8","heading":"Effects & synchronization › useEffectEvent › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-7aed53e02b3f","heading":"Effects & synchronization › useEffectEvent › Example","text":"function ConnectionNotice({ roomId, theme }) { const onConnected = useEffectEvent(() => notify('Connected', theme)); useEffect(() => { const connection = createConnection(roomId); // Application API. connection.on('connected', () => onConnected()); connection.connect(); return () => connection.disconnect(); }, [roomId]); return null; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ded0a829941e","heading":"Effects & synchronization › useEffectEvent › Example","text":"roomId remains reactive. The effect-triggered notification sees the latest theme without replacing the connection.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-58d209f7e184","heading":"Effects & synchronization › useEffectEvent › Example","text":"When not to use & alternatives: Do not use it to hide dependencies that should re-synchronize an effect. Use ordinary handlers for UI events, useCallback for a memoized callback prop, or complete effect dependencies for reactive logic.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f7d2c0bf4bde","heading":"Effects & synchronization › useEffectEvent › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0b2e539ba139","heading":"Effects & synchronization › useEffectEvent › Benefits & tradeoffs","text":"Benefits: Separates resource lifetime from incidental reads without manual ref synchronization.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9f59edd9d6f4","heading":"Effects & synchronization › useEffectEvent › Benefits & tradeoffs","text":"Tradeoffs: Has deliberately narrow calling rules and needs compatible React/lint tooling.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-132c35acd9b5","heading":"Effects & synchronization › useEffectEvent › Benefits & tradeoffs","text":"Pitfalls & guarantees: Call Effect Events only from effects or their effect-triggered logic in the same component/hook. Do not call them during render or from UI handlers, pass them to children, or add them to dependency arrays. They are not a general-purpose stable callback.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-1a8ad8d7fb79","heading":"Effects & synchronization › useEffectEvent › Benefits & tradeoffs","text":"Related concepts: Effect dependencies · Official reference · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-insertion-effect-title","heading":"Effects & synchronization › useInsertionEffect","text":"useInsertionEffect","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-77616076eef3","heading":"Effects & synchronization › useInsertionEffect","text":"Purpose: Provides a specialized phase for CSS-in-JS libraries to insert styles before layout effects run.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a31505cac781","heading":"Effects & synchronization › useInsertionEffect","text":"When to use: You maintain a runtime styling library whose dynamic rules must exist before consumers measure layout.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-054a56c7d6d4","heading":"Effects & synchronization › useInsertionEffect › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-678696e8f36f","heading":"Effects & synchronization › useInsertionEffect › Example","text":"// Library-internal illustration, not a recommended application pattern. function useRuntimeRule(rule) { useInsertionEffect(() => { const style = document.createElement('style'); style.textContent = rule; document.head.append(style); return () => style.remove(); }, [rule]); }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a5680b513e37","heading":"Effects & synchronization › useInsertionEffect › Example","text":"The example shows ordering and cleanup. A production library also needs deduplication, SSR extraction, and CSP-compatible style insertion.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2c53b7fb6254","heading":"Effects & synchronization › useInsertionEffect › Example","text":"When not to use & alternatives: Use static CSS, CSS Modules, or your styling library’s supported API in application code. Use layout effects for measurement, not insertion effects.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2bbad0134898","heading":"Effects & synchronization › useInsertionEffect › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d399bf795c5d","heading":"Effects & synchronization › useInsertionEffect › Benefits & tradeoffs","text":"Benefits: Makes styles available before layout-effect readers need them.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-04b8c9cccfeb","heading":"Effects & synchronization › useInsertionEffect › Benefits & tradeoffs","text":"Tradeoffs: Advanced integration surface; runtime style insertion adds complexity and browser style work.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4d62b6289df7","heading":"Effects & synchronization › useInsertionEffect › Benefits & tradeoffs","text":"Pitfalls & guarantees: Do not update state or rely on refs being attached. DOM mutation ordering is not an application measurement contract. It does not run on the server; server styles need a separate strategy. Never interpolate untrusted CSS without an appropriate security model.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d593313f7602","heading":"Effects & synchronization › useInsertionEffect › Benefits & tradeoffs","text":"Related concepts: Style calculation and rendering · Pre-paint measurement · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-memoization","heading":"Memoization & identity","text":"Memoization & identity","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-memo-title","heading":"Memoization & identity › useMemo","text":"useMemo","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-49ea598a35b4","heading":"Memoization & identity › useMemo","text":"Purpose: Caches the result of a pure calculation while dependencies remain equal by Object.is.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a2bc468daef8","heading":"Memoization & identity › useMemo","text":"When to use: Profiling identifies an expensive repeated calculation, or a stable object enables another measured optimization.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4861862ca997","heading":"Memoization & identity › useMemo › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0214b74dd1f4","heading":"Memoization & identity › useMemo › Example","text":"// Fragment inside a component; filterProducts is a pure helper. const visibleProducts = useMemo( () => filterProducts(products, query), [products, query] );","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4e1e1bb7c9b1","heading":"Memoization & identity › useMemo › Example","text":"It reuses results only when both dependency references/values remain unchanged; the initial calculation still runs.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0f3915891355","heading":"Memoization & identity › useMemo › Example","text":"When not to use & alternatives: Use a plain calculation when cheap. Use state/ref for semantic persistence or resource ownership; a cache must not be required for correctness.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-778160ff7b59","heading":"Memoization & identity › useMemo › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e593b2a7ce9d","heading":"Memoization & identity › useMemo › Benefits & tradeoffs","text":"Benefits: Can avoid repeated CPU work and stabilize derived object identity.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-146cd85a1732","heading":"Memoization & identity › useMemo › Benefits & tradeoffs","text":"Tradeoffs: Retains values and compares dependencies; unstable inputs or cheap calculations can erase the benefit.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0f99731eb317","heading":"Memoization & identity › useMemo › Benefits & tradeoffs","text":"Pitfalls & guarantees: React may discard the cache; StrictMode may call the calculation twice in development. Keep calculations pure and dependencies complete. React Compiler can reduce manual memoization when enabled, but does not fix bad ownership or impure code.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-29654723943b","heading":"Memoization & identity › useMemo › Benefits & tradeoffs","text":"Related concepts: Memoization tradeoffs · Profiling · Provider identity · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-callback-title","heading":"Memoization & identity › useCallback","text":"useCallback","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ae0570a7997a","heading":"Memoization & identity › useCallback","text":"Purpose: Caches a function identity while dependencies remain equal; it does not cache results or make the function’s body faster.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8e8f76eb7125","heading":"Memoization & identity › useCallback","text":"When to use: A memoized child benefits from a stable callback prop, or a subscription API’s contract needs a stable function.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-497df7ddb544","heading":"Memoization & identity › useCallback › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-b49ce425a3aa","heading":"Memoization & identity › useCallback › Example","text":"// Fragment inside a component; api is a stable imported application API. const handleSave = useCallback( draft => api.save(projectId, draft), [projectId] ); return \u003cMemoizedEditor onSave={handleSave} />;","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8d2ff855d4f5","heading":"Memoization & identity › useCallback › Example","text":"The editor can reuse the callback until projectId changes. Child memoization only helps if its other props also permit skipping work.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-7b9690a2ace1","heading":"Memoization & identity › useCallback › Example","text":"When not to use & alternatives: Use a normal function when identity does not matter. Put an effect-only helper inside the effect rather than adding an unnecessary callback layer.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2ff460f522ac","heading":"Memoization & identity › useCallback › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8453ff14eb48","heading":"Memoization & identity › useCallback › Benefits & tradeoffs","text":"Benefits: Can preserve memoized-child bailouts and make identity contracts explicit.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-548ce4b6a494","heading":"Memoization & identity › useCallback › Benefits & tradeoffs","text":"Tradeoffs: Dependency maintenance and cache overhead add complexity without guaranteed savings.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-dc3785027b46","heading":"Memoization & identity › useCallback › Benefits & tradeoffs","text":"Pitfalls & guarantees: Omitting captured values causes stale closures. Creating the function expression still happens; React chooses whether to return the cached one. Its cache is an optimization, not a permanent identity guarantee. Compiler-enabled code may need less manual memoization.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-81c6db32cfd2","heading":"Memoization & identity › useCallback › Benefits & tradeoffs","text":"Related concepts: Result vs. function caching · Callback identity for listener removal · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-context-stores","heading":"Context & external stores","text":"Context & external stores","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-context-title","heading":"Context & external stores › useContext","text":"useContext","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8a5345b92d23","heading":"Context & external stores › useContext","text":"Purpose: Reads and subscribes to the nearest matching provider’s value. The context distributes data; it does not own state transitions.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-1ad0e392a73b","heading":"Context & external stores › useContext","text":"When to use: A subtree shares a theme, dependency, session display value, or domain state without prop drilling through unrelated layers.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-440b3aa7cfe1","heading":"Context & external stores › useContext › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-7e2804151433","heading":"Context & external stores › useContext › Example","text":"const ThemeContext = createContext('light'); function ThemedButton() { const theme = useContext(ThemeContext); return \u003cbutton className={'button-' + theme}>Save\u003c/button>; } // An ancestor may override the default with a ThemeContext provider.","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9b1a93e70fc9","heading":"Context & external stores › useContext › Example","text":"The fallback applies only when there is no provider; a provider value of undefined does not restore the fallback.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ac3e7dbe3cab","heading":"Context & external stores › useContext › Example","text":"When not to use & alternatives: Use props for explicit, shallow dependencies; use composition to avoid needless plumbing. For fine-grained frequent subscriptions, consider context selectors or an external store.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-66fe3bd044c2","heading":"Context & external stores › useContext › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8a85fdd96bdb","heading":"Context & external stores › useContext › Benefits & tradeoffs","text":"Benefits: Simple scoped dependency distribution, with different values in different subtrees.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9dfd9cee7f94","heading":"Context & external stores › useContext › Benefits & tradeoffs","text":"Tradeoffs: Changing the provider value updates all consumers of that context, potentially broadening render work.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4350dc0e9f4e","heading":"Context & external stores › useContext › Benefits & tradeoffs","text":"Pitfalls & guarantees: React compares provider values using Object.is. React.memo does not block a consumed context update; returning one field from a custom hook is not a selector subscription. Split domains/actions deliberately; read the existing architecture rather than rebuilding it here.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e1ad63ec2e6a","heading":"Context & external stores › useContext › Benefits & tradeoffs","text":"Related concepts: Provider implementation · Selectors · Propagation and stability · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-sync-external-store-title","heading":"Context & external stores › useSyncExternalStore","text":"useSyncExternalStore","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-3fc8e1b96558","heading":"Context & external stores › useSyncExternalStore","text":"Purpose: Subscribes to a store outside React while coordinating snapshots with concurrent rendering to avoid inconsistent reads (tearing).","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-7071a1e5bc55","heading":"Context & external stores › useSyncExternalStore","text":"When to use: An external state library or browser source of truth changes independently of React.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-717c8a84a389","heading":"Context & external stores › useSyncExternalStore › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-213f18aad417","heading":"Context & external stores › useSyncExternalStore › Example","text":"// Module-scope functions keep the subscription identity stable. function subscribeOnline(onChange) { window.addEventListener('online', onChange); window.addEventListener('offline', onChange); return () => { window.removeEventListener('online', onChange); window.removeEventListener('offline', onChange); }; } const getSnapshot = () => navigator.onLine; const getServerSnapshot = () => true; // Shared initial SSR/client assumption. function OnlineStatus() { const online = useSyncExternalStore( subscribeOnline, getSnapshot, getServerSnapshot ); return \u003cp>{online ? 'Browser reports online' : 'Offline'}\u003c/p>; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-1f125f076ffd","heading":"Context & external stores › useSyncExternalStore › Example","text":"The Boolean snapshot is stable when unchanged. The same server snapshot is used for SSR and initial hydration, then the browser snapshot is read. navigator.onLine does not prove the backend is reachable.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-cc51d7973b76","heading":"Context & external stores › useSyncExternalStore › Example","text":"When not to use & alternatives: Use React state/reducers for React-owned data. A hand-written effect subscription may suffice for an independent side effect, but does not replace this API’s store-consistency contract.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-6ba819cd6f52","heading":"Context & external stores › useSyncExternalStore › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-44898891ab42","heading":"Context & external stores › useSyncExternalStore › Benefits & tradeoffs","text":"Benefits: Provides concurrency-safe subscription semantics and an explicit hydration snapshot.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2ef2389cea9a","heading":"Context & external stores › useSyncExternalStore › Benefits & tradeoffs","text":"Tradeoffs: Requires careful store design, immutable/cached snapshots, and an SSR policy.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a0825db25bad","heading":"Context & external stores › useSyncExternalStore › Benefits & tradeoffs","text":"Pitfalls & guarantees: subscribe must return unsubscribe. getSnapshot must be Object.is-equal when data has not changed; returning a fresh object each call can loop. Prefer stable subscription functions. SSR consumers need a matching getServerSnapshot or a deliberate client-only strategy. Updates to external mutable stores cannot be made non-blocking merely by wrapping a mutation in startTransition.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-65ac2e4cfdfc","heading":"Context & external stores › useSyncExternalStore › Benefits & tradeoffs","text":"Related concepts: Subscription cleanup · Hydration · External store selection · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-responsiveness","heading":"Responsive interactions","text":"Responsive interactions","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-transition-title","heading":"Responsive interactions › useTransition","text":"useTransition","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-eaa4a0257f79","heading":"Responsive interactions › useTransition","text":"Purpose: Returns pending state and startTransition, which marks non-urgent state updates for interruptible background rendering.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-cbffcdfe2fdf","heading":"Responsive interactions › useTransition","text":"When to use: You own the setter for costly tab content or a result view, while input feedback must remain urgent.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f2e89603891b","heading":"Responsive interactions › useTransition › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-486b9bdfd4d6","heading":"Responsive interactions › useTransition › Example","text":"// Fragment inside a tab component; tabs is the available tab list. const [tab, setTab] = useState('overview'); const [isPending, startTransition] = useTransition(); return ( \u003c> {tabs.map(next => ( \u003cbutton key={next} onClick={() => { startTransition(() => setTab(next)); }}>{next}\u003c/button> ))} \u003cdiv aria-busy={isPending}>\u003cTabContent tab={tab} />\u003c/div> \u003c/> );","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9e2e519e67ba","heading":"Responsive interactions › useTransition › Example","text":"Urgent interactions can interrupt transition rendering; isPending lets the UI communicate outstanding work.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-b5343bdb98e4","heading":"Responsive interactions › useTransition › Example","text":"When not to use & alternatives: Do not transition a controlled text input’s own value update. Use useDeferredValue when you receive a changing value rather than controlling its setter. Use task splitting/workers for long synchronous CPU work.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-54f3ad7da034","heading":"Responsive interactions › useTransition › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2665f787fa95","heading":"Responsive interactions › useTransition › Benefits & tradeoffs","text":"Benefits: Prioritizes interaction feedback and can preserve already-visible content during suspension.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8598700cd690","heading":"Responsive interactions › useTransition › Benefits & tradeoffs","text":"Tradeoffs: Background rendering may restart, doing additional work; the pending state needs deliberate UX.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f220c4a8c9ba","heading":"Responsive interactions › useTransition › Benefits & tradeoffs","text":"Pitfalls & guarantees: The callback begins immediately; it is not a timer or worker. React 19 supports async Actions, but updates after await currently need another startTransition to be transition updates. General async transitions do not guarantee request completion order; guard stale responses or use an action API with suitable queue semantics.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-33369fc827df","heading":"Responsive interactions › useTransition › Benefits & tradeoffs","text":"Related concepts: Deferring received values · Scheduling · Queued Actions · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-deferred-value-title","heading":"Responsive interactions › useDeferredValue","text":"useDeferredValue","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-cae245169e84","heading":"Responsive interactions › useDeferredValue","text":"Purpose: Lets part of the UI render with an older value while React prepares the updated value in the background.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-cf353483e5cb","heading":"Responsive interactions › useDeferredValue","text":"When to use: A fast input feeds an expensive result subtree and you want that subtree to catch up without blocking typing.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-aedb54bfce3e","heading":"Responsive interactions › useDeferredValue › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-209208515c13","heading":"Responsive interactions › useDeferredValue › Example","text":"function Search() { const [query, setQuery] = useState(''); const deferredQuery = useDeferredValue(query); return ( \u003c> \u003cinput aria-label=\"Search\" value={query} onChange={event => setQuery(event.target.value)} /> \u003cdiv style={{ opacity: query !== deferredQuery ? 0.6 : 1 }}> \u003cSlowResults query={deferredQuery} /> \u003c/div> \u003c/> ); } // SlowResults must be memoized or compiler-optimized appropriately.","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-34826bbcdfb0","heading":"Responsive interactions › useDeferredValue › Example","text":"The input updates immediately. Isolating the costly subtree lets the unchanged deferred value skip its urgent render.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-71abb3dedf9f","heading":"Responsive interactions › useDeferredValue › Example","text":"When not to use & alternatives: Use debouncing to reduce request frequency; useTransition when you control the update. A cheap subtree does not need deferred rendering.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-65bc7e1f540d","heading":"Responsive interactions › useDeferredValue › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0e05fa8645fe","heading":"Responsive interactions › useDeferredValue › Benefits & tradeoffs","text":"Benefits: Adaptive scheduling without choosing a fixed debounce delay; can keep stale results visible while loading.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-fac2932704f7","heading":"Responsive interactions › useDeferredValue › Benefits & tradeoffs","text":"Tradeoffs: Users temporarily see stale data, and background renders may restart.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-599a7f893780","heading":"Responsive interactions › useDeferredValue › Benefits & tradeoffs","text":"Pitfalls & guarantees: It does not prevent a network request per keystroke or offload CPU work. Pass a stable value; a newly created object can cause unnecessary background renders. React 19 supports an optional initialValue for the initial client render; SSR ignores that argument during initial hydration.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-66c164df0b13","heading":"Responsive interactions › useDeferredValue › Benefits & tradeoffs","text":"Related concepts: Debouncing · Transitions · Suspense · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-forms-async","heading":"Actions, forms & async resources","text":"Actions, forms & async resources","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-action-state-title","heading":"Actions, forms & async resources › useActionState","text":"useActionState","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e5d73b5cc18d","heading":"Actions, forms & async resources › useActionState","text":"Purpose: Tracks an Action’s returned state and pending status, with queued dispatches through the same hook. Returns state, dispatchAction, and isPending.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-22f4ef188884","heading":"Actions, forms & async resources › useActionState","text":"When to use: A form submission returns validation errors or a result needed by the UI.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e7fa2aea8ec2","heading":"Actions, forms & async resources › useActionState › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a72e48b0e1ac","heading":"Actions, forms & async resources › useActionState › Example","text":"async function saveProfile(previousState, formData) { // Application API: returns { error: string | null }. return profileApi.save({ name: formData.get('name') }); } function ProfileForm() { const [state, formAction, isPending] = useActionState( saveProfile, { error: null } ); return ( \u003cform action={formAction} aria-busy={isPending}> \u003clabel>Name \u003cinput name=\"name\" required />\u003c/label> \u003cbutton disabled={isPending}>Save\u003c/button> {state.error && \u003cp role=\"alert\">{state.error}\u003c/p>} \u003c/form> ); }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-08975ce30a87","heading":"Actions, forms & async resources › useActionState › Example","text":"The form establishes the Action context. The action receives previousState before its form payload and returns the next UI state.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-3ccc9d7f1ad6","heading":"Actions, forms & async resources › useActionState › Example","text":"When not to use & alternatives: For trivial synchronous state use useState. For server-state caching, invalidation, and retries, or complex form validation, use an appropriate query/form abstraction rather than expecting this hook to supply those features.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-fb87a8f64f74","heading":"Actions, forms & async resources › useActionState › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-86c82e3ca21f","heading":"Actions, forms & async resources › useActionState › Benefits & tradeoffs","text":"Benefits: Combines action results, queueing, and pending state without manual coordination.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-afabc095df1b","heading":"Actions, forms & async resources › useActionState › Benefits & tradeoffs","text":"Tradeoffs: Adds an Action-specific signature and semantics; queueing can delay later submissions.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2ae29a5c5faf","heading":"Actions, forms & async resources › useActionState › Benefits & tradeoffs","text":"Pitfalls & guarantees: Manual dispatch needs an appropriate Action/transition context. Represent expected validation failures in state; thrown failures need error handling, such as an Error Boundary. A React Action is not automatically a Server Function. The optional permalink argument supports specific progressive-enhancement flows with Server Functions; framework support and matching action identity matter.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-09f51ad55f05","heading":"Actions, forms & async resources › useActionState › Benefits & tradeoffs","text":"Related concepts: Form-scoped pending UI · Server authorization · CSRF protections · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-form-status-title","heading":"Actions, forms & async resources › useFormStatus","text":"useFormStatus","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-90f7b82cb98f","heading":"Actions, forms & async resources › useFormStatus","text":"Purpose: Reads the nearest parent form’s submission status and submitted data from a descendant. Import it from react-dom.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-eae808f73e09","heading":"Actions, forms & async resources › useFormStatus","text":"When to use: A reusable submit button or status indicator should work without passing pending state through every layer.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-1e01a9bd5261","heading":"Actions, forms & async resources › useFormStatus › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c7a51dded37b","heading":"Actions, forms & async resources › useFormStatus › Example","text":"import { useFormStatus } from 'react-dom'; function SubmitButton() { const { pending } = useFormStatus(); return \u003cbutton disabled={pending}>{pending ? 'Saving…' : 'Save'}\u003c/button>; } // Render \u003cSubmitButton /> inside ProfileForm's \u003cform> above, // replacing its ordinary submit button.","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-195953d11b1b","heading":"Actions, forms & async resources › useFormStatus › Example","text":"The descendant subscribes to the containing form; it does not need to know which action implementation is used.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-bd2be8416824","heading":"Actions, forms & async resources › useFormStatus › Example","text":"When not to use & alternatives: Use useActionState’s isPending when the form-owning component needs that action’s status, or explicit props for a non-form async button.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-afba760ffd32","heading":"Actions, forms & async resources › useFormStatus › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-150d7ea69648","heading":"Actions, forms & async resources › useFormStatus › Benefits & tradeoffs","text":"Benefits: Encapsulates form-aware presentation and removes pending-state prop drilling.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-408a2444ed53","heading":"Actions, forms & async resources › useFormStatus › Benefits & tradeoffs","text":"Tradeoffs: Couples the consumer to a parent form; placement determines which submission it observes.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f818c5e13040","heading":"Actions, forms & async resources › useFormStatus › Benefits & tradeoffs","text":"Pitfalls & guarantees: It cannot read a form merely returned by the same component, or an unrelated/sibling form. Besides pending, it exposes data, method, and action for the relevant submission. Do not assume it observes arbitrary fetches outside the form’s action lifecycle.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8954f672a030","heading":"Actions, forms & async resources › useFormStatus › Benefits & tradeoffs","text":"Related concepts: Complete form example · Containment and composition · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-optimistic-title","heading":"Actions, forms & async resources › useOptimistic","text":"useOptimistic","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2d8db08bfe38","heading":"Actions, forms & async resources › useOptimistic","text":"Purpose: Layers temporary speculative state over authoritative base state while an Action is pending.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-7b4df1db4070","heading":"Actions, forms & async resources › useOptimistic","text":"When to use: A comment, reaction, or toggle should feel immediate before a server confirms the change.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e7d443b177e4","heading":"Actions, forms & async resources › useOptimistic › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-12faba2ca0ce","heading":"Actions, forms & async resources › useOptimistic › Example","text":"// Fragment inside a component. saveLikes is an application API. const [likes, setLikes] = useState(initialLikes); const [optimisticLikes, addOptimisticLike] = useOptimistic( likes, (current, amount) => current + amount ); const [isPending, startTransition] = useTransition(); function like() { startTransition(async () => { addOptimisticLike(1); try { const confirmedLikes = await saveLikes(); startTransition(() => setLikes(confirmedLikes)); } catch (error) { reportError(error); // Application-level failure feedback. } }); } return \u003cbutton disabled={isPending} onClick={like}>{optimisticLikes}\u003c/button>;","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e145d948be80","heading":"Actions, forms & async resources › useOptimistic › Example","text":"The speculative increment is visible immediately. Success updates the base value; failure leaves the base unchanged once the Action finishes.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e36cc33e51dd","heading":"Actions, forms & async resources › useOptimistic › Example","text":"When not to use & alternatives: Use a pending indicator when failure is common or the operation is irreversible/high impact. A query library’s optimistic mutation support may better coordinate an existing server-state cache; see mutation reconciliation.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-b619888b290d","heading":"Actions, forms & async resources › useOptimistic › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-dbf3bd8faa3f","heading":"Actions, forms & async resources › useOptimistic › Benefits & tradeoffs","text":"Benefits: Reduces perceived latency and centralizes reconciliation over a base value.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-fecd831d3844","heading":"Actions, forms & async resources › useOptimistic › Benefits & tradeoffs","text":"Tradeoffs: Requires a credible rollback/failure experience and careful ordering when mutations overlap.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-6835125e0ef8","heading":"Actions, forms & async resources › useOptimistic › Benefits & tradeoffs","text":"Pitfalls & guarantees: Dispatch optimistic updates in an Action/transition; keep updateFn pure. Commit confirmed data to base state, handle server-generated IDs, and avoid duplicates. Optimistic state is temporary, not durable. This example disables overlapping clicks; multi-request workflows need an explicit ordering policy.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-164b789015ae","heading":"Actions, forms & async resources › useOptimistic › Benefits & tradeoffs","text":"Related concepts: Action lifetime · Transition guards · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-title","heading":"Actions, forms & async resources › use","text":"use","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2fb231702262","heading":"Actions, forms & async resources › use","text":"Purpose: Reads a supported Promise or context during rendering. Pending Promises suspend; rejected Promises reach an Error Boundary.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-018bf37b6b6c","heading":"Actions, forms & async resources › use","text":"When to use: A Suspense-compatible framework/cache supplies a stable Promise, or conditional context reading fits the component.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-fb497a17877a","heading":"Actions, forms & async resources › use › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4b77e6695cb9","heading":"Actions, forms & async resources › use › Example","text":"function ProductDetails({ productPromise }) { const product = use(productPromise); return \u003ch2>{product.name}\u003c/h2>; } // Parent: \u003cSuspense fallback={\u003cp>Loading…\u003c/p>}> // \u003cProductDetails productPromise={stablePromise} /> // \u003c/Suspense> // Provide an Error Boundary for rejected resources.","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-75f14e3390fa","heading":"Actions, forms & async resources › use › Example","text":"The Promise is supplied rather than recreated during every client render. Suspense owns the pending UI.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ce559344fdf8","heading":"Actions, forms & async resources › use › Example","text":"When not to use & alternatives: Prefer await inside async Server Components when it fits. Use a query library/framework for resource ownership; use does not supply caching, invalidation, cancellation, or a fetch trigger by itself.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2c2173b2c81f","heading":"Actions, forms & async resources › use › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ff9566f9779e","heading":"Actions, forms & async resources › use › Benefits & tradeoffs","text":"Benefits: Integrates async reads with Suspense and can read context conditionally.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a9194b01e897","heading":"Actions, forms & async resources › use › Benefits & tradeoffs","text":"Tradeoffs: Requires a resource-lifetime strategy plus loading/error boundaries.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-fba00516fba5","heading":"Actions, forms & async resources › use › Benefits & tradeoffs","text":"Pitfalls & guarantees: Unlike ordinary hooks, use can appear in loops and conditions, but still only inside components/hooks. Do not wrap Promise reads in try/catch. Fresh uncached client-render Promises are unsupported; obtain stable resources from an appropriate cache/framework. Do not confuse use with useEffect: a resource read is not a render side effect.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-748b38858d5c","heading":"Actions, forms & async resources › use › Benefits & tradeoffs","text":"Related concepts: Suspense and streaming · Server vs. Client Components · Caching · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-supporting","heading":"Accessibility & diagnostics","text":"Accessibility & diagnostics","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-id-title","heading":"Accessibility & diagnostics › useId","text":"useId","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-5d72901922e9","heading":"Accessibility & diagnostics › useId","text":"Purpose: Generates an ID suitable for relationships between elements, including consistent SSR/hydration identities.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8d85881a5ddd","heading":"Accessibility & diagnostics › useId","text":"When to use: Reusable fields need unique label/input or description/input associations across multiple instances.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a6e7c142b51f","heading":"Accessibility & diagnostics › useId › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-39b4b8098c5a","heading":"Accessibility & diagnostics › useId › Example","text":"function EmailField() { const id = useId(); return ( \u003c> \u003clabel htmlFor={id}>Email\u003c/label> \u003cinput id={id} type=\"email\" aria-describedby={id + '-help'} /> \u003cp id={id + '-help'}>Use your work email.\u003c/p> \u003c/> ); }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-154ad01b2be7","heading":"Accessibility & diagnostics › useId › Example","text":"One generated ID can derive related IDs without hard-coded collisions between field instances.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2f45b1af5c2f","heading":"Accessibility & diagnostics › useId › Example","text":"When not to use & alternatives: Use data-derived stable keys for lists, database identifiers for records, and domain keys for caches. A fixed ID only fits a guaranteed singleton.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-6912ae940ae8","heading":"Accessibility & diagnostics › useId › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4bbcdb7ab5c0","heading":"Accessibility & diagnostics › useId › Benefits & tradeoffs","text":"Benefits: Supports reusable accessible markup and coordinated server/client rendering.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e06c547bb694","heading":"Accessibility & diagnostics › useId › Benefits & tradeoffs","text":"Tradeoffs: IDs depend on React’s tree coordination and are not portable business identifiers.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9b18e75eaf39","heading":"Accessibility & diagnostics › useId › Benefits & tradeoffs","text":"Pitfalls & guarantees: Do not call it inside a list loop; extract a field component per instance. Multiple independent roots may need coordinated identifierPrefix values. Server and client trees must match; useId does not fix arbitrary hydration mismatches. It is not currently supported in async Server Components.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-38a852ff1965","heading":"Accessibility & diagnostics › useId › Benefits & tradeoffs","text":"Related concepts: Accessibility contracts · Hydration · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-debug-value-title","heading":"Accessibility & diagnostics › useDebugValue","text":"useDebugValue","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f20c91010d16","heading":"Accessibility & diagnostics › useDebugValue","text":"Purpose: Adds a diagnostic label for a custom hook in React DevTools without changing its rendered UI.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-04d4c7e966fa","heading":"Accessibility & diagnostics › useDebugValue","text":"When to use: A reusable library/domain hook exposes a useful internal state such as connection status or cache freshness.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f4c692664422","heading":"Accessibility & diagnostics › useDebugValue › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-75a80779c4c6","heading":"Accessibility & diagnostics › useDebugValue › Example","text":"function useDebuggedOnlineStatus() { const online = useOnlineStatus(); // Shared domain hook, implemented elsewhere. useDebugValue(online, value => value ? 'Online' : 'Offline'); return online; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-5c6f7757367a","heading":"Accessibility & diagnostics › useDebugValue › Example","text":"The formatter produces an inspection label; this snippet illustrates diagnostics, not a second subscription implementation.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-573565d0809c","heading":"Accessibility & diagnostics › useDebugValue › Example","text":"When not to use & alternatives: Use application logging/telemetry for production diagnostics and the Profiler for timing. Simple local hooks may not need custom labels.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2ca8acf804b4","heading":"Accessibility & diagnostics › useDebugValue › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ce3b610a1eb4","heading":"Accessibility & diagnostics › useDebugValue › Benefits & tradeoffs","text":"Benefits: Makes reusable abstractions easier to inspect; an optional formatter defers label-formatting work until inspection.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ef66b139da31","heading":"Accessibility & diagnostics › useDebugValue › Benefits & tradeoffs","text":"Tradeoffs: Only benefits inspection and can clutter DevTools if used indiscriminately.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4e8212622e72","heading":"Accessibility & diagnostics › useDebugValue › Benefits & tradeoffs","text":"Pitfalls & guarantees: Keep formatting pure. Do not perform expensive work before passing the value if it can live in the formatter. Labels do not measure performance and should not be relied on for application behavior.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2418a423541d","heading":"Accessibility & diagnostics › useDebugValue › Benefits & tradeoffs","text":"Related concepts: Custom hook design · Profiler and timing tools · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-custom","heading":"Custom hooks","text":"Custom hooks","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-custom-hooks-title","heading":"Custom hooks › Custom hooks","text":"Custom hooks","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-afd35545bd7e","heading":"Custom hooks › Custom hooks","text":"Purpose: Functions named use… compose hooks into a coherent reusable capability. Each call has independent state unless it explicitly consumes Context or an external store.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c95b9178c7b4","heading":"Custom hooks › Custom hooks","text":"When to use: Several components share a behavior with a meaningful lifecycle and API, such as a debounced value, browser subscription, or domain operation.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-052143033a88","heading":"Custom hooks › Custom hooks › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2e828a43365f","heading":"Custom hooks › Custom hooks › Example","text":"function useDebouncedValue(value, delayMs) { const [debouncedValue, setDebouncedValue] = useState(value); useEffect(() => { const timer = setTimeout(() => setDebouncedValue(value), delayMs); return () => clearTimeout(timer); }, [value, delayMs]); return debouncedValue; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-376c0c38b4ad","heading":"Custom hooks › Custom hooks › Example","text":"The initial value is immediate; subsequent changes use trailing-edge debouncing. Value/delay changes restart the timer, and cleanup prevents an obsolete timer from committing.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-990e788d9479","heading":"Custom hooks › Custom hooks › Example","text":"When not to use & alternatives: Use an ordinary utility function for pure non-hook logic. Do not extract merely to hide lines or create useMount wrappers that conceal dependencies. Use Context/store ownership when callers actually need shared state.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-64d3f25a519f","heading":"Custom hooks › Custom hooks › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a1f897ea2f05","heading":"Custom hooks › Custom hooks › Benefits & tradeoffs","text":"Benefits: Reuses lifecycle logic, hides implementation details, and exposes a testable domain contract.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2f33764e71f5","heading":"Custom hooks › Custom hooks › Benefits & tradeoffs","text":"Tradeoffs: An overly generic API hides dependencies, introduces naming/return-shape commitments, and can obscure state ownership.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-1f5bf52d533b","heading":"Custom hooks › Custom hooks › Benefits & tradeoffs","text":"Pitfalls & guarantees: Document callback stability, return values, errors, cancellation, and controlled/uncontrolled behavior. Debouncing does not cancel an already-started request. Test observable behavior under changed inputs, cleanup, unmount, failures, and obsolete completions; do not assert incidental render counts.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ce68000dee47","heading":"Custom hooks › Custom hooks › Benefits & tradeoffs","text":"Related concepts: Debouncing · Cancellation · Domain consumers · Headless APIs · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-custom-variants","heading":"Custom hooks › Custom hook API variations","text":"Custom hook API variations","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-db37f9160698","heading":"Custom hooks › Custom hook API variations","text":"Choosing an owner: Custom hooks reuse logic; they do not automatically share state across callers. Compare hooks, Context, reducers, and stores, then choose Redux Toolkit or XState only when their model solves a concrete sharing or lifecycle problem.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a3269e8ae8ad","heading":"Custom hooks › Custom hook API variations","text":"Value hooks: Return a focused value or tuple; define initial and subsequent behavior.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-5cd1e5f8ecb7","heading":"Custom hooks › Custom hook API variations","text":"Subscription hooks: Own setup/teardown; use useSyncExternalStore when an external source of truth needs consistent snapshots.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-debea77cf372","heading":"Custom hooks › Custom hook API variations","text":"Domain hooks: Expose meaningful state/actions with provider checks and narrow subscriptions; see Context consumer hooks.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8e6aaae619fa","heading":"Custom hooks › Custom hook API variations","text":"Headless hooks: Return actions, refs, or prop getters while the caller owns markup. Document accessibility, adapters, and event-handler composition.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-review","heading":"Decision process","text":"Decision process","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e7dfe51ba844","heading":"Decision process","text":"Who owns the state? Distinguish client ownership from a remote source of truth, then choose local state, Context, a query cache, or another store.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-cdd2f4c03183","heading":"Decision process","text":"Is this derived data, an event, or synchronization? Calculate during render, act in a handler, or synchronize with an effect accordingly.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-62bdaa5a2dce","heading":"Decision process","text":"Does it need to block paint or be urgent? Reserve layout effects for pre-paint work; transitions for non-urgent UI.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4aaf216cb3ff","heading":"Decision process","text":"What is the lifecycle contract? Specify dependencies, cleanup, cancellation, snapshots, and race handling.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2f65c25a695a","heading":"Decision process","text":"What evidence justifies optimization? Use profiling before relying on memoization, and keep correctness independent of caches.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4135c24eb33a","heading":"Decision process","text":"References: React built-in hooks, use API, useFormStatus, and custom hook design.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-rendering-title","heading":"","text":"React Rendering: Updates, Strategies & Hydration","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-f382e078a156","heading":"","text":"Start with the update cycle, then distinguish Server and Client Components. Learn their boundary rules before following CSR, SSR, hydration and streaming. Finish with recovery, tradeoffs and an end-to-end explanation.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-5b29791ce3d3","heading":"","text":"Core idea: SSR determines how initial HTML is produced; RSC determines which component code stays on the server; hydration connects browser-side React to server-rendered HTML.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-c6065ac331fa","heading":"","text":"The big picture","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-33ea11466b24","heading":"","text":"React updates: render, reconciliation & commit","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-d5b64eebdaea","heading":"","text":"Server vs Client Components: the execution model","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-22822daec235","heading":"","text":"Server Components: data and server-only execution","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-6525f2344e06","heading":"","text":"Client Components: interactivity and browser execution","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-5a3bab14d6ad","heading":"","text":"Boundary rules: imports, props and composition","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-e6c53e10d097","heading":"","text":"CSR vs traditional SSR","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-98d978807363","heading":"","text":"Hydration","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-bc6957c5c686","heading":"","text":"Streaming SSR and Suspense","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-604c1c9f615d","heading":"","text":"How RSC, SSR, and hydration fit together","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-d455a747d1b9","heading":"","text":"Error boundaries: isolate rendering failures","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-45ba6cff0eb3","heading":"","text":"Choosing an approach","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-884397c1e592","heading":"","text":"Key takeaways","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-big-picture","heading":"The big picture","text":"The big picture","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-92c451060d03","heading":"The big picture","text":"ConceptWhat it solvesMain idea","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-3055de577681","heading":"The big picture","text":"CSR (Client-Side Rendering)Where UI is initially renderedBrowser executes React and creates the DOM.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-58f7dc4c637b","heading":"The big picture","text":"SSR (Server-Side Rendering)How initial HTML is deliveredServer renders HTML before the browser runs React.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-2aadaa5deec0","heading":"The big picture","text":"Streaming SSRWhen pieces of HTML arriveServer sends ready HTML in chunks, often around Suspense boundaries.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-1f1fafb133a7","heading":"The big picture","text":"RSC (React Server Components)Where component code executesServer Components run only on the server; their implementation JS isn't sent to the browser.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-big-picture-client-components","heading":"The big picture","text":"Client ComponentsWhere browser-side UI behavior executesTheir implementation JavaScript is shipped to the browser for state, effects and event handlers. They can also be pre-rendered through SSR, then hydrated. See Client Components.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-8d6ef61b461a","heading":"The big picture","text":"HydrationHow server HTML becomes interactiveReact attaches its client-side tree and behavior to existing HTML.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-ad882b421119","heading":"The big picture","text":"Two different decisions:","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-939089072a2e","heading":"The big picture","text":"Rendering strategy and component boundariesRendering strategyCSR or SSRWhere the initial application UI is rendered.Component execution boundaryServer or Client ComponentWhich component implementations execute in the browser.These are independent decisions: a page can combine Server Components, Client Components, and SSR.","kind":"Diagram"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-b7d2b390a3ac","heading":"The big picture","text":"RSC and SSR are not alternatives. A framework such as Next.js can use both on the same page.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-update-cycle","heading":"React updates: render, reconciliation & commit","text":"React updates: render, reconciliation & commit","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-fa03782a56bf","heading":"React updates: render, reconciliation & commit","text":"Trigger → render → commit: An initial root render or a state update schedules work. During render, React calls components to calculate the next UI and performs reconciliation: matching new elements against the previous tree to determine what can be preserved and which changes are needed. Rendering a component does not necessarily change the DOM.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-098733005c7e","heading":"React updates: render, reconciliation & commit","text":"Render phase: Must remain pure. Do not mutate external data, send requests, or subscribe while rendering. React may restart or discard this work, so a render is not proof that the UI appeared.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-77cedcc52fcd","heading":"React updates: render, reconciliation & commit","text":"Commit phase: React applies the selected tree’s DOM changes and attaches refs. Layout effects run before the browser repaints; passive effects synchronize external systems after commit, with timing dependent on the interaction. See effect timing and cleanup.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-087bfef23912","heading":"React updates: render, reconciliation & commit","text":"Diagnosis: Distinguish component execution, DOM mutations, and browser layout/paint. They are separate costs; use the React Profiler and browser performance trace together.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-identity-keys","heading":"React updates: render, reconciliation & commit › Component identity & keys: preserve or reset state deliberately","text":"Component identity & keys: preserve or reset state deliberately","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-d81fb9bcf556","heading":"React updates: render, reconciliation & commit › Component identity & keys: preserve or reset state deliberately","text":"State belongs to a component’s position in React’s tree, identified by element type and, where supplied, its key within the parent. Matching identity preserves state; removing a component or changing its type/key resets its subtree, including effects and uncontrolled input values.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-76f9bf3abd55","heading":"React updates: render, reconciliation & commit › Component identity & keys: preserve or reset state deliberately","text":"// Stable domain IDs preserve each row's state when sorting or inserting. products.map(product => \u003cProductRow key={product.id} product={product} />); // A different account should receive a fresh local editing draft. \u003cProfileEditor key={account.id} initialProfile={account} />;","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-1eab62dc3521","heading":"React updates: render, reconciliation & commit › Component identity & keys: preserve or reset state deliberately","text":"Use stable sibling-unique IDs: Keys need not be globally unique and are not passed as ordinary props. Pass a separate id prop when the child needs it.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-305c6d470f97","heading":"React updates: render, reconciliation & commit › Component identity & keys: preserve or reset state deliberately","text":"Avoid index keys for changing lists: Insertion, deletion, or sorting can attach state to the wrong record. Random keys remount everything on every render. Keys do not prevent rerenders and cannot preserve state across arbitrary parent changes.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-d23efacb547f","heading":"React updates: render, reconciliation & commit › Component identity & keys: preserve or reset state deliberately","text":"Intentional reset: Key an editor by record identity when switching records should reset it. Do not key by each server version unless losing unsaved edits is intended; see server snapshots and local drafts.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-batching","heading":"React updates: render, reconciliation & commit › Automatic batching & state update queues","text":"Automatic batching & state update queues","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-46e26273f016","heading":"React updates: render, reconciliation & commit › Automatic batching & state update queues","text":"With modern createRoot roots, React automatically batches updates from handlers and asynchronous callbacks such as promises and timers, reducing separate renders. Each render still observes a fixed state snapshot; a setter queues an update rather than changing the current variable.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-6ed371346cac","heading":"React updates: render, reconciliation & commit › Automatic batching & state update queues","text":"// Starting at 0, these request the same next value: the result is 1. setCount(count + 1); setCount(count + 1); // Functional updaters compose: starting at 0, the result is 2. setCount(c => c + 1); setCount(c => c + 1);","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-e1f02c699cad","heading":"React updates: render, reconciliation & commit › Automatic batching & state update queues","text":"Batching does not combine distinct intentional user events into one transaction, and it is not a server transaction guarantee. Updaters must be pure. Use flushSync from react-dom sparingly for integrations that require the DOM to update before the next statement; it can hurt performance. For previous-state calculations, prefer functional state updates.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-concurrent","heading":"React updates: render, reconciliation & commit › Concurrent rendering: prioritize responsiveness","text":"Concurrent rendering: prioritize responsiveness","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-44b637c5a976","heading":"React updates: render, reconciliation & commit › Concurrent rendering: prioritize responsiveness","text":"Concurrent rendering lets React interrupt, restart, or discard eligible render work before committing it. This is cooperative scheduling on the JavaScript thread, not parallel component execution. The commit’s DOM mutation work is synchronous; users do not see a partially applied React tree from an interrupted render.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-66a7804131be","heading":"React updates: render, reconciliation & commit › Concurrent rendering: prioritize responsiveness","text":"Use case: Keep a search input update urgent while marking an expensive results update as a transition. Use useTransition for an update you control, or useDeferredValue to let a consumed value lag behind.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-7c2441c88e96","heading":"React updates: render, reconciliation & commit › Concurrent rendering: prioritize responsiveness","text":"Limits: A transition does not debounce requests, make computation faster, or interrupt a single long synchronous calculation inside your function. Split that calculation or use a Web Worker.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-99c9354c6245","heading":"React updates: render, reconciliation & commit › Concurrent rendering: prioritize responsiveness","text":"Correctness: Pure renders and useSyncExternalStore help React work with consistent snapshots. Suspense can coordinate pending UI; transition scheduling does not order overlapping network mutations.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-components","heading":"Server vs Client Components: the execution model","text":"Server vs Client Components: the execution model","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-component-model","heading":"Server vs Client Components: the execution model","text":"Choose which component implementations run in the browser separately from how the initial HTML is delivered. In an RSC-enabled application, Server Components handle server-side rendering logic and data access; Client Components supply browser-side behavior. Both can contribute to the initial page.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-49cc5f41aaf1","heading":"Server vs Client Components: the execution model › Side-by-side","text":"Side-by-side","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-a067acbab239","heading":"Server vs Client Components: the execution model › Side-by-side","text":"AspectServer ComponentClient Component with initial SSR","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-44196943828b","heading":"Server vs Client Components: the execution model › Side-by-side","text":"Runs on serverYesYes, for initial HTML","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-1f73ac16d4ab","heading":"Server vs Client Components: the execution model › Side-by-side","text":"Contributes to initial HTMLYesYes","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-daec4b99825e","heading":"Server vs Client Components: the execution model › Side-by-side","text":"Component implementation JS shippedNoYes","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-79e25f01f0fb","heading":"Server vs Client Components: the execution model › Side-by-side","text":"Executes in browserNoYes","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-7ff35500d35e","heading":"Server vs Client Components: the execution model › Side-by-side","text":"HydratedNoYes","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-1d6dbb67feac","heading":"Server vs Client Components: the execution model › Side-by-side","text":"useState / onClickNoYes","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-90dac0511763","heading":"Server vs Client Components: the execution model › Side-by-side","text":"Direct database accessYesNo, keep DB code server-side","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-1eaae7bfbaa2","heading":"Server Components: data and server-only execution","text":"Server Components: data and server-only execution","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-server-component-definition","heading":"Server Components: data and server-only execution","text":"A Server Component executes in the server/build environment and sends its rendered result through the RSC payload. Use it for server-side reads and non-interactive composition. Its implementation stays out of the browser bundle, but anything it returns or passes to a Client Component can be exposed to the browser. RSC requires framework/bundler support; adding a directive to an ordinary client-only React app does not create a server runtime.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-5b9bc48c7109","heading":"Server Components: data and server-only execution","text":"// Server Component, for example in Next.js App Router async function ProductInfo() { const product = await db.getProduct(); return \u003ch1>{product.name}\u003c/h1>; }","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-cc5d75a35e3a","heading":"Server Components: data and server-only execution","text":"Runs only on the server.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-e453ed72d538","heading":"Server Components: data and server-only execution","text":"Can fetch data and access databases and server-side secrets directly. Keep secrets out of rendered output and props sent to Client Components. Server-state ownership is independent of component execution location. Server execution also does not replace authentication and authorization.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-ab3d0a5d6c7e","heading":"Server Components: data and server-only execution","text":"Can be async and await data during rendering, as in the example above.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-a38ed916ed0b","heading":"Server Components: data and server-only execution","text":"Its component implementation JavaScript is not shipped to the browser.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-5f8d0760f98e","heading":"Server Components: data and server-only execution","text":"Is never hydrated.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-f64a2a26b349","heading":"Server Components: data and server-only execution","text":"Cannot use useState, useEffect, or browser event handlers.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-17aab697e09a","heading":"Server Components: data and server-only execution","text":"Nuance: RSC rendering produces a serialized RSC/Flight payload, not simply an HTML string. SSR can use the resulting tree to produce initial HTML.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-f5a8b68851d2","heading":"Client Components: interactivity and browser execution","text":"Client Components: interactivity and browser execution","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-client-component-definition","heading":"Client Components: interactivity and browser execution","text":"A Client Component is a component whose implementation is available to execute in the browser. Use it for interactive state, event handlers, effects, context providers and browser integrations. It may also render on the server to produce initial HTML; “Client” describes its execution boundary, not an exclusive rendering location. A Client Component can be purely presentational—it does not have to use hooks.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-7667dec4943f","heading":"Client Components: interactivity and browser execution","text":"'use client'; import { useState } from 'react'; function LikeButton() { const [liked, setLiked] = useState(false); return ( \u003cbutton onClick={() => setLiked(true)}> {liked ? 'Liked' : 'Like'} \u003c/button> ); }","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-177e1679fb63","heading":"Client Components: interactivity and browser execution","text":"Its JavaScript is shipped to the browser.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-2b163ff771de","heading":"Client Components: interactivity and browser execution","text":"Can use useState, useEffect, and event handlers. Access browser APIs in effects or handlers, since initial rendering may run on the server.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-13359388f581","heading":"Client Components: interactivity and browser execution","text":"The component itself must be synchronous, but event handlers can be async. Effects can start async work inside an inner function; the useEffect callback itself must not be async, because it must return either a cleanup function or nothing, not a Promise.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-68fb510d264e","heading":"Client Components: interactivity and browser execution","text":"Can also be rendered to HTML on the server on the initial request.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-35fb8ce47e5b","heading":"Client Components: interactivity and browser execution","text":"If server-rendered, it is subsequently hydrated.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-3c75ee6bdc4d","heading":"Client Components: interactivity and browser execution","text":"'use client' does not mean “render only in the browser.” It marks a module dependency boundary: the module and its transitive imports enter the client module graph. A Client Component can still participate in initial SSR. See children and composition patterns for UI composition; the module boundary is a separate concern.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-component-boundaries","heading":"Boundary rules: imports, props and composition","text":"Boundary rules: imports, props and composition","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-6ff70b9c23d9","heading":"Boundary rules: imports, props and composition","text":"Async vs. synchronous components: A synchronous function component returns a React node (often JSX, but also text, null, or other supported values). An async component returns a Promise and can use await during rendering. Server Components support both forms; Client Components cannot be async functions. An async handler still follows event-loop scheduling; async does not move CPU work off the main thread.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-4564a08b75e8","heading":"Boundary rules: imports, props and composition","text":"DistinctionWhat to say precisely","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-9f55046c4b62","heading":"Boundary rules: imports, props and composition","text":"Server Component vs SSRRSC determines where component implementations execute; SSR produces initial HTML. A component rendered on the server during SSR is not automatically a Server Component. A Client Component can participate in SSR and then hydrate.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-df72003d9fd9","heading":"Boundary rules: imports, props and composition","text":"Client Component vs browser-only rendering'use client' does not disable SSR. Accessing window during initial render can still fail. Use effects/handlers for browser access; a framework-specific SSR opt-out is a separate choice for browser-only libraries.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-04b4b759af45","heading":"Boundary rules: imports, props and composition","text":"Module graph vs rendered treeThe directive goes at the top of a module, before imports, and marks a client entry boundary. Its transitive dependencies become client-side dependencies. You need it at entry boundaries, not in every descendant file. Passing server-rendered JSX through children does not import that Server Component into the client graph.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-fb45681e1686","heading":"Boundary rules: imports, props and composition","text":"Async component vs async interactionA Server Component may be async; it need not be. A Client Component function cannot be async, but its event handlers can. React’s use(promise) can suspend a synchronous Client Component on a supported stable Promise; it does not make async Client Components valid. See the use API.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-3f0ce413e172","heading":"Boundary rules: imports, props and composition","text":"Server state vs Server ComponentA Client Component can fetch and cache server-owned data through an API. A Server Component can provide the initial data. Data ownership and component execution are separate decisions; see server state versus client state.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-8e2ec7576ea7","heading":"Boundary rules: imports, props and composition","text":"Server Function vs Server Component'use server' marks Server Functions, not Server Components. A function invoked as an Action handles server-side work such as mutations. Treat remotely callable functions as security boundaries: authenticate, authorize and validate each invocation.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-component-props","heading":"Boundary rules: imports, props and composition › What can cross the server/client boundary?","text":"What can cross the server/client boundary?","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-46ba6835df5a","heading":"Boundary rules: imports, props and composition › What can cross the server/client boundary?","text":"Server → Client props must use React-supported serializable values. This is broader than JSON: React supports values such as Date, Map, Set and supported Promises, as well as React elements in composition. Ordinary functions, arbitrary class instances and DOM nodes cannot simply cross. Server Function references are a supported exception; an ordinary callback is not.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-a74c95d99472","heading":"Boundary rules: imports, props and composition › What can cross the server/client boundary?","text":"A Server Component cannot pass an ordinary onClick={() => ...} handler into a Client Component. Define the interactive handler inside the client boundary. Pass only necessary fields: keeping database access on the server does not stop a secret from leaking through props or rendered output.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-component-composition","heading":"Boundary rules: imports, props and composition › Combine them: server data, client interaction, server-rendered children","text":"Combine them: server data, client interaction, server-rendered children","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-75e86a231c4c","heading":"Boundary rules: imports, props and composition › Combine them: server data, client interaction, server-rendered children","text":"// ProductPage.jsx — Server Component in an RSC-enabled framework import ProductTabs from './ProductTabs'; import ProductDetails from './ProductDetails'; // Server Component export default async function ProductPage() { return ( \u003cProductTabs> \u003cProductDetails /> \u003c/ProductTabs> ); } // ProductTabs.jsx — Client Component 'use client'; import { useState } from 'react'; export default function ProductTabs({ children }) { const [expanded, setExpanded] = useState(false); return ( \u003csection> \u003cbutton onClick={() => setExpanded(value => !value)} aria-expanded={expanded}> Product details \u003c/button> {expanded && children} \u003c/section> ); }","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-15f8a7c9e40d","heading":"Boundary rules: imports, props and composition › Combine them: server data, client interaction, server-rendered children","text":"ProductPage composes the server-rendered details into the client wrapper’s children. ProductTabs imports neither the server implementation nor database code; it controls only whether to show the supplied content. Expanding does not execute ProductDetails in the browser or fetch it on demand: the server-rendered content was already supplied. To fetch on expansion, design an explicit request/navigation boundary.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-csr-ssr","heading":"CSR vs traditional SSR","text":"CSR vs traditional SSR","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-0dedd61819ac","heading":"CSR vs traditional SSR › Client-Side Rendering (CSR)","text":"Client-Side Rendering (CSR)","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-543bfee91977","heading":"CSR vs traditional SSR › Client-Side Rendering (CSR)","text":"Client-side rendering: from request to interactivityRequestThe browser requests the application.HTML shellAn initial document provides the root container.Download JavaScriptLoad the application bundle.Run ReactExecute the component tree in the browser.Create the DOMReact commits the application content.Interactive UIThe rendered controls can respond to input.The browser creates the application content. There is no server-rendered React DOM to hydrate in this example.","kind":"Diagram"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-027a1abed951","heading":"CSR vs traditional SSR › Client-Side Rendering (CSR)","text":"The initial HTML might contain only \u003cdiv id=\"root\">\u003c/div>. React creates the content in the browser:","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-fc05cb236cba","heading":"CSR vs traditional SSR › Client-Side Rendering (CSR)","text":"import { createRoot } from 'react-dom/client'; createRoot(document.getElementById('root')!).render(\u003cCounter />);","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-455815f72682","heading":"CSR vs traditional SSR › Client-Side Rendering (CSR)","text":"There is no hydration because there is no pre-existing React-rendered DOM to reuse.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-3a4bd5997af9","heading":"CSR vs traditional SSR › Server-Side Rendering (SSR)","text":"Server-Side Rendering (SSR)","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-228d2f219ec9","heading":"CSR vs traditional SSR › Server-Side Rendering (SSR)","text":"Server-side rendering: visibility before interactivityRequestThe browser requests the page.Server renders ReactGenerate initial HTML on the server.HTML arrivesThe browser displays the server-rendered content.Visible UIContent such as Count: 0 is already on screen.Interactive UIDownload client JavaScript, then hydrate the client tree so React interactions work.Visibility and React interactivity have separate milestones; JavaScript may download in parallel with HTML delivery.","kind":"Diagram"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-eced62434440","heading":"CSR vs traditional SSR › Server-Side Rendering (SSR)","text":"The server might send \u003cbutton>Count: 0\u003c/button> before the browser has loaded the JavaScript needed to make the button work.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-7325c9e0c70f","heading":"CSR vs traditional SSR › Server-Side Rendering (SSR)","text":"Important: In traditional React SSR, client-capable component code is generally also shipped to the browser. The server render improves initial HTML delivery but does not eliminate browser-side React.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-ba26e2f030c3","heading":"CSR vs traditional SSR › Quick comparison","text":"Quick comparison","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-802466d953d1","heading":"CSR vs traditional SSR › Quick comparison","text":"AspectCSRTraditional SSR","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-bf36070d549e","heading":"CSR vs traditional SSR › Quick comparison","text":"Initial application HTMLGenerated in browserGenerated on server","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-8d94e7b2a6a4","heading":"CSR vs traditional SSR › Quick comparison","text":"Content visible before application JS executesUsually noOften yes","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-e183ad0c3a73","heading":"CSR vs traditional SSR › Quick comparison","text":"HydrationNoYes, for client React tree","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-2d92645f1515","heading":"CSR vs traditional SSR › Quick comparison","text":"Browser JS needed for interactivityYesYes","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-hydration","heading":"Hydration","text":"Hydration","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-5ae4a429c1cf","heading":"Hydration","text":"Hydration is React connecting client-side component logic to HTML that already exists in the browser.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-1ca97eea174c","heading":"Hydration","text":"import { useState } from 'react'; function Counter() { const [count, setCount] = useState(0); return ( \u003cbutton onClick={() => setCount(c => c + 1)}> Count: {count} \u003c/button> ); }","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-549ec46c8e13","heading":"Hydration","text":"Server output:","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-c90929df9c16","heading":"Hydration","text":"\u003cdiv id=\"root\">\u003cbutton>Count: 0\u003c/button>\u003c/div>","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-3e00f4221415","heading":"Hydration","text":"Browser hydration:","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-e8324a1ce4c8","heading":"Hydration","text":"import { hydrateRoot } from 'react-dom/client'; hydrateRoot(document.getElementById('root')!, \u003cCounter />);","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-c68efc1c8da2","heading":"Hydration","text":"Hydration: reuse existing HTMLServer HTML is visibleThe browser shows Count: 0; its React click handler is not active yet.Client React hydratesExecute browser-side component logic and connect it to the existing DOM.State updates workClicking the existing button updates its count.Hydration reuses server-rendered markup. The server and client must agree on the initial output.","kind":"Diagram"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-5a91cb115836","heading":"Hydration › Hydration mismatch","text":"Hydration mismatch","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-caf84b0b9748","heading":"Hydration › Hydration mismatch","text":"Server and browser should produce the same initial output. This can fail:","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-df1729f9dce2","heading":"Hydration › Hydration mismatch","text":"function RandomValue() { return \u003cdiv>{Math.random()}\u003c/div>; }","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-a0fa30680f46","heading":"Hydration › Hydration mismatch","text":"The server might render 0.42 while the client initially renders 0.81. Avoid nondeterministic values in initial rendering, or defer browser-only values until after hydration. See effect setup and cleanup for an example of browser-side work.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-e60d2c96d89b","heading":"Hydration › Hydration mismatch","text":"Remember: In the browser, React’s render phase computes the next UI tree; reconciliation compares trees, and the commit phase applies DOM changes. SSR produces HTML; hydration reuses that HTML while connecting client-side React logic.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-streaming","heading":"Streaming SSR and Suspense","text":"Streaming SSR and Suspense","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-b049da3753c7","heading":"Streaming SSR and Suspense","text":"Traditional SSR may wait for a slow section before sending the full page. Streaming SSR lets the server send ready sections earlier.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-20a98fe87885","heading":"Streaming SSR and Suspense","text":"import { Suspense } from 'react'; function ProductPage() { return ( \u003c> \u003cHeader /> \u003cProductDetails /> \u003cSuspense fallback={\u003cReviewsSkeleton />}> \u003cReviews /> \u003c/Suspense> \u003c/> ); }","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-d6dbe883fdd4","heading":"Streaming SSR and Suspense","text":"Illustrative timeline:","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-fdb9ebdcf592","heading":"Streaming SSR and Suspense","text":"Streaming SSR: a progressive delivery timeline0 msServerHeader and product are ready; reviews are still loading. Send HTML chunk 1.BrowserShow the header, product, and reviews skeleton.~500 msServerReviews are still pending.BrowserClient JavaScript is available; hydration may begin for ready interactive parts.2000 msServerReviews finish. Send HTML chunk 2.BrowserReviews replace the skeleton. Interactive parts can hydrate.Illustrative timings. Both HTML chunks travel through the same HTTP response; streaming and hydration can overlap.","kind":"Diagram"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-76d7f05e7718","heading":"Streaming SSR and Suspense","text":"The chunks travel through the same HTTP response. Suspense boundaries help React isolate content that is not ready. Selective hydration lets React hydrate Suspense boundaries independently and prioritise boundaries the user interacts with. Hydration can overlap with streaming rather than waiting for the whole page. The data source must support Suspense; fetching inside useEffect does not trigger a Suspense fallback.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-86f25b6ef050","heading":"Streaming SSR and Suspense","text":"Distinction: Streaming controls when HTML arrives; hydration controls when browser-side React becomes active.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-473fe748c902","heading":"Streaming SSR and Suspense","text":"For state, effects, refs, and async APIs within these execution boundaries, see React Hooks.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-lifecycle","heading":"How RSC, SSR, and hydration fit together","text":"How RSC, SSR, and hydration fit together","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-129dbb5d2f68","heading":"How RSC, SSR, and hydration fit together","text":"// Server Component async function ProductPage() { const product = await db.getProduct(); return ( \u003c> \u003ch1>{product.name}\u003c/h1> \u003cLikeButton /> \u003c/> ); }","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-8319309b5c97","heading":"How RSC, SSR, and hydration fit together","text":"Combine the two: ProductPage handles server-side data fetching, while LikeButton, the Client Component from the component-boundary example, handles interactive state.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-5d5361d9f655","heading":"How RSC, SSR, and hydration fit together › Initial page load","text":"Initial page load","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-a7663d01236a","heading":"How RSC, SSR, and hydration fit together › Initial page load","text":"Initial page load: RSC, SSR, and hydration togetherOn the serverExecute ProductPageThe Server Component fetches the product.Produce the RSC payloadSerialize the result, including a reference to the LikeButton Client Component.Render initial HTML with SSRInclude both the product heading and LikeButton markup.Browser displays the pageMacBook Pro and the Like button are visible.ProductPage · Server ComponentImplementation JavaScript stays on the server. This component is not hydrated.LikeButton · Client ComponentSend its JavaScript to the browser, execute it, and hydrate. The Like interaction now works.Both component types contribute to initial HTML, while the Client Component supplies browser-side interaction logic.","kind":"Diagram"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-a9f9691222f3","heading":"How RSC, SSR, and hydration fit together › Subsequent client-side navigation","text":"Subsequent client-side navigation","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-25d1c384a4de","heading":"How RSC, SSR, and hydration fit together › Subsequent client-side navigation","text":"Client-side navigation with Server ComponentsNavigate to /products/2The framework handles a client-side navigation.Execute Server ComponentsThe server renders the next product’s component result.Return the RSC payloadSend the new serialized component result.Reconcile in the browserReact updates the existing UI using the new result.A client-side navigation does not necessarily download a new full HTML document. RSC updates do not require SSR on every navigation.","kind":"Diagram"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-bc8866b6723f","heading":"How RSC, SSR, and hydration fit together › Subsequent client-side navigation","text":"A new full HTML document is not necessarily generated or downloaded on each client-side navigation. This is why RSC does not require SSR for every update.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-error-boundaries","heading":"Error boundaries: isolate rendering failures","text":"Error boundaries: isolate rendering failures","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-551f7b0f8553","heading":"Error boundaries: isolate rendering failures","text":"Purpose: Replace a failed React subtree with a fallback while preserving useful surrounding UI. Choose boundaries by independent recovery and user tasks, not automatically around every component.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-6d4d7f9ea4f6","heading":"Error boundaries: isolate rendering failures","text":"Example: Put recommendations behind a boundary so a rendering exception does not remove product details and the purchase controls. Keep a broader route boundary for failures that make the route unusable.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-df3f65b5c6fc","heading":"Error boundaries: isolate rendering failures","text":"import { Component } from 'react'; class ErrorBoundary extends Component { state = { failed: false }; static getDerivedStateFromError() { return { failed: true }; } componentDidCatch(error, info) { // Send error and component stack to the application's reporting service. } render() { return this.state.failed ? this.props.fallback : this.props.children; } } // Usage: \u003cErrorBoundary fallback={\u003cp>Recommendations unavailable.\u003c/p>}> // \u003cRecommendations /> // \u003c/ErrorBoundary>","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-4b81b040e0ba","heading":"Error boundaries: isolate rendering failures","text":"Scope: Boundaries catch descendant rendering, constructor, and lifecycle errors. They do not catch their own errors, ordinary event-handler exceptions, arbitrary rejected promises/timer callbacks, or the server render itself. Handle request errors through the data layer and event failures with explicit error handling. Suspense-enabled render reads can surface errors to a boundary through their integration.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-01b8838e5708","heading":"Error boundaries: isolate rendering failures","text":"Use when: A route or widget can fail independently and has a meaningful fallback. A framework’s route error handling or a maintained boundary library often supplies reset/reporting integration. React has no built-in function-component error-boundary hook.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-ca29c6484229","heading":"Error boundaries: isolate rendering failures","text":"Benefits and tradeoffs: Limits UI failure scope and improves diagnostics. Too many boundaries can conceal broken workflows behind generic messages; never imply a purchase succeeded because its UI failed. Define reset behavior when the resource changes or the user retries; a remount via a changed key resets subtree state but cannot repair invalid data.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-57dcb3ce2abd","heading":"Error boundaries: isolate rendering failures","text":"Compare: Suspense handles supported pending rendering; error boundaries handle rendering failure. Neither is a retry policy or circuit breaker. Request timeouts and server failure containment address different layers.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-choices","heading":"Choosing an approach","text":"Choosing an approach","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-component-choices","heading":"Choosing an approach › When to choose which—and the costs","text":"When to choose which—and the costs","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-193891960ce7","heading":"Choosing an approach › When to choose which—and the costs","text":"Keep reads and static composition server-side when an RSC framework is available: direct server data access and less client JavaScript. Costs include server latency, boundary serialization and potential data waterfalls; parallelize independent reads and use Suspense/streaming intentionally.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-408861584b1f","heading":"Choosing an approach › When to choose which—and the costs","text":"Use Client Components for interactive regions: state, effects, providers and browser APIs. Costs include downloaded JavaScript, hydration work when SSR is used and client execution. Place boundaries near interaction; marking the whole page client-side can pull large dependencies into the bundle.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-1c5ebe61dd2a","heading":"Choosing an approach › When to choose which—and the costs","text":"Do not prescribe RSC for every application: a client-rendered React app with an API/query cache can be simpler for highly interactive authenticated tools. SSR can also work without RSC. Choose based on delivery, SEO, latency, interaction and operational requirements.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-0cc5a5c71787","heading":"Choosing an approach › When to choose which—and the costs","text":"Explanation: “A Server Component runs only in the server/build environment; its implementation is not hydrated in the browser. A Client Component provides browser-side behavior and may first be rendered to HTML on the server. I choose component boundaries separately from the initial rendering strategy.”","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-da1a066ac4da","heading":"Choosing an approach › When to choose which—and the costs","text":"CSR: Useful for highly interactive applications where server-rendered initial HTML is not important.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-1f7e6c1eecbd","heading":"Choosing an approach › When to choose which—and the costs","text":"SSR: Useful when the first response should already contain meaningful HTML, including for content visibility and SEO.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-b363c19bfdd6","heading":"Choosing an approach › When to choose which—and the costs","text":"Streaming SSR: Useful when parts of a page depend on slow data and can be separated with Suspense.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-f15dc347e24c","heading":"Choosing an approach › When to choose which—and the costs","text":"Server Components: Good default for server data fetching, non-interactive UI, and keeping implementation JS out of the browser.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-54d39523d46d","heading":"Choosing an approach › When to choose which—and the costs","text":"Client Components: Needed for local interactive state, effects, browser APIs, and event handlers.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-bcb51c95d37a","heading":"Choosing an approach › When to choose which—and the costs","text":"In Next.js App Router, a practical default is to use Server Components for server-only work and add Client Components at interactive boundaries, while letting SSR produce the initial page HTML.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-review","heading":"Key takeaways","text":"Key takeaways","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-5b1357d79d42","heading":"Key takeaways","text":"CSR creates the UI in the browser. SSR generates initial HTML on the server and then hydrates client-side React so the page becomes interactive. Streaming SSR sends that HTML progressively, often using Suspense boundaries, so slow sections do not block ready content. React Server Components run exclusively on the server and send a serialized result rather than their component implementation JavaScript; they are never hydrated. Client Components can still contribute to server-rendered HTML, but their JavaScript is sent to the browser and hydrated. Modern Next.js combines RSC, SSR, streaming, and hydration rather than treating them as mutually exclusive choices.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-8d13a3c770aa","heading":"Key takeaways › Five things to remember","text":"Five things to remember","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-889f4b18780b","heading":"Key takeaways › Five things to remember","text":"CSR: React creates the DOM in the browser.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-c9d39d38549a","heading":"Key takeaways › Five things to remember","text":"SSR: The server generates initial HTML.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-ef24389f534a","heading":"Key takeaways › Five things to remember","text":"Streaming: Ready HTML can arrive before slower sections finish.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-34c1875ad87a","heading":"Key takeaways › Five things to remember","text":"RSC: Server-only component code stays on the server; no hydration for those components.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-ebe6601f8e0a","heading":"Key takeaways › Five things to remember","text":"Hydration: Browser-side React activates previously server-rendered interactive UI.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-d8c46b1ac722","heading":"Key takeaways › Five things to remember","text":"One-line summary: SSR is about HTML generation, RSC is about component execution boundaries, streaming is about delivery timing, and hydration is about client interactivity.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"routing-navigation-title","heading":"","text":"Routing & Navigation","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-4adc9a0911e6","heading":"","text":"Treat navigation as a complete lifecycle: URL, data, errors, history, accessibility, and unsaved work.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-ac329b5e25b5","heading":"","text":"Navigation models: document loads vs. client transitions","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-f1977a1032b6","heading":"","text":"History API: push, replace & back/forward","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-aba52b1eb0ce","heading":"","text":"Nested routes: layout, data & error ownership","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-a5141f8fc547","heading":"","text":"Navigation data: cancellation, prefetching & revalidation","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-1e4265ca6321","heading":"","text":"Scroll, focus & announcements after navigation","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-92257f301056","heading":"","text":"Unsaved changes: blockers, drafts & submission races","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-230198a873fe","heading":"","text":"Review: describe one complete navigation","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"routing-model","heading":"Navigation models: document loads vs. client transitions","text":"Navigation models: document loads vs. client transitions","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"routing-model-definition","heading":"Navigation models: document loads vs. client transitions","text":"Document navigation asks the browser to load a document. Client-side routing updates the URL and rendered route within the current document. A hybrid framework can serve the initial HTML, then perform client transitions; routing is distinct from CSR/SSR rendering choices.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-5808e8230ea9","heading":"Navigation models: document loads vs. client transitions","text":"Use: Client transitions support persistent layouts, local interaction state, and route-level loading. Document navigation is simpler for independent pages and provides native loading/history behavior. Both need valid URLs, authorization, accessible navigation, and a working direct-load path.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-3184e2853d2c","heading":"Navigation models: document loads vs. client transitions","text":"Contract: Preserve real anchors for destinations and buttons for actions. A router may intercept an eligible same-origin click, but must preserve modified clicks, downloads, target behavior, and external destinations. On a static SPA host, deep links need an appropriate fallback; avoid turning asset failures or real 404s into misleading HTML success responses.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-24997a31868e","heading":"Navigation models: document loads vs. client transitions","text":"State ownership: Paths identify resources; query parameters represent shareable view state. Keep one authoritative owner and validate parsed values using the existing URL-state model.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"routing-history","heading":"History API: push, replace & back/forward","text":"History API: push, replace & back/forward","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"routing-history-definition","heading":"History API: push, replace & back/forward","text":"The History API manages same-document history entries. pushState adds an entry; replaceState changes the current entry. Neither dispatches popstate immediately. Back/forward traversal between relevant history entries can dispatch popstate, which a client router uses to restore the route.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-0d921bc251a0","heading":"History API: push, replace & back/forward","text":"function renderRoute() { const url = new URL(location.href); console.log('Render route:', url.pathname, url.searchParams.get('tab')); } function navigate(path, { replace = false } = {}) { const url = new URL(path, location.href); if (url.origin !== location.origin) throw new Error('Same-origin routes only'); history[replace ? 'replaceState' : 'pushState'](null, '', url); renderRoute(); // pushState does not emit popstate } window.addEventListener('popstate', renderRoute); // navigate('/orders?tab=open'); // Adds a history entry // navigate('/orders?tab=all', { replace: true });","kind":"Code"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-c36bfcd7fa2c","heading":"History API: push, replace & back/forward","text":"Choose: Push for a meaningful destination the user should return from. Replace for canonicalization, redirects, or intermediate edits that should not flood history. History state is structured-serializable metadata, not a durable database or a suitable place for large sensitive payloads.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-6d4dbeb35789","heading":"History API: push, replace & back/forward","text":"Use a router: This example illustrates the primitive; it omits route matching, cancellation, focus, loaders, and blockers. Use an established router/framework for application navigation. Hash routing can work without server fallback, but has URL and fragment-navigation tradeoffs.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"routing-boundaries","heading":"Nested routes: layout, data & error ownership","text":"Nested routes: layout, data & error ownership","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"routing-boundaries-definition","heading":"Nested routes: layout, data & error ownership","text":"Nested routes express a hierarchy of URL segments and UI ownership: an orders layout can persist while its list or detail outlet changes. A layout route may group UI without adding a path segment. Nest routes when they share a lifecycle, not merely because their components are visually adjacent.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-d91115324b88","heading":"Nested routes: layout, data & error ownership","text":"Example: /orders/:orderId owns the selected order’s loader and detail error boundary; its parent owns navigation and the list layout. A failed detail request should show a local recovery state while preserving useful navigation.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-b07f02edcb08","heading":"Nested routes: layout, data & error ownership","text":"Loading: Independent parent/child requests should start in parallel when supported. Await a parent only for a real dependency such as a required identifier. Avoid fetching everything in nested mount effects, which can create waterfalls; see performance techniques.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-89faf9c5ae61","heading":"Nested routes: layout, data & error ownership","text":"Error boundaries: Router loader/action errors and React render errors have related but distinct interception mechanisms. React boundaries do not catch every async rejection or event-handler exception; routers can integrate loader failures into route boundaries. Place retry UI at the owner of the failed operation; see rendering failure isolation.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-4661f5113791","heading":"Nested routes: layout, data & error ownership","text":"Security: Client route guards improve UX but cannot enforce permissions. Loaders, mutations, and APIs must validate identity and resource authorization on the server.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"routing-data","heading":"Navigation data: cancellation, prefetching & revalidation","text":"Navigation data: cancellation, prefetching & revalidation","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"routing-data-definition","heading":"Navigation data: cancellation, prefetching & revalidation","text":"A navigation has a data lifecycle: start the needed work, show useful pending UI, commit the winning result, and handle failure or cancellation. Separate the route’s current location from a pending destination so stale completions cannot replace newer navigation.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-27704561752f","heading":"Navigation data: cancellation, prefetching & revalidation","text":"Example: The user opens order A and immediately switches to B. Pass the router-provided AbortSignal to fetch where available; ignore A’s obsolete result even if cancellation arrives too late. fetch abort does not guarantee that the server stopped processing. See AbortController.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-4fea741281a7","heading":"Navigation data: cancellation, prefetching & revalidation","text":"Prefetch: Fetch route code or data on strong intent, such as focus/hover, or for likely destinations. Balance latency savings against bandwidth, authorization-sensitive cache contents, and wasted work. Avoid prefetching mutations or URLs that incorrectly cause side effects.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-75792b3a6d87","heading":"Navigation data: cancellation, prefetching & revalidation","text":"Cache ownership: Coordinate router loaders with an existing query cache rather than creating two independent stale copies. After a mutation, invalidate/revalidate the authoritative data according to the framework contract. Deduplicate overlapping loads and retain a policy for back/forward restoration; see server-state lifecycle.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"routing-accessibility","heading":"Scroll, focus & announcements after navigation","text":"Scroll, focus & announcements after navigation","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"routing-accessibility-definition","heading":"Scroll, focus & announcements after navigation","text":"Same-document navigation does not automatically reproduce a document load’s accessibility behavior. Define focus management, document title updates, route announcements, and scroll restoration as part of the router contract.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-43b1b0346e12","heading":"Scroll, focus & announcements after navigation","text":"New destination: after the winning route commits, update the title and usually focus a meaningful heading or main region using tabindex=-1. Avoid stealing focus for background refreshes.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-e8442abed122","heading":"Scroll, focus & announcements after navigation","text":"Fragment navigation: reveal the target and account for sticky-header offsets; move focus when needed for keyboard orientation.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-aa8afd8a0e3a","heading":"Scroll, focus & announcements after navigation","text":"Back/forward: restore a meaningful history position rather than always scrolling to the top. Wait until content/layout can support that position.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-ebe816829e44","heading":"Scroll, focus & announcements after navigation","text":"Announcements: use a restrained live-region message if the transition otherwise lacks a clear announcement; avoid duplicate announcements from focus and live regions.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-42c88a164985","heading":"Scroll, focus & announcements after navigation","text":"Implementation: Prefer your router’s restoration facilities; if using history.scrollRestoration='manual', the application owns restoration and must handle images, deferred data, and virtualized lists. Test keyboard and screen-reader journeys using focus foundations.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"routing-unsaved","heading":"Unsaved changes: blockers, drafts & submission races","text":"Unsaved changes: blockers, drafts & submission races","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"routing-unsaved-definition","heading":"Unsaved changes: blockers, drafts & submission races","text":"An unsaved-change guard protects a dirty draft during navigation. Dirty means the current draft differs from its saved baseline, not merely that the user has focused a field. Update the baseline after a confirmed save; preserve the draft on failure.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-867ff0562ef1","heading":"Unsaved changes: blockers, drafts & submission races","text":"Use: A router blocker for internal transitions with a real risk of losing work. It should explain the loss, offer stay/discard choices, and resume exactly the blocked transition after confirmation. Do not mutate history repeatedly to trap the user.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-25e7dbf5bc15","heading":"Unsaved changes: blockers, drafts & submission races","text":"External exits: Attach beforeunload only while genuinely dirty. Browsers control the warning text and may require prior interaction; the event is unreliable on some mobile termination paths and can affect back/forward caching in some browsers. Use draft persistence or autosave where appropriate rather than treating the prompt as a guarantee.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"search-ee809eb3070c","heading":"Unsaved changes: blockers, drafts & submission races","text":"Submission races: A pending save is not a successful save. Define whether navigation waits, cancels local work, or lets server processing continue. Protect duplicate submissions with the server’s idempotency policy, and handle failures after the user leaves. See form submission contracts and server snapshots and drafts.","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"routing-review","heading":"Review: describe one complete navigation","text":"Review: describe one complete navigation","kind":"Notes"},{"page":"routing-navigation.html","topic":"Routing & Navigation","anchor":"routing-review-definition","heading":"Review: describe one complete navigation","text":"Walk through direct loading, a link click, pending data, cancellation, commit, focus/scroll, and back navigation. Then add a failed loader and a dirty form. Explain ownership and failure behavior before naming a routing library. A correct URL update alone is not a complete navigation implementation.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"system-design-autocomplete-title","heading":"","text":"Case Study: Reusable Autocomplete","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-302f30496daa","heading":"","text":"Design a reusable imported component from UI behavior to package exports: framework-independent logic, accessible interactions, asynchronous data, and explicit tradeoffs.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-d97bcd8416bb","heading":"","text":"Step 1 · Understand the reusable component","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-9905cbb772b5","heading":"","text":"UI sketch: query, active option & feedback","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-5d1d69ce623a","heading":"","text":"Component sketch · host page, slots and event paths","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-2da0f51598b6","heading":"","text":"Step 2 · Blueprint and dependency boundaries","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-37f300138af6","heading":"","text":"Public API: types, identity & ownership","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-bff793a25fa3","heading":"","text":"Step 3 · State and transition model","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-1473c212a937","heading":"","text":"Async search: debounce, cancellation & stale-result guards","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-73e2302279d7","heading":"","text":"Accessibility: combobox/listbox as a contract","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-5c2926b9f067","heading":"","text":"Presentation and host adapters: imported, not embedded","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-b9af8f3f156b","heading":"","text":"Directory structure: core, adapters & public exports","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-84486e59f8a7","heading":"","text":"Packaging, SSR & compatibility","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-d67b7e81698e","heading":"","text":"Performance, caching & fallback decisions","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-c32e3722eb25","heading":"","text":"Verification: test interactions, races and the packed artifact","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-c3d2ddcc7cad","heading":"","text":"Step 4 · Wrap up and defend the tradeoffs","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-requirements","heading":"Step 1 · Understand the reusable component","text":"Step 1 · Understand the reusable component","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-requirements-definition","heading":"Step 1 · Understand the reusable component","text":"Prompt: Design an importable, single-select autocomplete for users, products, or locations. Consumers supply item identity, labels, data access, and rendering. The package owns a predictable accessible interaction contract; it does not own the host application’s domain model or backend.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-functional","heading":"Step 1 · Understand the reusable component › Functional requirements","text":"Functional requirements","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-89e4513458fb","heading":"Step 1 · Understand the reusable component › Functional requirements","text":"Type a query, see suggestions, navigate enabled options with keyboard/pointer, select an item, clear the value, and dismiss the popup.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-69a50d30fac3","heading":"Step 1 · Understand the reusable component › Functional requirements","text":"Support local in-memory suggestions and asynchronous remote sources through the same data-source interface.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-6d8600feda48","heading":"Step 1 · Understand the reusable component › Functional requirements","text":"Expose distinct input text, selected item, open state, and highlighted option; provide controlled and uncontrolled ownership modes with clear change reasons.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-2c08225f4417","heading":"Step 1 · Understand the reusable component › Functional requirements","text":"Represent loading, empty, failed, disabled, and retry states. Preserve correct behavior during rapid input, IME composition, and out-of-order responses.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-5a5c4fd51f72","heading":"Step 1 · Understand the reusable component › Functional requirements","text":"Provide a headless core, a React adapter, optional default UI/styles, and supported customization without deep internal imports.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-quality","heading":"Step 1 · Understand the reusable component › Non-functional requirements","text":"Non-functional requirements","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-401535fdc4e4","heading":"Step 1 · Understand the reusable component › Non-functional requirements","text":"Accessibility: Follow the editable combobox/listbox interaction pattern with meaningful names and correct focus/active-option behavior; verify browser/screen-reader combinations.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-281afbcf329c","heading":"Step 1 · Understand the reusable component › Non-functional requirements","text":"Responsiveness: Keep keystroke rendering immediate; choose an illustrative 200 ms debounce for remote queries and render a bounded result set (for example 20). Measure typing/interaction latency separately from network latency.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-ee1f29518e11","heading":"Step 1 · Understand the reusable component › Non-functional requirements","text":"Correctness: The newest eligible query/context owns the displayed results; one user selection yields one semantic onValueChange notification.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-a7617839c5ae","heading":"Step 1 · Understand the reusable component › Non-functional requirements","text":"Packaging: Side-effect-safe imports, explicit exports, types, peer React dependency in the adapter, SSR-safe initialization, and disposal of timers/requests/listeners.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-e4a3be1c70e1","heading":"Step 1 · Understand the reusable component › Non-functional requirements","text":"Isolation: No global shared personalized cache, router dependency, Redux/XState requirement, or hard-coded authentication/API URL.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-scope","heading":"Step 1 · Understand the reusable component › In scope and out of scope","text":"In scope and out of scope","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-600d72c602e9","heading":"Step 1 · Understand the reusable component › In scope and out of scope","text":"In scope: A framework-independent TypeScript controller and optional React integration, asynchronous orchestration, single selection, headless slots, default non-portaled results, and small bounded lists. Form integration happens through adapters.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-8656cb560985","heading":"Step 1 · Understand the reusable component › In scope and out of scope","text":"Out of scope: Multi-select, arbitrary free-text creation, a search-engine backend, infinite results, a universal design system, and complete bindings for every framework. Portals, virtualization, grouped options, and other adapters are explicit extensions with additional accessibility contracts.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-f7351b6bbdb4","heading":"Step 1 · Understand the reusable component › In scope and out of scope","text":"Validate ambiguity: “Agnostic” means domain/data/presentation independence and a framework-independent core; the React adapter itself requires React. It does not promise that the same React component can be imported into Vue unchanged. Follow the four-step design framework.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-wireframe","heading":"UI sketch: query, active option & feedback","text":"UI sketch: query, active option & feedback","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-wireframe-definition","heading":"UI sketch: query, active option & feedback","text":"Sketch the visible contract before the implementation. Input text is not the selected item, and keyboard highlight is not selection. The following is a static design wireframe, not a live autocomplete.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-80c97fa755ca","heading":"UI sketch: query, active option & feedback","text":"People picker · keyboard navigation in progressChoose a personaliInput queryAlice ChenActive option · not selected yetAlina RossiAnother suggestionAli PatelDisabled · cannot select2 selectable suggestions · Arrow keys navigate · Enter selects · Escape closesDOM focus stays in the input. Active-option state identifies Alice; selected value changes only when selection is committed.","kind":"Diagram"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-f9c2d0d0d6da","heading":"UI sketch: query, active option & feedback","text":"StateUI behaviorConsideration","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-e25a2ff42547","heading":"UI sketch: query, active option & feedback","text":"Typing / loadingKeep input responsive; expose a quiet busy/status signal.Do not announce every keystroke or present an old-query result as current.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-b22e9b6b3420","heading":"UI sketch: query, active option & feedback","text":"No matchesShow a distinct empty-results message.An empty response is different from a failed request.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-cda028f5422f","heading":"UI sketch: query, active option & feedback","text":"FailureShow a safe error and retry action without clearing the draft.Do not turn infrastructure failures into “no matches.”","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-50d28798a4a8","heading":"UI sketch: query, active option & feedback","text":"Selection / clearCommit item identity; display its label; clear according to documented policy.If the user edits the selected label, this case clears selection and notifies the host.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-3dd55f16d678","heading":"UI sketch: query, active option & feedback","text":"DismissalEscape closes the popup without submitting the form; Tab follows normal focus navigation.Avoid trapping focus or selecting merely because focus left.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-e669f139fac3","heading":"UI sketch: query, active option & feedback","text":"Mobile: Avoid results hidden by the virtual keyboard; keep touch targets usable and do not rely on hover. Define positioning/collision behavior if a portal/popover extension is added.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-component-map","heading":"Component sketch · host page, slots and event paths","text":"Component sketch · host page, slots and event paths","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-component-map-definition","heading":"Component sketch · host page, slots and event paths","text":"Draw the consumer page and imported component first, then expand its slots and scoped controller. This is component composition, not a requirement to deploy a service for each box.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-ae0e76e9405f","heading":"Component sketch · host page, slots and event paths","text":"Page and component sketch · imported autocompleteOpen full-size diagramScroll horizontally on smaller screens.Autocomplete: host page and component compositionThe host form imports the React entry point. The root owns one controller instance and distributes bindings. Input emits query/key events, Option emits selection events, and the adapter reads snapshots. DOM focus stays on the input.props ↓ / onChange ↑input bindingsitems / activeKeyrequest statusitem propsinput / key eventsSELECT(key)snapshot subscriptionHost page / FormDomain value; validation; API/cache adapterAutocomplete.RootOne scoped owner; controlled prop contractAutocomplete.InputQuery, key and composition eventsAutocomplete.ResultsListbox; loading/empty/error statesAutocomplete.StatusPolite feedback and safe retry UIAutocomplete.Option × NStable key / ID; pointer selectionReact adapter + controller instanceSubscriptions, state snapshots and semantic callbacksSolid arrows show composition/bindings; dashed arrows show events and snapshot subscription. The root/adapter refers to one controller instance, not a separate controller in every slot. Input keeps DOM focus; Option sends a semantic selection event.","kind":"Diagram"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-89d96b7de069","heading":"Component sketch · host page, slots and event paths","text":"Sketch it in this order: Host form → imported root → input/results/status → option instances → single state owner → injected data source. Keep selected value, query text and active option distinct. Expand the controller/data-source box in the next architecture sketch.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-blueprint","heading":"Step 2 · Blueprint and dependency boundaries","text":"Step 2 · Blueprint and dependency boundaries","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-blueprint-definition","heading":"Step 2 · Blueprint and dependency boundaries","text":"Separate domain adapters, interaction state, framework integration, and presentation. A UI framework or an API client should be replaceable without rewriting selection semantics.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-25d32e432eac","heading":"Step 2 · Blueprint and dependency boundaries","text":"Architecture sketch · autocomplete core and data boundaryOpen full-size diagramScroll horizontally on smaller screens.Autocomplete: core, framework adapter and data boundaryHost props enter the React adapter, which dispatches events and reads immutable snapshots from a TypeScript controller. A pure reducer updates state. An async coordinator owns request generation and cancellation; an injected source accesses a local index or remote API/cache.config / controlled changesdispatch / snapshotsjobs / resultsstate + event → next statequery + signal / items or errorlocal call OR HTTPSHost applicationItem model, labels, keys, auth/cache scopeReact adapter + optional UIBindings, stable IDs, lifecycle and subscriptionsFramework-independent controllerImmutable snapshot; dispatch and subscribeAsync coordinatorDebounce, AbortSignal, generation guardsPure reducer / selectorsValid transitions; derived active/selected stateInjected DataSource\u003cT>Host adapter; validation; cache/cancellation policyLocal index OR remote API/cacheNo hard-coded endpoint or global personalized cacheArrows name the exchanged contract; paired arrowheads show a request/result or event/snapshot relationship, not a module dependency cycle. The React adapter depends on core interfaces; the core has no React, DOM or host-API dependency.","kind":"Diagram"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-93edcadf21f6","heading":"Step 2 · Blueprint and dependency boundaries","text":"Start simple: Use a reducer/controller plus a scoped instance. Native React Context can distribute that stable instance among compound subcomponents; the subscription mechanism reads its snapshots. A custom hook alone does not make separate callers share an owner.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-0b74b731edd8","heading":"Step 2 · Blueprint and dependency boundaries","text":"Alternative: A React-only useReducer hook is simpler if framework independence is not a real requirement. An established accessible combobox library may reduce risk further; justify a custom package only when requirements or integration constraints warrant it. See headless composition and state-tool comparisons.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-contract","heading":"Public API: types, identity & ownership","text":"Public API: types, identity & ownership","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-contract-definition","heading":"Public API: types, identity & ownership","text":"Expose a small typed contract. The following is a proposed API sketch, not an installed package. It separates optional controlled/default pairs and treats asynchronous loading as an injected dependency.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-b12958aa19ca","heading":"Public API: types, identity & ownership","text":"export type DataSource\u003cT> = ( query: string, context: { signal: AbortSignal } ) => Promise\u003creadonly T[]>; type Owned\u003cT, Name extends string> = | { mode: 'controlled'; value: T; onChange: (value: T, reason: Name) => void } | { mode: 'uncontrolled'; defaultValue?: T; onChange?: (value: T, reason: Name) => void }; export type AutocompleteConfig\u003cT> = { dataSource: DataSource\u003cT>; getItemKey: (item: T) => string; getItemLabel: (item: T) => string; isItemDisabled?: (item: T) => boolean; query: Owned\u003cstring, 'input' | 'select' | 'clear'>; selection: Owned\u003cT | null, 'select' | 'clear' | 'input'>; // Changes in permissions, tenant, locale or source semantics invalidate requests. dataScopeKey: string; minQueryLength?: number; debounceMs?: number; };","kind":"Code"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-45a49f4be6bf","heading":"Public API: types, identity & ownership","text":"Semantics: Controlled values are authoritative host inputs; a change request is not committed until the owner supplies the new value. Default values initialize an uncontrolled owner and are not a synchronization channel. Validate/warn against changing ownership modes after mount; do not call change callbacks solely because a controlled prop was echoed back.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-e9750be304c7","heading":"Public API: types, identity & ownership","text":"Separate facts: Query text, selected item identity, and active option key have different lifetimes. Stable keys survive result replacement/reordering; labels need not be unique. If an item’s shape changes remotely, preserve identity while defining how its latest label is resolved. Do not compare whole items only by object reference.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-e40965b891cb","heading":"Public API: types, identity & ownership","text":"API surface: Expose open state similarly if required; keep active option internal initially. Return semantic reason codes rather than leaking the internal event format. A simpler single-select product can expose fewer ownership knobs; a large generic API increases invalid combinations and test scope.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-47e8d32f8381","heading":"Public API: types, identity & ownership","text":"Type boundary: Generic T preserves relationships between items and callbacks but does not validate remote JSON. The host data adapter validates results and permissions; see reusable React typing and controlled contracts.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-transitions","heading":"Step 3 · State and transition model","text":"Step 3 · State and transition model","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-transitions-definition","heading":"Step 3 · State and transition model","text":"Use a small explicit transition model before introducing a statechart library. Keep synchronous transitions pure, with timers/network work owned by the coordinator.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-02f998fdea82","heading":"Step 3 · State and transition model","text":"Event / transitionRuleFailure avoided","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-3858128d079b","heading":"Step 3 · State and transition model","text":"Input changedUpdate query; clear committed selection under this case’s policy; reset active option; invalidate older requests.A selected identity remaining after the user has changed its displayed text.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-6b31b21a30f2","heading":"Step 3 · State and transition model","text":"Request started / resolved / rejectedAttach request generation + scope; apply only if current and still eligible.A slow old query overwriting a newer result.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-890b8f18144e","heading":"Step 3 · State and transition model","text":"Move activeNavigate enabled results; keep the active item visible; handle bounds according to the documented wrap policy.Selecting disabled or removed options.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-a3971e149892","heading":"Step 3 · State and transition model","text":"Select active/pointer optionCommit once; request label update; close; clear pending requests.Blur/click/key handlers each committing the same selection.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-336983fdad1f","heading":"Step 3 · State and transition model","text":"Escape / outside dismissalClose without changing confirmed value; invalidate work that must not reopen results.A late response reopening a dismissed popup.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-4bc3570ea977","heading":"Step 3 · State and transition model","text":"Reset / scope change / disposalReset to defined defaults/current controlled values; cancel pending work; clear personalized data.Cross-user result leakage and updates after disposal.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-db44250b52fe","heading":"Step 3 · State and transition model","text":"State shape: Store canonical keys and small status unions, derive visible/selected flags, and keep immutable snapshots stable while nothing changed. A finite listbox usually does not need a global Redux store. XState earns consideration for significantly richer parallel/loading/creation workflows; Context only distributes the chosen owner. See same-problem alternatives.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-async","heading":"Async search: debounce, cancellation & stale-result guards","text":"Async search: debounce, cancellation & stale-result guards","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-async-definition","heading":"Async search: debounce, cancellation & stale-result guards","text":"The hard guarantee is latest eligible request wins, not simply “we debounce fetch.” The request key must include the data scope as well as the query.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-04fc05f87a7e","heading":"Async search: debounce, cancellation & stale-result guards","text":"MechanismPurposeLimit","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-db29c2936038","heading":"Async search: debounce, cancellation & stale-result guards","text":"DebounceDelay remote work until rapid input pauses.It reduces request count but does not stop earlier requests completing out of order.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-75901d4ec37e","heading":"Async search: debounce, cancellation & stale-result guards","text":"AbortControllerCancel obsolete work supported by the data source.Cancellation may arrive too late or be ignored; it does not guarantee server cancellation.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-cd41f1a89dd8","heading":"Async search: debounce, cancellation & stale-result guards","text":"Generation + scope checkIgnore completion from an obsolete query, account, locale, source, or disposed instance.Use it even when abort exists; ensure close/clear invalidates relevant generations.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-b63613669ad7","heading":"Async search: debounce, cancellation & stale-result guards","text":"Min length + bounded result countAvoid expensive broad requests and excessive rendering.The API still needs server-enforced limits.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-0ec4cba1a1c5","heading":"Async search: debounce, cancellation & stale-result guards","text":"Cache / request deduplicationReuse equivalent results or in-flight work through a host policy.A single instance must not abort shared work that other consumers still need.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-12f3a7d32a86","heading":"Async search: debounce, cancellation & stale-result guards","text":"Sequence example: Query “a” starts generation 1; “al” starts generation 2 and aborts 1. If generation 1 still resolves last, its result is ignored. If the user closes the popup before 2 resolves, the result must not reopen it. If tenant/account changes, old results are invalid even if the string remains “al.”","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-9c919ad35eb5","heading":"Async search: debounce, cancellation & stale-result guards","text":"IME composition: Update visible text while composition is active, but defer search/selection shortcuts until compositionend under the documented policy. Enter may confirm composed text rather than select a result; check isComposing and verify real browser behavior.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-5b23a1e7c658","heading":"Async search: debounce, cancellation & stale-result guards","text":"Normalization: Local filtering can be injected; do not lowercase/remove accents unconditionally if locale/domain semantics differ. Remote ranking belongs to the data source. Choose a minimum-length and empty-query policy with the host rather than embedding a product assumption.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-9cdf26b71735","heading":"Async search: debounce, cancellation & stale-result guards","text":"Related: cancellation, stale completion, and frequency control.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-d10ee4178fea","heading":"Async search: debounce, cancellation & stale-result guards","text":"Sequence sketch · typing, cancellation and selectionOpen full-size diagramScroll horizontally on smaller screens.Async query sequence: newer input owns the resultTime moves downward. Input starts a debounced query through the controller and coordinator. New input aborts old work; a stale completion is ignored even if cancellation is not honored. Only the current result is rendered.1. INPUT: a2. debounce then request A3. query a + AbortSignal4. INPUT: al5. invalidate A; request B6. abort A; query al7. B results (current)8. apply generation B9. snapshot → render options10. late A result: ignored11. SELECT stable item key12. onValueChange(item, reason)Input / UIControllerCoordinatorData sourceHost pageControlled selection commits only when the host echoes the new value; onChange is a request, not a forced mutation.Time moves downward. Query B owns the results even if A ignores cancellation. An old completion does not mutate the visible snapshot. A controlled host may accept or reject the proposed value; identity and callback reasons are part of the public API.","kind":"Diagram"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-accessibility","heading":"Accessibility: combobox/listbox as a contract","text":"Accessibility: combobox/listbox as a contract","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-accessibility-definition","heading":"Accessibility: combobox/listbox as a contract","text":"Use the editable combobox with listbox popup pattern for this case. Accessibility comes from consistent roles, relationships, state, focus, and interaction—not from adding aria labels after implementation.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-e914bba43eb7","heading":"Accessibility: combobox/listbox as a contract","text":"Element / interactionRequired contract","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-bc45c960dd10","heading":"Accessibility: combobox/listbox as a contract","text":"InputAn accessible label; role=combobox; aria-expanded reflects popup visibility; aria-controls refers to the related listbox when applicable; aria-autocomplete=list for suggestions.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-854eb7995d3d","heading":"Accessibility: combobox/listbox as a contract","text":"Popup and itemsrole=listbox and role=option; stable DOM IDs; aria-selected follows the documented committed-selection model; aria-disabled for disabled options.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-d36ffb201aa3","heading":"Accessibility: combobox/listbox as a contract","text":"Active optionDOM focus remains on input; aria-activedescendant refers only to the currently mounted active option. Selection and highlight remain distinct.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-11f8f7fdbed1","heading":"Accessibility: combobox/listbox as a contract","text":"KeyboardArrow keys navigate/open as defined, Enter commits an enabled active option, Escape dismisses, Tab preserves normal focus flow. Do not hijack native text-editing shortcuts.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-d4508555e3e7","heading":"Accessibility: combobox/listbox as a contract","text":"PointerKeep the intended option interaction alive across input blur; avoid duplicate selection and avoid indiscriminately preventing focus on touch/scroll.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-3fd23c7c27b6","heading":"Accessibility: combobox/listbox as a contract","text":"Async feedbackUse a polite status for useful loading/results/error changes, not a live announcement for each keystroke. Keep interactive retry controls out of the option model.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-49552968f063","heading":"Accessibility: combobox/listbox as a contract","text":"ID ownership: Generate per-instance IDs in the adapter using an SSR-compatible mechanism such as React useId. Keep item-key → option-ID mapping stable; do not concatenate untrusted keys into selectors/markup without appropriate handling.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-e896f8c659f0","heading":"Accessibility: combobox/listbox as a contract","text":"Virtualization extension: aria-activedescendant cannot reference an unmounted item. Scroll/mount before exposing it, and test list-size/position metadata and screen-reader behavior. For 20 results, a normal list is usually simpler and more robust.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-78f6990c60d4","heading":"Accessibility: combobox/listbox as a contract","text":"Verification: Test keyboard, touch, zoom, IME, disabled items, empty/error states, and target screen-reader/browser combinations against the current WAI-ARIA Authoring Practices. Start from an established accessible primitive when custom behavior is not essential. See focus ownership and component accessibility contracts.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-composition","heading":"Presentation and host adapters: imported, not embedded","text":"Presentation and host adapters: imported, not embedded","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-composition-definition","heading":"Presentation and host adapters: imported, not embedded","text":"Offer supported exports for a headless hook/compound API and an optional styled convenience component. Both share the same interaction owner; slots change presentation without duplicating behavioral logic.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-f21016b02a6f","heading":"Presentation and host adapters: imported, not embedded","text":"// Proposed consumer API; implementation belongs to the package in this case study. import { Autocomplete } from '@acme/autocomplete/react'; import '@acme/autocomplete/styles.css'; type Person = { id: string; displayName: string }; const loadPeople = async (query: string, { signal }: { signal: AbortSignal }) => { const response = await fetch(`/api/people?q=${encodeURIComponent(query)}`, { signal }); if (!response.ok) throw new Error('Could not load people'); return response.json() as Promise\u003cPerson[]>; // Host validates real JSON at this boundary. }; export function PersonPicker({ accountScope }: { accountScope: string }) { return \u003cAutocomplete\u003cPerson> dataSource={loadPeople} dataScopeKey={accountScope} getItemKey={person => person.id} getItemLabel={person => person.displayName} query={{ mode: 'uncontrolled', defaultValue: '' }} selection={{ mode: 'uncontrolled', defaultValue: null }} label=\"Choose a person\" renderOption={person => \u003cspan>{person.displayName}\u003c/span>} />; }","kind":"Code"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-8774ad63dc65","heading":"Presentation and host adapters: imported, not embedded","text":"Adapter API: The convenience component extends the core configuration with label, renderOption, and optional presentation props. Those React-specific types live only in the React entry point; core types remain framework-independent.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-8813c25de300","heading":"Presentation and host adapters: imported, not embedded","text":"Slots/bindings: A headless variant can expose Input, Results, Option, and Status or prop-getter functions. Merge required IDs/roles/event handlers predictably; preserve caller refs and document which handlers may prevent library behavior. A renderOption customizes option content, not arbitrary nested buttons or replacement focus semantics.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-f5abcd914aa6","heading":"Presentation and host adapters: imported, not embedded","text":"Form adapter: Submit the selected item’s domain key in a hidden/native field or integrate with the host form library’s field API. Pass validation error, required, disabled, blur/touched, reset, and focus behavior intentionally. Input text is not proof that a valid item was selected.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-da312a344b3d","heading":"Presentation and host adapters: imported, not embedded","text":"Tradeoffs: One highly polymorphic component can become harder to type and use than a focused default plus a headless API. Avoid hidden dependencies on a router, theme provider, global store, or fetch wrapper. See compound slots and adapters.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-directories","heading":"Directory structure: core, adapters & public exports","text":"Directory structure: core, adapters & public exports","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-directories-definition","heading":"Directory structure: core, adapters & public exports","text":"Organize by ownership boundaries, not a generic utils folder. This is an illustrative source layout for the proposed component package; these files describe the design and are not a claim that an implementation has been added to this documentation repository.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-efc53c1e1b49","heading":"Directory structure: core, adapters & public exports","text":"Package layout · optional React dependency stays at the edgepackages/autocomplete/package.json Exports, peer dependencies, files and side-effect metadata.src/core/index.ts Framework-independent public exports.types.ts State, events, identity and DataSource contracts.reducer.ts Pure transitions and derived selectors.controller.ts Per-instance snapshot/subscription owner.requestCoordinator.ts Debounce, abort, generations and disposal.react/index.ts React-only public exports.useAutocomplete.ts Lifecycle, subscriptions and controlled integration.bindings.ts Input/listbox/option prop relationships and handler merging.Autocomplete.tsx Optional default component/compound presentation.styles.css Explicit opt-in default styling.tests/core.test.ts Transition invariants and stale-result races.react.test.tsx Ownership, subscriptions, SSR/hydration and event integration.combobox.spec.ts Real-browser keyboard, IME, focus, touch and accessibility.examples/people-picker.tsx Remote source; validated domain adapter.local-products.tsx Local source; custom rendering/form integration.README.md Supported imports, behavior, accessibility and migration notes.Dependency direction: React adapter → core; default UI → adapter. Core must not import React, DOM globals, host business types, or private application clients.","kind":"Diagram"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-e7fa78221841","heading":"Directory structure: core, adapters & public exports","text":"Why this split: Pure transitions are easy to verify independently. The coordinator owns asynchronous resources, while React owns mounting/subscription/DOM relationships. Stable domain-facing adapters prevent examples from becoming hard-coded production dependencies.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-packaging","heading":"Packaging, SSR & compatibility","text":"Packaging, SSR & compatibility","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-packaging-definition","heading":"Packaging, SSR & compatibility","text":"An importable component includes a distribution contract, not just a source file. Document supported runtime/framework versions, exports, CSS behavior, and semantic-versioning rules.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-42ccec15652b","heading":"Packaging, SSR & compatibility","text":"{ \"name\": \"@acme/autocomplete\", \"type\": \"module\", \"exports\": { \"./core\": { \"types\": \"./dist/core/index.d.ts\", \"import\": \"./dist/core/index.js\" }, \"./react\": { \"types\": \"./dist/react/index.d.ts\", \"import\": \"./dist/react/index.js\" }, \"./styles.css\": \"./dist/styles.css\" }, \"files\": [\"dist\"], \"sideEffects\": [\"**/*.css\"], \"peerDependencies\": { \"react\": \"^18.0.0 || ^19.0.0\" }, \"peerDependenciesMeta\": { \"react\": { \"optional\": true } } }","kind":"Code"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-6880cabc2c6c","heading":"Packaging, SSR & compatibility","text":"Interpretation: This illustrative ESM-only export map assumes the build emits exactly these files. Mark React optional so core-only consumers need not install it; React-adapter consumers must install a supported version. Externalize React from the bundle to avoid duplicate runtimes. Include declaration files and opt-in CSS; exclude examples/test infrastructure from the published artifact.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-9e4d579f4af2","heading":"Packaging, SSR & compatibility","text":"Build pipeline: Type-check, test, emit JS/declarations, copy CSS, and verify imports from a packed tarball in consumer fixtures. ESM-only is simpler; add a documented CommonJS build only for an actual support requirement, then verify conditional exports and module identity. Do not deep-import unexported source paths.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-39de9efd7b12","heading":"Packaging, SSR & compatibility","text":"SSR: Core imports must not touch window/document; create browser resources after the adapter is mounted. Provide a stable initial/server snapshot to useSyncExternalStore and stable hydration IDs. For server/client frameworks, expose the React interactive boundary appropriately without marking the whole core client-only.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-d38590207186","heading":"Packaging, SSR & compatibility","text":"Lifetime: Strict Mode setup/cleanup replay must not leak a controller, timer, subscription, or request. Never start network work at module import or perform it inside a pure reducer. Behavior changes to keyboard handling or callback reasons can be breaking changes even if TypeScript still compiles. See module boundaries and snapshot contracts.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-performance","heading":"Performance, caching & fallback decisions","text":"Performance, caching & fallback decisions","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-performance-definition","heading":"Performance, caching & fallback decisions","text":"Optimize the path that is actually slow: typing/rendering, local matching, network suggestions, or list layout. The package cannot guarantee the host search service’s scale or ranking latency.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-59197efe1a3d","heading":"Performance, caching & fallback decisions","text":"PressureChoiceTradeoff","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-fd9db4f02ff5","heading":"Performance, caching & fallback decisions","text":"Remote requests on each keyDebounce eligible queries; cancel/ignore obsolete work.Adds intentional response delay; do not debounce the visible input value.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-a047f80829e5","heading":"Performance, caching & fallback decisions","text":"Repeated equivalent searchesLet a host cache own keys, TTL, in-flight reuse and account scope.Library-global caches can leak personalized data; shared cancellation needs independent ownership.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-6e7cd6f2075e","heading":"Performance, caching & fallback decisions","text":"Large local collectionPre-index/filter outside render or use a worker when measured CPU cost justifies it.Worker messaging/index lifecycle adds complexity; a remote source or smaller result set may be simpler.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-a7ee4dbc3cbd","heading":"Performance, caching & fallback decisions","text":"Many visible optionsBound result count first; virtualize only with the accessibility contract intact.Virtualization complicates active-descendant IDs, scrolling, and screen-reader behavior.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-17e5835e9a97","heading":"Performance, caching & fallback decisions","text":"Remote source failsRetain typed query, expose error/retry, optionally show clearly scoped cached results.Stale results may be useful but permissions/selection must still be validated server-side.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-69968bd2e90d","heading":"Performance, caching & fallback decisions","text":"Rich custom contentKeep render callbacks pure and render safe React content.Do not accept raw unsanitized HTML; expensive option markup needs profiling.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-b08c927a1ca7","heading":"Performance, caching & fallback decisions","text":"Monitoring: Optional host callbacks can report request duration, safe failure codes, stale completions discarded, selection completion, and keyboard journey failures. Do not emit raw queries or option content by default: they can contain personal/sensitive data. Use bounded metric labels and a host-provided telemetry sink instead of a mandatory analytics SDK.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-2d61bb968d5f","heading":"Performance, caching & fallback decisions","text":"Security boundary: Even an authorized cached suggestion is not permanent authorization to submit that item. Revalidate on the server. Avoid public/CDN caching of personalized suggestions unless cache/auth contracts explicitly permit it; see cache placement.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-verification","heading":"Verification: test interactions, races and the packed artifact","text":"Verification: test interactions, races and the packed artifact","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-verification-definition","heading":"Verification: test interactions, races and the packed artifact","text":"Test the reusable contract at its boundaries. A reducer snapshot alone cannot establish browser focus behavior, accessible interactions, or package compatibility.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-dfb74aa1e6b7","heading":"Verification: test interactions, races and the packed artifact","text":"LayerCritical cases","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-05945f209e3c","heading":"Verification: test interactions, races and the packed artifact","text":"Pure transitionsDisabled/all-disabled/empty results; selection versus highlight; clear/reset; changing ownership mode; same label with different keys; active key removed.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-4f9d1d1c2651","heading":"Verification: test interactions, races and the packed artifact","text":"Async coordinatorSlow A after fast B; ignored abort; close while loading; account/source changes; retry; disposal; debounce timers; shared-cache cancellation.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-bbe3c87e60eb","heading":"Verification: test interactions, races and the packed artifact","text":"React integrationControlled parent accepts/rejects a change; no callback loop; multiple instances; stable snapshots; Strict Mode cleanup; form reset; ref/handler composition.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-f523d32e0080","heading":"Verification: test interactions, races and the packed artifact","text":"Browser accessibilityArrows/Enter/Escape/Tab, text-editing shortcuts, IME composition, touch/pointer blur, zoom, labeling, active-descendant validity, and target screen-reader behavior.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-b1a6376f278d","heading":"Verification: test interactions, races and the packed artifact","text":"Consumer packageCore import without React/DOM; adapter import with supported React; SSR/hydration; opt-in styles; packed tarball exports/types; bundle excludes duplicate React.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-9bc5b9e1080e","heading":"Verification: test interactions, races and the packed artifact","text":"Fallback criteria: A library failure must not submit an unintended value, trap focus, or silently replace results from the wrong account. Document unsupported combinations rather than advertising a universal solution. Use examples as compatibility fixtures, not only marketing demos.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-review","heading":"Step 4 · Wrap up and defend the tradeoffs","text":"Step 4 · Wrap up and defend the tradeoffs","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"ac-review-definition","heading":"Step 4 · Wrap up and defend the tradeoffs","text":"Recap: A per-instance TypeScript controller owns transitions; a coordinator owns async work; the React adapter binds the combobox contract; host adapters own domain data, authentication, caching, and form integration. Public subpath exports make these boundaries importable.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-433d47107a43","heading":"Step 4 · Wrap up and defend the tradeoffs","text":"AlternativeChoose whenWhy not always","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-6d9daee652d4","heading":"Step 4 · Wrap up and defend the tradeoffs","text":"Native datalistA small native suggestion list meets interaction and presentation requirements.Customization, async states, consistent keyboard/display behavior, and rich options are limited.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-151e3cb80e24","heading":"Step 4 · Wrap up and defend the tradeoffs","text":"Existing accessible combobox primitiveIts behavior and customization model fit the product.Audit support/license/bundle/API requirements; avoid writing a custom control merely for uniqueness.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-3119c91c4c95","heading":"Step 4 · Wrap up and defend the tradeoffs","text":"React-only hook/componentOnly React consumers exist and framework independence adds no real value.A future framework adapter would need extraction, but premature abstraction also has cost.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-f4a4cf9a8d4f","heading":"Step 4 · Wrap up and defend the tradeoffs","text":"Framework-independent core + adaptersMultiple host frameworks/products need the same behavior and data contract.More public APIs, adapter tests, versioning and lifecycle integration to maintain.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-d5e6d5301458","heading":"Step 4 · Wrap up and defend the tradeoffs","text":"Reducer/controller vs XStateSmall transitions favor a reducer; complex hierarchical/parallel actor workflows can favor XState.A machine library is not required to implement a valid FSM; Context/Redux solve different ownership/subscription concerns.","kind":"Notes"},{"page":"system-design-autocomplete.html","topic":"Case Study: Reusable Autocomplete","anchor":"search-acc25ee39db9","heading":"Step 4 · Wrap up and defend the tradeoffs","text":"Next questions: How would multi-select change state and keyboard semantics? How would pagination/virtualization preserve active-option identity? How would a Vue adapter subscribe and dispose? Change requirements first, then extend the smallest boundary. For the architecture method, return to the four-step framework.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"system-design-chat-title","heading":"","text":"Case Study: Design a Chat Web App","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-f5efa32fd34c","heading":"","text":"A worked system design from requirements to failure recovery. Follow one message through the system, understand each component, and defend the tradeoffs.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-8f28fb600cd2","heading":"","text":"Clarify the product: what are we building?","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-3ad37e62ab19","heading":"","text":"Estimate scale: writes, connections, fanout & storage","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-cd4ef906e6cb","heading":"","text":"Define APIs and the meaning of an acknowledgement","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-081f17788166","heading":"","text":"REST endpoints and idempotency keys","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-2e12f8e05074","heading":"","text":"Model authoritative data and access patterns","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-2f6c09de6b21","heading":"","text":"Frontend sketch · pages, components and data flow","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-0e1fdd159bbc","heading":"","text":"Sketch the chat UI and architecture","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-643d549268e3","heading":"","text":"Draw the baseline: persistence plus live delivery","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-5f458d0b86d0","heading":"","text":"Understand each component’s responsibility","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-6c5a68608427","heading":"","text":"Deployment choices: modular first, microservices when justified","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-85c7e5a1a1e7","heading":"","text":"Directory structure: feature modules and service boundaries","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-fc1680d9b1af","heading":"","text":"Trace one send, including a lost acknowledgement","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-26ac5e472543","heading":"","text":"Ordering and consistency: define the visible guarantees","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-12aea3df1b64","heading":"","text":"Reconnect and offline catch-up: live events are an optimization","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-cbf21314b84c","heading":"","text":"Queue vs. topic: fanout and offline notifications","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-717474487f2b","heading":"","text":"Scale and cache by the actual bottleneck","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-de600a08e2e4","heading":"","text":"Chat cache policy: where freshness matters","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-05d7e38f9ce8","heading":"","text":"CDN: deliver the app shell, isolate private data","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-e965972e984c","heading":"","text":"Failure drills, backpressure & observability","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-561781877f59","heading":"","text":"Observe a failed send: browser to database to recipient","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-7d4d847c183e","heading":"","text":"Fallbacks: preserve truth and recover deliberately","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-b7c6e5ce7feb","heading":"","text":"Frontend design: reliable UX over an unreliable connection","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-e07ceffc9666","heading":"","text":"Security and privacy boundaries","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-3c5d457549fd","heading":"","text":"Review: defend the design, then change a constraint","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-scope","heading":"Clarify the product: what are we building?","text":"Clarify the product: what are we building?","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-scope-definition","heading":"Clarify the product: what are we building?","text":"Prompt: Design a web chat app with direct messages and groups of up to 100 members. Users can send text, load history, see new messages live, and recover after disconnecting. We will support multiple devices per user.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-f7bc2a5b69de","heading":"Clarify the product: what are we building?","text":"Functional requirements describe behavior; non-functional requirements describe quality and constraints. Scope defines which parts of the product and infrastructure this design will cover. The targets below are illustrative assumptions to validate with the stakeholder.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-functional-requirements","heading":"Clarify the product: what are we building? › Functional requirements: what users can do","text":"Functional requirements: what users can do","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-6676765a8c28","heading":"Clarify the product: what are we building? › Functional requirements: what users can do","text":"Create direct conversations and groups of up to 100 members; list the conversations the user belongs to.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-39f7e3ee1e96","heading":"Clarify the product: what are we building? › Functional requirements: what users can do","text":"Add or remove members through authorized operations; enforce current membership for sending, history access, and live subscriptions.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-7fc6555c5e90","heading":"Clarify the product: what are we building? › Functional requirements: what users can do","text":"Send plain-text messages with a 4 KB text limit and retrieve paginated message history.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-3afb731b2c51","heading":"Clarify the product: what are we building? › Functional requirements: what users can do","text":"Receive new messages in near real time while connected, and catch up on missed messages after reconnecting.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-35e350c41409","heading":"Clarify the product: what are we building? › Functional requirements: what users can do","text":"Show pending, accepted, delivered, read, and failed/uncertain states with defined meanings; allow safe retries without creating a new logical message.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-2c8d429fa587","heading":"Clarify the product: what are we building? › Functional requirements: what users can do","text":"Support multiple authenticated devices per user and synchronize their accepted messages and relevant receipt state.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-d859eb5abc28","heading":"Clarify the product: what are we building? › Functional requirements: what users can do","text":"Preserve an unsent draft during supported in-app navigation and recoverable connection failures; show clear loading, empty, error, and reconnect states.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-nonfunctional-requirements","heading":"Clarify the product: what are we building? › Non-functional requirements: quality targets & constraints","text":"Non-functional requirements: quality targets & constraints","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-236d26c08b62","heading":"Clarify the product: what are we building? › Non-functional requirements: quality targets & constraints","text":"Latency: Target p95 online message delivery under 300 ms within the chosen region under normal load; define eligibility and measure failed/timed-out deliveries too. This is not a guarantee for disconnected recipients.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-dc9b34b3e650","heading":"Clarify the product: what are we building? › Non-functional requirements: quality targets & constraints","text":"Availability: Target 99.9% monthly durable-send success for eligible requests, using the denominator defined in the monitoring contract.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-57392063b548","heading":"Clarify the product: what are we building? › Non-functional requirements: quality targets & constraints","text":"Durability: Once accepted, a message survives the defined single database-node/availability-zone failure model; acceptance waits for the configured durable replication acknowledgement.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-bd544b3194b6","heading":"Clarify the product: what are we building? › Non-functional requirements: quality targets & constraints","text":"Consistency: Preserve canonical order within each conversation and read-your-writes for acknowledged sends. Receipt/presence state may be eventually consistent. Avoid a second visible message on a retry within the deduplication contract.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-df8724118df6","heading":"Clarify the product: what are we building? › Non-functional requirements: quality targets & constraints","text":"Capacity: Plan against the illustrative 1 million daily active users, 50 million sent messages/day, and 100,000 concurrent device connections from the workload estimates, with peak and failure headroom.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-c7b0851c2db1","heading":"Clarify the product: what are we building? › Non-functional requirements: quality targets & constraints","text":"Retention: Retain message history for one year under the case’s policy; account for indexes, replicas, backups, and archival/deletion procedures.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-f479a73f42a0","heading":"Clarify the product: what are we building? › Non-functional requirements: quality targets & constraints","text":"Security & privacy: Encrypt transport, authenticate sessions, authorize resources, bound inputs, protect private cached data, and avoid sensitive content in telemetry.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-d49a46052714","heading":"Clarify the product: what are we building? › Non-functional requirements: quality targets & constraints","text":"Usability & accessibility: Support responsive mobile/desktop layouts, keyboard and screen-reader interaction, draft preservation, truthful pending/error feedback, and deliberate scroll/focus behavior.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-65aca5003db7","heading":"Clarify the product: what are we building? › Non-functional requirements: quality targets & constraints","text":"Operability & resilience: Bound queues/buffers/retries, recover missed events, instrument end-to-end outcomes, and define alerts, graceful shutdown, and degraded behavior.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-in-scope","heading":"Clarify the product: what are we building? › In scope: what this design covers","text":"In scope: what this design covers","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-9b8817c93c33","heading":"Clarify the product: what are we building? › In scope: what this design covers","text":"Product: Private one-to-one chat and small groups, plain text, history, membership, receipt cursors, and multiple devices.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-b03615366229","heading":"Clarify the product: what are we building? › In scope: what this design covers","text":"Frontend: Conversation list, history view, composer, optimistic/pending items, retries, pagination/virtualization, accessibility, and reconnect UX.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-6b179fb715c9","heading":"Clarify the product: what are we building? › In scope: what this design covers","text":"Application boundary: REST resources and WebSocket events using shared authorization, validation, idempotency, and error semantics.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-53f5c3540c98","heading":"Clarify the product: what are we building? › In scope: what this design covers","text":"Architecture: Gateway/load balancing, message service, authoritative database, outbox, delivery workers/broker, and transient connection routing.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-78aa6cc623de","heading":"Clarify the product: what are we building? › In scope: what this design covers","text":"Operations: Single-region multi-zone deployment, capacity estimates, cache/CDN placement, monitoring, failure recovery, and fallback decisions.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-86fe9a91e266","heading":"Clarify the product: what are we building? › In scope: what this design covers","text":"Dependencies: Integrate an existing identity/session mechanism. Discuss optional approximate presence and offline notifications where they illustrate delivery tradeoffs; a complete notification platform is not required.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-out-of-scope","heading":"Clarify the product: what are we building? › Out of scope: boundaries and extensions","text":"Out of scope: boundaries and extensions","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-b247e4019404","heading":"Clarify the product: what are we building? › Out of scope: boundaries and extensions","text":"Large public channels, global ordering across conversations, and active-active cross-region writes.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-302698f71abd","heading":"Clarify the product: what are we building? › Out of scope: boundaries and extensions","text":"Images/files, voice/video calls, full-text search, message editing/deletion, reactions, and threads.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-c244a5515d2a","heading":"Clarify the product: what are we building? › Out of scope: boundaries and extensions","text":"End-to-end encryption, device-key recovery, and a complete moderation/anti-abuse platform; basic security, authorization, and rate limiting remain required.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-1b9fc509f76f","heading":"Clarify the product: what are we building? › Out of scope: boundaries and extensions","text":"Building identity-provider internals, a general push-notification service, or a complete disaster-recovery implementation. State regional-loss limitations and recovery objectives rather than silently promising them.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-a1a5892529a8","heading":"Clarify the product: what are we building? › Out of scope: boundaries and extensions","text":"Exactly-once execution or unconditional instant delivery during partitions, overload, or client disconnection. These are excluded guarantees, not hidden features.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-d88a4678d47f","heading":"Clarify the product: what are we building? › Out of scope: boundaries and extensions","text":"Clarifying questions: Can a newly added member read earlier history? We assume yes for this case, subject to current membership. What counts as read: opening the conversation, or actually revealing a message? We use an explicit client report after the conversation is visible and the relevant messages are rendered. Presence is approximate and may lag.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-5c2000d29122","heading":"Clarify the product: what are we building? › Out of scope: boundaries and extensions","text":"Product choice: If the conversation write authority is unavailable, leave the message pending or fail clearly; do not acknowledge an uncommitted local-only message as durable. Existing object-level authorization applies to history, sends, receipts, and subscriptions.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-estimates","heading":"Estimate scale: writes, connections, fanout & storage","text":"Estimate scale: writes, connections, fanout & storage","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-estimates-definition","heading":"Estimate scale: writes, connections, fanout & storage","text":"Use explicit, rounded assumptions. These are illustrative capacity inputs, not benchmark claims. Re-estimate if product usage differs.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-9a1bb93ced85","heading":"Estimate scale: writes, connections, fanout & storage","text":"Assumption / calculationResultDesign implication","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-3907fc21d25b","heading":"Estimate scale: writes, connections, fanout & storage","text":"1 million daily active users × 50 sent messages/day50 million messages/day.Retention and sustained write throughput matter.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-01c5783d577b","heading":"Estimate scale: writes, connections, fanout & storage","text":"50 million ÷ 86,400 secondsAbout 580 message writes/second average.Average is not the provisioning target.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-79b9b937ea7b","heading":"Estimate scale: writes, connections, fanout & storage","text":"Illustrative 5× peak multiplierAbout 2,900 sends/second peak.Load test peak plus safety headroom.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-b2bdf2b044a1","heading":"Estimate scale: writes, connections, fanout & storage","text":"100,000 concurrent devices × one connection/device100,000 long-lived sockets.Budget gateway memory, heartbeat traffic, and reconnect storms.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-469894dc6693","heading":"Estimate scale: writes, connections, fanout & storage","text":"Average 4 recipient-device deliveries per messageAbout 11,600 peak delivery events/second.Fanout can dominate the write rate; measure actual group/device mix.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-d1bd09c36a55","heading":"Estimate scale: writes, connections, fanout & storage","text":"50 million × 1 KB decimal envelopeAbout 50 GB/day; 18.25 TB/year raw.At three full copies: about 54.75 TB before indexes, WAL, backups, and overhead.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-08b86a63e119","heading":"Estimate scale: writes, connections, fanout & storage","text":"Important gaps: History reads, inbox refreshes, connection handshakes, receipts, and heartbeats add RPS beyond message writes. Rough peak application egress from the assumed message envelope alone is 11.6 MB/s before TLS/protocol overhead, history, and retries. A 4 KB maximum is a limit, not the average used in this estimate.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-6c393fd0842d","heading":"Estimate scale: writes, connections, fanout & storage","text":"Connection sizing: If load tests show a gateway can safely handle 10,000 sockets at the expected traffic, 100,000 connections need at least 10 instances before headroom and zone failure capacity. Socket counts alone are insufficient: benchmark CPU, per-connection memory, event rate, and slow-client buffers.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-contracts","heading":"Define APIs and the meaning of an acknowledgement","text":"Define APIs and the meaning of an acknowledgement","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-contracts-definition","heading":"Define APIs and the meaning of an acknowledgement","text":"Use HTTPS for history, membership, and session operations; use WSS for bidirectional message/receipt events. This is one reasonable transport split. HTTP POST for sends plus SSE for downstream updates is a simpler alternative when that traffic pattern fits; compare WebSockets and SSE.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-27b70c5dc414","heading":"Define APIs and the meaning of an acknowledgement","text":"OperationExample contractImportant behavior","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-377539658600","heading":"Define APIs and the meaning of an acknowledgement","text":"HistoryGET /conversations/{id}/messages?beforeSeq=501&limit=50Bound page size, verify membership, return messages and an opaque continuation cursor.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-0d7ba5dd4258","heading":"Define APIs and the meaning of an acknowledgement","text":"Reconnect catch-upGET /conversations/{id}/messages?afterSeq=480&limit=100Read canonical history after the last contiguous applied position.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-2cc238131b56","heading":"Define APIs and the meaning of an acknowledgement","text":"SendWS send_message: conversationId, clientMessageId, textServer derives sender identity; validate limits and current membership.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-4d482eae3788","heading":"Define APIs and the meaning of an acknowledgement","text":"AcceptedWS message_accepted: clientMessageId, messageId, sequenceEmit only after the defined durable commit succeeds.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-88097170f6e2","heading":"Define APIs and the meaning of an acknowledgement","text":"Delivery/read reportWS receipt: conversationId, deliveredThrough / readThroughAuthenticate the reporting device; advance cursors monotonically within valid history.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-8c7dbfeec86e","heading":"Define APIs and the meaning of an acknowledgement","text":"{ \"type\": \"send_message\", \"conversationId\": \"c-42\", \"clientMessageId\": \"uuid-kept-across-retries\", \"text\": \"Hello\" }","kind":"Code"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-f484daf9b56d","heading":"Define APIs and the meaning of an acknowledgement","text":"States: Pending is client-owned intent. Accepted means durable server storage, not that a recipient received it. Delivered means a recipient device explicitly acknowledged receipt under our chosen policy; a socket write is insufficient. Read is an explicit user/device signal, not proof that a human understood the text. Define whether “delivered to a user” means any device or every device; this case uses any authorized device.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-e1015dbe385a","heading":"Define APIs and the meaning of an acknowledgement","text":"Errors: Return correlated codes such as NOT_MEMBER, PAYLOAD_TOO_LARGE, or RATE_LIMITED. A timeout after send is ambiguous: retry with the same clientMessageId or query its outcome. See error and retry contracts.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-rest","heading":"REST endpoints and idempotency keys","text":"REST endpoints and idempotency keys","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-rest-definition","heading":"REST endpoints and idempotency keys","text":"The HTTPS surface models conversations, memberships, messages, and receipt state as resources. WebSocket commands share the same application-service invariants; two transports must not implement different permission or deduplication rules.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-cc92874285f8","heading":"REST endpoints and idempotency keys","text":"Method + endpointInput / outputSemantics","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-3595b8a1a447","heading":"REST endpoints and idempotency keys","text":"POST /conversationsMember IDs → 201 Created + Location.Check limits and membership policy; an idempotency key avoids duplicate groups on retry.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-70443ed1da9c","heading":"REST endpoints and idempotency keys","text":"GET /conversations?cursor=…Authorized conversation summaries + next cursor.Paginated discovery after reconnect; do not leak other users’ conversations.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-6819b7784b42","heading":"REST endpoints and idempotency keys","text":"POST /conversations/{id}/messagesText + Idempotency-Key → 201 + canonical message.HTTP alternative to WS sending; the key maps to clientMessageId under the same scoped deduplication contract.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-4d0b405c3262","heading":"REST endpoints and idempotency keys","text":"GET /conversations/{id}/messages?afterSeq=…Authorized messages + catch-up boundary/cursor.Validate bounds; a GET does not mark messages read.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-dbc3315f7caf","heading":"REST endpoints and idempotency keys","text":"PUT /conversations/{id}/read-cursorreadThrough → stored cursor / 200 or 204.Monotonically advance via max(current, supplied); validate range and policy. Repeating the same update has the same intended effect.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-a79d294e4a9e","heading":"REST endpoints and idempotency keys","text":"DELETE /conversations/{id}/members/{userId}Authorized membership change → 204.Coordinate revocation with sends/history/fanout. A repeat may use 204 or a documented 404 without repeating the removal.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-38446ed9a3ac","heading":"REST endpoints and idempotency keys","text":"Key handling: Scope the send key to authenticated sender + operation; store the conversation, canonical payload fingerprint, state, and result. A unique constraint and the message transaction resolve concurrent retries. Same key/different payload returns a documented conflict (for example 409), while an in-progress retry follows an explicit wait/lookup policy. Keep keys across offline retries; communicate any retention expiry.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-56801300ccf5","heading":"REST endpoints and idempotency keys","text":"Errors: Distinguish unauthenticated (401), forbidden or deliberately hidden resources (403/404 policy), invalid content (documented 400/422), oversized payload (413), throttling (429 with retry guidance), and transient unavailability (503). GET history can be conditionally revalidated with a resource-specific validator; personalized content needs private caching rules. See the reusable REST checklist.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-data","heading":"Model authoritative data and access patterns","text":"Model authoritative data and access patterns","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-data-definition","heading":"Model authoritative data and access patterns","text":"Start with a relational message store because transactions can atomically enforce membership, allocate a conversation sequence, deduplicate sends, and record an outbox event. This is a starting choice, not a claim that one database fits every chat workload.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-9ef7c72616a3","heading":"Model authoritative data and access patterns","text":"EntityKey fields / invariantMain access pattern","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-06776ad5107f","heading":"Model authoritative data and access patterns","text":"Conversationid, lastSequence, membershipVersionAllocate canonical per-conversation order.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-52f34894d929","heading":"Model authoritative data and access patterns","text":"MembershipconversationId, userId; unique pairAuthorize sends/reads; enumerate small-group members.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-7aeb966f3310","heading":"Model authoritative data and access patterns","text":"MessageconversationId, sequence, messageId, senderId, clientMessageId, textUnique (conversationId, sequence); range-read history.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-95444fd37334","heading":"Model authoritative data and access patterns","text":"Send deduplicationUnique (senderId, clientMessageId), associated conversation/payload hash/resultSame logical retry returns the same accepted result; mismatched reuse is rejected.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-c4e5f3a03a8c","heading":"Model authoritative data and access patterns","text":"Receipt cursorconversationId, userId, deliveredThrough, readThroughMonotonic maximum for aggregated user state; keep per-device positions when needed.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-47cbcb52380a","heading":"Model authoritative data and access patterns","text":"Outbox eventeventId, conversationId, sequence, publishedAtFind committed events that still need publication.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-ceb010613e29","heading":"Model authoritative data and access patterns","text":"Indexes: Order message history by (conversationId, sequence), and index membership lookup and pending outbox scanning. Use keyset/cursor pagination, not offset over a long active conversation. Store history ascending internally; reverse a backward page for display where useful. See pagination.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-4f5e3f6119ad","heading":"Model authoritative data and access patterns","text":"Transaction: Enforce authorization against a membership version/lock that coordinates with membership changes, serialize sequence allocation on the conversation, insert the message and outbox event, then commit. Handle a deduplication conflict by rolling back and returning the original stored outcome. A UUID identifies a message but does not define its order.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-34eab682e7dc","heading":"Model authoritative data and access patterns","text":"Growth: One year of retained messages requires a real partitioning, archival, backup, and restore plan. Partition/shard by conversation ownership to keep a conversation’s ordered writes together; a large partition key or hot group can still bottleneck. A wide-column store becomes an alternative when access patterns and measured scale justify more application-managed coordination.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-component-map","heading":"Frontend sketch · pages, components and data flow","text":"Frontend sketch · pages, components and data flow","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-component-map-definition","heading":"Frontend sketch · pages, components and data flow","text":"Draw the frontend separately from the backend architecture: show what renders what, who owns state, and how interaction reaches the network. Solid arrows below show composition/props; dashed arrows show runtime commands and subscriptions.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-a4831ec4b69a","heading":"Frontend sketch · pages, components and data flow","text":"Page and component sketch · chat clientOpen full-size diagramScroll horizontally on smaller screens.Chat frontend: route, components and shared dataSolid arrows show page composition and props. Dashed arrows show runtime commands and data subscriptions. URL owns conversation selection; Composer owns draft; the message cache owns remote snapshots; the realtime adapter reconciles socket events.propsconversationIditems / callbackssubmit callbackmessage propssend intentmerge / invalidatesubscribe / rendersummary subscriptionChatRoute / pageURL conversationId; layout and loadersConversationListSummaries; navigation linksConversationPanelSelected conversation and scoped actionsMessageListPages, scroll and virtualizationComposerLocal draft; pending feedbackMessageRowMessage text and receipt stateServer-state message cacheCanonical messages, receipts and cursorsRealtime / API adapterWS lifecycle; HTTP history + sendsThe selected conversation comes from the URL. ConversationPanel scopes the interaction; Composer owns the draft. Server-owned messages live in one cache; the network adapter reconciles events into it. Dashed subscriptions are data flow, not child-parent ownership.","kind":"Diagram"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-e66507faa4c9","heading":"Frontend sketch · pages, components and data flow","text":"Sketch it in this order: Route/layout → visible components → state owner → API/realtime adapter → event/cache updates. Explain one send and one history fetch. Then use the system sketch to expand the server side.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-sketches","heading":"Sketch the chat UI and architecture","text":"Sketch the chat UI and architecture","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-sketches-definition","heading":"Sketch the chat UI and architecture","text":"Use two sketches in the design discussion: one makes the user journey concrete; the other connects UI actions to components and authoritative data. These static wireframes illustrate the agreed baseline.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-c8bea55515ec","heading":"Sketch the chat UI and architecture","text":"Chat UI · accepted message with reconnect feedbackConversationsDesign teamSelected conversationMorganAnother conversationDesign team · delivery delayed while reconnectingMorgan: Can we review the API?You: Yes, I’ll share it.Accepted · delivery not confirmedNew-message indicator appears here when reading older history.Write a message…Composer draftConversation selection belongs in the URL; draft and focus are local; message/receipt history is server-owned. A reconnect notice never downgrades an accepted message into an unsent local draft.","kind":"Diagram"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-b8459f4e9b79","heading":"Sketch the chat UI and architecture","text":"System sketch · chat services and communicationOpen full-size diagramScroll horizontally on smaller screens.Chat system: durable write and live fanoutHTTPS and WSS enter through a load balancer. The message service writes messages and outbox atomically. A relay publishes to a broker; fanout looks up device routes and sends events through gateways. History reads recover missed events.HTTPS / WSSHTTP requestsWS commands / eventsapplication callssend / receipt commandstransaction / queryoutboxpublishconsumeroute lookuplive events to owning gatewayBrowser clientsSender, recipient and other devicesLoad balancerHTTPS / WSS; readiness and drainingHTTP applicationHistory and membership endpointsWebSocket gatewaysSocket ownership; bounded buffersConnection directoryUser/device → gateway + epochMessage serviceAuthorize, deduplicate, sequenceMessage databaseMessages + transactional outboxOutbox relayRetry committed publicationDurable brokerCommitted message eventsFanout workersDeliver; handle duplicatesSolid arrows show commands, calls and durable publication; dashed paths show transient routing/delivery. The connection directory is consulted for device routes. Accepted is returned only after the database commit policy is met; reconnect history uses the HTTP application/database path.","kind":"Diagram"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-baseline","heading":"Draw the baseline: persistence plus live delivery","text":"Draw the baseline: persistence plus live delivery","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-baseline-definition","heading":"Draw the baseline: persistence plus live delivery","text":"Start with stateless HTTP application instances, a gateway tier for long-lived sockets, and a durable database. An outbox relay plus broker decouples persistence from live fanout as operational needs justify it. These are logical roles: the first version can deploy application logic and gateways together.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-bb0e70e33841","heading":"Draw the baseline: persistence plus live delivery","text":"Write path and delivery pathBrowser → load balancer → gatewayWSS carries authenticated commands. The gateway holds sockets and bounds their buffers.Gateway → message service → databaseAuthorize, deduplicate, allocate sequence, and commit the message plus outbox event in one transaction.Database → accepted acknowledgementAfter durable commit, return the canonical ID and sequence to the sender.Outbox relay → durable brokerPublish committed events; tolerate duplicate publication after a relay crash.Fanout consumer → connection directory → gatewaysFind recipient devices, route events to their current gateway, and deliver on sockets.Recipient → receipt serviceExplicit delivery/read reports advance cursors. Missing live events remain recoverable from history.History reads go through the application service to the authoritative message store or a replica that satisfies the requested consistency. Redis-style caches and socket delivery are not the source of truth.","kind":"Diagram"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-19ef6ab25341","heading":"Draw the baseline: persistence plus live delivery","text":"Why an outbox? “Commit to DB, then publish” can lose the event if the process crashes between those operations. Publishing first can expose a message that later rolls back. A transactional outbox records the publication intent with the message; the relay retries independently. It gives durable intent with at-least-once publication, not exactly-once effects.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-68ed4825914e","heading":"Draw the baseline: persistence plus live delivery","text":"Durability configuration: For this baseline, configure the database so acceptance waits for durable local WAL and a synchronously persisted copy in another availability zone, under the chosen database’s documented commit/failover guarantees. This targets survival of one database-node/zone failure, not loss of the entire region. If the required replica acknowledgement is unavailable, do not acknowledge the write. Backups provide recovery for corruption or operator error; replication alone is not a backup.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-8c78b68026a4","heading":"Draw the baseline: persistence plus live delivery","text":"Simpler version: At small scale, one service can persist and attempt live delivery with reconnect-based reconciliation; this trades prompt offline notifications and delivery recovery latency for fewer components. Add the broker/outbox when durable asynchronous fanout and independent consumers are requirements.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-components","heading":"Understand each component’s responsibility","text":"Understand each component’s responsibility","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-components-definition","heading":"Understand each component’s responsibility","text":"Separate authoritative records, transient routing, and asynchronous work. A cache miss or gateway crash must not erase accepted history.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-233f7505539d","heading":"Understand each component’s responsibility","text":"ComponentWhy it existsBoundary / failure behavior","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-190ded450270","heading":"Understand each component’s responsibility","text":"Load balancerDistributes handshakes and HTTP requests; routes established sockets.Supports WebSocket upgrade and appropriate idle timeouts; an established socket lives on one gateway until disconnect.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-3edcfd66eb57","heading":"Understand each component’s responsibility","text":"GatewayOwns sockets, heartbeats, session binding, and bounded outbound buffers.Drains connections on deploy; clients reconnect elsewhere after failure.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-bd98890c96b7","heading":"Understand each component’s responsibility","text":"Message serviceOwns authorization, idempotency, sequence allocation, and commit.A service module can suffice initially; retries need stable operation IDs.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-212edf5a2cca","heading":"Understand each component’s responsibility","text":"Message databaseAuthoritative history, membership, cursors, and outbox.Multi-zone replication/failover and backups must match the promised failure model.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-27634c4ef173","heading":"Understand each component’s responsibility","text":"Connection directoryMaps user/device to gateway and connection epoch with TTL.Transient routing data; stale entries cause delivery attempts to fail and require recovery.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-301f1c35beec","heading":"Understand each component’s responsibility","text":"Outbox relay + brokerCarry committed work across component failures.Bound backlog and retention; detect stalled relays and consumers.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-cee815cb6148","heading":"Understand each component’s responsibility","text":"Fanout / notification workersDeliver to online devices or schedule permitted offline notifications.Deduplicate events, respect membership changes, and retry with bounded policies.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-b0850bf85fc1","heading":"Understand each component’s responsibility","text":"Caches / object storage / CDNCache hot reads; store/serve frontend assets and future media.Do not store authoritative chat history only in cache or public-cache private messages.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-e099bfc8e6f7","heading":"Understand each component’s responsibility","text":"Connection epochs: A reconnect can replace an old device connection. Register a fresh epoch and delete directory entries conditionally so an old disconnect handler cannot remove the new connection. Where ownership expires, reuse lease/generation principles. Presence is derived and approximate.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-service-boundaries","heading":"Deployment choices: modular first, microservices when justified","text":"Deployment choices: modular first, microservices when justified","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-service-boundaries-definition","heading":"Deployment choices: modular first, microservices when justified","text":"Deploying a gateway, message handler, and fanout module separately is a choice, not a prerequisite for the diagram. For an initial product, one modular application plus a durable store and background relay can be easier to operate.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-4e1b93061ee6","heading":"Deployment choices: modular first, microservices when justified","text":"Split when evidence supports it: Gateways have socket/memory-heavy lifecycles; message writes need transactional correctness; fanout/notifications absorb bursts. Extracting these boundaries can allow independent scaling and deployment. Keep message + deduplication + outbox in one transaction owner rather than creating a network call per table.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-e8b4d90b5647","heading":"Deployment choices: modular first, microservices when justified","text":"Cost: Every split adds versioned contracts, network timeouts, tracing, authentication, rollout coordination, and on-call ownership. Start by isolating modules and measuring resource saturation. A “microservice per entity” decomposition would make the send transaction harder without necessarily improving throughput.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-6e81d07ad7e7","heading":"Deployment choices: modular first, microservices when justified","text":"Load balancing: Use an HTTP/WebSocket-capable L7 balancer if handshake routing and TLS termination require it. Distribute new connections using measured capacity, readiness and zone health; existing sockets remain pinned to their gateway. Least-connections is a useful heuristic, but hot group traffic can make equal socket counts unequal workloads. Drain before shutdown and provision capacity to survive a zone loss.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-f497b2f7d3ae","heading":"Deployment choices: modular first, microservices when justified","text":"Blueprint validation: Before this deep dive, confirm that the stakeholder accepts durable ordered history, small-group fanout, one region, and eventual receipt/presence state. If the intended product is massive public channels, revisit the high-level design first. See architecture tradeoffs.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-directories","heading":"Directory structure: feature modules and service boundaries","text":"Directory structure: feature modules and service boundaries","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-directories-definition","heading":"Directory structure: feature modules and service boundaries","text":"This illustrative monorepo starts with feature boundaries and separates deployment units only when justified. It is a design sketch, not additional application code implemented by this documentation project.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-b49cca05a072","heading":"Directory structure: feature modules and service boundaries","text":"Chat layout · shared contracts, independent business ownershipapps/web/src/features/chat/components/ ConversationList, MessageList and Composer.state/ Draft/pending interaction state and selectors.data/ Message cache, pagination and event reconciliation.realtime/ Connection lifecycle, subscriptions and cursor recovery.routes/ URL ownership, loaders and navigation boundaries.api/src/transport/ HTTP/WS adapters and request validation.modules/conversations/ Membership rules and authorization.modules/messages/ Send use case, deduplication, sequence and outbox transaction.modules/receipts/ Monotonic delivered/read cursors.infrastructure/ Database, clock, telemetry and connection adapters.worker/src/outbox/ Bounded publication and retry.fanout/ Recipient routing and duplicate-safe consumption.notifications/ Preference-aware offline notifications.packages/contracts/ Versioned transport schemas; do not expose database entities blindly.ui/ Reusable presentation primitives, independent of chat business rules.database/migrations/ Schema, constraints, indexes and retention changes.tests/contracts/ HTTP/WS compatibility and authorization boundaries.integration/ Transactions, outbox, replicas/retry recovery.e2e/ Two-device send, reconnect, failed acknowledgement and accessible UX.ops/ SLOs, dashboards, alert rules, deploy/drain configuration and runbooks.API and workers may share domain modules initially. A separate gateway app is an optional extraction when socket lifecycle/scaling pressure warrants it; folder names alone do not create isolation.","kind":"Diagram"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-1ef106f65e80","heading":"Directory structure: feature modules and service boundaries","text":"Ownership rules: UI components do not call the database; transport adapters do not independently reimplement membership rules; workers do not bypass authorization/fencing contracts. Keep the message + deduplication + outbox invariant inside one transaction-owning module. Avoid a giant shared package containing business state or a global database singleton exposed to all layers.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-2176f7c59241","heading":"Directory structure: feature modules and service boundaries","text":"Deployment tradeoff: A monorepo shares versioned source/contract checks, not automatically a shared release lifecycle. Separately deployed consumers still need compatible schemas and rollout plans. See the modular versus microservice decision.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-send","heading":"Trace one send, including a lost acknowledgement","text":"Trace one send, including a lost acknowledgement","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-send-definition","heading":"Trace one send, including a lost acknowledgement","text":"Alice sends “Hello” to Bob. Trace the durable write separately from the live notification so you can explain every acknowledgement and retry.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-bfa5c7147945","heading":"Trace one send, including a lost acknowledgement","text":"A send that survives retriesCreate a stable client operationAlice generates clientMessageId once, adds a pending UI item, and sends it.Authorize and commitThe service derives Alice’s identity, checks membership, and commits one canonical message plus outbox event.Return acceptedAlice replaces the pending item with the canonical message. If the acknowledgement is lost, the record still exists.Publish and routeThe relay publishes; fanout reaches Bob’s device and Alice’s other devices. Duplicate events are possible.Apply idempotentlyEach device merges by canonical message ID/sequence; Bob acknowledges delivery.Retry an uncertain resultAlice resends with the same clientMessageId. The uniqueness/result contract returns the original message instead of creating another.","kind":"Diagram"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-d99b54532dd9","heading":"Trace one send, including a lost acknowledgement","text":"Subtle point: The same clientMessageId must not silently accept different text or a different conversation. Store enough request identity to reject conflicting reuse. Keep a documented deduplication window compatible with allowed client retries; if deduplication expires while offline retries remain possible, duplicates can reappear.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-fab65755a4f8","heading":"Trace one send, including a lost acknowledgement","text":"Related mechanisms: This is the same ambiguous-outcome issue as job idempotency. It does not require claiming exactly-once network delivery.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-27193e5b164f","heading":"Trace one send, including a lost acknowledgement","text":"Sequence sketch · one message from send to deliveryOpen full-size diagramScroll horizontally on smaller screens.Send sequence: durable acceptance before deliveryTime moves downward. The service commits a message and outbox before acknowledging the sender; asynchronous relay/fanout reaches the recipient. A lost acknowledgement is resolved by retrying the same clientMessageId.1. send stable clientMessageId2. authorize + dedupe + commit3. durable result + sequence4. accepted (canonical ID)5. poll committed outbox → publish6. message event via gateway7. device delivery acknowledgement8. retry same key if uncertain9. original stored resultSender UIMessage serviceDatabase/outboxRelay / fanoutRecipient UIGateway/broker hops are expanded in the system diagram. Dashed arrows are replies/acknowledgements.Time moves downward. Replies/acknowledgements are dashed. Relay polling is asynchronous; publication may happen before or after the sender observes accepted. The invariant is that both accepted and publication follow commit. The retry at the end illustrates a lost acknowledgement, not an instruction to retry every successful send.","kind":"Diagram"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-consistency","heading":"Ordering and consistency: define the visible guarantees","text":"Ordering and consistency: define the visible guarantees","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-consistency-definition","heading":"Ordering and consistency: define the visible guarantees","text":"Guarantee a canonical order within one conversation, not a global order across the app. Concurrent sends from different users receive server-assigned sequences; there is no unique “real-world first” when their operations overlap.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-99bc3f0ce77f","heading":"Ordering and consistency: define the visible guarantees","text":"Implementation: A transactional conversation row counter or a single write owner serializes accepted writes. The database’s ownership/failover mechanism must prevent two unfenced owners from assigning conflicting sequences. This introduces contention in a hot conversation; shard different conversations independently before redesigning ordering for exceptionally large channels.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-930207689eb2","heading":"Ordering and consistency: define the visible guarantees","text":"Live transport: A WebSocket preserves order on its own connection, but retries, separate gateways, broker consumers, and reconnect can reorder application events. Store events by canonical sequence, deduplicate, and recover detected gaps. Broker partition ordering only covers its own append order; ensure per-conversation relay ordering if relying on it, or reconcile against database sequences.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-8d43ffab4d2c","heading":"Ordering and consistency: define the visible guarantees","text":"Read consistency: An accepted send can be absent from a lagging replica. For read-your-writes, serve the authoritative writer or use a supported minimum-position/consistency-token policy. Do not hide stale-replica gaps as permanent message loss. History is durable; presence and receipts can be eventually consistent.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-696188fb90ab","heading":"Ordering and consistency: define the visible guarantees","text":"Availability tradeoff: During loss of safe write ownership, reject or hold sends as pending rather than pretending they are durably ordered. Acknowledged writes survive only the stated replication failure model: async cross-region copies can still lose recent data in regional disaster recovery. State RPO/RTO explicitly before promising zero loss.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-reconnect","heading":"Reconnect and offline catch-up: live events are an optimization","text":"Reconnect and offline catch-up: live events are an optimization","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-reconnect-definition","heading":"Reconnect and offline catch-up: live events are an optimization","text":"Clients need a reconciliation protocol, not just an automatic socket reconnect. Treat authoritative history as the recovery source and live events as a low-latency delivery path.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-a30b95626d87","heading":"Reconnect and offline catch-up: live events are an optimization","text":"Close the history/subscription raceReconnect with backoff and jitterAuthenticate again, register the device connection, and resume only authorized subscriptions.Subscribe and buffer live eventsEstablish the subscription before reading history; keep a bounded temporary buffer.Fetch after the last contiguous positionThe server returns ordered authorized history and a snapshot high-water mark through which the catch-up is complete.Merge history and buffered eventsDeduplicate and sort by canonical sequence. Fetch remaining gaps; do not advance the contiguous cursor past a missing message.Switch to normal live deliveryContinue gap detection. If the buffer overflows or history expires, discard the partial attempt and resynchronize explicitly.","kind":"Diagram"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-bc41d7bb27f7","heading":"Reconnect and offline catch-up: live events are an optimization","text":"Why subscribe first? Fetching history and only then subscribing can miss a message committed in between. A framework-specific replay token or durable per-user sync stream is another valid design, but must define the same boundary. Never assume socket replay exists without a server protocol.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-ac85dc8054e7","heading":"Reconnect and offline catch-up: live events are an optimization","text":"Multi-conversation recovery: At small scale, sync each known conversation from its cursor and refresh the conversation list to discover new membership. At larger scale, introduce a per-user change feed with retention and resume tokens. If tokens expire, fall back to a bounded full refresh. A sequence cursor is not authorization.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-80553c9405fc","heading":"Reconnect and offline catch-up: live events are an optimization","text":"Browser limits: Keep offline cursors/drafts in appropriate storage, account for quota/eviction, and avoid treating local persistence as a durable server acknowledgement. Coordinate duplicate tabs if needed using cross-tab synchronization.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-fanout","heading":"Queue vs. topic: fanout and offline notifications","text":"Queue vs. topic: fanout and offline notifications","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-fanout-definition","heading":"Queue vs. topic: fanout and offline notifications","text":"Fanout converts one message into recipient/device deliveries. For groups capped at 100, looking up members and routing to their online devices is a reasonable starting point. Avoid writing a full message copy per recipient unless read patterns justify the storage amplification.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-159441674ba5","heading":"Queue vs. topic: fanout and offline notifications","text":"Queue versus topic: A queue normally distributes each work item to one competing consumer. An event topic/stream lets independent subscriptions or consumer groups each process the same message event. Within one Kafka consumer group, partitions are assigned among consumers; every consumer does not automatically receive every event.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-fe352f23b515","heading":"Queue vs. topic: fanout and offline notifications","text":"Kafka option: Key by conversationId to keep one conversation on a partition, then use independent consumer groups for delivery and notifications. Kafka retains a replayable log and supports partition ordering; it adds operational cost and finite retention. A simpler managed queue or outbox poller may be enough. Kafka transactions do not make database writes and arbitrary push-provider calls one exactly-once transaction.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-8a06320dacac","heading":"Queue vs. topic: fanout and offline notifications","text":"Routing: A fanout worker consults the connection directory and sends to the owning gateways through internal routing/pub-sub. A live ephemeral pub/sub system can lose events; durable history and catch-up repair missed delivery. Broker backlog must not turn into unbounded memory in gateways.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-3c6928f4ed33","heading":"Queue vs. topic: fanout and offline notifications","text":"Offline notification: After a short policy-defined delay, check receipts/preferences and send a bounded push notification. Presence alone is too stale to prove that the user received the message. Deduplicate notification jobs; lease/sweeper recovery can help if the queue does not already provide redelivery. See recovery mechanisms.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-48dec474a512","heading":"Queue vs. topic: fanout and offline notifications","text":"Large-channel extension: Huge groups create O(member/device count) fanout and hot conversations. Consider fanout-on-read, selective subscription, batching, separate channel infrastructure, and explicit product latency tradeoffs. Do not apply the small-group design unchanged.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-scale","heading":"Scale and cache by the actual bottleneck","text":"Scale and cache by the actual bottleneck","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-scale-definition","heading":"Scale and cache by the actual bottleneck","text":"Scale connections, writes, reads, and fanout independently where evidence supports it. Start with measurements; adding replicas or caches changes specific bottlenecks, not every bottleneck.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-87fefc50f74c","heading":"Scale and cache by the actual bottleneck","text":"PressureInterventionTradeoff","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-5aec0e9c248d","heading":"Scale and cache by the actual bottleneck","text":"Many socketsAdd gateways with headroom and zone diversity.More connection-directory churn; tune heartbeat and reconnect behavior.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-37ec08f16c52","heading":"Scale and cache by the actual bottleneck","text":"Many conversation writesShard by conversation ownership.Cross-conversation queries and rebalancing become harder.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-7ccdb078e290","heading":"Scale and cache by the actual bottleneck","text":"One extremely hot groupRevisit serialized writes and fanout architecture.More database shards alone do not split one ordered key.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-66e27ffd3647","heading":"Scale and cache by the actual bottleneck","text":"Repeated membership/recent-history readsCache-aside with bounded TTL and event invalidation.Stale authorization is dangerous: authoritative checks must enforce revocation semantics.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-841428ab112a","heading":"Scale and cache by the actual bottleneck","text":"History read loadIndexes, pagination, retention, and eligible replicas.Replica lag needs explicit read consistency.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-cdd9a31d61d2","heading":"Scale and cache by the actual bottleneck","text":"Media extensionSigned uploads, object storage, and a CDN.Size/type limits, scanning, authorization, and cache-key policy become necessary.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-cdb2c7e47d26","heading":"Scale and cache by the actual bottleneck","text":"Caching strategies: Cache-aside reads the database on a miss and fills the cache; invalidation and races remain your responsibility. Write-through coordinates writes via a cache layer but adds failure coupling. Write-behind buffers durable writes and risks loss unless backed by a durable contract; it is unsuitable for acknowledging messages based only on volatile memory. Use TTL as a staleness bound, not proof of current permission.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-622106bb0113","heading":"Scale and cache by the actual bottleneck","text":"Load balancing: Existing sockets are not redistributed when adding gateways; new connections may balance better while older instances remain busy. Use connection draining and jittered reconnects during deploys. Apply graceful shutdown and avoid reconnecting all clients at once.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-cache-policy","heading":"Chat cache policy: where freshness matters","text":"Chat cache policy: where freshness matters","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-cache-policy-definition","heading":"Chat cache policy: where freshness matters","text":"Cache only the paths that have an explicit staleness allowance. Durable history, UI snapshots, authorization, and presence do not share the same freshness contract.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-47a3f7c7b558","heading":"Chat cache policy: where freshness matters","text":"Location / dataPolicyFailure / stale behavior","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-f3685439a1f9","heading":"Chat cache policy: where freshness matters","text":"Browser: message pagesKey by account + conversation + page/cursor; merge by canonical ID/sequence.Show loaded history with reconnect state; clear personalized cache on logout; reconcile gaps.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-c5fb89f07b29","heading":"Chat cache policy: where freshness matters","text":"Service: recent historyCache-aside, short bounded freshness or version-aware update/invalidation.A read-after-send request must satisfy its minimum accepted position, using the writer if necessary.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-0edaffe04d44","heading":"Chat cache policy: where freshness matters","text":"Service: membershipOptional lookup accelerator with invalidation/versioning.Do not let a stale allow decision bypass the authoritative revocation contract.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-79df0b09e8a5","heading":"Chat cache policy: where freshness matters","text":"Directory: user/device → gatewayEphemeral entries, heartbeat/TTL, connection epoch.A miss is a routing miss, not “no message exists”; fall back to catch-up/history.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-dc6b4689d52a","heading":"Chat cache policy: where freshness matters","text":"Presence/typingShort-lived ephemeral state.Hide or label unknown rather than block message sends.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-9c95695ebac9","heading":"Chat cache policy: where freshness matters","text":"Database/outboxAuthoritative durable state, not a volatile cache.Reject durable acceptance if its commit contract cannot be met.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-6eeccfb1351d","heading":"Chat cache policy: where freshness matters","text":"Stampede example: A gateway restart can reconnect thousands of clients that request the same hot histories and membership lists. Coalesce identical reads, use bounded concurrency and jittered reconnects, and protect database capacity. Cache bypass during an outage must remain rate-limited. Refer to the strategy and invalidation checklist.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-cdn","heading":"CDN: deliver the app shell, isolate private data","text":"CDN: deliver the app shell, isolate private data","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-cdn-definition","heading":"CDN: deliver the app shell, isolate private data","text":"Use a CDN to serve content-hashed JavaScript/CSS and approved public static assets near users. It reduces origin load and startup latency; it does not replace WebSocket gateways, private message storage, or authorization.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-652ced1c01b8","heading":"CDN: deliver the app shell, isolate private data","text":"Deployment: Publish versioned assets before serving HTML that references them, retain prior assets for an appropriate transition window, and use an HTML freshness/revalidation policy compatible with deployment and rollback. Long-lived immutable caching fits hashed assets; avoid assigning that same policy indiscriminately to the HTML entry point.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-2b8e480539f6","heading":"CDN: deliver the app shell, isolate private data","text":"Private media extension: Upload/download through scoped signed URLs or an authenticated media edge flow, with bounded expiry, object permissions, scanning, and a deliberate cache-key policy. Ensure a cached object is not served to an unauthorized caller merely because an earlier authorized request warmed it.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-88e673bea778","heading":"CDN: deliver the app shell, isolate private data","text":"Failure: Observe asset load failures and CDN/origin errors separately from API failures. Retry boundedly, detect a stale HTML/missing-chunk mismatch, and offer a controlled refresh while preserving drafts where safe. A fallback origin must retain the same security and capacity protections. Offline caching via a service worker is an additional design with versioning/revocation costs, not a free guarantee.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-failures","heading":"Failure drills, backpressure & observability","text":"Failure drills, backpressure & observability","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-failures-definition","heading":"Failure drills, backpressure & observability","text":"Test the promises made by the design. A healthy-path diagram alone cannot establish durability, recovery, or overload behavior.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-7b3342e98b7b","heading":"Failure drills, backpressure & observability","text":"FailureExpected responseSignal to watch","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-4977a234a79b","heading":"Failure drills, backpressure & observability","text":"Gateway crashesReconnect elsewhere and catch up from durable history.Disconnect/reconnect rate, catch-up latency.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-fe42838a6e42","heading":"Failure drills, backpressure & observability","text":"Commit succeeds; acknowledgement is lostRetry the same logical send and return the stored result.Deduplication hit rate, ambiguous-send duration.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-b2364e460266","heading":"Failure drills, backpressure & observability","text":"Relay crashes after publishRepublish may duplicate; consumers merge idempotently.Outbox oldest age and duplicate rate.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-bd3d9c6e2dd9","heading":"Failure drills, backpressure & observability","text":"Broker unavailableMessages may still be accepted if durable outbox capacity/policy permits; live delivery is delayed.Backlog age/size; reject new work before storage exhaustion.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-3a4a91c5d6b3","heading":"Failure drills, backpressure & observability","text":"Database writer unavailableDo not emit accepted; return retryable failure/pending UX.Durable-send availability, commit latency, failover time.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-6d8d6433b166","heading":"Failure drills, backpressure & observability","text":"Recipient is slowBound outbound buffers; disconnect/resync rather than accumulate unlimited memory.Buffer pressure, dropped/resync connections.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-81d6b8259f8e","heading":"Failure drills, backpressure & observability","text":"Membership revokedBlock future reads/sends/deliveries according to the contract; remove subscriptions.Authorization denials, stale-route/cache errors.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-363409a1e974","heading":"Failure drills, backpressure & observability","text":"Backpressure: Bound payloads, in-flight sends, database-pool waits, broker batches, and per-socket queues. Rate-limit abusive users and protect tenants from noisy neighbors. Retries need capped backoff and jitter; overload should produce explicit retry guidance.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-d6539ee35272","heading":"Failure drills, backpressure & observability","text":"Observe the user journey: Measure send-to-accepted and accepted-to-delivered separately, plus p95/p99 history latency, sequence-gap recovery, error-budget consumption, and queue lag. Propagate clientMessageId/messageId/trace identifiers across services without logging message bodies or credentials. See request context and backpressure.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-observe-errors","heading":"Observe a failed send: browser to database to recipient","text":"Observe a failed send: browser to database to recipient","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-observe-errors-definition","heading":"Observe a failed send: browser to database to recipient","text":"Start diagnosis from the user-visible failure: “My message is still pending” is different from “accepted but not delivered.” Instrument the state transitions so each has evidence.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-86b55f7e34dc","heading":"Observe a failed send: browser to database to recipient","text":"EvidenceCaptureHow it helps","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-6f36de83d290","heading":"Observe a failed send: browser to database to recipient","text":"Browser actionclientMessageId, safe error code, connection state, app release, attempt count.Tells local validation, offline state, asset/render errors, and transport failure apart.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-9980c26864fd","heading":"Observe a failed send: browser to database to recipient","text":"Gateway / serviceTrace context, authenticated principal reference, request/message IDs, authorization result, safe timings.Connects the command to deduplication, membership, and the transaction without logging message text.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-4616603d0962","heading":"Observe a failed send: browser to database to recipient","text":"Database / outboxCommit result, canonical sequence, outbox event ID, publish attempts and age.Distinguishes accepted storage from delayed publication.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-7cd15781f717","heading":"Observe a failed send: browser to database to recipient","text":"Broker / fanoutConsumer lag, routing result, recipient-device delivery attempt.Finds queue backlog, stale directory entries, and slow gateways.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-1c6fedc9af0c","heading":"Observe a failed send: browser to database to recipient","text":"Recipient acknowledgementDelivery/read cursor progress and gap-recovery outcome.Separates a socket write from confirmed device receipt.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-5e7ac9e4e25c","heading":"Observe a failed send: browser to database to recipient","text":"SLIs/SLOs: Measure durable-send success over eligible authorized, valid send attempts; define treatment of client disconnects and user cancellations. Track latency to durable acceptance separately from online delivery. An online-delivery SLI must define “online” and include eligible failures/timeouts, not only successful samples, otherwise it hides missing deliveries. Keep receipts, queue age, history latency, and gap recovery as separate signals.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-2d13e56c7ce0","heading":"Observe a failed send: browser to database to recipient","text":"Alerts: Page on sustained send-availability/latency error-budget burn, critical storage health, or a stuck/out-of-capacity outbox. Notify at lower urgency for rising reconnects or optional presence errors. Correlate with deploys and zone health, use trace exemplars or logs for IDs rather than high-cardinality metric labels, and keep a runbook with ownership and safe recovery commands.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-5780899f6daf","heading":"Observe a failed send: browser to database to recipient","text":"Frontend capture: Use error boundaries for render failures and explicit reports for handled network/validation paths; monitor unhandled rejections with deduplication. Attach release/source-map context to diagnostic reports, apply privacy controls, and never log session tokens or private chat content. See error-boundary limits and server correlation context.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-fallbacks","heading":"Fallbacks: preserve truth and recover deliberately","text":"Fallbacks: preserve truth and recover deliberately","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-fallbacks-definition","heading":"Fallbacks: preserve truth and recover deliberately","text":"A fallback strategy defines a degraded but honest service behavior, with a trigger and a recovery path. It is not “retry forever” or return a successful-looking response from incomplete data.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-6b4109ffa653","heading":"Fallbacks: preserve truth and recover deliberately","text":"TriggerUser-visible fallbackRecovery / limit","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-70501a5ebe67","heading":"Fallbacks: preserve truth and recover deliberately","text":"WebSocket unavailableShow reconnecting; keep draft and uncertain sends pending.If supported, switch to HTTP sends using the same idempotency keys and bounded polling/catch-up; reconcile both transports to avoid duplicate display.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-b3a676f053fb","heading":"Fallbacks: preserve truth and recover deliberately","text":"Presence/receipt subsystem slowShow presence/receipt as unknown or delayed.Messages continue if their durable path is healthy; do not fabricate read status.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-6dd314ccb56b","heading":"Fallbacks: preserve truth and recover deliberately","text":"History service unavailableShow already loaded history with a clear stale/offline indication.Retry boundedly; do not show “empty conversation” for a failed fetch or bypass authorization.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-0a31b34db950","heading":"Fallbacks: preserve truth and recover deliberately","text":"Cache unavailableUse limited authoritative reads when capacity permits.Coalesce, rate-limit, and shed excess load; unbounded bypass can crash the database.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-5145520f3135","heading":"Fallbacks: preserve truth and recover deliberately","text":"Broker unavailableAccepted messages show delivery delayed if the durable outbox policy permits continued sends.Publish backlog after recovery; stop admission before durable backlog capacity runs out.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-52dbbe2c116c","heading":"Fallbacks: preserve truth and recover deliberately","text":"Database commit uncertain/unavailableKeep pending or show retryable failure; never mark accepted.Resolve outcome/retry with the same logical key after safe ownership recovers.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-6b87907ef15d","heading":"Fallbacks: preserve truth and recover deliberately","text":"Repeated downstream failureOpen a circuit breaker for the affected optional path if appropriate.Use bounded half-open probes; do not fail open for membership/authorization.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-1d6fd4fc8887","heading":"Fallbacks: preserve truth and recover deliberately","text":"Transport caution: HTTP+polling fallback must be designed and capacity-tested, not improvised during an outage. SSE is useful if available but may share proxy/network failure causes with WebSockets. Switching protocols changes load, ordering, and retry paths; use one canonical persistence/deduplication contract.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-6ee92e6439ca","heading":"Fallbacks: preserve truth and recover deliberately","text":"Wrap-up decision: State which feature degrades, which invariant remains, how long recovery may take, and what the user can safely do. See circuit breakers and bulkheads and observability and fallback principles.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-frontend","heading":"Frontend design: reliable UX over an unreliable connection","text":"Frontend design: reliable UX over an unreliable connection","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-frontend-definition","heading":"Frontend design: reliable UX over an unreliable connection","text":"Model a chat UI as server-owned history plus client-owned interaction state. A socket event is an update source, not a replacement for an authoritative cache and reconciliation rules.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-a7711bb0bb7d","heading":"Frontend design: reliable UX over an unreliable connection","text":"Ownership: The URL owns selected conversation; component state owns draft and focus; a server-state cache owns normalized messages and receipts.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-03088fec3cf5","heading":"Frontend design: reliable UX over an unreliable connection","text":"Optimistic send: Key pending items by clientMessageId, merge accepted events with canonical IDs, and expose retry/error states. Avoid duplicate display if acceptance arrives before the send callback.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-eac4af6358b5","heading":"Frontend design: reliable UX over an unreliable connection","text":"Ordering: Render canonical sequence, retain pending items with an explicit temporary policy, and recover gaps. Do not sort exclusively by device timestamps.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-4fffa7fb5544","heading":"Frontend design: reliable UX over an unreliable connection","text":"History: Paginate and virtualize long lists; preserve scroll position when prepending older messages. Auto-scroll only when the user is near the bottom or has explicitly requested it.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-92700ce8c724","heading":"Frontend design: reliable UX over an unreliable connection","text":"Lifecycle: Cancel obsolete history fetches and unsubscribe from old conversations. Clean up sockets/listeners and manage reconnect state. Background tabs and offline transitions can pause timers.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-addc758e7227","heading":"Frontend design: reliable UX over an unreliable connection","text":"Accessibility: Label the composer, support keyboard actions, and announce new messages without repeatedly reading the full history or moving focus.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-61a94dc3a1ce","heading":"Frontend design: reliable UX over an unreliable connection","text":"Existing material: Use server versus client state, optimistic conflict handling, focus and scroll behavior, and virtualization and loading techniques.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-ux-states","heading":"Frontend design: reliable UX over an unreliable connection › UX state matrix: map feedback to guarantees","text":"UX state matrix: map feedback to guarantees","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-b8cf8627adaa","heading":"Frontend design: reliable UX over an unreliable connection › UX state matrix: map feedback to guarantees","text":"SituationUI solutionReason / consideration","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-0867243a8307","heading":"Frontend design: reliable UX over an unreliable connection › UX state matrix: map feedback to guarantees","text":"Initial loadConversation list and selected history have independent loading/error states.One failed panel should not blank the whole app.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-4644cb2fb253","heading":"Frontend design: reliable UX over an unreliable connection › UX state matrix: map feedback to guarantees","text":"Send pendingShow a pending item keyed by clientMessageId, retain the draft until safely transferred to the pending model.Do not label local intent as durable acceptance.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-8d129bbe1ff0","heading":"Frontend design: reliable UX over an unreliable connection › UX state matrix: map feedback to guarantees","text":"Accepted / delivered / readRender explicit receipt states with accessible labels.Keep the meanings from the API contract; delayed receipts are not a failed send.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-7ce121dda8bc","heading":"Frontend design: reliable UX over an unreliable connection › UX state matrix: map feedback to guarantees","text":"Send uncertain or failedExpose retry for the same logical operation, safe edit/discard choices, and conflict feedback.Editing a new attempt needs an intentional new operation; never reuse a key with different content silently.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-25eee7bb178b","heading":"Frontend design: reliable UX over an unreliable connection › UX state matrix: map feedback to guarantees","text":"Reading older historyShow a new-message indicator instead of forcing scroll.Preserve context, keyboard focus, and screen-reader usability.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-2a0408824f3d","heading":"Frontend design: reliable UX over an unreliable connection › UX state matrix: map feedback to guarantees","text":"Disconnected / recoveringShow reconnect status, bounded retry timing, and visible draft preservation.Offer only operations the backend contract can eventually reconcile.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-c86ef0e6aa13","heading":"Frontend design: reliable UX over an unreliable connection › UX state matrix: map feedback to guarantees","text":"Product validation: Demonstrate the mobile composer, keyboard send/newline behavior, accessible error/retry controls, and the distinction between an empty inbox and a load failure. Use the UI decision checklist to tie these choices to rendering and state ownership.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-b0e1936d88d9","heading":"Frontend design: reliable UX over an unreliable connection › UX state matrix: map feedback to guarantees","text":"Client-library tradeoff: See Context, Redux Toolkit, and XState. For this case, start with local drafts and one server-message cache; a reconnect actor may own connecting/connected/backoff states. An external store can coordinate truly shared client state, but should not create a second independent history cache.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-security","heading":"Security and privacy boundaries","text":"Security and privacy boundaries","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-security-definition","heading":"Security and privacy boundaries","text":"Authenticate the connection and authorize each resource operation. A valid session does not authorize every conversation, and a gateway subscription made earlier does not grant permanent access.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-a90440af25e5","heading":"Security and privacy boundaries","text":"WebSocket specifics: Use WSS, validate the handshake Origin against an allowlist when browser cookies authenticate it, and protect against cross-site WebSocket hijacking. CORS is not a substitute for WebSocket Origin validation or server authorization. Avoid long-lived bearer tokens in URLs because URLs can leak into logs; use an appropriate cookie/session or short-lived connection-ticket flow.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-f25b33cc0d7a","heading":"Security and privacy boundaries","text":"Session changes: Define token/session expiry and revocation on long-lived connections. On logout, close relevant sessions, revoke access, and clear personalized cached content. Recheck or invalidate permissions when membership changes, including before fanout; define whether revocation can race an already authorized delivery.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-a24e4c913d96","heading":"Security and privacy boundaries","text":"Content: Render plain text using safe text rendering. If rich content is added, use a narrowly defined format and the existing XSS defenses, including sanitization where HTML is allowed. Apply abuse controls, payload limits, retention, and restricted operational access.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-25206e2203fb","heading":"Security and privacy boundaries","text":"Encryption scope: TLS protects transit; encryption at rest protects stored data under a key-access model. Neither is end-to-end encryption. E2EE changes device keys, group membership, recovery, search, moderation, and server visibility and needs its own design. See session lifecycle.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-review","heading":"Review: defend the design, then change a constraint","text":"Review: defend the design, then change a constraint","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"chat-review-definition","heading":"Review: defend the design, then change a constraint","text":"One-minute explanation: Keep durable ordered history in the message store. Acknowledge only after commit, with a stable client operation ID for retries. Publish committed changes through an outbox, fan out to currently authorized devices, and treat reconnect history synchronization as the recovery path. Scale gateways separately from conversation write ownership; keep presence and receipts eventually consistent where the product permits it.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-d4385de70954","heading":"Review: defend the design, then change a constraint","text":"Challenge yourself: What if the database commits but the socket closes? What if an outbox event is published twice? What if a replica is behind? What if the broker is unavailable for an hour? What if a user is removed while an event is queued? For each answer, identify the authoritative record and the precise recovery path.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-73b9d5994ce6","heading":"Review: defend the design, then change a constraint","text":"Next design iteration: Choose one extension—large channels, regional disaster recovery, attachments, or E2EE. Change the assumptions and estimates first, then explain which component contracts must change. Do not append every possible component to the baseline.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-6124367ee907","heading":"Review: defend the design, then change a constraint","text":"Return to the System Design practice guide.","kind":"Notes"},{"page":"system-design-chat.html","topic":"Case Study: Design a Chat Web App","anchor":"search-697eee5e4228","heading":"Review: defend the design, then change a constraint","text":"Four-step recap: (1) Confirm scope, entities, operations, scale, and UX. (2) Propose the durable-write/live-delivery blueprint and validate alignment. (3) Deep-dive into ordering, idempotency, cache/CDN policy, service boundaries, monitoring, and fallback contracts. (4) Name bottlenecks, remaining risks, SLOs, cost, and the next requirement to test. Prioritize a few critical risks rather than rushing through every possible technology.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"system-design-jobs-title","heading":"","text":"Case Study: Dynamic Job Discovery","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-b6aaa06fd27e","heading":"","text":"Design hierarchical categories, dynamic faceted filtering and job results as one consistent search experience—from URL state to search aggregations and indexing.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-e65620c34d7c","heading":"","text":"Step 1 · Clarify the discovery contract","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-77baca0397a2","heading":"","text":"Define facet eligibility and count semantics before implementation","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-0f1c1615a19f","heading":"","text":"Estimate load and choose the simplest search engine that fits","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-7aa316547e5b","heading":"","text":"UI sketch · categories, filters and results","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-5da8fc42a188","heading":"","text":"Frontend sketch · URL ownership and one search snapshot","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-d83eead3ecde","heading":"","text":"Step 2 · High-level architecture and indexing","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-e8942d393747","heading":"","text":"API contract · one query, one coordinated response","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-e8878c01c44e","heading":"","text":"Step 3 · Query planning, taxonomy and salary semantics","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-4f8fde1ef41f","heading":"","text":"Interaction sequence · atomic panels and stale-response safety","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-0c47b7abaa2b","heading":"","text":"Scale, consistency, caching and failure recovery","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-5d3221eb0fa2","heading":"","text":"Directory sketch · isolate domain semantics from transport","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-4f8e46e3cb3d","heading":"","text":"Step 4 · Verify the invariants and defend the tradeoffs","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-requirements","heading":"Step 1 · Clarify the discovery contract","text":"Step 1 · Clarify the discovery contract","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-requirements-definition","heading":"Step 1 · Clarify the discovery contract","text":"Design a job discovery page where category navigation, eligible filters, dynamic counts and job results are projections of the same applied search query. The difficult part is defining what each count means and keeping every panel synchronized.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-2ecfc142eef5","heading":"Step 1 · Clarify the discovery contract › Functional requirements","text":"Functional requirements","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-f7f2249206d7","heading":"Step 1 · Clarify the discovery contract › Functional requirements","text":"Browse a hierarchical category taxonomy; selecting a category shows its matching immediate children, breadcrumb ancestors and descendant jobs.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-6679192a89ae","heading":"Step 1 · Clarify the discovery contract › Functional requirements","text":"Apply experience, salary, skills and job-type filters. Update categories, facet options, counts and listings together.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-2c13a461edaa","heading":"Step 1 · Clarify the discovery contract › Functional requirements","text":"Remove individual filters, clear all, change sort and paginate. Preserve searches in shareable URLs and browser Back/Forward.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-574c23a9a58c","heading":"Step 1 · Clarify the discovery contract › Functional requirements","text":"Open a job detail page; support loading, empty, error and retry states.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-e65c587c9a01","heading":"Step 1 · Clarify the discovery contract › Non-functional requirements","text":"Non-functional requirements","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-29e458fdcbd9","heading":"Step 1 · Clarify the discovery contract › Non-functional requirements","text":"Illustrative targets to validate: search API p95 ≤300 ms at agreed load; interactive update p95 ≤500 ms on the target network; 99.9% monthly search availability.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-0fc45033e2f8","heading":"Step 1 · Clarify the discovery contract › Non-functional requirements","text":"Keyboard and screen-reader access; responsive layout; deterministic query semantics; no stale-response overwrite.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-1265b5865a03","heading":"Step 1 · Clarify the discovery contract › Non-functional requirements","text":"Search freshness target: 99% of accepted job changes indexed within 30 seconds. Closed jobs must be revalidated on the detail/application boundary.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-a7b4fd5f0bd8","heading":"Step 1 · Clarify the discovery contract › In scope","text":"In scope","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-83a07affa7d9","heading":"Step 1 · Clarify the discovery contract › In scope","text":"Discovery, taxonomy navigation, faceting, public job detail, ingestion into a search read model and operational recovery.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-a34b5c50c84e","heading":"Step 1 · Clarify the discovery contract › Out of scope","text":"Out of scope","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-b6389d84a3db","heading":"Step 1 · Clarify the discovery contract › Out of scope","text":"Application submission, employer billing, recommendations/personalization, CV storage and chat. Employer writes are an indexing input, not a fully designed recruiting workflow.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-3d9c2c60aed6","heading":"Step 1 · Clarify the discovery contract › Out of scope","text":"Clarify before drawing: single or multiple categories? OR or AND for skills? Include descendants? Count jobs or vacancies? Hide zero-count options? Currency and salary-period conversion? This design assumes one category subtree, OR within categorical facets, AND across facets, and one count per unique visible job.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-counts","heading":"Define facet eligibility and count semantics before implementation","text":"Define facet eligibility and count semantics before implementation","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-counts-definition","heading":"Define facet eligibility and count semantics before implementation","text":"Conjunctive filtering: results match the text query, visibility scope, selected category subtree and every active facet. Within one multi-select facet, selected values are OR-ed. A skills “must have all” mode would require explicit AND semantics and different aggregation logic.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-b2473263cf90","heading":"Define facet eligibility and count semantics before implementation","text":"There are two valid count contracts. Do not silently mix them:","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-3e7f54b26899","heading":"Define facet eligibility and count semantics before implementation","text":"ContractCount for option v in facet FBehavior / cost","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-4f1a470c7323","heading":"Define facet eligibility and count semantics before implementation","text":"Strict / conjunctiveApply all current constraints, including F, then count jobs also having v.Only options in the current result set remain eligible; meets a literal narrowing-only interpretation, but alternatives can disappear.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-e377e278e794","heading":"Define facet eligibility and count semantics before implementation","text":"Disjunctive / self-excludingApply every constraint except F, then count jobs having v.Lets users choose alternatives or broaden an OR selection. Requires per-facet aggregation scopes. The displayed count is not the predicted total after adding v.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-2a5f3455cb05","heading":"Define facet eligibility and count semantics before implementation","text":"Chosen baseline: disjunctive faceting for useful multi-select discovery; explicitly confirm this product decision. “Eligible” means nonzero under that facet’s self-excluding scope. If the stakeholder requires strict narrowing, use the first contract; the architecture stays the same. Return countMode in the response.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-6a36b81f2a74","heading":"Define facet eligibility and count semantics before implementation","text":"Worked example: A = Engineering / Remote / React / Full-time; B = Engineering / Remote / React / Contract; C = Engineering / Onsite / React / Full-time. With Engineering + Remote + Full-time, results contain A. Strict job-type counts: Full-time 1, Contract 0. Self-excluding job-type counts: Full-time 1, Contract 1. Selecting both returns A and B. Counts overlap for multi-valued facets, so adding counts does not produce a distinct-job total.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-ca76c5d6a472","heading":"Define facet eligibility and count semantics before implementation","text":"Category counts: exclude the current category constraint but retain query, visibility and every active facet; bucket by ancestor category IDs. Show matching immediate children of the selected node plus breadcrumb navigation. Parent counts deduplicate jobs, so sibling totals can exceed a parent when jobs have multiple classifications.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-c5183c5464d8","heading":"Define facet eligibility and count semantics before implementation","text":"Never strand the user: retain selected zero-count options with a removable chip, and retain selected categories/ancestors even if empty. Hide or disable unselected zero-count options according to the agreed contract. An empty result must still allow recovery.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-scale","heading":"Estimate load and choose the simplest search engine that fits","text":"Estimate load and choose the simplest search engine that fits","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-aa27fd3d33bb","heading":"Estimate load and choose the simplest search engine that fits","text":"Assume 5 million active jobs, 200,000 daily searchers and 20 committed searches each: 4 million searches/day ≈46 average RPS; a 10× peak is approximately 460 RPS. Draft keystrokes are excluded: count actual requests after debouncing. A 2 KB search document gives roughly 10 GB raw data before inverted indexes, replicas and operational headroom.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-e3b91ddab529","heading":"Estimate load and choose the simplest search engine that fits","text":"One request performs hits plus several aggregations: API RPS is not shard work. Benchmark realistic facet cardinality, skew, OR selections and cold caches; measure query fanout and memory before selecting shard counts.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-e5e8841e9f96","heading":"Estimate load and choose the simplest search engine that fits","text":"OptionUse whenTradeoff","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-de0c273203d6","heading":"Estimate load and choose the simplest search engine that fits","text":"SQL with indexes / full-text searchSmaller catalog, modest load, simple filters; start here when benchmarks satisfy targets.Transactional simplicity; many dynamic facet counts may become expensive joins/grouping.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-b50da8ceea4e","heading":"Estimate load and choose the simplest search engine that fits","text":"OpenSearch / Elasticsearch read modelFull-text relevance, many facets, large catalog or high query volume.Fast inverted-index filtering and aggregations; extra operations and eventual indexing consistency.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-c9121bc10265","heading":"Estimate load and choose the simplest search engine that fits","text":"Client-side filteringSmall complete local dataset only.Low network latency; partial downloaded pages cannot yield correct global facets or totals.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-ui","heading":"UI sketch · categories, filters and results","text":"UI sketch · categories, filters and results","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-6a17b2dc501b","heading":"UI sketch · categories, filters and results","text":"Desktop discovery page · mobile uses a filter drawerJob categoriesAll jobs → EngineeringFrontend (240)Backend (180)Data (95)Search jobs: React engineerRemote ✓ · Full-time ✓ Clear allExperience: Mid (120) · Senior (85)Job type: Full-time (240) · Contract (70)Salary: currency + annual range · Apply240 results · Sort: relevanceSenior Frontend EngineerCompany · Remote · salary disclosedReact EngineerCompany · Remote · salary not disclosedPrevious Next pageIllustrative counts, not an execution of the worked example. Keep clear headings, selected chips and breadcrumb recovery. On mobile, edit a draft in a drawer and commit once with “Show results.”","kind":"Diagram"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-cc127818187f","heading":"UI sketch · categories, filters and results","text":"Use nested lists with links/disclosures for category navigation unless a full ARIA tree interaction is required. Use labeled checkboxes, fieldsets and legends for facets; salary gets labeled number inputs as an alternative to a slider. Keep focus on the activated control; politely announce the final result count and use aria-busy during updates. Do not announce every intermediate keystroke.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-331e1eb369f2","heading":"UI sketch · categories, filters and results","text":"Keep the previous complete snapshot visible with an “Updating results” state. On failure, identify that the visible snapshot belongs to the previous applied query; offer retry or undo. Never present old counts as though they match new selections.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-components","heading":"Frontend sketch · URL ownership and one search snapshot","text":"Frontend sketch · URL ownership and one search snapshot","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-e3698b47801a","heading":"Frontend sketch · URL ownership and one search snapshot","text":"Pages, components and query ownershipOpen full-size diagramScroll horizontally on smaller screens.Job search frontend: ownership and communicationSearchRoute owns URL parsing and the canonical query. A single query coordinator produces a complete snapshot for category navigation, facets, count and results. Local drafts do not own applied filters.query + scopecategoriesfacetsjobs + totalatomic responseselection → URL; reset cursorSearchRoute / jobsURL → normalized SearchQuerySearch coordinatorQuery key; abort; generation guardCategoryNavigationBreadcrumb + eligible childrenFacetPanelCheckboxes; range drafts; chipsJobResultsCount; cards; paginationSearch API adapterOne response → one snapshotSolid arrows carry query/snapshot data; dashed arrows show response or interaction paths. Category, facet and result selections all return to the route’s canonical query.","kind":"Diagram"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-components-definition","heading":"Frontend sketch · URL ownership and one search snapshot","text":"URL state: text, category ID, stable facet IDs, salary range, sort and cursor. Server state: jobs, counts, eligible options and category labels. Local state: drawer visibility, expanded navigation and uncommitted input/range drafts. Do not copy the server snapshot into independent component reducers.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-d0a47252ee90","heading":"Frontend sketch · URL ownership and one search snapshot","text":"A query-cache library handles keyed remote snapshots, deduplication and cancellation. A local reducer can coordinate draft/apply/reset transitions. Redux is optional for broader client workflows; Context distributes stable dependencies; neither computes authoritative facet counts. Reuse the state-tool comparison.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-c7ee971ead63","heading":"Frontend sketch · URL ownership and one search snapshot","text":"Normalize selected values (sorted, deduplicated IDs), omit defaults and validate URL parameters. Changing query/filter/category/sort resets the cursor in one transition. Debounce text input; apply checkbox changes immediately on desktop, batch drawer changes on mobile. Back/Forward restores URL state. See routing and navigation.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-architecture","heading":"Step 2 · High-level architecture and indexing","text":"Step 2 · High-level architecture and indexing","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-8372b1359dc0","heading":"Step 2 · High-level architecture and indexing","text":"Search read path and asynchronous indexing write pathOpen full-size diagramScroll horizontally on smaller screens.Job discovery: query and indexing pathsBrowser sends a canonical query to a search API through a load balancer. The API executes hits and aggregations against a search index. Job updates flow from a transactional database through an outbox and indexer; the search index is eventually consistent.HTTPS querynormalized querysearch + aggregationscachetransactioncommitted outbox eventsversioned index updatesBrowser / SSR routeURL query; one result snapshotLoad balancer + APIValidate; tenant/visibility scopeQuery plannerHits + facets + category countsSearch indexInverted index; aggregationsJob write applicationValidate job and taxonomySQL + outboxAuthoritative jobs; versionsIndexer workersUpsert/delete; retries; DLQBounded response cacheCanonical query + scopeThe database owns job records. The search index is a denormalized read model. Search hits and all aggregations are assembled into one response for one normalized query.","kind":"Diagram"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-architecture-definition","heading":"Step 2 · High-level architecture and indexing","text":"Start with a modular application and independently scalable search cluster; microservices are not a prerequisite. Serve static assets through a CDN. The search API authenticates where needed, validates filters, adds visibility constraints, checks a bounded cache and submits the search plan.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-8ff6635a86c0","heading":"Step 2 · High-level architecture and indexing","text":"Index documents contain job ID, title/description search fields, employer summary, stable skill IDs, job type, experience, location/remote policy, salary metadata, category IDs plus ancestor IDs, visibility, status and version. Use keyword fields/doc values for exact filters and aggregations; analyzed text for relevance. A taxonomy registry defines facet IDs, labels, types and category applicability; observed matching values determine eligibility.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-59f16ecc5cc7","heading":"Step 2 · High-level architecture and indexing","text":"Write the job and outbox record in one SQL transaction. Indexers process at least once, apply monotonically versioned upserts/deletion tombstones and retry with backoff/dead-letter handling. Prevent an old update from resurrecting a closed job. Taxonomy moves require ancestor-path reindexing; build a versioned replacement index, verify it, then switch an alias. See durable outbox publication.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-api","heading":"API contract · one query, one coordinated response","text":"API contract · one query, one coordinated response","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-api-definition","heading":"API contract · one query, one coordinated response","text":"Use GET /api/job-search for bounded public search parameters; repeated query parameters encode multi-select values. Use GET /api/job-categories/{id} for taxonomy metadata and GET /api/jobs/{id} for authoritative detail. Long complex searches can use a documented read-only POST search endpoint with explicit cache identity. GET search needs no idempotency key.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-943848ff70e1","heading":"API contract · one query, one coordinated response","text":"GET /api/job-search?q=react&category=engineering&type=full-time&remote=true&sort=relevance&limit=20","kind":"Code"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-cca83ff3dd4e","heading":"API contract · one query, one coordinated response","text":"{ \"queryKey\": \"normalized-query-hash\", \"countMode\": \"self-excluding\", \"indexVersion\": \"jobs-v7\", \"total\": { \"value\": 240, \"relation\": \"eq\" }, \"category\": { \"selectedId\": \"engineering\", \"breadcrumbs\": [{ \"id\": \"engineering\", \"label\": \"Engineering\" }], \"children\": [{ \"id\": \"frontend\", \"label\": \"Frontend\", \"count\": 120 }] }, \"facets\": [{ \"id\": \"type\", \"selectionMode\": \"or\", \"countAccuracy\": \"exact\", \"options\": [ { \"id\": \"full-time\", \"label\": \"Full-time\", \"count\": 240, \"selected\": true }, { \"id\": \"contract\", \"label\": \"Contract\", \"count\": 70, \"selected\": false } ], \"truncated\": false }], \"jobs\": [{ \"id\": \"j42\", \"title\": \"React Engineer\", \"company\": \"Example\" }], \"nextCursor\": \"opaque-query-bound-cursor\" }","kind":"Code"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-40c1a9efec96","heading":"API contract · one query, one coordinated response","text":"Return normalized applied constraints/warnings when they differ from the request. Bound page size, selected values, query length and facet buckets. Reject invalid ranges, unknown filters and tampered cursors with structured 400 errors; 429 includes Retry-After; 503 indicates temporary unavailability. Do not silently drop a salary or permission filter.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-4e982c82a50c","heading":"API contract · one query, one coordinated response","text":"Bind the opaque cursor to normalized query, sort, visibility scope and expiry. Sort by relevance/date plus a unique ID tiebreaker. Offset pagination is simpler for shallow browsing; search_after plus a point-in-time (PIT) reader avoids duplicate/missing hits during deeper navigation at the cost of retained search resources. On expired PIT, ask the client to restart. Detail pages recheck current visibility/status.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-query","heading":"Step 3 · Query planning, taxonomy and salary semantics","text":"Step 3 · Query planning, taxonomy and salary semantics","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-query-definition","heading":"Step 3 · Query planning, taxonomy and salary semantics","text":"For result hits, apply the full predicate. For each self-excluding facet F, aggregate with that facet’s selection removed while retaining all other constraints and authorization. For categories, aggregate ancestor IDs without the category selection, then project the selected node’s immediate children. A single search request can express filtered aggregations over the same reader context; separate requests may observe different refresh states.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-604a474b5a63","heading":"Step 3 · Query planning, taxonomy and salary semantics","text":"In Elasticsearch-style execution, a post_filter changes hits after aggregations; it does not automatically implement all self-excluding facets. Build explicit per-facet filter scopes. Put mandatory visibility/security constraints outside any user-filter exclusion so no aggregation can reveal hidden jobs.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-24d8983f4fb7","heading":"Step 3 · Query planning, taxonomy and salary semantics","text":"For a salary interval, decide whether a job must overlap or be contained. Baseline: interval overlap, so job.max ≥ requested.min and job.min ≤ requested.max. Unknown salary is excluded only when an explicit salary filter is active; expose an optional “include undisclosed” policy. Store amount, currency, period and normalized annual amounts using a documented exchange-rate date. Do not compare raw hourly and annual salaries or different currencies.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-b21dd6723064","heading":"Step 3 · Query planning, taxonomy and salary semantics","text":"Global facet counts must come from the index, never the current page of 20 jobs. Distributed top-terms aggregations may omit rare values or have count error. For bounded enums use explicit filter buckets/exhaustive terms; for high-cardinality skills use searchable facet values and an explicit truncation/accuracy contract. Exact distinct counts for multiply classified jobs may require more expensive aggregation; do not relabel approximate cardinality as exact.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-2bf66db4e447","heading":"Step 3 · Query planning, taxonomy and salary semantics","text":"A selected category can make a previously selected facet inapplicable. Prefer retaining it visibly and explaining zero results; if the agreed product policy clears incompatible values, return the normalized query and surface what changed. Avoid hidden filter removal.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-sequence","heading":"Interaction sequence · atomic panels and stale-response safety","text":"Interaction sequence · atomic panels and stale-response safety","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-13de1ccab778","heading":"Interaction sequence · atomic panels and stale-response safety","text":"A filter change updates categories, facets and jobs togetherOpen full-size diagramScroll horizontally on smaller screens.Filter change: one coordinated search snapshotTime flows downward. The route changes query identity, cancels obsolete work and requests hits and all aggregations together. A late response cannot replace the current query.1. select full-time; reset cursor2. new canonical query key B3. abort A; GET search B4. hits + all facet aggregations5. one search response6. queryKey B + snapshot7. commit all panels together8. late A: discard by identityFacet UIURL / queryCoordinatorSearch APISearch indexTransport cancellation saves work; identity checks guarantee that obsolete responses never win.One envelope is one renderable search snapshot. Guard it by canonical query identity, request generation and viewer scope.","kind":"Diagram"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-5a69df291669","heading":"Interaction sequence · atomic panels and stale-response safety","text":"Use AbortController to stop obsolete requests and a monotonically increasing generation/query-key check before committing. Cancellation alone is insufficient: the response may already have completed. A cache may retain A under A’s key, but must not display it as B. Commit the complete response, not three separately arriving panel updates. Reuse the autocomplete race-handling mechanism.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-b20d8a16d181","heading":"Interaction sequence · atomic panels and stale-response safety","text":"SSR the initial query for discoverability and fast first content, hydrate with the same normalized key, then use client navigation. Never assume React transitions debounce network calls or eliminate races. Preserve structural layout, avoid list-wide skeleton flicker, and defer costly rendering only after measuring.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-operations","heading":"Scale, consistency, caching and failure recovery","text":"Scale, consistency, caching and failure recovery","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-operations-definition","heading":"Scale, consistency, caching and failure recovery","text":"Consistency: all panels describe one search response/read context, not a globally serializable database snapshot. Search is eventually consistent with authoritative writes. Detail/application validation prevents relying on a stale open-job status; expose an unavailable detail state when a listing has closed.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-88db879db92c","heading":"Scale, consistency, caching and failure recovery","text":"DecisionChoice and benefitCost / fallback","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-e863b95a7ade","heading":"Scale, consistency, caching and failure recovery","text":"CacheShort-lived bounded cache keyed by canonical query, locale, currency policy, taxonomy/index version and visibility scope. Cache popular anonymous queries; CDN static assets and public taxonomy.Combinatorial filter space lowers hit rate; use admission/size limits and TTL jitter. Private results require private caching. Do not cache by text alone.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-d36f68b095c0","heading":"Scale, consistency, caching and failure recovery","text":"Scale searchScale stateless API behind a load balancer; use search replicas, sensible shards, query timeouts and aggregation limits.Too many shards amplify aggregation fanout. Benchmark hot categories; avoid unbounded skill buckets.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-5f9a3a999a18","heading":"Scale, consistency, caching and failure recovery","text":"Facet failureBaseline fails the coordinated query while retaining a clearly labeled previous snapshot.An explicit partial-response contract may show jobs with facets marked unavailable; never display invented/stale counts as current.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-52846504a20c","heading":"Scale, consistency, caching and failure recovery","text":"Index failureRetry transient errors within a time budget; use a circuit breaker and controlled unavailable state.An SQL fallback is safe only if it preserves filter/security semantics and has reserved capacity. Otherwise fail clearly.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-b966d431d961","heading":"Scale, consistency, caching and failure recovery","text":"Indexing lagAlert on oldest outbox age and commit-to-searchable latency; replay/version-check failed events.Extra replicas do not cure a stalled indexer. Provide rebuild and rollback runbooks.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-938395de30d5","heading":"Scale, consistency, caching and failure recovery","text":"Observe: p50/p95/p99 end-to-end query latency, aggregation vs hit time, error/timeout rate, aborted/obsolete responses, cache hit ratio, shard saturation, queue age, index lag, zero-result rate and filter abandonment. Correlate traces by request ID across API and search; log a query fingerprint, not raw sensitive search text. Track field interaction-to-paint and long tasks in the browser.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-397528759cf4","heading":"Scale, consistency, caching and failure recovery","text":"Security: validate allowed fields/operators; never pass arbitrary search DSL from the browser. Enforce object-level visibility on search, facets and detail endpoints. Rate-limit expensive queries, cap pagination/PIT lifetime, escape job text and sanitize permitted rich HTML. See security foundations.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-directories","heading":"Directory sketch · isolate domain semantics from transport","text":"Directory sketch · isolate domain semantics from transport","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-d498db3dc160","heading":"Directory sketch · isolate domain semantics from transport","text":"Illustrative modular structureapps/web/routes/jobs/ — URL parsing, SSR loader, layout and route errorsapps/web/features/job-search/components/ — CategoryNavigation, FacetPanel, AppliedFilters, JobResults, JobCard, Paginationapps/web/features/job-search/query/ — canonical key, query-cache adapter, request cancellation and snapshot checkspackages/search-contracts/ — runtime schemas, SearchQuery, response types and cursor/error contractsapps/api/job-search/domain/ — count scopes, salary semantics and eligibility rulesapps/api/job-search/adapters/ — HTTP controller, search-engine implementation and response-cache adapterapps/indexer/ — outbox consumer, versioned mapping, retries, dead-letter replay and rebuildtests/search-fixtures/ — small catalogs with known category/facet countsDomain rules depend on contracts, not React or a search-engine SDK. Keep the engine adapter replaceable; do not duplicate count semantics in the browser.","kind":"Diagram"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"jobs-review","heading":"Step 4 · Verify the invariants and defend the tradeoffs","text":"Step 4 · Verify the invariants and defend the tradeoffs","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-95699154c532","heading":"Step 4 · Verify the invariants and defend the tradeoffs","text":"Correctness tests: run a tiny catalog through every facet scope and compare hits/counts to a simple reference evaluator. Include OR selections, overlapping skills, multiple category paths, selected zero-count options, salary boundaries/unknowns, visibility restrictions and taxonomy moves. Assert no unauthorized job contributes to any bucket.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-8e6d5062b8b4","heading":"Step 4 · Verify the invariants and defend the tradeoffs","text":"Interaction tests: late response A after B, canceled request still completing, Back/Forward, mobile draft cancel/apply, cursor reset, empty-state recovery, expired PIT, keyboard/focus and live announcements. Test ingestion duplicates, out-of-order close/update events and rebuild alias switches. Load-test realistic facets and cold caches against latency targets.","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-e6f8bd927f59","heading":"Step 4 · Verify the invariants and defend the tradeoffs","text":"Design wrap-up: “The URL owns the applied query. One search operation returns coherent hits, facets and category counts. We explicitly choose self-excluding counts to allow alternatives. SQL owns job records; a versioned index enables discovery with bounded freshness. We control expensive aggregations, protect visibility in every scope and recover without misrepresenting stale results.”","kind":"Notes"},{"page":"system-design-jobs.html","topic":"Case Study: Dynamic Job Discovery","anchor":"search-7d032db62a12","heading":"Step 4 · Verify the invariants and defend the tradeoffs","text":"Defend these choices: strict versus disjunctive facets; immediate versus Apply-button interaction; SQL versus search index; exact counts versus bounded/approximate counts; offset versus cursor/PIT; fresh availability versus cached resilience. Change the requirements first, then explain which choice changes. Return to the design framework.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"system-design-title","heading":"","text":"System Design Fundamentals","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-b39269bb69dc","heading":"","text":"A separate study track for turning product requirements into clear architectures. Start with the method, then learn the components through a worked chat case.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-53e7255fda67","heading":"","text":"Practice dynamic discovery with the job search case study: category trees, disjunctive facets, count correctness and search-index consistency.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-e558b8a734f5","heading":"","text":"Start here: learn design through a complete case","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-1d0a2facbc08","heading":"","text":"The four-step system design framework","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-fa9b9bfb9aa5","heading":"","text":"Requirements: behavior, quality & explicit limits","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-301f668d8eea","heading":"","text":"Components: choose a role before choosing a product","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-d40bc5a785c6","heading":"","text":"UI solutions: start from journeys and visible states","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-f5edf1614af8","heading":"","text":"RESTful contracts: entities, methods, errors & idempotency","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-551f9d1445f2","heading":"","text":"Architecture: modular services, load balancing & scale","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-f2febb2356a3","heading":"","text":"Consistency: specify guarantees per operation","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-fe827e846a72","heading":"","text":"Caching and CDNs: place, key, freshness & failure","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-2770c2ad93e8","heading":"","text":"Observe errors, monitor outcomes & define fallbacks","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-f57f488855de","heading":"","text":"Practice with requirement changes","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-start","heading":"Start here: learn design through a complete case","text":"Start here: learn design through a complete case","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-start-definition","heading":"Start here: learn design through a complete case","text":"System design connects requirements to a defensible architecture. The goal is to explain how data moves, where correctness is enforced, what limits capacity, and how the system behaves when components fail. Naming technologies is useful only after their responsibilities are clear.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-05111b6e1eae","heading":"Start here: learn design through a complete case","text":"First case: Design a chat web app. Work through requirements, estimates, APIs, storage, live delivery, recovery, scaling, and the frontend contract. The proposed system is one reasonable answer under stated assumptions, not a universal chat architecture.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-555337cfa9b6","heading":"Start here: learn design through a complete case","text":"How to study: Sketch your own solution before opening each section. Predict a failure, then compare the recovery path. Revisit the same design after changing one requirement. These are original worked examples using the common requirements → design → deep-dive → tradeoff structure.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-d299cf528b74","heading":"Start here: learn design through a complete case","text":"Frontend component case: Design an agnostic autocomplete package to practice UI contracts, accessibility, state/async ownership, import boundaries, and a directory layout. Compare its in-process component boundaries with the chat app’s distributed boundaries.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-design-framework","heading":"The four-step system design framework","text":"The four-step system design framework","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-design-framework-definition","heading":"The four-step system design framework","text":"Use these four explicit stages to organize the design discussion. Endpoint/entity discovery starts during clarification; detailed contracts and the blueprint are proposed next, then optimizations follow the critical deep dives. Validation is continuous: restate assumptions and ask for alignment before investing in detail.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-47406eb18efd","heading":"The four-step system design framework","text":"From an ambiguous prompt to an explained designUnderstand the problemGather functional and non-functional requirements, users and journeys; define scope/out of scope. Clarify entities and essential endpoint operations, estimate the workload, and validate your understanding. Record optimization pressures without prematurely choosing solutions.Propose the high-level designDraw the core components and their boundaries. Walk through one read and one write, explain the API/data contracts, and ask whether the blueprint matches the agreed scope before expanding it.Design deep-diveDetail the highest-risk components and algorithms. Analyze consistency, idempotency, cache strategy, load balancing, scaling, UI states, monitoring, and fallback behavior. Compare alternatives and optimize identified bottlenecks.Wrap upRecap the requirements-to-decisions story. Name remaining bottlenecks, failure modes, operating signals, cost/security limits, and the next changes you would validate.","kind":"Diagram"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-ff582fdf2605","heading":"The four-step system design framework","text":"Working order: clarify requirements and scale, sketch the high-level design, examine the highest-risk components, then review bottlenecks and recovery. Revisit assumptions as constraints change.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-requirements","heading":"Requirements: behavior, quality & explicit limits","text":"Requirements: behavior, quality & explicit limits","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-requirements-definition","heading":"Requirements: behavior, quality & explicit limits","text":"Functional requirements describe what users can do. Non-functional requirements describe measurable qualities and constraints. Out of scope states what this design deliberately postpones. All three shape architecture.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-requirements-cheatsheet","heading":"Requirements: behavior, quality & explicit limits › Requirements cheat sheet · requirements and scope","text":"Requirements cheat sheet · requirements and scope","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-requirements-cheatsheet-definition","heading":"Requirements: behavior, quality & explicit limits › Requirements cheat sheet · requirements and scope","text":"Goal: agree on who the system serves, the essential journeys, measurable quality targets and explicit boundaries before drawing architecture. Prioritize questions that change the design.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-82fbe07fe589","heading":"Requirements: behavior, quality & explicit limits › Requirements cheat sheet · requirements and scope","text":"OrderAskWrite down","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-010a121b2e99","heading":"Requirements: behavior, quality & explicit limits › Requirements cheat sheet · requirements and scope","text":"1 · Goal and actorsWho uses this? What outcome matters most? Which client surfaces: web, mobile, third-party API?One-sentence goal, primary actors and critical journey.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-db89c97c2946","heading":"Requirements: behavior, quality & explicit limits › Requirements cheat sheet · requirements and scope","text":"2 · Functional requirementsWhat are the 3–5 essential user actions? What must happen after each action? Which edge cases change the behavior?Actor + action + observable result. Example: selecting a filter updates jobs, categories and facet counts.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-ef870e0026a2","heading":"Requirements: behavior, quality & explicit limits › Requirements cheat sheet · requirements and scope","text":"3 · ScopeWhich actions are required today, optional if time permits, or explicitly excluded? Which external systems do we integrate with?Must-have / stretch / out-of-scope lists. Scope applies to quality and scale too, not only features.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-51b6aee403d3","heading":"Requirements: behavior, quality & explicit limits › Requirements cheat sheet · requirements and scope","text":"4 · Scale and workloadHow many daily/concurrent users, requests per user, peak RPS and stored records? Read/write ratio? Payload, retention, geography and hot keys?Only estimates that affect capacity or design. Average RPS ≈ daily operations ÷ 86,400; estimate peak separately.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-93e6d6300b1c","heading":"Requirements: behavior, quality & explicit limits › Requirements cheat sheet · requirements and scope","text":"5 · Non-functional requirementsWhich operation needs what latency, availability and freshness? What must survive a failure? Which security/accessibility constraints apply?Measurable target + measurement boundary + failure behavior. Mark assumptions as assumptions.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-6b85048ccafc","heading":"Requirements: behavior, quality & explicit limits › Requirements cheat sheet · requirements and scope","text":"6 · Data and contractsWhat are the main entities, identities and relationships? Who owns the data? Which reads/writes cross a boundary?Core entities and a small operation/API inventory; defer detailed schemas until the high-level design.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-19970dc2d887","heading":"Requirements: behavior, quality & explicit limits › Requirements cheat sheet · requirements and scope","text":"7 · Confirm priorities“Are these the right requirements and exclusions? Which area should I prioritize for the deep dive?”Agreed scope and the most important tradeoff; then draw.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-functional-discovery","heading":"Requirements: behavior, quality & explicit limits › Functional requirements · what should I ask?","text":"Functional requirements · what should I ask?","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-functional-discovery-definition","heading":"Requirements: behavior, quality & explicit limits › Functional requirements · what should I ask?","text":"Ask about behavior first, then write the requirement from the answer. Use these as prompts, not a script to read in full.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-e38d5895012a","heading":"Requirements: behavior, quality & explicit limits › Functional requirements · what should I ask?","text":"Ask the stakeholderWhat the answer revealsExample requirement after agreement","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-2c63f6b96099","heading":"Requirements: behavior, quality & explicit limits › Functional requirements · what should I ask?","text":"“Who are the users, and what is the main task each needs to complete?”Actors, permissions and primary journeys.A job seeker can discover and open relevant job postings.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-764f8b5e12cb","heading":"Requirements: behavior, quality & explicit limits › Functional requirements · what should I ask?","text":"“Walk me through the main journey. What can the user create, view, change or remove?”Core operations and their observable results.A seeker can choose a category, apply filters and view matching jobs.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-7e8628b67c40","heading":"Requirements: behavior, quality & explicit limits › Functional requirements · what should I ask?","text":"“When the user does X, what else must update? Immediately, after Apply, or after a refresh?”Interaction behavior and dependent UI updates.Applying a filter updates listings, categories and facet counts together.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-813ce8c441b1","heading":"Requirements: behavior, quality & explicit limits › Functional requirements · what should I ask?","text":"“What do these terms mean here? Can users select multiple values? What counts as a match?”Domain rules that the prompt leaves ambiguous.Selected job types use OR; different facets combine with AND.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-818d9318c95a","heading":"Requirements: behavior, quality & explicit limits › Functional requirements · what should I ask?","text":"“What should happen with no results, invalid input or a failed action? Can users undo or retry?”Required alternate journeys and recovery behavior.An empty search retains removable active filters and offers Clear all.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-38033b2791ec","heading":"Requirements: behavior, quality & explicit limits › Functional requirements · what should I ask?","text":"“Must this work across refreshes, shared links or devices? Are updates live?”Persistence, navigation and synchronization behavior.Applied searches survive refresh and can be shared through the URL.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-9549d6cdb554","heading":"Requirements: behavior, quality & explicit limits › Functional requirements · what should I ask?","text":"Write the FR: “[Actor] can [action]; the system produces [observable result], subject to [agreed business rule].” Ask about the user-visible behavior before choosing endpoints or technologies.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-requirement-quality-prompts","heading":"Requirements: behavior, quality & explicit limits › Non-functional requirements · what should I ask?","text":"Non-functional requirements · what should I ask?","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-604cb09adad8","heading":"Requirements: behavior, quality & explicit limits › Non-functional requirements · what should I ask?","text":"Latency: “p95 of which operation, measured from where?” Distinguish API response time from interaction-to-visible-result time.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-a156baea35a4","heading":"Requirements: behavior, quality & explicit limits › Non-functional requirements · what should I ask?","text":"Availability: “What percentage of valid requests must succeed, over what window? What is a usable degraded response?”","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-19f9f03539b8","heading":"Requirements: behavior, quality & explicit limits › Non-functional requirements · what should I ask?","text":"Consistency and freshness: “Must users immediately see their own writes? Can search lag? Must ordering be global or per entity?” Choose guarantees per operation.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-a0801bf131c1","heading":"Requirements: behavior, quality & explicit limits › Non-functional requirements · what should I ask?","text":"Durability and recovery: “Can an acknowledged write be lost? Which failures must we survive? What RPO (acceptable data loss) and RTO (recovery time) are needed?”","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-11471cbfff24","heading":"Requirements: behavior, quality & explicit limits › Non-functional requirements · what should I ask?","text":"Security and privacy: “Who may access each resource? Is there sensitive data, tenant isolation or a deletion/retention requirement?”","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-0b5421135486","heading":"Requirements: behavior, quality & explicit limits › Non-functional requirements · what should I ask?","text":"Frontend experience: “Which devices/networks? Keyboard/screen-reader requirements? What should users see while loading, offline, empty or failing?”","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-scope-discovery","heading":"Requirements: behavior, quality & explicit limits › Scope · what should I ask?","text":"Scope · what should I ask?","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-7c736d159f81","heading":"Requirements: behavior, quality & explicit limits › Scope · what should I ask?","text":"Ask the stakeholderRecord after the answer","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-4e5219273e75","heading":"Requirements: behavior, quality & explicit limits › Scope · what should I ask?","text":"“Which journeys must this design cover? If we can only finish three, which matter most?”In scope: the essential behaviors to design end to end.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-d51cc39748cb","heading":"Requirements: behavior, quality & explicit limits › Scope · what should I ask?","text":"“Should I include [adjacent feature], or focus on [core journey]?” Example: job discovery only, or application submission too?Out of scope: named exclusions confirmed with the stakeholder, rather than silently omitted.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-f3be5d7371c2","heading":"Requirements: behavior, quality & explicit limits › Scope · what should I ask?","text":"“Which features are useful extensions if we have time?”Stretch: optional work, separate from the baseline design.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-65d0b145c26f","heading":"Requirements: behavior, quality & explicit limits › Scope · what should I ask?","text":"“Are we designing the frontend, backend/API, or both? Is [external service] already provided?”System boundary: what you own, what you integrate with and the assumed dependency contracts.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-7b9ef7cf4139","heading":"Requirements: behavior, quality & explicit limits › Scope · what should I ask?","text":"“Which clients, regions and workload must we support now? Can offline mode, global deployment or personalization wait?”Limits: the operating envelope and explicit exclusions. Confirm these against the non-functional targets.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-d1461cce0261","heading":"Requirements: behavior, quality & explicit limits › Scope · what should I ask?","text":"Confirm before drawing: “I’ll cover [A, B, C], assume [scale/quality targets], and leave [D, E] out. Does that match your expectations?” Scope is a boundary around the agreed requirements, not a separate type of user feature.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-scope-template","heading":"Requirements: behavior, quality & explicit limits › Whiteboard template · fill this before architecture","text":"Whiteboard template · fill this before architecture","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-2bc57a12e1e8","heading":"Requirements: behavior, quality & explicit limits › Whiteboard template · fill this before architecture","text":"Requirements agreementGoal / actorsFor [users], enable [primary outcome] on [client surfaces].Must-have functional requirements1. [Journey] · 2. [Journey] · 3. [Journey]. Define success for each.Non-functional targets[Operation + p95 latency + boundary]; [availability window]; [consistency/freshness]; [durability]; [security/accessibility].Scale / limits[Peak RPS], [records], [payload], [retention], [regions]; label unconfirmed estimates.In scope / stretch / out of scope[Required behaviors and guarantees] / [optional extensions] / [explicit exclusions].Entities / operations[Core entities]; [critical read]; [critical write]; [external dependencies].Assumptions / priority“I will assume [X] unless you prefer otherwise. The hardest requirement is [Y]; I will focus the deep dive there.”If the stakeholder leaves a number open, propose a reasonable assumption, state why it matters, and continue. Do not turn clarification into an exhaustive questionnaire.","kind":"Diagram"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-scope-jobs-example","heading":"Requirements: behavior, quality & explicit limits › After clarification · agreed job-discovery requirements","text":"After clarification · agreed job-discovery requirements","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-97d739ce0711","heading":"Requirements: behavior, quality & explicit limits › After clarification · agreed job-discovery requirements","text":"Goal / actors: job seekers discover relevant open roles on responsive web.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-5d9d4c5f2430","heading":"Requirements: behavior, quality & explicit limits › After clarification · agreed job-discovery requirements","text":"Must-have: browse category descendants; apply facets; update categories/counts/results together; paginate and open job details; share applied searches via URL.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-d7a62934da2b","heading":"Requirements: behavior, quality & explicit limits › After clarification · agreed job-discovery requirements","text":"Quality / scale assumptions: search API p95 ≤300 ms, interaction-to-result p95 ≤500 ms on the target network, 99.9% monthly search availability, 5 million active jobs, about 460 peak search RPS. These are proposed targets, not facts from the prompt.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-885829bbc197","heading":"Requirements: behavior, quality & explicit limits › After clarification · agreed job-discovery requirements","text":"Consistency: all panels represent one applied query; search indexing may lag writes by up to the agreed freshness target. Revalidate current job status on the detail/application boundary.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-bdc171ca2424","heading":"Requirements: behavior, quality & explicit limits › After clarification · agreed job-discovery requirements","text":"In scope: discovery, taxonomy, faceting and indexing. Stretch: saved searches. Out of scope: submitting applications, employer billing, chat and personalized recommendations.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-9e19305dca80","heading":"Requirements: behavior, quality & explicit limits › After clarification · agreed job-discovery requirements","text":"Clarify the ambiguity: “Do facet counts only describe current matches, or show alternatives that could broaden the search?” This changes aggregation semantics.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-448d118e809f","heading":"Requirements: behavior, quality & explicit limits › After clarification · agreed job-discovery requirements","text":"Continue with the job case’s count contract, or compare chat’s functional requirements. The same checklist applies; the critical guarantees differ.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-requirement-pitfalls","heading":"Requirements: behavior, quality & explicit limits › Common requirements pitfalls","text":"Common requirements pitfalls","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-924fc2eda920","heading":"Requirements: behavior, quality & explicit limits › Common requirements pitfalls","text":"Do not confuse requirements with solutions: “Users see new messages within the latency target” is a requirement; “use Kafka/WebSockets/Redis” is a proposed solution. “Scalable” needs a workload; “strong consistency” needs a specific operation and guarantee. Excluding application submission does not exclude authorization or safe handling of private data in the included features.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-requirements-reference","heading":"Requirements: behavior, quality & explicit limits › Reference: requirement categories and terminology","text":"Reference: requirement categories and terminology","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-5115baf29b1f","heading":"Requirements: behavior, quality & explicit limits › Reference: requirement categories and terminology","text":"CategoryChat exampleQuestion to ask","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-0e0b455750be","heading":"Requirements: behavior, quality & explicit limits › Reference: requirement categories and terminology","text":"FunctionalSend messages and retrieve history.Direct messages, groups, or public channels?","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-62b253350994","heading":"Requirements: behavior, quality & explicit limits › Reference: requirement categories and terminology","text":"LatencyTarget p95 online delivery under 300 ms within the chosen region.Does this include client network time?","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-4adb23ec8496","heading":"Requirements: behavior, quality & explicit limits › Reference: requirement categories and terminology","text":"AvailabilityIllustrative 99.9% monthly successful durable-send availability.Which operation and measurement boundary define success?","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-e4081860cb0d","heading":"Requirements: behavior, quality & explicit limits › Reference: requirement categories and terminology","text":"DurabilityAcknowledged messages survive the defined failure model.One node, one zone, or an entire region?","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-32b898acd694","heading":"Requirements: behavior, quality & explicit limits › Reference: requirement categories and terminology","text":"ConsistencyCanonical order per conversation; eventual receipts/presence.What happens if ordering cannot be safely assigned?","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-27bae105003d","heading":"Requirements: behavior, quality & explicit limits › Reference: requirement categories and terminology","text":"LimitsBound group size, payload size, retention, and concurrent devices.What workload would invalidate this design?","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-cf0e2ffbc921","heading":"Requirements: behavior, quality & explicit limits › Reference: requirement categories and terminology","text":"Terminology: Availability is an observed service outcome over a window, not a synonym for replication. Latency needs a percentile and boundary. Consistency describes observable data guarantees; it is separate from durability. During a network partition, CAP concerns the tradeoff between linearizable consistency and availability in its formal sense; it does not mean every system always “chooses two of three.”","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-components","heading":"Components: choose a role before choosing a product","text":"Components: choose a role before choosing a product","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-components-definition","heading":"Components: choose a role before choosing a product","text":"A component earns its place by solving a specific pressure. The same product may fill several roles; separating responsibilities on a diagram does not require deploying a microservice for each box.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-479c534330fb","heading":"Components: choose a role before choosing a product","text":"RoleWhat it solvesLimit or alternative","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-47836d5f6d97","heading":"Components: choose a role before choosing a product","text":"Load balancer / reverse proxyRoutes traffic to healthy instances; can terminate TLS.Does not own conversation data or guarantee delivery.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-8f3f0c75de2b","heading":"Components: choose a role before choosing a product","text":"Application serviceValidates requests, authorizes resources, applies business rules.Start as modules in one service when that is enough.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-9316b0692c2d","heading":"Components: choose a role before choosing a product","text":"DatabaseDurable authoritative state and transactional invariants.Choose by access pattern and correctness; indexes and replicas have costs.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-28461fd0ef81","heading":"Components: choose a role before choosing a product","text":"CacheAvoids repeated expensive reads.Define keys, TTL, invalidation, and acceptable staleness; never assume it is authoritative.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-bffbe2edc4dd","heading":"Components: choose a role before choosing a product","text":"QueueDistributes work among competing consumers.Retries and redelivery require idempotent effects.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-0c65050a6f67","heading":"Components: choose a role before choosing a product","text":"Topic / event streamLets independent consumer groups process the same event history.A Kafka partition orders its records; it does not globally order a whole topic.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-2c1cb18ead20","heading":"Components: choose a role before choosing a product","text":"Object storage + CDNStores large immutable objects and serves them near users.CDNs do not replace authorization or live message persistence.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-4555125e1dfd","heading":"Components: choose a role before choosing a product","text":"Coordination / leaseTemporary ownership and recovery when owners fail.A lease alone does not stop stale writes; enforce fencing where needed.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-29759c59e8c4","heading":"Components: choose a role before choosing a product","text":"Existing foundations: Reuse HTTP caching, database transactions, and leases and sweepers. The chat case demonstrates why and where to combine them.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-ui-ux","heading":"UI solutions: start from journeys and visible states","text":"UI solutions: start from journeys and visible states","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-ui-ux-definition","heading":"UI solutions: start from journeys and visible states","text":"For fullstack application design, connect architecture to a concrete user journey. Define what the user sees before, during, and after each operation—including slow, disconnected, empty, partial, unauthorized, and failed states.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-19ac50f1188e","heading":"UI solutions: start from journeys and visible states","text":"DecisionQuestionTradeoff","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-648a07706766","heading":"UI solutions: start from journeys and visible states","text":"Rendering and navigationWhat must appear immediately? What needs SEO, streaming, or persistent layouts?SSR can improve initial delivery but adds server/hydration complexity; client transitions need data/focus/scroll ownership.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-36fef9b9ad0e","heading":"UI solutions: start from journeys and visible states","text":"State ownershipWhich values belong in the URL, local state, or server cache?Duplicated owners create synchronization bugs; normalized state adds indirection.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-132025a2d310","heading":"UI solutions: start from journeys and visible states","text":"Interaction feedbackCan an action be optimistic? Can it be reversed?Fast feedback helps UX; an irreversible operation needs a truthful pending/confirmed contract.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-f179b638bdcf","heading":"UI solutions: start from journeys and visible states","text":"Data volumePagination, virtualization, or both?Pagination bounds transfer; virtualization bounds DOM work and complicates scroll/accessibility.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-78cae4f937bf","heading":"UI solutions: start from journeys and visible states","text":"Accessibility and devicesHow do keyboard, screen reader, mobile, and slow-network users complete the task?Avoid a mouse-only happy path or desktop-only assumptions.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-848c7f0d174d","heading":"UI solutions: start from journeys and visible states","text":"Design summary: Sketch the main screen, an interaction sequence, and the state transitions. Tie each to an API and data owner. Use the chat UX state matrix, then reference rendering choices, state ownership, and accessibility verification.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-70a4078abc83","heading":"UI solutions: start from journeys and visible states","text":"Compare implementations: Use the same UI problem under different state tools and the checkout pattern comparison to explain why a chosen architecture earns its complexity.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-rest","heading":"RESTful contracts: entities, methods, errors & idempotency","text":"RESTful contracts: entities, methods, errors & idempotency","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-rest-definition","heading":"RESTful contracts: entities, methods, errors & idempotency","text":"RESTful resource design starts with domain entities and lifecycle operations. Resource-oriented URLs and HTTP semantics make a contract predictable; using JSON over HTTP alone does not establish all REST constraints. Choose a practical contract and be precise about its guarantees.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-596d6abf47f3","heading":"RESTful contracts: entities, methods, errors & idempotency","text":"ConcernDecision to explain","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-2787ee70be8d","heading":"RESTful contracts: entities, methods, errors & idempotency","text":"ResourcesIdentify collections, resource IDs, relationships, and ownership; avoid leaking database tables as the API by default.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-611ef5c35f14","heading":"RESTful contracts: entities, methods, errors & idempotency","text":"MethodsGET reads without intentional state changes; POST commonly creates/processes; PUT replaces a target representation; PATCH partially modifies; DELETE removes a resource association according to the contract.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-abfdc99912c6","heading":"RESTful contracts: entities, methods, errors & idempotency","text":"OutcomesUse meaningful 2xx/4xx/5xx statuses, validation codes, pagination cursors, rate-limit guidance, and a consistent error body.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-0cf4db1ef8b9","heading":"RESTful contracts: entities, methods, errors & idempotency","text":"RetriesPUT/DELETE are idempotent in intended effect, though responses may differ; POST/PATCH are not inherently idempotent. Define application deduplication when needed.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-c48dc0379a11","heading":"RESTful contracts: entities, methods, errors & idempotency","text":"ConcurrencyUse a version or ETag/If-Match where stale updates must be rejected; idempotency keys address repeated operations, not conflicting independent operations.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-2e7cd7bddd44","heading":"RESTful contracts: entities, methods, errors & idempotency","text":"SecurityAuthenticate the caller and authorize each resource; validate bounds and never trust client-owned prices, identities, or roles.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-459d0accf93c","heading":"RESTful contracts: entities, methods, errors & idempotency","text":"Idempotency-key contract: Scope a stable key to the authenticated principal and operation, fingerprint the relevant payload, and atomically reserve/store its outcome with the business mutation. Define in-progress retries, conflicting reuse, retention, and recovery after a crash. A cached HTTP response written after the side effect leaves a dangerous failure window. For external effects, use the dependency’s idempotency contract or reconcile.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-88c2ad1ffe03","heading":"RESTful contracts: entities, methods, errors & idempotency","text":"Alternatives: REST fits stable resource operations and standard HTTP infrastructure. GraphQL can suit varied client query shapes; RPC can express commands naturally. WebSocket messages still need schemas, authorization, correlation, retry, and error contracts. See HTTP semantics, GraphQL comparisons, and the chat REST surface.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-architecture","heading":"Architecture: modular services, load balancing & scale","text":"Architecture: modular services, load balancing & scale","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-architecture-definition","heading":"Architecture: modular services, load balancing & scale","text":"Draw logical responsibilities before deciding deployment boundaries. Start with a modular monolith when one team and one deployment can meet the needs. Choose microservices when independent scaling, ownership, isolation, or release cadence justifies distributed-system costs.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-e60d979082be","heading":"Architecture: modular services, load balancing & scale","text":"ChoiceBenefitCost / caution","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-2e5e7b1853fb","heading":"Architecture: modular services, load balancing & scale","text":"Modular monolithLocal calls and simpler transactions, deployment, debugging.Scaling/releasing the whole unit can couple teams and resources.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-7b35f6bb16aa","heading":"Architecture: modular services, load balancing & scale","text":"MicroservicesIndependent deployment, domain ownership, and targeted resource scaling.Network failures, API/version compatibility, observability, deployment overhead, and cross-service consistency become explicit work.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-e696a4f65756","heading":"Architecture: modular services, load balancing & scale","text":"Horizontal scalingAdds instances to distribute load and survive instance failure.Shared state, hot keys, database limits, and coordination may still bottleneck.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-d64fcb05c3cd","heading":"Architecture: modular services, load balancing & scale","text":"Load balancingRoutes eligible traffic to healthy instances.Choose L4/L7 needs, health/readiness checks, timeout policy, and zone capacity; sticky sessions can cause skew.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-0c942459aadd","heading":"Architecture: modular services, load balancing & scale","text":"Async workBuffers bursts and decouples slow consumers.Adds backlog latency, retries, deduplication, and eventual outcomes.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-3a8344e93f92","heading":"Architecture: modular services, load balancing & scale","text":"Load-balancing decisions: Round-robin is simple; least-connections can help unequal long-lived connection counts, but neither guarantees equal CPU or message fanout. Health checks should separate liveness from readiness; removing a draining instance from new traffic does not finish existing work. Autoscale on a useful saturation signal and keep failure headroom, not just average CPU.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-94dec9521a7f","heading":"Architecture: modular services, load balancing & scale","text":"Service boundaries: Keep one owner for an invariant where possible. If a write crosses services, define the workflow, compensation/reconciliation, and idempotency rather than assuming a distributed transaction exists. A circuit breaker isolates repeated dependency failures; it does not create a correct fallback. See application boundaries and chat deployment choices.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-consistency","heading":"Consistency: specify guarantees per operation","text":"Consistency: specify guarantees per operation","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-consistency-definition","heading":"Consistency: specify guarantees per operation","text":"A design should name the observable guarantee for each operation. “Strong” and “eventual” are starting labels; explain what a client may see after concurrent writes, replica lag, retries, and failover.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-e12615157ab0","heading":"Consistency: specify guarantees per operation","text":"Guarantee / mechanismMeaningCost or limit","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-6d70d6fe8a8c","heading":"Consistency: specify guarantees per operation","text":"LinearizabilityEach operation appears atomic at a point between its call and response, respecting real-time order.Requires coordination; latency or availability may suffer during partitions.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-dc922fe87f50","heading":"Consistency: specify guarantees per operation","text":"Read-your-writesA client can observe its own acknowledged mutation.Can use writer reads or consistency tokens; does not imply global linearizability.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-c03d31ac183c","heading":"Consistency: specify guarantees per operation","text":"Eventual consistencyReplicas converge if updates stop and propagation succeeds.Stale reads/conflicts need policy; no finite staleness bound follows automatically.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-41902bf5570a","heading":"Consistency: specify guarantees per operation","text":"Monotonic reads / cursorsA session does not move backward in the relevant observed version.Needs version-aware routing/merging; a timestamp alone may be insufficient.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-fd3870068684","heading":"Consistency: specify guarantees per operation","text":"Optimistic concurrency controlReject a write whose expected version is no longer current.Callers must merge or retry intentionally; it does not deduplicate repeated effects.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-f32e98cbc942","heading":"Consistency: specify guarantees per operation","text":"Distinguish: Transaction isolation describes concurrent transaction behavior; durability describes committed data survival; delivery semantics describe message handling. Neither a replica count nor an “exactly once” slogan defines all three. State the failure model, write acknowledgement rule, replication mode, and RPO/RTO.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-f7a6b88ed9b7","heading":"Consistency: specify guarantees per operation","text":"Use selectively: A permission revocation or account balance may need authoritative checks, while typing indicators can tolerate staleness. Explain the product consequence of each relaxation. Apply this to conversation ordering and replica reads, and reuse optimistic concurrency choices.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-cache-cdn","heading":"Caching and CDNs: place, key, freshness & failure","text":"Caching and CDNs: place, key, freshness & failure","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-cache-cdn-definition","heading":"Caching and CDNs: place, key, freshness & failure","text":"A cache strategy specifies what is cached, where it lives, who owns the source of truth, and how stale or missing data is handled. A cache hit improves a specific path; it is not automatically a correctness guarantee.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-f5321eac857b","heading":"Caching and CDNs: place, key, freshness & failure","text":"Strategy / locationUse whenTradeoff","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-acdce584b376","heading":"Caching and CDNs: place, key, freshness & failure","text":"Browser/query cacheReuse UI data, deduplicate requests, keep interactions responsive.Clear personalized data on logout; coordinate invalidation and optimistic updates.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-8255f79f7f87","heading":"Caching and CDNs: place, key, freshness & failure","text":"Cache-aside at the serviceRead-heavy data can tolerate a defined freshness policy.Misses still hit the database; invalidation/refill races can reintroduce stale data.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-f20cd2a42177","heading":"Caching and CDNs: place, key, freshness & failure","text":"Read-through / write-throughA cache layer owns loading or synchronously coordinates writes.Adds layer coupling and failure handling; persistence atomicity must be specified.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-d08c6bfba58e","heading":"Caching and CDNs: place, key, freshness & failure","text":"Write-behindDelayed writes are acceptable under a durable buffering contract.Volatile buffering risks data loss; inappropriate for pretending unpersisted messages are accepted.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-57c1e63d2cc2","heading":"Caching and CDNs: place, key, freshness & failure","text":"CDN/edge cacheVersioned frontend assets and approved static/media content.Cache keys, access checks, purge behavior, and origin protection matter.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-ad844527b743","heading":"Caching and CDNs: place, key, freshness & failure","text":"Key and freshness: Include relevant tenant/user scope, resource version, locale, filters, and permission context; avoid secrets in keys/logs. Define TTL, event-driven invalidation or versioning, and whether stale-while-revalidate or stale-if-error is acceptable. A delayed refill can overwrite newer cache data; use version-aware updates where correctness requires it. Coalesce concurrent misses and jitter expiry to reduce cache stampedes.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-1c819d9e1cd3","heading":"Caching and CDNs: place, key, freshness & failure","text":"CDN policy: Content-hashed JS/CSS can use long freshness and immutable caching, while the HTML entry point needs a compatible update/revalidation policy. Private API/message data should not enter a public shared cache. Signed media URLs need validated expiry/access at the appropriate layer and a deliberate cache key; URL signing alone does not make every shared-cache configuration safe.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-c3b855e86b05","heading":"Caching and CDNs: place, key, freshness & failure","text":"Failure: Bypassing a failed cache can overload the origin—bound concurrency and shed load. Stale content may be fine for a past message display but unsafe for membership authorization. See HTTP validators/cache directives, chat cache placement, and CDN behavior.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-observability","heading":"Observe errors, monitor outcomes & define fallbacks","text":"Observe errors, monitor outcomes & define fallbacks","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-observability-definition","heading":"Observe errors, monitor outcomes & define fallbacks","text":"Monitoring checks known signals and thresholds; observability helps explain system behavior using metrics, logs, traces, and events. A dashboard is useful only if it connects to a user outcome, a diagnosis, and an action.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-2d97a2a51e20","heading":"Observe errors, monitor outcomes & define fallbacks","text":"SignalPurposeDesign consideration","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-23890af95206","heading":"Observe errors, monitor outcomes & define fallbacks","text":"Metrics / SLIsRates, latency distributions, availability, saturation, queue age.Use bounded labels; request IDs/user IDs create high-cardinality metric problems.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-75875d12f0dc","heading":"Observe errors, monitor outcomes & define fallbacks","text":"Structured logsExplain a specific failure or state transition.Include safe codes, trace/correlation IDs, versions; redact credentials and sensitive bodies.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-12de7aebd2d4","heading":"Observe errors, monitor outcomes & define fallbacks","text":"Distributed tracesFollow timing and dependencies through an operation.Propagate context across HTTP, sockets, and async jobs; choose sampling and privacy policies.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-37de07153d06","heading":"Observe errors, monitor outcomes & define fallbacks","text":"Frontend error reporting / RUMCapture render exceptions, rejected operations, failed assets, and real user latency.Use release/source-map context, deduplication, and consent/privacy rules; handled failures need explicit reports.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-fc534b47277a","heading":"Observe errors, monitor outcomes & define fallbacks","text":"Synthetic checksExercise login, load history, and send through an end-to-end probe.A health endpoint cannot prove a full journey works; bound test side effects.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-f53ccca64e2e","heading":"Observe errors, monitor outcomes & define fallbacks","text":"Alerting: Define SLOs with a denominator, eligible population, time window, and latency threshold. Alert on sustained/multi-window error-budget burn or loss of critical durability, not every individual error. Include owner, runbook, recent deploy context, and the first diagnostic queries.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-3d04abf518a3","heading":"Observe errors, monitor outcomes & define fallbacks","text":"Fallback contract: For each dependency, document timeout, retry budget, circuit-breaker policy if useful, degraded UI, recovery path, and what must never be claimed. Serve explicitly stale read data when permitted; disable optional presence; keep uncertain sends pending. Never fabricate success or silently weaken authorization. See chat error diagnosis and fallback decisions.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-practice","heading":"Practice with requirement changes","text":"Practice with requirement changes","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"sd-practice-definition","heading":"Practice with requirement changes","text":"After the baseline chat design, change one assumption and identify what breaks before proposing another technology.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-af05b320df26","heading":"Practice with requirement changes","text":"100,000-member channels: revisit fanout, hot partitions, membership reads, and retention.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-5eaaf3866be0","heading":"Practice with requirement changes","text":"Active users across continents: revisit home regions, write ownership, replication lag, failover, and latency.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-5e8c93fc5d6e","heading":"Practice with requirement changes","text":"End-to-end encryption: revisit key distribution, device membership, recovery, search, and moderation.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-e7ddbb544f57","heading":"Practice with requirement changes","text":"Images and attachments: introduce signed upload/download URLs, malware scanning, object storage, and CDN caching rules.","kind":"Notes"},{"page":"system-design.html","topic":"System Design Fundamentals","anchor":"search-6f04375a5d5f","heading":"Practice with requirement changes","text":"Self-check: Can you explain one message from send to persistence to display, then recover it after a gateway crash? If not, refine that path before expanding the architecture. Continue to the worked chat case.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"typescript-title","heading":"","text":"TypeScript","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-3dd064551908","heading":"","text":"Model valid states and reusable contracts while keeping static guarantees separate from runtime validation.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-a2129b1d773b","heading":"","text":"Static types vs. runtime validation","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-ffb60694fc7f","heading":"","text":"Structural typing, interfaces & object contracts","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-ad9305f22ba6","heading":"","text":"Discriminated unions, narrowing & never","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-4173940e8415","heading":"","text":"Generics, constraints & reusable APIs","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-b6124fd50abd","heading":"","text":"satisfies, const assertions & utility types","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-cdc03255bbe2","heading":"","text":"Variance: safe substitution for producers & consumers","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-21e3ac4e3d9c","heading":"","text":"Function overloads: express distinct call contracts","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-4bcc1184a790","heading":"","text":"Mapped & conditional types: derive contracts deliberately","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-e48b6fcd19f6","heading":"","text":"Typing reusable React components: preserve useful relationships","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-6015471b9b3e","heading":"","text":"Review: types express guarantees you can defend","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-boundaries","heading":"Static types vs. runtime validation","text":"Static types vs. runtime validation","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-boundaries-definition","heading":"Static types vs. runtime validation","text":"TypeScript checks code statically and erases most type syntax during compilation. It does not validate incoming JSON, enforce authorization, or change JavaScript runtime behavior. A type assertion tells the compiler to trust you; it is not a conversion or validation step.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-ebf3e811e0c5","heading":"Static types vs. runtime validation","text":"type User = { id: string; name: string }; function isUser(value: unknown): value is User { return typeof value === 'object' && value !== null && 'id' in value && typeof value.id === 'string' && 'name' in value && typeof value.name === 'string'; } const raw: unknown = JSON.parse('{\"id\":\"42\",\"name\":\"Ada\"}'); if (!isUser(raw)) throw new Error('Invalid user response'); raw.name.toUpperCase(); // Narrowed to User.","kind":"Code"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-a17a807be4e0","heading":"Static types vs. runtime validation","text":"Use: Treat network/storage values as unknown and validate at trust boundaries. For complex schemas, use a maintained schema validator and infer compatible types where possible. A hand-written type predicate can lie too; verify its checks and contract.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-c3f8492f7ad1","heading":"Static types vs. runtime validation","text":"Choose: unknown requires narrowing before use; any disables checking and can propagate unsafety. Reserve any for constrained interop boundaries rather than application-wide models. Generated API types improve consistency but still do not validate a response.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-structural","heading":"Structural typing, interfaces & object contracts","text":"Structural typing, interfaces & object contracts","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-structural-definition","heading":"Structural typing, interfaces & object contracts","text":"Structural typing checks whether a value has the required shape, rather than requiring a declared nominal relationship. Extra-property checks on fresh object literals catch likely mistakes, but TypeScript object types are not generally exact object schemas.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-e9dd59a424be","heading":"Structural typing, interfaces & object contracts","text":"Example: A value with id, name, and avatar can satisfy a function accepting only id/name. Use interface for extendable object contracts and type for unions, tuples, and other compositions; both can describe most ordinary object shapes.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-99f8804d597a","heading":"Structural typing, interfaces & object contracts","text":"Important distinctions: readonly restricts writes through that type, not runtime mutation or deep aliasing. Optional properties and explicit undefined are not always interchangeable, especially with exactOptionalPropertyTypes. Enable strict null checking and avoid treating missing data as present with repeated non-null assertions.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-96d27bff4846","heading":"Structural typing, interfaces & object contracts","text":"When not to model everything: Prefer small domain contracts over types that mirror every implementation detail. Branded types can prevent accidental mixing of structurally identical IDs, but require disciplined constructors/validation; they are not a runtime security mechanism.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-unions","heading":"Discriminated unions, narrowing & never","text":"Discriminated unions, narrowing & never","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-unions-definition","heading":"Discriminated unions, narrowing & never","text":"A discriminated union represents valid alternatives with a shared literal field. Narrowing refines the type through control flow. never represents an impossible value and can enforce exhaustive handling as the union evolves.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-77f7ff18a62e","heading":"Discriminated unions, narrowing & never","text":"type Result = | { status: 'success'; value: string } | { status: 'error'; message: string }; function assertNever(value: never): never { throw new Error('Unhandled result'); } function describe(result: Result): string { switch (result.status) { case 'success': return result.value; case 'error': return result.message; default: return assertNever(result); } }","kind":"Code"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-15221962bda8","heading":"Discriminated unions, narrowing & never","text":"Use: Async outcomes, reducer actions, parser results, and component props with mutually exclusive modes. This avoids optional fields that permit impossible combinations. See the state-machine union.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-2e2a9e585757","heading":"Discriminated unions, narrowing & never","text":"Alternatives: A boolean is enough for one independent toggle. Avoid a large union for unrelated data; separate responsibilities. Narrow unknown inputs with checks before relying on the discriminant.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-generics","heading":"Generics, constraints & reusable APIs","text":"Generics, constraints & reusable APIs","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-generics-definition","heading":"Generics, constraints & reusable APIs","text":"Generics preserve relationships between types. A useful generic says how an input type relates to an output or another input; it is more than a placeholder for any.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-dd72fb45296e","heading":"Generics, constraints & reusable APIs","text":"function byId\u003cT extends { id: string }>(items: readonly T[], id: string): T | undefined { return items.find(item => item.id === id); } const user = byId([{ id: '42', name: 'Ada' }], '42'); // user is { id: string; name: string } | undefined; the name field is preserved.","kind":"Code"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-838d4eba848d","heading":"Generics, constraints & reusable APIs","text":"Use: Generic collections, typed component items, and adapters that preserve a domain model. Constrain only what the implementation needs; allow inference instead of requiring many explicit type arguments.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-7adf17c5fb31","heading":"Generics, constraints & reusable APIs","text":"Tradeoffs: Deep conditional types and broad generic component APIs can make errors inscrutable. If two inputs need no type relationship, a concrete interface or unknown is often clearer. Avoid a “generic” response helper that simply casts unvalidated JSON to T.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-2ec7488712e5","heading":"Generics, constraints & reusable APIs","text":"Comparison: Use unions for known alternatives, overloads for distinct call signatures where inference benefits, and generics for a relationship that varies across calls. These choices complement reusable component contracts.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-utilities","heading":"satisfies, const assertions & utility types","text":"satisfies, const assertions & utility types","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-utilities-definition","heading":"satisfies, const assertions & utility types","text":"satisfies checks assignability without replacing the expression’s inferred type with the target type. as const preserves literal types and makes literal object/array members readonly at the type level; neither freezes an object at runtime.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-24de2ec73ac4","heading":"satisfies, const assertions & utility types","text":"const routes = { home: '/', profile: '/profile' } as const satisfies Record\u003cstring, `/${string}`>; type RouteName = keyof typeof routes; // 'home' | 'profile' type User = { id: string; name: string; email: string }; type UserSummary = Pick\u003cUser, 'id' | 'name'>; type EditableUser = Omit\u003cUser, 'id'>;","kind":"Code"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-94e749fe2e8c","heading":"satisfies, const assertions & utility types","text":"Use utilities: Pick/Omit define projections; Record describes keyed values; Partial makes fields optional; ReturnType/Awaited extract related types. Partial is shallow and is not automatically a valid PATCH schema—some field combinations may be forbidden.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-e12dd8f2c012","heading":"satisfies, const assertions & utility types","text":"Choose deliberately: Use an annotation when callers should see an abstract contract, satisfies to check a configuration while retaining its useful inferred shape, and an assertion only when external evidence justifies it. Prefer an explicit domain type over a long chain of utility transformations that hides business meaning.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-variance","heading":"Variance: safe substitution for producers & consumers","text":"Variance: safe substitution for producers & consumers","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-variance-definition","heading":"Variance: safe substitution for producers & consumers","text":"Variance describes how assignability changes when a generic’s type argument changes. Covariance follows the subtype direction; contravariance reverses it; invariance permits neither direction generally. These are substitution rules, not runtime behaviors.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-e494554398f1","heading":"Variance: safe substitution for producers & consumers","text":"type Animal = { name: string }; type Dog = Animal & { bark(): void }; type Producer\u003cT> = () => T; type Consumer\u003cT> = (value: T) => void; declare const makeDog: Producer\u003cDog>; const makeAnimal: Producer\u003cAnimal> = makeDog; // safe declare const consumeAnimal: Consumer\u003cAnimal>; const consumeDog: Consumer\u003cDog> = consumeAnimal; // safe // Reverse assignment is unsafe: a dog-only handler cannot handle every Animal.","kind":"Code"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-9d7e9c021a1e","heading":"Variance: safe substitution for producers & consumers","text":"Mechanics: Under strictFunctionTypes, standalone function parameters and function-valued properties are checked contravariantly; return values are covariant. Method parameters retain a bivariance exception for compatibility. Some library event-handler definitions deliberately use that exception, so successful assignment is not proof of universal soundness.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-05690bfb8554","heading":"Variance: safe substitution for producers & consumers","text":"Use: Review callback, repository, and component APIs: “Can this replacement accept every value the caller can provide?” A mutable container both consumes and produces values, which motivates invariance; TypeScript permits some unsound mutable-array assignments for compatibility. Prefer readonly inputs when callers should not mutate through your API.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-9e19a5246d99","heading":"Variance: safe substitution for producers & consumers","text":"Keep it simple: Usually let TypeScript infer variance from structure. Use concrete domain callbacks and strict checking before reaching for explicit variance annotations or casts. See generic relationships and component callback contracts.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-overloads","heading":"Function overloads: express distinct call contracts","text":"Function overloads: express distinct call contracts","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-overloads-definition","heading":"Function overloads: express distinct call contracts","text":"Overload signatures describe allowed calls and their associated return types. A single implementation must handle them all; its implementation signature is not an extra public overload. Overloads disappear at runtime.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-f99a367a5201","heading":"Function overloads: express distinct call contracts","text":"function toLabel(value: string): string; function toLabel(value: readonly string[]): string[]; function toLabel(value: string | readonly string[]): string | string[] { return typeof value === 'string' ? value.trim() : value.map(v => v.trim()); } const one = toLabel(' Ada '); // string const many = toLabel([' Ada ']); // string[]","kind":"Code"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-953c5a5a4f55","heading":"Function overloads: express distinct call contracts","text":"Use: A small set of distinct input/output contracts, such as a single value versus a batch. Runtime narrowing still does the work. List specific overloads before broad ones to avoid losing useful inference.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-6b85e7466211","heading":"Function overloads: express distinct call contracts","text":"Pitfalls: An argument typed as a union does not automatically match separate narrow overloads. Expose a union overload if union callers are intended, or choose a union parameter. ReturnType of an overloaded function uses its last signature, rather than computing each possible call.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-e8028eb3ed0f","heading":"Function overloads: express distinct call contracts","text":"Alternatives: Use a union parameter when return behavior is the same; use a generic when one reusable relationship covers the cases; use separate named functions when they do different jobs. Avoid a large overload matrix that hides an unclear API.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-type-transformations","heading":"Mapped & conditional types: derive contracts deliberately","text":"Mapped & conditional types: derive contracts deliberately","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-type-transformations-definition","heading":"Mapped & conditional types: derive contracts deliberately","text":"A mapped type transforms properties over a key set; a conditional type selects a type using an assignability test. Together with keyof, indexed access, and infer, they express reusable type relationships without duplicating every field.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-19c3606b1c1a","heading":"Mapped & conditional types: derive contracts deliberately","text":"type Flags\u003cT> = { [K in keyof T]: boolean }; type Settings = { email: string; retries: number }; type SettingFlags = Flags\u003cSettings>; // { email: boolean; retries: boolean } type Item\u003cT> = T extends readonly (infer U)[] ? U : T; type Name = Item\u003creadonly string[]>; // string type IsString\u003cT> = T extends string ? true : false; type Mixed = IsString\u003cstring | number>; // true | false (distributive) type AllStrings\u003cT> = [T] extends [string] ? true : false; type All = AllStrings\u003cstring | number>; // false","kind":"Code"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-66dc73689faa","heading":"Mapped & conditional types: derive contracts deliberately","text":"Mechanics: A conditional with a naked type parameter distributes over union members; tuple wrapping suppresses distribution. infer extracts a type in the matching branch. Mapped modifiers such as -readonly and -? remove modifiers; key remapping uses as. None of these transforms runtime objects.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-756a1a053489","heading":"Mapped & conditional types: derive contracts deliberately","text":"Use: Schema-driven helpers, projections, and preserving a library’s input/output relationships. Prefer standard utilities such as Pick, Omit, Awaited, and ReturnType before writing custom transformations. Mapped types preserve optional/readonly modifiers in common homomorphic mappings; do not assume every remapping has identical semantics.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-4cfa3b9dea7d","heading":"Mapped & conditional types: derive contracts deliberately","text":"When simpler is better: Deep recursive types increase compiler work, weaken error readability, and can hide domain rules. A named domain interface or discriminated union often communicates more. Never substitute a conditional type for runtime validation.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-react-components","heading":"Typing reusable React components: preserve useful relationships","text":"Typing reusable React components: preserve useful relationships","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-react-components-definition","heading":"Typing reusable React components: preserve useful relationships","text":"A reusable component’s types should enforce its public contract: valid prop combinations, item/callback relationships, native element behavior, and explicit customization points. Reuse the composition model rather than making every component arbitrarily polymorphic.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-b9d7924d9e6a","heading":"Typing reusable React components: preserve useful relationships","text":"import type { ComponentPropsWithoutRef, ReactNode } from 'react'; type ButtonProps = ComponentPropsWithoutRef\u003c'button'> & { tone?: 'primary' | 'quiet'; }; function Button({ tone = 'primary', type = 'button', ...props }: ButtonProps) { return \u003cbutton {...props} type={type} data-tone={tone} />; } type ListProps\u003cT> = { items: readonly T[]; getKey: (item: T) => string; renderItem: (item: T) => ReactNode; }; function ItemList\u003cT>({ items, getKey, renderItem }: ListProps\u003cT>) { return \u003cul>{items.map(item => \u003cli key={getKey(item)}>{renderItem(item)}\u003c/li>)}\u003c/ul>; } // T is inferred from items and shared with getKey/renderItem.","kind":"Code"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-b8b0b1606c50","heading":"Typing reusable React components: preserve useful relationships","text":"Use: Native prop types preserve event and ARIA attributes. A generic list keeps the item type across slots without any. Use ReactNode for content that React can render; use a render-function prop when the caller needs access to component-owned data.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-b4e5a57c64dd","heading":"Typing reusable React components: preserve useful relationships","text":"Invalid combinations: Use a discriminated union for controlled versus uncontrolled props; forbid simultaneous value/defaultValue with never and require onChange for the controlled branch. This expresses the ownership rules from controlled components.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-e7461e65aec7","heading":"Typing reusable React components: preserve useful relationships","text":"Ref & customization tradeoffs: In React 19, function components can accept ref as a prop; React 18 integrations commonly use forwardRef. Declare the element/ref contract intentionally. A generic as prop must correlate element, native props, and ref; prefer separate Button and Link components or explicit adapters when that complexity adds little value.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-99d29e932992","heading":"Typing reusable React components: preserve useful relationships","text":"Limits: Type checking cannot prove accessible keyboard behavior, stable keys, or semantic HTML. Keep accessible contracts and runtime verification alongside types.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-review","heading":"Review: types express guarantees you can defend","text":"Review: types express guarantees you can defend","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-review-definition","heading":"Review: types express guarantees you can defend","text":"Show how types eliminate invalid states, preserve input/output relationships, and expose null/error paths. Then identify where runtime validation is still necessary. A well-typed API should be easier to use correctly, not simply impressive to read. Connect contracts to server validation and generated GraphQL types.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"web-security-title","heading":"","text":"Web Security & Authentication","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-b233b83661e5","heading":"","text":"Establish identity and resource permissions, manage sessions and credentials, then examine browser vulnerabilities and API defenses.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-fcde8723064a","heading":"","text":"Secure applications protect against browser attacks, verify identity, enforce permissions, and defend API endpoints. Each layer addresses a different risk.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-d20082617724","heading":"","text":"Authentication & authorization","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-e58064699e95","heading":"","text":"Connect the concepts: login, credentials and permissions","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-fc43fa5d0230","heading":"","text":"OAuth 2.0 and OIDC: follow a sign-in from start to finish","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-2beb58918fe2","heading":"","text":"JWT-based authentication: issuing, using and validating a token","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-8e112a050934","heading":"","text":"Protect the login: passwords, MFA and abuse","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-18398ff73632","heading":"","text":"Session lifecycle: establish, renew & expire","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-423392b8b00a","heading":"","text":"Object-level authorization: enforce access per resource","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-df4e351a0461","heading":"","text":"Web vulnerabilities","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-d26ad62f895e","heading":"","text":"API security","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-884397c1e592","heading":"","text":"Key takeaways","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-auth","heading":"Authentication & authorization","text":"Authentication & authorization","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-6d83b6ece1d4","heading":"Authentication & authorization","text":"Authentication verifies who the user is. Authorization determines what that user may do. For example, signing in establishes identity; checking whether that user can delete a project enforces permissions. Enforce authorization on the server for every protected operation. Scope caches to the correct user or tenant so performance optimizations do not bypass data isolation.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-af03e751f76c","heading":"Authentication & authorization","text":"OAuth 2.0: A framework for delegated authorization using access tokens, such as allowing an app to access a user’s calendar without sharing their password. OAuth itself is not a login protocol; OpenID Connect (OIDC) adds an identity layer. Browser and mobile apps commonly use the Authorization Code flow with PKCE (Proof Key for Code Exchange), which binds authorization-code redemption to the client that initiated the flow.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-042271bf5ec1","heading":"Authentication & authorization","text":"JWT · JSON Web Token: A token format containing claims, commonly signed and used in authentication and authorization systems. A signed JWT provides integrity, not confidentiality: its payload is readable, so do not put secrets in it. Verify the signature and permitted algorithm, then validate claims including issuer (iss), audience (aud), expiration (exp), and not-before (nbf, when present). JWT is a format; OAuth is a framework, and OAuth access tokens do not have to be JWTs.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-cc8a1a177642","heading":"Authentication & authorization","text":"RBAC · Role-Based Access Control: Assign permissions to roles such as admin, editor, and viewer, then assign roles to users. Also enforce object-level authorization for resource ownership and tenant isolation. Missing these checks can cause IDOR (Insecure Direct Object Reference), also called BOLA (Broken Object Level Authorization) in API security.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-auth-models","heading":"Connect the concepts: login, credentials and permissions","text":"Connect the concepts: login, credentials and permissions","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-auth-models-definition","heading":"Connect the concepts: login, credentials and permissions","text":"Think in three steps: establish identity → carry credentials on later requests → authorize the requested operation. OAuth, JWT and sessions fit into different steps; they are not competing names for login.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-1750c3c21879","heading":"Connect the concepts: login, credentials and permissions","text":"ConceptQuestion it answersExample","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-045235c8f4c3","heading":"Connect the concepts: login, credentials and permissions","text":"AuthenticationWho is making this request?Verify a password, passkey or OIDC login.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-e4acaff519a4","heading":"Connect the concepts: login, credentials and permissions","text":"Session / access tokenHow does the next request present credentials?A session cookie or a Bearer access token.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-ba8299d10b0f","heading":"Connect the concepts: login, credentials and permissions","text":"AuthorizationMay this identity perform this action on this resource?An editor may change jobs belonging to their organization.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-915f579afbc3","heading":"Connect the concepts: login, credentials and permissions","text":"OAuth 2.0How does an app obtain delegated API access?Allow an app to read a user’s calendar.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-1745b58bec37","heading":"Connect the concepts: login, credentials and permissions","text":"OIDCHow can an app establish identity through an identity provider?Sign in with Google, built on OAuth 2.0.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-523e9cd4e39f","heading":"Connect the concepts: login, credentials and permissions","text":"JWTHow can token claims be represented and integrity-protected?A signed access token intended for your API.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-d8676c1ca0e2","heading":"Connect the concepts: login, credentials and permissions","text":"Two common architectures: a web backend completes OIDC and creates an opaque browser session, keeping upstream tokens server-side; alternatively, a browser client obtains an access token with Authorization Code + PKCE and calls its intended API. A JWT can also be issued after your own password login. OAuth access tokens can be opaque rather than JWTs.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-18fd0b7db5f4","heading":"Connect the concepts: login, credentials and permissions","text":"Cookie versus JWT is not a direct comparison: a cookie is a browser storage/transport mechanism; JWT is a token format. A cookie can contain an opaque session ID or a JWT. A signed JWT does not automatically provide a safer session lifecycle.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-oauth-flow","heading":"OAuth 2.0 and OIDC: follow a sign-in from start to finish","text":"OAuth 2.0 and OIDC: follow a sign-in from start to finish","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-oauth-flow-definition","heading":"OAuth 2.0 and OIDC: follow a sign-in from start to finish","text":"Example: a job platform offers “Sign in with Google.” Google authenticates the user; the platform establishes its own local user and session. OIDC adds identity to the OAuth flow.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-a1d63f103edb","heading":"OAuth 2.0 and OIDC: follow a sign-in from start to finish","text":"RoleIn this example","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-314503a03a66","heading":"OAuth 2.0 and OIDC: follow a sign-in from start to finish","text":"Resource ownerThe user granting access.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-6326e6488877","heading":"OAuth 2.0 and OIDC: follow a sign-in from start to finish","text":"ClientYour job platform—the application requesting tokens. “Client” can include a backend.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-5dec02eb1646","heading":"OAuth 2.0 and OIDC: follow a sign-in from start to finish","text":"Authorization server / OIDC providerGoogle’s authorization/token service; authenticates the user and issues tokens.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-dec11921462c","heading":"OAuth 2.0 and OIDC: follow a sign-in from start to finish","text":"Resource serverThe API an access token is intended for, such as Google Calendar. Your API requires tokens explicitly issued for it.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-20f9aa6bd203","heading":"OAuth 2.0 and OIDC: follow a sign-in from start to finish","text":"Authorization Code + PKCE · web backend / BFF exampleStart the loginThe app stores login-attempt state and redirects the browser to the provider with client ID, registered redirect URI, scopes including openid, state, a PKCE challenge and an OIDC nonce.Authenticate and consentThe provider signs in the user and requests any necessary consent. Your app does not receive the provider password.Return an authorization codeThe provider redirects to the registered callback with a short-lived, single-use code and state. The app checks state against its login attempt.Exchange the codeThe backend calls the token endpoint using the code, matching redirect URI, PKCE verifier and its configured client authentication where applicable. It receives tokens.Validate identityValidate the ID token’s signature, issuer, audience, expiration and nonce. Map issuer + subject (sub) to the local account; do not automatically link accounts just because email strings match.Create the app sessionRotate/create the app’s session ID and set a Secure, HttpOnly cookie with an appropriate SameSite policy. Later requests use this session; the server still authorizes every operation.This is the backend/BFF variant. A browser-only app is a public client: it cannot protect a client secret and has different token-storage responsibilities.","kind":"Diagram"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-oauth-tokens","heading":"OAuth 2.0 and OIDC: follow a sign-in from start to finish › The returned tokens have different jobs","text":"The returned tokens have different jobs","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-ca6dbc25404d","heading":"OAuth 2.0 and OIDC: follow a sign-in from start to finish › The returned tokens have different jobs","text":"TokenPurposeImportant boundary","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-46a52d153d96","heading":"OAuth 2.0 and OIDC: follow a sign-in from start to finish › The returned tokens have different jobs","text":"ID token (OIDC)Tell the client about the authenticated identity.Not a replacement for an API access token.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-303d821641e1","heading":"OAuth 2.0 and OIDC: follow a sign-in from start to finish › The returned tokens have different jobs","text":"Access tokenAuthorize requests to the intended resource server within granted scopes.A Google API token does not automatically grant access to your job API.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-e159f8759212","heading":"OAuth 2.0 and OIDC: follow a sign-in from start to finish › The returned tokens have different jobs","text":"Refresh token, if issuedObtain replacement access tokens without another interactive login.Send only to the intended token endpoint; protect and rotate it.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-378dbb1dfd57","heading":"OAuth 2.0 and OIDC: follow a sign-in from start to finish › The returned tokens have different jobs","text":"PKCE binds code redemption to the verifier held by the initiating client. state correlates the callback to the login attempt and helps prevent login CSRF. nonce binds the OIDC ID token to that authentication request. They address different checks. Use an established OIDC client library and registered redirect URIs; do not invent the protocol.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-47eed0ffe0c6","heading":"OAuth 2.0 and OIDC: follow a sign-in from start to finish › The returned tokens have different jobs","text":"Continue with session lifecycle and refresh-token rotation. Permission scopes limit delegated access; they do not replace resource-level authorization.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-jwt-flow","heading":"JWT-based authentication: issuing, using and validating a token","text":"JWT-based authentication: issuing, using and validating a token","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-jwt-flow-definition","heading":"JWT-based authentication: issuing, using and validating a token","text":"A JWT is not a login protocol. It is a token format. After the user authenticates—through your login endpoint or an identity provider—an issuer can create a signed JWT access token. The API validates it on later requests.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-ca7f32efbfe1","heading":"JWT-based authentication: issuing, using and validating a token","text":"Example · password login followed by Bearer API requestsAuthenticate onceThe browser sends credentials over HTTPS. The authentication service verifies the password hash and any required additional factor.Issue credentialsThe issuer creates a short-lived access token with identity, audience, expiry and permitted claims. A refresh mechanism is a separate decision.Present the access tokenThe client sends Authorization: Bearer \u003ctoken> to the intended API over HTTPS. Anyone possessing a bearer token can use it until prevented by expiry or server policy.Validate, then authorizeThe API verifies the signature and allowed algorithm, issuer, audience, expiration and other applicable claims. Then it checks action permissions, organization membership and access to the requested job.Changing a role in the database does not automatically change an already-issued JWT. Choose short lifetimes and/or server-side permission/revocation checks where timely changes matter.","kind":"Diagram"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-5d21d0ab3ba7","heading":"JWT-based authentication: issuing, using and validating a token","text":"PATCH /api/jobs/42 HTTP/1.1 Authorization: Bearer \u003caccess-token> Content-Type: application/json {\"title\":\"Senior React Engineer\"}","kind":"Code"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-a7da498d4da3","heading":"JWT-based authentication: issuing, using and validating a token","text":"Readable payload example: these claims are signed, not encrypted. This is a decoded illustrative payload, not a usable token.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-0aa415f623dc","heading":"JWT-based authentication: issuing, using and validating a token","text":"{ \"iss\": \"https://identity.example.com\", \"aud\": \"jobs-api\", \"sub\": \"user-123\", \"exp\": 2000000000, \"scope\": \"jobs:write\" }","kind":"Code"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-cc8c645adcc7","heading":"JWT-based authentication: issuing, using and validating a token","text":"iss identifies the trusted issuer; aud identifies the intended recipient; sub identifies the subject; exp limits validity; scopes describe granted access. A typical signed JWT has header.payload.signature. Decoding claims is not verification: use a trusted validation library and configured issuer/key source. With asymmetric signing, the issuer signs with a private key and APIs verify using public keys, commonly published through JWKS; plan for key rotation.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-e9d1240b061c","heading":"JWT-based authentication: issuing, using and validating a token","text":"What this does not solve: XSS, safe token storage, immediate revocation or object permissions. See storage tradeoffs, logout/revocation and object-level checks. Do not send bearer tokens in URLs or log them. An opaque session is often simpler when one web backend owns authentication and requests.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-login-protection","heading":"Protect the login: passwords, MFA and abuse","text":"Protect the login: passwords, MFA and abuse","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-login-protection-definition","heading":"Protect the login: passwords, MFA and abuse","text":"A correct token flow still depends on secure authentication and recovery. Know these foundations; use maintained authentication libraries or an identity platform for the mechanisms.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-1556b7e1dcce","heading":"Protect the login: passwords, MFA and abuse","text":"Password hashing: store salted, deliberately expensive password hashes, such as Argon2id—not plaintext, reversible encryption or a fast general-purpose hash. Verify with the password-hashing library; TLS protects credentials in transit.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-e82ab1950625","heading":"Protect the login: passwords, MFA and abuse","text":"MFA and passkeys: an additional factor reduces password-only compromise. WebAuthn/passkeys use origin-bound public-key credentials and resist phishing; MFA methods have different security properties.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-ea91d658f721","heading":"Protect the login: passwords, MFA and abuse","text":"Login abuse: rate-limit attempts with account and network signals, detect credential stuffing and use non-enumerating error/recovery responses. Avoid a lockout policy that lets attackers trivially deny access to other users.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-5e16428ba7b3","heading":"Protect the login: passwords, MFA and abuse","text":"Password reset / account recovery: use expiring, single-use recovery credentials and a verified delivery path; protect against enumeration. Revoke affected sessions according to policy and require reauthentication for sensitive changes.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-88250a761933","heading":"Protect the login: passwords, MFA and abuse","text":"Trust boundaries: the frontend can hide controls, but the server must validate credentials and enforce permissions. CORS, route guards and a decoded JWT are not authorization controls.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-5f08690eb062","heading":"Protect the login: passwords, MFA and abuse","text":"Study next: the existing session/storage/rotation lifecycle, RBAC and object-level access, and XSS, CSRF, injection and clickjacking. Connect each attack to the trust boundary and its prevention mechanism.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-sessions","heading":"Session lifecycle: establish, renew & expire","text":"Session lifecycle: establish, renew & expire","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-7aaf8435ef29","heading":"Session lifecycle: establish, renew & expire","text":"A session links subsequent requests to an authenticated identity. A server-side session commonly uses an opaque cookie identifier; token-based APIs may use short-lived access tokens and longer-lived refresh credentials. Both designs need expiration, revocation, and server-side authorization.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-2018ae2d3681","heading":"Session lifecycle: establish, renew & expire","text":"Establish: Verify credentials or complete OIDC, then rotate the session identifier after login or privilege changes to prevent session fixation. Set appropriate cookie attributes and return only the user data the UI needs.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-f85bc33d6473","heading":"Session lifecycle: establish, renew & expire","text":"Use: Validate the session or token on protected requests. Apply idle and absolute timeouts appropriate to the application. A frontend timer is a UX hint; the server enforces expiration.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-8c3e4a414f46","heading":"Session lifecycle: establish, renew & expire","text":"Renew: Refresh through the intended protocol or session endpoint. Coordinate concurrent renewal attempts and retry the original request at most under a bounded policy. Avoid recursive refresh loops; an unauthenticated 401 differs from a permission-denied 403.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-5579c1c7ffd3","heading":"Session lifecycle: establish, renew & expire","text":"End: Invalidate the relevant server session or refresh credential and clear identity-scoped client data. Require reauthentication for sensitive actions when the risk warrants it.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-token-storage","heading":"Session lifecycle: establish, renew & expire › Token storage: model XSS and CSRF separately","text":"Token storage: model XSS and CSRF separately","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-7cd4bc156446","heading":"Session lifecycle: establish, renew & expire › Token storage: model XSS and CSRF separately","text":"ChoiceBenefitExposure and mitigation","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-0cb5584e6bbc","heading":"Session lifecycle: establish, renew & expire › Token storage: model XSS and CSRF separately","text":"HttpOnly session cookie / BFFJavaScript cannot read the credential; a backend-for-frontend can keep upstream tokens server-side.Cookies are sent automatically: apply CSRF protection. XSS can still issue authenticated actions. Adds server-side session/proxy responsibilities.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-f095b0f2d93c","heading":"Session lifecycle: establish, renew & expire › Token storage: model XSS and CSRF separately","text":"In-memory access tokenNo persistent token remains in web storage after the page is gone.Reload requires a renewal/login path. Injected JavaScript can still steal or use a token during execution; memory is not an XSS boundary.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-7d3aeddce7a5","heading":"Session lifecycle: establish, renew & expire › Token storage: model XSS and CSRF separately","text":"localStorage / sessionStorage tokenConvenient client access; localStorage survives restarts, sessionStorage supports tab-lifetime persistence.Readable by same-origin JavaScript and exposed to XSS. Avoid persistent high-value credentials where a safer architecture fits. Encrypting with a key available to the same JavaScript does not fix this exposure.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-51eaf7611407","heading":"Session lifecycle: establish, renew & expire › Token storage: model XSS and CSRF separately","text":"Cookie configuration: Use Secure, HttpOnly, an appropriate SameSite policy, and narrow scope. A __Host- cookie requires Secure, Path=/, and no Domain attribute, reducing domain-scoping mistakes. Cross-site cookie flows may require SameSite=None; Secure and can still face browser restrictions. Cookie storage does not replace XSS prevention.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-refresh-rotation","heading":"Session lifecycle: establish, renew & expire › Refresh-token rotation & replay detection","text":"Refresh-token rotation & replay detection","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-389bc4d9a177","heading":"Session lifecycle: establish, renew & expire › Refresh-token rotation & replay detection","text":"With refresh-token rotation, the authorization server issues a replacement refresh token and invalidates the previous one on successful redemption. Reuse of an invalidated token can indicate theft; the server can revoke the affected token family and require reauthentication according to its policy. Short access-token lifetimes limit exposure but do not make already-issued tokens immediately revocable.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-e1569b3ae7eb","heading":"Session lifecycle: establish, renew & expire › Refresh-token rotation & replay detection","text":"Concurrency trap: Two tabs redeeming the same refresh token can look like replay. Coordinate renewal through a shared owner/BFF or a suitable coordination mechanism; a promise shared within one tab does not coordinate other tabs. Follow the identity provider’s rotation and reuse policy, and avoid storing refresh tokens in ordinary web storage. BroadcastChannel can distribute session-change notifications without distributing credentials.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-logout","heading":"Session lifecycle: establish, renew & expire › Logout, revocation & cache cleanup","text":"Logout, revocation & cache cleanup","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-71d5527d11fb","heading":"Session lifecycle: establish, renew & expire › Logout, revocation & cache cleanup","text":"Server boundary: Invalidate the session or revoke refresh credentials through a protected endpoint. Clear cookies with matching name, path, and domain scope. Local token deletion alone does not invalidate a stolen token.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-5531ca7d8d26","heading":"Session lifecycle: establish, renew & expire › Logout, revocation & cache cleanup","text":"Access-token limits: A self-contained JWT can remain valid until expiry unless resource servers consult revocation/introspection or another server-side policy. Local app logout and identity-provider logout are distinct operations.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-192a00b86c0c","heading":"Session lifecycle: establish, renew & expire › Logout, revocation & cache cleanup","text":"Client boundary: Clear user/tenant query caches, stores, and sensitive persisted drafts; close real-time subscriptions. Cancel reads and prevent already-started responses from repopulating the previous user’s cache. Notify other tabs and revalidate on resume.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-b37f51a1efa7","heading":"Session lifecycle: establish, renew & expire › Logout, revocation & cache cleanup","text":"Failure behavior: If server invalidation fails, report that logout was not fully confirmed; clearing the local UI does not prove remote revocation. Personalized responses also need appropriate HTTP caching policies.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-object-authorization","heading":"Object-level authorization: enforce access per resource","text":"Object-level authorization: enforce access per resource","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-12b987a9717a","heading":"Object-level authorization: enforce access per resource","text":"BOLA / IDOR occurs when an API accepts a resource identifier without checking whether the authenticated principal may perform the requested action on that specific object. A valid login and an “editor” role are insufficient if the object belongs to another tenant.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-edbc78dcf8eb","heading":"Object-level authorization: enforce access per resource","text":"Example: For PATCH /api/projects/42, derive identity and tenant membership from the validated session; load project 42 within an authorized tenant/ownership scope; verify edit permission; allowlist editable fields; then write. Do not trust a client-supplied tenant ID, hidden button, or unguessable UUID as authorization. Apply equivalent checks to reads, downloads, list queries, batch endpoints, and real-time subscriptions.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-7a0d3ba5ca92","heading":"Object-level authorization: enforce access per resource","text":"Implementation and tradeoff: Centralize policy checks so every handler enforces the same rules, while keeping resource-specific decisions explicit. Recheck permissions when membership changes and deny by default. Cache isolation and UI permission checks improve correctness and UX but never replace this server enforcement; see identity-scoped query lifecycles.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-vulnerabilities","heading":"Web vulnerabilities","text":"Web vulnerabilities","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-xss","heading":"Web vulnerabilities › XSS · Cross-Site Scripting","text":"XSS · Cross-Site Scripting","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-4a9e74ec91cf","heading":"Web vulnerabilities › XSS · Cross-Site Scripting","text":"What happens: An attacker injects malicious JavaScript that runs in the context of your website, potentially reading page data or acting as the user.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-d8e4a959fb55","heading":"Web vulnerabilities › XSS · Cross-Site Scripting","text":"Prevent it: treat user input as text, not executable code.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-91a8070a19af","heading":"Web vulnerabilities › XSS · Cross-Site Scripting","text":"Output encoding (escaping): React escapes text interpolated as {comment}. When accepting children or render props, distinguish text nodes from intentionally supplied markup. For plain DOM code, element.textContent = comment is a safe DOM sink: it inserts text without parsing HTML. Encoding must match the output context; HTML escaping alone does not make arbitrary URLs or JavaScript safe.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-da763f17778b","heading":"Web vulnerabilities › XSS · Cross-Site Scripting","text":"HTML sanitisation: Sanitise rich HTML with a trusted library such as DOMPurify to remove unsafe elements, attributes, and URL schemes while keeping permitted markup. Never send raw user input to innerHTML or dangerouslySetInnerHTML.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-a484225d2cc9","heading":"Web vulnerabilities › XSS · Cross-Site Scripting","text":"Content Security Policy (CSP) — defense in depth: Restrict script execution with script-src, using nonces or hashes for approved scripts. CSP supplements output encoding and sanitisation. These protections remain necessary with both CSR and SSR.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-csrf","heading":"Web vulnerabilities › CSRF · Cross-Site Request Forgery","text":"CSRF · Cross-Site Request Forgery","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-fc37491ff638","heading":"Web vulnerabilities › CSRF · Cross-Site Request Forgery","text":"What happens: An attacker tricks an authenticated browser into sending an unwanted request, such as changing an email address. The attack relies on credentials the browser sends automatically, typically session cookies.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-7a087277eb10","heading":"Web vulnerabilities › CSRF · Cross-Site Request Forgery","text":"Prevent it: a login cookie alone should not approve a sensitive action.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-6143ee23b85e","heading":"Web vulnerabilities › CSRF · Cross-Site Request Forgery","text":"CSRF token validation: With the synchronizer token pattern, include an unpredictable, session-bound token in state-changing requests. The server validates it; the browser’s same-origin policy prevents an attacker’s site from reading it, assuming no XSS or permissive cross-origin access.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-e2d695a097fe","heading":"Web vulnerabilities › CSRF · Cross-Site Request Forgery","text":"SameSite cookie policy: Use SameSite=Lax or Strict where your flow allows it. This restricts when cookies accompany requests from other sites.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-75ccb929f4f0","heading":"Web vulnerabilities › CSRF · Cross-Site Request Forgery","text":"Origin validation & safe HTTP methods: Validate the Origin header against trusted origins, with a Referer check where appropriate. Client-side default-action cancellation does not protect a server endpoint from CSRF. GET must have read-only semantics; use state-changing methods such as POST with CSRF protection.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-8fece37a59e0","heading":"Web vulnerabilities › CSRF · Cross-Site Request Forgery","text":"Key distinction: XSS runs attacker code inside your site. CSRF exploits the browser’s existing authentication to send requests. HttpOnly cookies prevent JavaScript from reading the cookie, but do not stop injected code from making authenticated requests.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-2cc493d4ad31","heading":"Web vulnerabilities › SQL injection","text":"SQL injection","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-16be3789f24a","heading":"Web vulnerabilities › SQL injection","text":"The trap: User input becomes part of a SQL command.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-1c3bf7f5e140","heading":"Web vulnerabilities › SQL injection","text":"Prevent it: parameterized queries (parameter binding). Keep SQL structure separate from values by binding input to placeholders. The database treats bound values as data, even if they look like SQL. Dynamic table names, column names, and sort directions require an allowlist; value placeholders do not cover SQL identifiers.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-97514c555808","heading":"Web vulnerabilities › SQL injection","text":"// Parameterized query (placeholder syntax depends on your DB driver) db.query('SELECT * FROM users WHERE email = ?', [email]);","kind":"Code"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-b4926080257c","heading":"Web vulnerabilities › Clickjacking","text":"Clickjacking","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-1aa53d7d8492","heading":"Web vulnerabilities › Clickjacking","text":"The trap: An attacker hides your page inside an iframe and tricks a user into clicking its buttons.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-79243c331b6a","heading":"Web vulnerabilities › Clickjacking","text":"Prevent it: anti-framing with CSP frame-ancestors. This prevents UI redressing through framing. Send this HTTP response header to block all framing:","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-cb4565cce61e","heading":"Web vulnerabilities › Clickjacking","text":"Content-Security-Policy: frame-ancestors 'none'","kind":"Code"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-32018449cee2","heading":"Web vulnerabilities › Clickjacking","text":"Use 'self' if your own site needs to embed it. X-Frame-Options: DENY is a legacy alternative for blocking frames.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-be1ae355109f","heading":"Web vulnerabilities › Open redirects","text":"Open redirects","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-26d5d7c67782","heading":"Web vulnerabilities › Open redirects","text":"The trap: A trusted-looking link to your app forwards the user to an attacker’s site.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-121ec6457477","heading":"Web vulnerabilities › Open redirects","text":"Prevent it: redirect destination validation using an allowlist.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-d03c1fc8a793","heading":"Web vulnerabilities › Open redirects","text":"Server-side route mapping: Accept a destination key such as next=dashboard and map it to a fixed route such as /dashboard.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-4f085e19c44a","heading":"Web vulnerabilities › Open redirects","text":"URL parsing & origin validation: Resolve the URL with a standard parser, then validate its scheme and origin against an explicit allowlist. Checking that it starts with / is insufficient: //evil.example points to another site.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-api","heading":"API security","text":"API security","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-c94071c9efdb","heading":"API security","text":"Rate limiting: Restrict request frequency to reduce abuse, brute-force attempts, and resource exhaustion. Apply limits by user, API key, or IP as appropriate; Common algorithms include token bucket (allows controlled bursts) and sliding window (limits requests over a rolling interval). Return 429 Too Many Requests, optionally with Retry-After, when limits are exceeded.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-6ef3c4cc3526","heading":"API security","text":"HTTPS / TLS (Transport Layer Security): Provides confidentiality and integrity in transit, plus server authentication through certificate validation. TLS does not replace input validation or access checks.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-d7bcf7588fd2","heading":"API security","text":"CORS · Cross-Origin Resource Sharing: Browser-enforced rules controlling whether JavaScript from another origin can read a response. CORS builds on the same-origin policy (SOP); an origin is the scheme, host, and port. Configure Access-Control-Allow-Origin for trusted origins. Cookie-based credentialed requests also require Access-Control-Allow-Credentials: true and cannot use a wildcard allowed origin. For requests requiring a preflight, the browser sends OPTIONS to check permission before the actual request. CORS does not stop every cross-origin request or restrict non-browser clients, so it cannot replace authentication, authorization, or CSRF protection.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-fdb947d04a1a","heading":"API security","text":"For GraphQL, a single request may select substantial work. Apply operation cost limits and field/resource authorization alongside the HTTP and identity protections here.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-review","heading":"Key takeaways","text":"Key takeaways","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-98f6f890bb60","heading":"Key takeaways","text":"I separate identity, permissions, and attack prevention. Authentication establishes who the user is; server-side authorization checks what they can do. I prevent XSS with context-appropriate output encoding and HTML sanitisation, CSRF with token validation and SameSite cookie policies, and SQL injection with parameterized queries. For APIs, I use TLS, validate tokens, enforce access checks and rate limits, and configure CORS for the intended browser origins. OAuth delegates access, while JWT is one possible token format.","kind":"Notes"}];
